+        results.push(simulated);
+        scoreSum += simulated.cuppingScore;
+
+        if (performance.now() >= deadline) {
+          yieldCount += 1;
+          const processedCount = i + 1;
+          const pct = Math.round((processedCount / total) * 100);
+          progressEl.value = pct;
+          progressPctEl.textContent = `${pct}%`;
+          metricProcessedEl.textContent = `${processedCount.toLocaleString()} / ${total.toLocaleString()}`;
+          metricAvgScoreEl.textContent = (scoreSum / processedCount).toFixed(1);
+          metricYieldCountEl.textContent = String(yieldCount);
+          metricElapsedEl.textContent = `${Math.round(performance.now() - startTime)} ms`;
+
+          await yieldToMain();
+          deadline = performance.now() + 50;
+        }
+      }
+
+      const elapsed = Math.round(performance.now() - startTime);
+      const finalCount = results.length;
+      const finalPct = total > 0 ? Math.round((finalCount / total) * 100) : 0;
+
+      progressEl.value = finalPct;
+      progressPctEl.textContent = `${finalPct}%`;
+      metricProcessedEl.textContent = `${finalCount.toLocaleString()} / ${total.toLocaleString()}`;
+      metricAvgScoreEl.textContent = finalCount > 0 ? (scoreSum / finalCount).toFixed(1) : '—';
+      metricYieldCountEl.textContent = String(yieldCount);
+      metricElapsedEl.textContent = `${elapsed} ms`;
+
+      if (isCancelled) {
+        statusTextEl.textContent = `Simulation stopped at ${finalCount.toLocaleString()} blends`;
+      } else {
+        statusTextEl.textContent = `Completed ${finalCount.toLocaleString()} recipe simulations in ${elapsed} ms`;
+      }
+
+      if (results.length > 0) {
+        renderSimulationResults(results);
+      }
+    }
+
