+  <script>
+    (function () {
+      let accumulatedForegroundMs = 0;
+      let foregroundStartTime = document.visibilityState === 'visible' ? performance.now() : null;
+
+      function updateForegroundTime() {
+        const now = performance.now();
+        if (document.visibilityState === 'visible') {
+          if (foregroundStartTime === null) {
+            foregroundStartTime = now;
+          }
+        } else {
+          if (foregroundStartTime !== null) {
+            accumulatedForegroundMs += now - foregroundStartTime;
+            foregroundStartTime = null;
+          }
+        }
+      }
+
+      document.addEventListener('visibilitychange', updateForegroundTime);
+      window.addEventListener('pagehide', () => {
+        if (foregroundStartTime !== null) {
+          accumulatedForegroundMs += performance.now() - foregroundStartTime;
+          foregroundStartTime = null;
+        }
+      });
+      window.addEventListener('pageshow', () => {
+        if (document.visibilityState === 'visible' && foregroundStartTime === null) {
+          foregroundStartTime = performance.now();
+        }
+      });
+
+      /**
+       * Calculates the total time (in milliseconds) the page has been in the foreground.
+       * @param {Object} [options]
+       * @param {boolean} [options.inSeconds=false] - Return value in seconds instead of milliseconds.
+       * @returns {number} Total foreground duration.
+       */
+      function calculateTotalForegroundTime(options = {}) {
+        let totalMs = accumulatedForegroundMs;
+        if (document.visibilityState === 'visible' && foregroundStartTime !== null) {
+          totalMs += performance.now() - foregroundStartTime;
+        }
+        return options.inSeconds ? totalMs / 1000 : totalMs;
+      }
+
+      window.calculateTotalForegroundTime = calculateTotalForegroundTime;
