+        const isAnniversaryToday = annualAnniversary.equals(today.toPlainMonthDay());
+
+        // Convert PlainMonthDay to a PlainDate with a specific year before doing arithmetic
+        let nextOccurrence = annualAnniversary.toPlainDate({ year: today.year });
+        if (Temporal.PlainDate.compare(nextOccurrence, today) < 0) {
+          nextOccurrence = nextOccurrence.add({ years: 1 }, { overflow: 'constrain' });
+        }
+
+        // Format and display without time zone conversion
+        const formattedTime = `${String(hour).padStart(2, '0')}:${String(minute).padStart(2, '0')} (${reminderTime.toLocaleString()})`;
