+  <script>
+    const orderStatus = document.getElementById('order-status');
+    const orderForms = document.querySelectorAll('.order-form');
+    let orderCount = 0;
+
+    orderForms.forEach((form) => {
+      form.addEventListener('submit', (event) => {
+        event.preventDefault();
+        const formData = new FormData(form);
+        const drink = formData.get('drink');
+        const size = formData.get('size');
+        const submitBtn = form.querySelector('button[type="submit"]');
+
+        orderCount += 1;
+        if (orderStatus) {
+          const itemLabel = orderCount === 1 ? 'item' : 'items';
+          orderStatus.textContent = `Added ${size} ${drink} to order (${orderCount} ${itemLabel})`;
+        }
+
+        if (submitBtn) {
+          submitBtn.setAttribute('data-added', 'true');
+        }
+      });
+    });
+
+    /* Fallback for older browsers that do not support CSS :has() */
+    if (!CSS.supports('selector(:has(*))')) {
+      const cards = document.querySelectorAll('.card');
+      cards.forEach((card) => {
+        if (card.querySelector('img')) {
+          card.classList.add('has-image');
+        }
+
+        const radios = card.querySelectorAll('input[type="radio"]');
+        const syncRadioState = () => {
+          let anyChecked = false;
+          radios.forEach((radio) => {
+            const optionLabel = radio.closest('.size-option');
+            if (optionLabel) {
+              optionLabel.classList.toggle('is-checked', radio.checked);
+            }
+            if (radio.checked) {
+              anyChecked = true;
+            }
+          });
+          card.classList.toggle('is-selected', anyChecked);
+        };
+
+        radios.forEach((radio) => {
+          radio.addEventListener('change', syncRadioState);
+        });
+        syncRadioState();
+
+        const form = card.querySelector('.order-form');
+        if (form) {
+          form.addEventListener('submit', () => {
+            card.classList.add('is-added');
+          });
+        }
+      });
+    }
+  </script>
