+  <script>
+    (() => {
+      const orderItems = [];
+      const navCountEl = document.getElementById('nav-order-count');
+      const orderTrayEl = document.getElementById('order-tray');
+      const orderTrayItemsEl = document.getElementById('order-tray-items');
+      const orderTrayTotalEl = document.getElementById('order-tray-total');
+
+      function formatCurrency(amount) {
+        return `$${Number(amount).toFixed(2)}`;
+      }
+
+      function updateOrderSummary() {
+        const count = orderItems.length;
+        if (navCountEl) {
+          navCountEl.textContent = String(count);
+        }
+        if (!orderTrayEl || !orderTrayItemsEl || !orderTrayTotalEl) return;
+
+        if (count === 0) {
+          orderTrayEl.hidden = true;
+          return;
+        }
+
+        orderTrayEl.hidden = false;
+        const total = orderItems.reduce((sum, item) => sum + item.price, 0);
+        const latestItems = orderItems
+          .map((item) => `${item.name} (${item.sizeLabel})`)
+          .join(', ');
+        orderTrayItemsEl.textContent = `${count} item${count === 1 ? '' : 's'}: ${latestItems}`;
+        orderTrayTotalEl.textContent = `Total: ${formatCurrency(total)}`;
+      }
+
+      document.querySelectorAll('.card[data-drink-name]').forEach((card) => {
+        const drinkName = card.getAttribute('data-drink-name') || 'Drink';
+        const priceDisplay = card.querySelector('[data-price-display]');
+        const sizeSummary = card.querySelector('[data-size-summary]');
+        const addButton = card.querySelector('[data-add-button]');
+        const feedbackEl = card.querySelector('[data-order-feedback]');
+        const form = card.querySelector('.drink-order-form');
+        const radios = card.querySelectorAll('input[type="radio"]');
+
+        function syncCardState() {
+          const selected = card.querySelector('input[type="radio"]:checked');
+          if (!selected) return;
+          const price = parseFloat(selected.getAttribute('data-price') || '0');
+          const label = selected.getAttribute('data-label') || selected.value;
+          const formatted = formatCurrency(price);
+
+          if (priceDisplay) priceDisplay.textContent = formatted;
+          if (sizeSummary) sizeSummary.textContent = label;
+          if (addButton) addButton.textContent = `Add to Order · ${formatted}`;
+        }
+
+        radios.forEach((radio) => {
+          radio.addEventListener('change', syncCardState);
+        });
+
+        if (form) {
+          form.addEventListener('submit', (event) => {
+            event.preventDefault();
+            const selected = card.querySelector('input[type="radio"]:checked');
+            if (!selected) return;
+
+            const price = parseFloat(selected.getAttribute('data-price') || '0');
+            const sizeValue = selected.value;
+            const sizeLabel = sizeValue.charAt(0).toUpperCase() + sizeValue.slice(1);
+
+            orderItems.push({
+              name: drinkName,
+              size: sizeValue,
+              sizeLabel,
+              price
+            });
+
+            updateOrderSummary();
+
+            card.classList.add('is-added');
+            if (feedbackEl) {
+              feedbackEl.hidden = false;
+              feedbackEl.textContent = `Added 1 ${sizeLabel} ${drinkName} (${formatCurrency(price)}) to your order!`;
+            }
+          });
+        }
+
+        syncCardState();
+      });
+    })();
