diff --git a/crypto-notes.js b/crypto-notes.js
new file mode 100644
index 0000000..4f9fc99
--- /dev/null
+++ b/crypto-notes.js
@@ -0,0 +1,573 @@
+/**
+ * Client-side encrypted delivery notes using WebCrypto KEM ('MLKEM768-X25519',
+ * 'ML-KEM-768', 'ML-KEM-1024') + AEAD ('ChaCha20-Poly1305' or 'AES-GCM'),
+ * with an automatic classical fallback ('X25519' + 'HKDF' + 'AES-GCM').
+ */
+
+const KEM_PUBLIC_KEY_ALGORITHMS = {
+  1184: 'ML-KEM-768',
+  1216: 'MLKEM768-X25519',
+  1568: 'ML-KEM-1024',
+};
+
+const DB_NAME = 'daily-grind-crypto-store';
+const STORE_NAME = 'recipient-keys';
+const KEY_RECORD_ID = 'recipient-kem-key';
+
+const textEncoder = new TextEncoder();
+const textDecoder = new TextDecoder();
+
+/**
+ * Serializes a Uint8Array to Base64 using Uint8Array.prototype.toBase64 when
+ * available, falling back to chunked String.fromCharCode + btoa.
+ * @param {Uint8Array} bytes
+ * @returns {string}
+ */
+export function bytesToBase64(bytes) {
+  const uint8 = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes);
+  if (typeof uint8.toBase64 === 'function') {
+    return uint8.toBase64();
+  }
+  let binary = '';
+  const chunkSize = 0x8000;
+  for (let i = 0; i < uint8.length; i += chunkSize) {
+    binary += String.fromCharCode(...uint8.subarray(i, i + chunkSize));
+  }
+  return btoa(binary);
+}
+
+/**
+ * Detects whether the runtime supports post-quantum hybrid KEM encapsulation
+ * and ChaCha20-Poly1305 via the static SubtleCrypto.supports() method.
+ * @returns {boolean}
+ */
+export function supportsPostQuantumEnvelope() {
+  return (
+    typeof globalThis.SubtleCrypto?.supports === 'function' &&
+    SubtleCrypto.supports('encapsulateKey', 'MLKEM768-X25519', 'ChaCha20-Poly1305')
+  );
+}
+
+/**
+ * Persists a non-extractable CryptoKeyPair in IndexedDB via structured cloning.
+ * @param {CryptoKeyPair} keyPair
+ */
+async function saveKeyPairToIndexedDB(keyPair) {
+  if (typeof indexedDB === 'undefined') return;
+  try {
+    await new Promise((resolve, reject) => {
+      const request = indexedDB.open(DB_NAME, 1);
+      request.onupgradeneeded = () => {
+        const db = request.result;
+        if (!db.objectStoreNames.contains(STORE_NAME)) {
+          db.createObjectStore(STORE_NAME);
+        }
+      };
+      request.onsuccess = () => {
+        const db = request.result;
+        const tx = db.transaction(STORE_NAME, 'readwrite');
+        const objectStore = tx.objectStore(STORE_NAME);
+        objectStore.put(keyPair, KEY_RECORD_ID);
+        tx.oncomplete = () => {
+          db.close();
+          resolve();
+        };
+        tx.onerror = () => {
+          db.close();
+          reject(tx.error);
+        };
+      };
+      request.onerror = () => reject(request.error);
+    });
+  } catch {
+    // IndexedDB may be disabled in private browsing or restricted contexts
+  }
+}
+
+/**
+ * Loads a previously persisted CryptoKeyPair from IndexedDB if present.
+ * @returns {Promise<CryptoKeyPair | null>}
+ */
+async function loadKeyPairFromIndexedDB() {
+  if (typeof indexedDB === 'undefined') return null;
+  try {
+    return await new Promise((resolve, reject) => {
+      const request = indexedDB.open(DB_NAME, 1);
+      request.onupgradeneeded = () => {
+        const db = request.result;
+        if (!db.objectStoreNames.contains(STORE_NAME)) {
+          db.createObjectStore(STORE_NAME);
+        }
+      };
+      request.onsuccess = () => {
+        const db = request.result;
+        const tx = db.transaction(STORE_NAME, 'readonly');
+        const objectStore = tx.objectStore(STORE_NAME);
+        const getReq = objectStore.get(KEY_RECORD_ID);
+        getReq.onsuccess = () => {
+          db.close();
+          resolve(getReq.result || null);
+        };
+        getReq.onerror = () => {
+          db.close();
+          reject(getReq.error);
+        };
+      };
+      request.onerror = () => reject(request.error);
+    });
+  } catch {
+    return null;
+  }
+}
+
+/**
+ * Generates (or restores) a recipient key pair using 'MLKEM768-X25519' when
+ * supported, falling back to 'X25519' key agreement + 'HKDF' + 'AES-GCM'.
+ * @param {{ forceRotate?: boolean }} [options]
+ */
+export async function generateRecipientKeys({ forceRotate = false } = {}) {
+  const pqSupported = supportsPostQuantumEnvelope();
+
+  if (!forceRotate) {
+    const cachedPair = await loadKeyPairFromIndexedDB();
+    if (cachedPair?.publicKey && cachedPair?.privateKey) {
+      const algName = cachedPair.publicKey.algorithm.name;
+      if (pqSupported && algName === 'MLKEM768-X25519') {
+        const publicKeyBytes = new Uint8Array(
+          await crypto.subtle.exportKey('raw-public', cachedPair.publicKey),
+        );
+        return {
+          suite: 'MLKEM768-X25519+ChaCha20-Poly1305',
+          keyFormat: 'raw-public',
+          keyPair: cachedPair,
+          publicKeyBytes,
+        };
+      }
+      if (!pqSupported && algName === 'X25519') {
+        const publicKeyBytes = new Uint8Array(
+          await crypto.subtle.exportKey('raw', cachedPair.publicKey),
+        );
+        return {
+          suite: 'X25519+HKDF+AES-GCM',
+          keyFormat: 'raw',
+          keyPair: cachedPair,
+          publicKeyBytes,
+        };
+      }
+    }
+  }
+
+  if (pqSupported) {
+    const keyPair = await crypto.subtle.generateKey(
+      'MLKEM768-X25519',
+      false,
+      ['encapsulateKey', 'decapsulateKey'],
+    );
+    await saveKeyPairToIndexedDB(keyPair);
+    const publicKeyBytes = new Uint8Array(
+      await crypto.subtle.exportKey('raw-public', keyPair.publicKey),
+    );
+    return {
+      suite: 'MLKEM768-X25519+ChaCha20-Poly1305',
+      keyFormat: 'raw-public',
+      keyPair,
+      publicKeyBytes,
+    };
+  }
+
+  // Classical fallback: X25519 key agreement + HKDF + AES-GCM
+  const keyPair = await crypto.subtle.generateKey('X25519', false, ['deriveBits']);
+  await saveKeyPairToIndexedDB(keyPair);
+  const publicKeyBytes = new Uint8Array(
+    await crypto.subtle.exportKey('raw', keyPair.publicKey),
+  );
+  return {
+    suite: 'X25519+HKDF+AES-GCM',
+    keyFormat: 'raw',
+    keyPair,
+    publicKeyBytes,
+  };
+}
+
+/**
+ * Derives a 256-bit AES-GCM key from X25519 shared bits via HKDF-SHA-256.
+ * @param {CryptoKey} privateKey
+ * @param {CryptoKey} peerPublicKey
+ * @param {Uint8Array} [infoBytes]
+ */
+async function deriveFallbackAesKey(privateKey, peerPublicKey, infoBytes = new Uint8Array(0)) {
+  const sharedSecret = await crypto.subtle.deriveBits(
+    { name: 'X25519', public: peerPublicKey },
+    privateKey,
+    256,
+  );
+  const hkdfKey = await crypto.subtle.importKey('raw', sharedSecret, 'HKDF', false, ['deriveKey']);
+  return crypto.subtle.deriveKey(
+    {
+      name: 'HKDF',
+      hash: 'SHA-256',
+      salt: new Uint8Array(32),
+      info: infoBytes,
+    },
+    hkdfKey,
+    { name: 'AES-GCM', length: 256 },
+    false,
+    ['encrypt', 'decrypt'],
+  );
+}
+
+/**
+ * Encapsulates a one-time shared AEAD key and returns { sharedKey, capsuleBytes }.
+ * @param {CryptoKey | Uint8Array | ArrayBuffer} recipientPublicKeyOrBytes
+ * @param {Uint8Array} [infoBytes]
+ */
+export async function encapsulateEnvelopeKey(
+  recipientPublicKeyOrBytes,
+  infoBytes = new Uint8Array(0),
+) {
+  const pubKey =
+    recipientPublicKeyOrBytes instanceof CryptoKey
+      ? recipientPublicKeyOrBytes
+      : await (() => {
+          const bytes =
+            recipientPublicKeyOrBytes instanceof Uint8Array
+              ? recipientPublicKeyOrBytes
+              : new Uint8Array(recipientPublicKeyOrBytes);
+          const kemName = KEM_PUBLIC_KEY_ALGORITHMS[bytes.byteLength];
+          return kemName
+            ? crypto.subtle.importKey('raw-public', bytes, kemName, true, ['encapsulateKey'])
+            : crypto.subtle.importKey('raw', bytes, 'X25519', true, []);
+        })();
+
+  if (pubKey.algorithm.name !== 'X25519') {
+    const { sharedKey, ciphertext } = await crypto.subtle.encapsulateKey(
+      pubKey.algorithm.name,
+      pubKey,
+      'ChaCha20-Poly1305',
+      false,
+      ['encrypt', 'decrypt'],
+    );
+    return { sharedKey, capsuleBytes: new Uint8Array(ciphertext) };
+  }
+
+  // Classical fallback: generate ephemeral X25519 key pair and send ephemeral public key as capsule
+  const ephemeral = await crypto.subtle.generateKey('X25519', false, ['deriveBits']);
+  const capsuleBytes = new Uint8Array(await crypto.subtle.exportKey('raw', ephemeral.publicKey));
+  const sharedKey = await deriveFallbackAesKey(ephemeral.privateKey, pubKey, infoBytes);
+  return { sharedKey, capsuleBytes };
+}
+
+/**
+ * Decapsulates the ciphertext capsule to recover the identical AEAD key.
+ * @param {CryptoKey} recipientPrivateKey
+ * @param {Uint8Array} capsuleBytes
+ * @param {Uint8Array} [infoBytes]
+ */
+export async function decapsulateEnvelopeKey(
+  recipientPrivateKey,
+  capsuleBytes,
+  infoBytes = new Uint8Array(0),
+) {
+  if (recipientPrivateKey.algorithm.name !== 'X25519') {
+    return crypto.subtle.decapsulateKey(
+      recipientPrivateKey.algorithm.name,
+      recipientPrivateKey,
+      capsuleBytes,
+      'ChaCha20-Poly1305',
+      false,
+      ['encrypt', 'decrypt'],
+    );
+  }
+
+  const ephemeralPubKey = await crypto.subtle.importKey('raw', capsuleBytes, 'X25519', true, []);
+  return deriveFallbackAesKey(recipientPrivateKey, ephemeralPubKey, infoBytes);
+}
+
+/**
+ * Encrypts UTF-8 text with an AEAD CryptoKey ('ChaCha20-Poly1305' or 'AES-GCM').
+ * @param {CryptoKey} key
+ * @param {string} plaintext
+ * @param {Uint8Array} [additionalData]
+ */
+export async function encryptMessage(key, plaintext, additionalData = new Uint8Array(0)) {
+  // Always generate a fresh 12-byte (96-bit) IV per message
+  const iv = crypto.getRandomValues(new Uint8Array(12));
+  const encoded = textEncoder.encode(plaintext);
+
+  const ciphertextBuffer = await crypto.subtle.encrypt(
+    {
+      name: key.algorithm.name,
+      iv,
+      additionalData,
+    },
+    key,
+    encoded,
+  );
+
+  return { iv, ciphertext: new Uint8Array(ciphertextBuffer) };
+}
+
+/**
+ * Decrypts and authenticates an AEAD payload. Throws OperationError if tampered.
+ * @param {CryptoKey} key
+ * @param {Uint8Array} iv
+ * @param {Uint8Array} ciphertext
+ * @param {Uint8Array} [additionalData]
+ */
+export async function decryptMessage(key, iv, ciphertext, additionalData = new Uint8Array(0)) {
+  const plaintextBuffer = await crypto.subtle.decrypt(
+    {
+      name: key.algorithm.name,
+      iv,
+      additionalData,
+    },
+    key,
+    ciphertext,
+  );
+
+  return textDecoder.decode(plaintextBuffer);
+}
+
+// --- DOM Wiring ---
+function initDeliveryNotesUI() {
+  const form = document.getElementById('delivery-notes-form');
+  if (!form) return;
+
+  const orderInput = document.getElementById('order-reference');
+  const orderError = document.getElementById('order-reference-error');
+  const noteInput = document.getElementById('delivery-note');
+  const noteError = document.getElementById('delivery-note-error');
+  const submitBtn = document.getElementById('encrypt-submit-btn');
+  const rotateBtn = document.getElementById('rotate-keys-btn');
+  const decryptBtn = document.getElementById('decrypt-verify-btn');
+  const tamperBtn = document.getElementById('tamper-test-btn');
+
+  const suiteBadge = document.getElementById('active-suite-badge');
+  const pubKeyFormatLabel = document.getElementById('pub-key-format-label');
+  const pubKeyDisplay = document.getElementById('recipient-public-key-display');
+  const capsuleSizeLabel = document.getElementById('capsule-size-label');
+  const capsuleDisplay = document.getElementById('envelope-capsule-display');
+  const ivDisplay = document.getElementById('envelope-iv-display');
+  const ciphertextAlgLabel = document.getElementById('ciphertext-alg-label');
+  const ciphertextDisplay = document.getElementById('envelope-ciphertext-display');
+  const statusBanner = document.getElementById('encryption-status');
+  const decryptedBox = document.getElementById('decrypted-output-box');
+  const decryptedTitle = document.getElementById('decrypted-output-title');
+  const decryptedText = document.getElementById('decrypted-output-text');
+
+  let currentRecipient = null;
