+
+  function setStatus(message, isError = false) {
+    statusBanner.textContent = message;
+    statusBanner.dataset.state = isError ? 'error' : 'ok';
+    statusBanner.hidden = false;
+  }
+
+  function validateField(input, errorEl, customMessage) {
+    input.setCustomValidity('');
+    if (!input.checkValidity()) {
+      input.setCustomValidity(customMessage);
+      input.setAttribute('aria-invalid', 'true');
+      errorEl.textContent = customMessage;
+      errorEl.hidden = false;
+      return false;
+    }
+    input.removeAttribute('aria-invalid');
+    errorEl.textContent = '';
+    errorEl.hidden = true;
+    return true;
+  }
+
+  function clearFieldError(input, errorEl) {
+    input.setCustomValidity('');
+    if (input.checkValidity()) {
+      input.removeAttribute('aria-invalid');
+      errorEl.textContent = '';
+      errorEl.hidden = true;
+    }
+  }
+
+  orderInput.addEventListener('blur', () => {
+    if (orderInput.value.trim() !== '') {
+      validateField(
+        orderInput,
+        orderError,
+        'Please enter an order reference between 3 and 40 characters.',
+      );
+    }
+  });
+  orderInput.addEventListener('input', () => clearFieldError(orderInput, orderError));
+
+  noteInput.addEventListener('blur', () => {
+    if (noteInput.value.trim() !== '') {
+      validateField(
+        noteInput,
+        noteError,
+        'Please enter delivery instructions (at least 4 characters).',
+      );
+    }
+  });
+  noteInput.addEventListener('input', () => clearFieldError(noteInput, noteError));
+
+  async function setupKeys(forceRotate = false) {
+    try {
+      currentRecipient = await generateRecipientKeys({ forceRotate });
+      suiteBadge.textContent = `Suite: ${currentRecipient.suite}`;
+      pubKeyFormatLabel.textContent = `${currentRecipient.keyFormat} • ${currentRecipient.publicKeyBytes.byteLength} bytes`;
+      pubKeyDisplay.textContent = bytesToBase64(currentRecipient.publicKeyBytes);
+    } catch (err) {
+      suiteBadge.textContent = 'WebCrypto Key Error';
+      setStatus(`Failed to initialize recipient keys: ${err.message}`, true);
+    }
+  }
+
+  async function encryptCurrentNote() {
+    if (!currentRecipient) {
+      await setupKeys(false);
+    }
+    if (!currentRecipient) return;
+
+    const orderRef = orderInput.value.trim();
+    const plaintextNote = noteInput.value.trim();
+    const aadBytes = textEncoder.encode(`order:${orderRef}`);
+    const infoBytes = textEncoder.encode('daily-grind-delivery-note-v1');
+
+    // Sender imports the recipient's exported public key bytes and encapsulates a shared key
+    const { sharedKey, capsuleBytes } = await encapsulateEnvelopeKey(
+      currentRecipient.publicKeyBytes,
+      infoBytes,
+    );
+
+    const { iv, ciphertext } = await encryptMessage(sharedKey, plaintextNote, aadBytes);
+
+    lastEnvelope = {
+      capsuleBytes,
+      iv,
+      ciphertext,
+      aadBytes,
+      infoBytes,
+      orderRef,
+      algName: sharedKey.algorithm.name,
+    };
+
+    capsuleSizeLabel.textContent = `${capsuleBytes.byteLength} bytes`;
+    capsuleDisplay.textContent = bytesToBase64(capsuleBytes);
+    ivDisplay.textContent = `IV (${iv.byteLength}B): ${bytesToBase64(iv)} | AAD: "order:${orderRef}"`;
+    ciphertextAlgLabel.textContent = `${sharedKey.algorithm.name} • ${ciphertext.byteLength} bytes`;
+    ciphertextDisplay.textContent = bytesToBase64(ciphertext);
+
+    decryptBtn.disabled = false;
+    tamperBtn.disabled = false;
+    decryptedBox.hidden = true;
+
+    setStatus(
+      `Encrypted delivery note for ${orderRef} with ${currentRecipient.suite} (${capsuleBytes.byteLength}-byte capsule, 12-byte IV).`,
+      false,
+    );
+  }
+
+  form.addEventListener('submit', async (event) => {
+    event.preventDefault();
+    const orderValid = validateField(
+      orderInput,
+      orderError,
+      'Please enter an order reference between 3 and 40 characters.',
+    );
+    const noteValid = validateField(
+      noteInput,
+      noteError,
+      'Please enter delivery instructions (at least 4 characters).',
+    );
+
+    if (!orderValid) {
+      orderInput.focus();
+      return;
+    }
+    if (!noteValid) {
+      noteInput.focus();
+      return;
+    }
+
+    submitBtn.disabled = true;
+    try {
+      await encryptCurrentNote();
+    } catch (err) {
+      setStatus(`Encryption failed: ${err.message}`, true);
+    } finally {
+      submitBtn.disabled = false;
+    }
+  });
+
+  rotateBtn.addEventListener('click', async () => {
+    rotateBtn.disabled = true;
+    try {
+      await setupKeys(true);
+      await encryptCurrentNote();
+    } finally {
+      rotateBtn.disabled = false;
+    }
+  });
+
+  decryptBtn.addEventListener('click', async () => {
+    if (!lastEnvelope || !currentRecipient) return;
+    try {
+      const recipientKey = await decapsulateEnvelopeKey(
+        currentRecipient.keyPair.privateKey,
+        lastEnvelope.capsuleBytes,
+        lastEnvelope.infoBytes,
+      );
+      const recoveredText = await decryptMessage(
+        recipientKey,
+        lastEnvelope.iv,
+        lastEnvelope.ciphertext,
+        lastEnvelope.aadBytes,
+      );
+      decryptedTitle.textContent = `Decapsulated & Authenticated Plaintext (${lastEnvelope.algName}):`;
+      decryptedText.textContent = recoveredText;
+      decryptedBox.hidden = false;
+      setStatus(
+        `Decapsulated shared secret and verified AEAD authentication tag for ${lastEnvelope.orderRef}.`,
+        false,
+      );
+    } catch (err) {
+      decryptedBox.hidden = true;
+      setStatus(`Decryption rejected (${err.name}): authentication tag or AAD mismatch.`, true);
+    }
+  });
+
+  tamperBtn.addEventListener('click', async () => {
+    if (!lastEnvelope || !currentRecipient) return;
+    try {
+      const recipientKey = await decapsulateEnvelopeKey(
+        currentRecipient.keyPair.privateKey,
+        lastEnvelope.capsuleBytes,
+        lastEnvelope.infoBytes,
+      );
+      const tamperedAad = textEncoder.encode(`order:${lastEnvelope.orderRef}-TAMPERED`);
+      await decryptMessage(
+        recipientKey,
+        lastEnvelope.iv,
+        lastEnvelope.ciphertext,
+        tamperedAad,
+      );
+    } catch (err) {
+      decryptedBox.hidden = true;
+      setStatus(
+        `AEAD Integrity Verified: Tampered AAD rejected by crypto.subtle.decrypt() with ${err.name || 'OperationError'}.`,
+        true,
+      );
+    }
+  });
+
+  // Initialize keys and seal the default sample note on load
+  setupKeys(false).then(() => encryptCurrentNote());
+}
+
+if (typeof document !== 'undefined') {
+  if (document.readyState === 'loading') {
+    document.addEventListener('DOMContentLoaded', initDeliveryNotesUI);
+  } else {
+    initDeliveryNotesUI();
+  }
+}
