+          envelope.rsaCiphertext
+        );
+        return new Uint8Array(decapsulatedBuf);
+      }
+
+      // --- Encrypt & Authenticate Delivery Note (AES-GCM with AAD) ---
+      async function encryptDeliveryNote() {
+        if (!courierKeyRing) {
+          await generateCourierKeyRing();
+        }
+
+        const mode = document.getElementById('kem-mode').value;
+        const cipherSuite = document.getElementById('aead-cipher').value;
+        const orderRef = document.getElementById('order-reference').value.trim() || 'ORD-DEFAULT';
+        const accessCode = document.getElementById('access-code').value.trim();
+        const noteText = document.getElementById('delivery-note-input').value.trim();
+
+        if (!noteText) return;
+
+        const keyLengthBits = cipherSuite === 'AES-128-GCM' ? 128 : 256;
+        const encapResult = await encapsulateSharedSecret(mode, courierKeyRing);
+
+        const hkdfSalt = crypto.getRandomValues(new Uint8Array(16));
+        const hkdfInfo = `daily-grind-delivery-notes:v1:${mode}:${cipherSuite}`;
+        const { aeadKey, secretFingerprintHex } = await deriveAeadKeyFromSecret(
+          encapResult.combinedSecret,
+          hkdfSalt,
+          hkdfInfo,
+          keyLengthBits
+        );
+
+        const iv = crypto.getRandomValues(new Uint8Array(12)); // 96-bit NIST recommended GCM nonce
+        const timestamp = new Date().toISOString();
+        const aadObject = {
+          orderRef,
+          mode,
+          cipher: cipherSuite,
+          keyGen: courierKeyRing.generation
+        };
+        const aadBytes = textEncoder.encode(JSON.stringify(aadObject));
+
+        const payloadObject = {
+          orderReference: orderRef,
+          accessCode: accessCode || 'None',
+          instructions: noteText,
+          createdAt: timestamp
+        };
+        const plaintextBytes = textEncoder.encode(JSON.stringify(payloadObject));
+
+        const encryptedBuf = await crypto.subtle.encrypt(
+          {
+            name: 'AES-GCM',
+            iv,
+            additionalData: aadBytes,
+            tagLength: 128
+          },
+          aeadKey,
+          plaintextBytes
+        );
+
+        const encryptedBytes = new Uint8Array(encryptedBuf);
+        const ciphertextBody = encryptedBytes.slice(0, encryptedBytes.length - 16);
+        const authTag = encryptedBytes.slice(encryptedBytes.length - 16);
+
+        activeEnvelope = {
+          id: 'ENV-' + Math.random().toString(36).substring(2, 8).toUpperCase(),
+          mode,
+          cipherSuite,
+          keyLengthBits,
+          orderRef,
+          hkdfSalt,
+          hkdfInfo,
+          iv,
+          aadBytes,
+          aadObject,
+          encryptedBytes: new Uint8Array(encryptedBytes),
+          ciphertextHex: bytesToHex(ciphertextBody),
+          authTagHex: bytesToHex(authTag),
+          secretFingerprintHex,
+          ephemeralPubRaw: encapResult.ephemeralPubRaw,
+          pqEncap: encapResult.pqEncap,
+          rsaCiphertext: encapResult.rsaCiphertext,
+          encapsulatedDisplay: encapResult.encapsulatedDisplay,
+          keyRingSnapshot: courierKeyRing,
+          tampered: false
+        };
+
+        savedEnvelopes.unshift(activeEnvelope);
+        renderEnvelopeUI(activeEnvelope);
+        renderSavedNotesList();
+      }
+
+      function renderEnvelopeUI(env) {
+        updateRecipientKeyDisplay();
+        const statusPill = document.getElementById('crypto-status-pill');
+        statusPill.textContent = env.tampered ? 'Tampered Ciphertext' : 'Encrypted & Authenticated';
+        statusPill.style.background = env.tampered ? '#ffebee' : '#e8f5e9';
+        statusPill.style.color = env.tampered ? '#b71c1c' : '#2e7d32';
+
+        document.getElementById('encapsulated-key-box').textContent = env.encapsulatedDisplay;
+        document.getElementById('kdf-label').textContent = `HKDF-SHA-256 (Salt: ${bytesToHex(env.hkdfSalt).slice(0, 12)}...)`;
+        document.getElementById('shared-secret-box').textContent = `Derived Secret ID: ${env.secretFingerprintHex}`;
+        document.getElementById('iv-aad-label').textContent = `IV: ${bytesToHex(env.iv)} | Tag: 128-bit`;
+        document.getElementById('ciphertext-box').textContent =
+          `CT (B64): ${bytesToBase64(env.encryptedBytes)} | GCM-Tag: ${env.authTagHex}`;
+
+        const previewBox = document.getElementById('decrypted-preview-box');
+        previewBox.style.display = 'none';
+      }
+
+      async function verifyAndDecryptActiveEnvelope() {
+        const previewBox = document.getElementById('decrypted-preview-box');
+        if (!activeEnvelope) {
+          await encryptDeliveryNote();
+        }
+        try {
+          const decapsulatedSecret = await decapsulateSharedSecret(activeEnvelope);
+          const { aeadKey, secretFingerprintHex } = await deriveAeadKeyFromSecret(
+            decapsulatedSecret,
+            activeEnvelope.hkdfSalt,
+            activeEnvelope.hkdfInfo,
+            activeEnvelope.keyLengthBits
+          );
+
+          const decryptedBuf = await crypto.subtle.decrypt(
+            {
+              name: 'AES-GCM',
+              iv: activeEnvelope.iv,
+              additionalData: activeEnvelope.aadBytes,
+              tagLength: 128
+            },
+            aeadKey,
+            activeEnvelope.encryptedBytes
+          );
+
+          const parsed = JSON.parse(textDecoder.decode(new Uint8Array(decryptedBuf)));
+          previewBox.className = 'decrypted-preview';
+          previewBox.style.display = 'block';
+          previewBox.innerHTML =
+            `<strong>&#9989; Courier Decapsulation &amp; AEAD Tag Verified</strong><br>` +
+            `<span><strong>Order:</strong> ${escapeHtml(parsed.orderReference)} | <strong>PIN:</strong> ${escapeHtml(parsed.accessCode)}</span><br>` +
+            `<span><strong>Note:</strong> ${escapeHtml(parsed.instructions)}</span><br>` +
+            `<small>Shared Secret Match: ${secretFingerprintHex.slice(0, 24)}...</small>`;
+        } catch (err) {
+          previewBox.className = 'decrypted-preview error';
+          previewBox.style.display = 'block';
+          previewBox.innerHTML =
+            `<strong>&#10060; AEAD Authentication Failed (GCM Tag Mismatch)</strong><br>` +
+            `<span>Ciphertext or Associated Data (AAD) integrity check rejected modified payload. Sensitive delivery note was not exposed.</span>`;
+        }
+      }
+
+      function escapeHtml(str) {
+        return String(str)
+          .replace(/&/g, '&amp;')
+          .replace(/</g, '&lt;')
+          .replace(/>/g, '&gt;')
+          .replace(/"/g, '&quot;')
+          .replace(/'/g, '&#039;');
+      }
+
+      function renderSavedNotesList() {
+        const countEl = document.getElementById('saved-notes-count');
+        const listEl = document.getElementById('saved-notes-items');
+        countEl.textContent = String(savedEnvelopes.length);
+        listEl.innerHTML = '';
+
+        savedEnvelopes.slice(0, 4).forEach((env) => {
+          const item = document.createElement('div');
+          item.className = 'saved-note-item';
+          item.innerHTML = `
+            <div>
+              <strong>${escapeHtml(env.orderRef)}</strong>
+              <span style="color:#6d4c41; margin-left:6px;">[${escapeHtml(env.mode)} / ${escapeHtml(env.cipherSuite)}]</span><br>
+              <code style="font-size:0.75rem; color:#4e342e;">Tag: ${env.authTagHex.slice(0, 20)}...</code>
+            </div>
+            <button type="button" class="preset-tag" data-env-id="${env.id}">Inspect &amp; Decrypt</button>
+          `;
+          item.querySelector('button').addEventListener('click', async () => {
+            activeEnvelope = env;
+            renderEnvelopeUI(env);
+            await verifyAndDecryptActiveEnvelope();
+          });
+          listEl.appendChild(item);
+        });
+      }
+
+      // --- Event Listeners & Initial Setup ---
+      document.getElementById('encrypted-notes-form').addEventListener('submit', async (e) => {
+        e.preventDefault();
+        await encryptDeliveryNote();
+      });
+
+      document.getElementById('kem-mode').addEventListener('change', () => {
+        updateRecipientKeyDisplay();
+      });
+
+      document.getElementById('aead-cipher').addEventListener('change', () => {
+        updateRecipientKeyDisplay();
+      });
+
+      document.getElementById('rotate-keys-btn').addEventListener('click', async () => {
+        keyRotationCount += 1;
+        await generateCourierKeyRing();
+        await encryptDeliveryNote();
+      });
+
+      document.getElementById('verify-decrypt-btn').addEventListener('click', async () => {
+        await verifyAndDecryptActiveEnvelope();
+      });
+
+      document.getElementById('tamper-test-btn').addEventListener('click', async () => {
+        if (!activeEnvelope) {
+          await encryptDeliveryNote();
+        }
+        // Flip a bit in the encrypted payload to demonstrate AEAD authentication protection
+        activeEnvelope.encryptedBytes[0] ^= 0x01;
+        activeEnvelope.tampered = !activeEnvelope.tampered;
+        renderEnvelopeUI(activeEnvelope);
+        await verifyAndDecryptActiveEnvelope();
+      });
+
+      document.querySelectorAll('.preset-tag[data-preset]').forEach((btn) => {
+        btn.addEventListener('click', () => {
+          document.getElementById('delivery-note-input').value = btn.getAttribute('data-preset');
+        });
+      });
+
+      // Expose crypto API on window for programmatic inspection/testing if needed
+      window.DailyGrindCrypto = {
+        generateCourierKeyRing,
+        encapsulateSharedSecret,
+        decapsulateSharedSecret,
+        encryptDeliveryNote,
+        verifyAndDecryptActiveEnvelope,
+        getActiveEnvelope: () => activeEnvelope
+      };
+
+      // Initialize default hybrid keypair and encrypt initial sample note on page load
+      generateCourierKeyRing().then(() => encryptDeliveryNote());
+    })();
+  </script>
 </body>

 </html>

