@@ -0,0 +1,85 @@
+(function initTransitionSetup() {
+  const root = document.documentElement;
+  if (!root.dataset.theme) {
+    root.dataset.theme = localStorage.getItem('theme') || 'light';
+  }
+  if (!root.dataset.layout) {
+    root.dataset.layout = localStorage.getItem('layout') || 'grid';
+  }
+
+  const ROUTE_ORDER = [
+    '/',
+    '/menu',
+    '/menu/seasonal',
+    '/menu/espresso',
+    '/menu/cold-brew',
+    '/locations',
+    '/rewards',
+    '/account',
+    '/order-online',
+    '/about',
+    '/careers',
+    '/contact',
+    '/privacy-policy',
+    '/logout',
+  ];
+
+  function normalizePath(pathname) {
+    if (!pathname || pathname === '/index.html') return '/';
+    return pathname.replace(/\/index\.html$/, '').replace(/\.html$/, '').replace(/\/$/, '') || '/';
+  }
+
+  function resolveDrinkSlug(pathname) {
+    const clean = normalizePath(pathname);
+    if (clean.startsWith('/menu/')) {
+      return clean.slice('/menu/'.length);
+    }
+    return null;
+  }
+
+  if ('onpagereveal' in window) {
+    window.addEventListener('pagereveal', async (event) => {
+      if (!event.viewTransition) return;
+
+      const fromEntry = window.navigation?.activation?.from;
+      const toEntry = window.navigation?.activation?.entry;
+      if (!fromEntry) return;
