+  <script>
+    (function () {
+      const probe = document.createElement('div');
+      probe.style.display = 'none';
+
+      function getLuminance(r, g, b) {
+        const a = [r, g, b].map((v) => {
+          v /= 255;
+          return v <= 0.04045 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4);
+        });
+        return a[0] * 0.2126 + a[1] * 0.7152 + a[2] * 0.0722;
+      }
+
+      function parseRgb(colorStr) {
+        if (!colorStr) return null;
+        if (!probe.parentNode && document.body) {
+          document.body.appendChild(probe);
+        }
+        probe.style.backgroundColor = '';
+        probe.style.backgroundColor = colorStr;
+        const computed = getComputedStyle(probe).backgroundColor;
+        const match = computed.match(/rgba?\(\s*([\d.]+)[,\s]+([\d.]+)[,\s]+([\d.]+)/);
+        if (match) {
+          return [parseFloat(match[1]), parseFloat(match[2]), parseFloat(match[3])];
+        }
+        return null;
+      }
+
+      function getHighContrastColor(bgColorStr) {
+        const rgb = parseRgb(bgColorStr);
+        if (!rgb) return null;
+        const lum = getLuminance(rgb[0], rgb[1], rgb[2]);
+        // Compare WCAG contrast ratio against white (L=1) vs black (L=0)
+        // (1 + 0.05) / (lum + 0.05) vs (lum + 0.05) / (0 + 0.05) -> threshold at lum ~ 0.179
+        const contrastWhite = 1.05 / (lum + 0.05);
+        const contrastBlack = (lum + 0.05) / 0.05;
+        return contrastWhite >= contrastBlack ? '#ffffff' : '#000000';
+      }
+
+      let lastPrimary = '';
+      let lastSecondary = '';
+
+      function updateContrastColors() {
+        const rootStyles = getComputedStyle(document.documentElement);
+        const primary = rootStyles.getPropertyValue('--primary').trim();
+        const secondary = rootStyles.getPropertyValue('--secondary').trim();
+
+        const nav = document.querySelector('nav');
+        const btn = document.querySelector('.btn');
+        const footer = document.querySelector('footer');
+
+        const navBg = nav ? getComputedStyle(nav).backgroundColor : primary;
+        const btnBg = btn ? getComputedStyle(btn).backgroundColor : primary;
+        const footerBg = footer ? getComputedStyle(footer).backgroundColor : secondary;
+
+        const key = `${primary}|${secondary}|${navBg}|${btnBg}|${footerBg}`;
+        if (key === `${lastPrimary}|${lastSecondary}`) return;
+        lastPrimary = `${primary}|${secondary}`;
+        lastSecondary = `${navBg}|${btnBg}|${footerBg}`;
+
+        const primaryContrast = getHighContrastColor(navBg || primary);
+        const btnContrast = getHighContrastColor(btnBg || primary);
+        const secondaryContrast = getHighContrastColor(footerBg || secondary);
+
+        if (primaryContrast) {
+          document.documentElement.style.setProperty('--primary-contrast', primaryContrast);
+        }
+
+        if (btnContrast && btnContrast !== primaryContrast) {
+          document.querySelectorAll('.btn').forEach((el) => {
+            el.style.color = btnContrast;
+          });
+        } else {
+          document.querySelectorAll('.btn').forEach((el) => {
+            el.style.removeProperty('color');
+          });
+        }
+
+        if (secondaryContrast) {
+          document.documentElement.style.setProperty('--secondary-contrast', secondaryContrast);
+        }
+      }
+
+      if (document.readyState === 'loading') {
+        document.addEventListener('DOMContentLoaded', updateContrastColors);
+      } else {
+        updateContrastColors();
+      }
+
+      const observer = new MutationObserver(updateContrastColors);
+      observer.observe(document.documentElement, {
+        attributes: true,
+        childList: true,
+        subtree: true,
+        characterData: true
+      });
+
+      setInterval(updateContrastColors, 100);
