+        const wallAsUTC = Date.UTC(year, month - 1, day, hour, minute, 0, 0);
+
+        // Probe offsets around the target wall time (-6h, -2h, 0h, +2h, +6h) to capture both sides of any DST transition
+        const probeDeltas = [-6 * 3600000, -2 * 3600000, 0, 2 * 3600000, 6 * 3600000];
+        const candidateOffsets = new Set();
+
+        for (const delta of probeDeltas) {
+          const approxOffset = getOffsetMsAtInstant(wallAsUTC + delta, hostTz);
+          candidateOffsets.add(approxOffset);
+          const refinedOffset = getOffsetMsAtInstant(wallAsUTC - approxOffset + delta, hostTz);
+          candidateOffsets.add(refinedOffset);
+        }
+
+        const matchingInstants = [];
+        for (const offsetMs of candidateOffsets) {
+          const candidateUtc = wallAsUTC - offsetMs;
+          const parts = getZonedParts(candidateUtc, hostTz);
+          if (
+            parts.year === year &&
+            parts.month === month &&
+            parts.day === day &&
+            parts.hour === hour &&
+            parts.minute === minute
+          ) {
+            matchingInstants.push(candidateUtc);
+          }
+        }
+
+        if (matchingInstants.length === 0) {
+          return {
+            valid: false,
+            reason: 'dst-gap',
+            message: `Invalid time: ${timeStr.slice(0, 5)} on ${dateStr} does not exist in ${hostTz} due to a Daylight Saving Time (DST) spring-forward transition.`
+          };
+        }
+
+        // If ambiguous (fall-back overlap), pick the earliest (first occurrence)
+        matchingInstants.sort((a, b) => a - b);
+        return {
+          valid: true,
+          utcMs: matchingInstants[0],
+          year,
+          month,
+          day,
+          hour,
+          minute
+        };
+      }
+
+      /**
+       * Format UTC offset (ms) into "UTC+H" or "UTC+HH:MM"
+       */
+      function formatUtcOffset(offsetMs) {
+        const totalMinutes = Math.round(offsetMs / 60000);
+        if (totalMinutes === 0) return 'UTC+0';
+        const sign = totalMinutes > 0 ? '+' : '-';
+        const absMin = Math.abs(totalMinutes);
+        const h = Math.floor(absMin / 60);
+        const m = absMin % 60;
+        return m === 0 ? `UTC${sign}${h}` : `UTC${sign}${h}:${String(m).padStart(2, '0')}`;
+      }
+
+      /**
+       * Determine DST status in a timezone at a given UTC timestamp.
+       */
+      function getDstInfo(utcMs, timeZone, year) {
+        const janUtc = Date.UTC(year, 0, 1, 12, 0, 0);
+        const julUtc = Date.UTC(year, 6, 1, 12, 0, 0);
+        const offsetJan = getOffsetMsAtInstant(janUtc, timeZone);
+        const offsetJul = getOffsetMsAtInstant(julUtc, timeZone);
+        const offsetNow = getOffsetMsAtInstant(utcMs, timeZone);
+
+        const observesDst = offsetJan !== offsetJul;
+        const standardOffset = Math.min(offsetJan, offsetJul);
+        const isDstActive = observesDst && offsetNow > standardOffset;
