+        let tzAbbrev = '';
+        try {
+          const shortParts = new Intl.DateTimeFormat('en-US', {
+            timeZone,
+            timeZoneName: 'short'
+          }).formatToParts(new Date(utcMs));
+          const tzPart = shortParts.find(p => p.type === 'timeZoneName');
+          if (tzPart) tzAbbrev = tzPart.value;
+        } catch (_) {
+          tzAbbrev = '';
+        }
+
+        return {
+          offsetMs: offsetNow,
+          offsetLabel: formatUtcOffset(offsetNow),
+          observesDst,
+          isDstActive,
+          tzAbbrev
+        };
+      }
+
+      /**
+       * Format a UTC instant in a target timezone for card rendering.
+       */
+      function formatTargetZone(utcMs, timeZone, hostDateParts) {
+        const parts = getZonedParts(utcMs, timeZone);
+        const pad2 = n => String(n).padStart(2, '0');
+
+        const time24 = `${pad2(parts.hour)}:${pad2(parts.minute)}`;
+        const period = parts.hour >= 12 ? 'PM' : 'AM';
+        const hour12 = parts.hour % 12 === 0 ? 12 : parts.hour % 12;
+        const time12 = `${hour12}:${pad2(parts.minute)} ${period}`;
+        const isoDate = `${parts.year}-${pad2(parts.month)}-${pad2(parts.day)}`;
