+          dayDiffLabel,
+          dstInfo
+        };
+      }
+
+      function renderCoordinator() {
+        const dateVal = dateInput.value;
+        const timeVal = timeInput.value;
+        const hostTz = hostTzSelect.value;
+
+        // Reset custom validity before checking
+        timeInput.setCustomValidity('');
+        timeInput.classList.remove('input-invalid');
+        timeInput.removeAttribute('aria-invalid');
+
+        const resolved = resolveHostDateTime(dateVal, timeVal, hostTz);
+
+        if (!resolved.valid) {
+          timeInput.setCustomValidity(resolved.message);
+          timeInput.classList.add('input-invalid');
+          timeInput.setAttribute('aria-invalid', 'true');
