+          errorBanner.innerHTML = `<strong>Invalid Daylight Saving Time / Schedule Input</strong><span>${resolved.message}</span>`;
+          errorBanner.classList.add('visible');
+
+          hostSummary.innerHTML = `<span><strong>Status:</strong> Schedule rejected — invalid wall-clock time in <code>${hostTz}</code>.</span>`;
+
+          grid.innerHTML = `
+            <div class="grid-error-card" role="alert">
+              <h3>Invalid Time Rejected</h3>
+              <p>${resolved.message}</p>
+            </div>
+          `;
