+        errorBanner.innerHTML = '';
+        errorBanner.classList.remove('visible');
+
+        const hostFormatted = formatTargetZone(resolved.utcMs, hostTz, resolved);
+        const hostDstText = hostFormatted.dstInfo.isDstActive
+          ? 'DST Active'
+          : (hostFormatted.dstInfo.observesDst ? 'Standard Time' : 'No DST Observed');
+
+        hostSummary.innerHTML = `
+          <div>
+            <strong>Host Session:</strong> ${hostFormatted.readableDate} (${hostFormatted.isoDate}) at
+            <strong>${hostFormatted.time24}</strong> (${hostFormatted.time12}) —
+            <code>${hostTz}</code> (${hostFormatted.dstInfo.offsetLabel}${hostFormatted.dstInfo.tzAbbrev ? ' · ' + hostFormatted.dstInfo.tzAbbrev : ''})
+          </div>
+          <div>
+            <span class="badge ${hostFormatted.dstInfo.isDstActive ? 'badge-dst' : 'badge-std'}">${hostDstText}</span>
+          </div>
+        `;
+
+        // Ensure target zones always include the core global hubs (including Tokyo)
+        // and if hostTz is not in TARGET_TIMEZONES, also include hostTz card so the user sees it alongside the hubs.
+        const zonesToRender = [...TARGET_TIMEZONES];
+        if (!zonesToRender.some(z => z.id === hostTz)) {
+          const cityPart = hostTz.split('/').pop().replace(/_/g, ' ');
