+            city: cityPart,
+            country: 'Host Timezone',
+            tastingNote: 'Selected Host Tasting Hub'
+          });
+        }
+
+        grid.innerHTML = zonesToRender
+          .map(zone => {
+            const info = formatTargetZone(resolved.utcMs, zone.id, resolved);
+            const isHost = zone.id === hostTz;
+            const dstBadgeText = info.dstInfo.isDstActive
+              ? 'DST Active'
+              : (info.dstInfo.observesDst ? 'Standard Time' : 'Standard Time (No DST)');
+
+            return `
+              <div class="card${isHost ? ' is-host' : ''}" data-tz="${zone.id}" data-city="${zone.city}">
+                <div>
+                  <div class="card-top">
+                    <div>
+                      <h3>${zone.city}, ${zone.country}</h3>
+                      <div class="tz-id">${zone.id}</div>
+                    </div>
+                    <div class="badges">
+                      ${isHost ? '<span class="badge badge-host">Host Zone</span>' : ''}
+                      <span class="badge ${info.dstInfo.isDstActive ? 'badge-dst' : 'badge-std'}">${dstBadgeText}</span>
+                    </div>
+                  </div>
+
+                  <div class="time-block">
+                    <div class="time-primary" data-time-24="${info.time24}">${info.time24}</div>
+                    <div class="time-secondary" data-time-12="${info.time12}">${info.time12}</div>
+                  </div>
+
+                  <div class="date-line">
+                    <span>${info.readableDate} (${info.isoDate})</span>
+                    <span class="day-diff">${info.dayDiffLabel}</span>
+                  </div>
+                </div>
+
+                <div class="card-meta">
+                  <span>${info.dstInfo.offsetLabel}${info.dstInfo.tzAbbrev ? ' (' + info.dstInfo.tzAbbrev + ')' : ''}</span>
+                  <span>${zone.tastingNote}</span>
+                </div>
+              </div>
+            `;
+          })
+          .join('');
+      }
+
+      ['input', 'change'].forEach(evt => {
+        dateInput.addEventListener(evt, renderCoordinator);
+        timeInput.addEventListener(evt, renderCoordinator);
+        hostTzSelect.addEventListener(evt, renderCoordinator);
+      });
+
+      renderCoordinator();
+    })();
+  </script>
 </body>

 </html>

