+const canvas = document.getElementById('render-canvas');
+const ctx = canvas.getContext('2d');
+const randomizeBtn = document.getElementById('randomize-btn');
+const resetBtn = document.getElementById('reset-btn');
+const samplesSelect = document.getElementById('samples-select');
+const resolutionSelect = document.getElementById('resolution-select');
+const statusBadge = document.getElementById('status-badge');
+const progressBar = document.getElementById('render-progress');
+const statsSpp = document.getElementById('stats-spp');
+const statsResolution = document.getElementById('stats-resolution');
+const statsElapsed = document.getElementById('stats-elapsed');
+const statsSeed = document.getElementById('stats-seed');
+const paletteList = document.getElementById('palette-list');
+
+const worker = new Worker(new URL('./worker.js', import.meta.url), {
+  type: 'module',
+});
+
+let currentJobId = 0;
+let currentSeed = 1;
+
+function nextRandomSeed() {
+  const buf = new Uint32Array(1);
+  crypto.getRandomValues(buf);
+  return buf[0] || Date.now() >>> 0;
+}
+
+function getResolution() {
+  const [w, h] = resolutionSelect.value.split('x').map(Number);
+  return { width: w || 320, height: h || 240 };
+}
+
+function getTargetSamplesPerSubpixel() {
+  const totalSpp = Number(samplesSelect.value) || 32;
+  return Math.max(1, Math.round(totalSpp / 4));
+}
+
+function renderPalette(palette) {
+  const items = palette.map((entry) => {
+    const li = document.createElement('li');
+    li.className = 'swatch-item';
+
+    const chip = document.createElement('span');
+    chip.className = 'swatch-chip';
+    chip.style.setProperty(
+      '--swatch-color',
+      `rgb(${entry.r} ${entry.g} ${entry.b})`,
+    );
+    chip.setAttribute('aria-hidden', 'true');
+
+    const meta = document.createElement('div');
+    meta.className = 'swatch-meta';
+
+    const nameEl = document.createElement('span');
+    nameEl.className = 'swatch-name';
+    nameEl.textContent = entry.name;
+
+    const hex = [entry.r, entry.g, entry.b]
+      .map((v) => v.toString(16).padStart(2, '0'))
+      .join('')
+      .toUpperCase();
+    const codeEl = document.createElement('code');
+    codeEl.className = 'swatch-hex';
+    codeEl.textContent = `#${hex}`;
+
+    meta.append(nameEl, codeEl);
+    li.append(chip, meta);
+    return li;
+  });
+
+  paletteList.replaceChildren(...items);
+}
+
+function startRender({ randomize = false, reset = false } = {}) {
+  currentJobId += 1;
+  if (randomize) {
+    currentSeed = nextRandomSeed();
+  } else if (reset) {
+    currentSeed = 1;
+  }
+
+  const { width, height } = getResolution();
+  const targetSamplesPerSubpixel = getTargetSamplesPerSubpixel();
+  const targetSpp = targetSamplesPerSubpixel * 4;
+
+  if (canvas.width !== width || canvas.height !== height) {
+    canvas.width = width;
+    canvas.height = height;
+  }
+
+  statusBadge.textContent = 'Rendering in WebAssembly…';
+  statusBadge.dataset.state = 'rendering';
+  progressBar.max = targetSpp;
+  progressBar.value = 0;
+  statsResolution.textContent = `${width} × ${height}`;
+  statsSpp.textContent = `0 / ${targetSpp} spp`;
+  statsSeed.textContent =
+    currentSeed === 1 && !randomize
+      ? 'Classic Cornell Box'
+      : `0x${currentSeed.toString(16).toUpperCase().padStart(8, '0')}`;
+
+  worker.postMessage({
