+
+  if (data.type === 'palette') {
+    renderPalette(data.palette);
+    return;
+  }
+
+  if (data.type === 'error') {
+    statusBadge.textContent = `Error: ${data.message}`;
+    statusBadge.dataset.state = 'error';
+    return;
+  }
+
+  if (data.type === 'frame') {
+    const imageData = new ImageData(data.pixels, data.width, data.height);
+    ctx.putImageData(imageData, 0, 0);
+
+    progressBar.max = data.targetSamplesPerPixel;
+    progressBar.value = data.samplesPerPixel;
+    statsSpp.textContent = `${data.samplesPerPixel} / ${data.targetSamplesPerPixel} spp`;
+    statsElapsed.textContent = `${(data.elapsedMs / 1000).toFixed(2)}s`;
+
+    if (data.done) {
+      statusBadge.textContent = 'Render Complete';
+      statusBadge.dataset.state = 'done';
+    } else {
+      const pct = Math.round(
+        (data.samplesPerPixel / data.targetSamplesPerPixel) * 100,
+      );
+      statusBadge.textContent = `Tracing Paths (${pct}%)…`;
+      statusBadge.dataset.state = 'rendering';
+    }
+  }
+});
+
+randomizeBtn.addEventListener('click', () => {
+  startRender({ randomize: true });
+});
+
+resetBtn.addEventListener('click', () => {
+  startRender({ reset: true });
+});
+
+samplesSelect.addEventListener('change', () => {
+  startRender({ randomize: false, reset: false });
+});
+
+resolutionSelect.addEventListener('change', () => {
+  startRender({ randomize: false, reset: false });
+});
+
+// Trigger initial render on load
+startRender({ reset: true });
