+// smallpt, a Path Tracer by Kevin Beason, 2008
+// Compiled to WebAssembly (Emscripten) for client-side execution with randomized sphere colors.
+
+#include <cmath>
+#include <cstdint>
+#include <cstdlib>
+
+struct Vec {
+  double x, y, z;
+  constexpr Vec(double x_ = 0.0, double y_ = 0.0, double z_ = 0.0)
+      : x(x_), y(y_), z(z_) {}
+  Vec operator+(const Vec& b) const { return Vec(x + b.x, y + b.y, z + b.z); }
+  Vec operator-(const Vec& b) const { return Vec(x - b.x, y - b.y, z - b.z); }
+  Vec operator*(double b) const { return Vec(x * b, y * b, z * b); }
+  Vec mult(const Vec& b) const { return Vec(x * b.x, y * b.y, z * b.z); }
+  Vec& norm() {
+    return *this = *this * (1.0 / std::sqrt(x * x + y * y + z * z));
+  }
+  double dot(const Vec& b) const { return x * b.x + y * b.y + z * b.z; }
+  Vec operator%(const Vec& b) const {
+    return Vec(y * b.z - z * b.y, z * b.x - x * b.z, x * b.y - y * b.x);
+  }
+};
+
+struct Ray {
+  Vec o, d;
+  Ray(const Vec& o_, const Vec& d_) : o(o_), d(d_) {}
+};
+
+enum Refl_t { DIFF, SPEC, REFR };
+
+struct Sphere {
+  double rad;
+  Vec p, e, c;
+  Refl_t refl;
+  Sphere(double rad_, Vec p_, Vec e_, Vec c_, Refl_t refl_)
+      : rad(rad_), p(p_), e(e_), c(c_), refl(refl_) {}
+  double intersect(const Ray& r) const {
+    Vec op = p - r.o;
+    double t;
+    double eps = 1e-4;
+    double b = op.dot(r.d);
+    double det = b * b - op.dot(op) + rad * rad;
+    if (det < 0.0) return 0.0;
+    det = std::sqrt(det);
+    return (t = b - det) > eps ? t : ((t = b + det) > eps ? t : 0.0);
+  }
+};
+
+static Sphere spheres[] = {
+    Sphere(1e5, Vec(1e5 + 1, 40.8, 81.6), Vec(), Vec(.75, .25, .25), DIFF),    // Left
+    Sphere(1e5, Vec(-1e5 + 99, 40.8, 81.6), Vec(), Vec(.25, .25, .75), DIFF),  // Rght
+    Sphere(1e5, Vec(50, 40.8, 1e5), Vec(), Vec(.75, .75, .75), DIFF),          // Back
+    Sphere(1e5, Vec(50, 40.8, -1e5 + 170), Vec(), Vec(), DIFF),                // Frnt
+    Sphere(1e5, Vec(50, 1e5, 81.6), Vec(), Vec(.75, .75, .75), DIFF),          // Botm
+    Sphere(1e5, Vec(50, -1e5 + 81.6, 81.6), Vec(), Vec(.75, .75, .75), DIFF),  // Top
+    Sphere(16.5, Vec(27, 16.5, 47), Vec(), Vec(1, 1, 1) * .999, SPEC),         // Mirr
+    Sphere(16.5, Vec(73, 16.5, 78), Vec(), Vec(1, 1, 1) * .999, REFR),         // Glas
+    Sphere(600, Vec(50, 681.6 - .27, 81.6), Vec(12, 12, 12), Vec(), DIFF)      // Lite
+};
+
+static constexpr int NUM_SPHERES = sizeof(spheres) / sizeof(Sphere);
+
+// Portable 48-bit linear congruential PRNG matching POSIX erand48 semantics
+static inline double next_erand48(uint16_t Xi[3]) {
+  uint64_t x = (static_cast<uint64_t>(Xi[2]) << 32) |
+               (static_cast<uint64_t>(Xi[1]) << 16) |
+               static_cast<uint64_t>(Xi[0]);
+  x = (0x5DEECE66DULL * x + 0xBULL) & ((1ULL << 48) - 1ULL);
+  Xi[0] = static_cast<uint16_t>(x & 0xFFFFU);
+  Xi[1] = static_cast<uint16_t>((x >> 16) & 0xFFFFU);
+  Xi[2] = static_cast<uint16_t>((x >> 32) & 0xFFFFU);
+  return static_cast<double>(x) / static_cast<double>(1ULL << 48);
+}
+
+static inline double clamp(double x) {
+  return x < 0.0 ? 0.0 : (x > 1.0 ? 1.0 : x);
+}
+
+static inline int toInt(double x) {
+  return static_cast<int>(std::pow(clamp(x), 1.0 / 2.2) * 255.0 + 0.5);
+}
+
+static inline bool intersect(const Ray& r, double& t, int& id) {
+  double d;
+  double inf = t = 1e20;
+  for (int i = NUM_SPHERES; i--;) {
+    if ((d = spheres[i].intersect(r)) && d < t) {
+      t = d;
+      id = i;
+    }
+  }
+  return t < inf;
+}
+
+static Vec radiance(const Ray& r, int depth, uint16_t* Xi) {
+  double t;
+  int id = 0;
+  if (!intersect(r, t, id)) return Vec();
+  const Sphere& obj = spheres[id];
+  Vec x = r.o + r.d * t;
+  Vec n = (x - obj.p).norm();
+  Vec nl = n.dot(r.d) < 0.0 ? n : n * -1.0;
+  Vec f = obj.c;
+  double p = (f.x > f.y && f.x > f.z) ? f.x : (f.y > f.z ? f.y : f.z);
+  if (++depth > 5) {
+    if (depth < 64 && next_erand48(Xi) < p) {
+      f = f * (1.0 / p);
+    } else {
+      return obj.e;
+    }
+  }
+  if (obj.refl == DIFF) {
+    double r1 = 2.0 * M_PI * next_erand48(Xi);
+    double r2 = next_erand48(Xi);
+    double r2s = std::sqrt(r2);
+    Vec w = nl;
+    Vec u = ((std::fabs(w.x) > .1 ? Vec(0, 1) : Vec(1)) % w).norm();
+    Vec v = w % u;
+    Vec d = (u * std::cos(r1) * r2s + v * std::sin(r1) * r2s +
+             w * std::sqrt(1.0 - r2))
+                .norm();
+    return obj.e + f.mult(radiance(Ray(x, d), depth, Xi));
+  } else if (obj.refl == SPEC) {
+    return obj.e +
+           f.mult(radiance(Ray(x, r.d - n * 2.0 * n.dot(r.d)), depth, Xi));
+  }
+  Ray reflRay(x, r.d - n * 2.0 * n.dot(r.d));
+  bool into = n.dot(nl) > 0.0;
+  double nc = 1.0;
+  double nt = 1.5;
+  double nnt = into ? nc / nt : nt / nc;
+  double ddn = r.d.dot(nl);
+  double cos2t;
+  if ((cos2t = 1.0 - nnt * nnt * (1.0 - ddn * ddn)) < 0.0) {
+    return obj.e + f.mult(radiance(reflRay, depth, Xi));
+  }
+  Vec tdir =
+      (r.d * nnt - n * ((into ? 1.0 : -1.0) * (ddn * nnt + std::sqrt(cos2t))))
+          .norm();
+  double a = nt - nc;
+  double b = nt + nc;
+  double R0 = (a * a) / (b * b);
+  double c = 1.0 - (into ? -ddn : tdir.dot(n));
+  double Re = R0 + (1.0 - R0) * c * c * c * c * c;
+  double Tr = 1.0 - Re;
+  double P = .25 + .5 * Re;
+  double RP = Re / P;
+  double TP = Tr / (1.0 - P);
+  return obj.e +
+         f.mult(depth > 2
+                    ? (next_erand48(Xi) < P
+                           ? radiance(reflRay, depth, Xi) * RP
+                           : radiance(Ray(x, tdir), depth, Xi) * TP)
+                    : radiance(reflRay, depth, Xi) * Re +
+                          radiance(Ray(x, tdir), depth, Xi) * Tr);
+}
+
+static uint32_t xorshift32(uint32_t& state) {
+  uint32_t x = state ? state : 0x9E3779B9U;
+  x ^= x << 13;
+  x ^= x >> 17;
+  x ^= x << 5;
+  state = x;
+  return x;
+}
+
+static double rand_range(uint32_t& state, double min_val, double max_val) {
+  double t = static_cast<double>(xorshift32(state)) / 4294967295.0;
+  return min_val + t * (max_val - min_val);
+}
+
+// Convert HSV (h in [0,1], s in [0,1], v in [0,1]) to linear RGB for vivid colors
+static Vec hsv_to_rgb(double h, double s, double v) {
+  double i = std::floor(h * 6.0);
+  double f = h * 6.0 - i;
+  double p = v * (1.0 - s);
+  double q = v * (1.0 - f * s);
+  double t = v * (1.0 - (1.0 - f) * s);
+  switch (static_cast<int>(i) % 6) {
+    case 0: return Vec(v, t, p);
+    case 1: return Vec(q, v, p);
+    case 2: return Vec(p, v, t);
+    case 3: return Vec(p, q, v);
+    case 4: return Vec(t, p, v);
+    default: return Vec(v, p, q);
+  }
+}
+
+extern "C" {
+
+void reset_colors() {
+  spheres[0].c = Vec(.75, .25, .25);          // Left wall
+  spheres[1].c = Vec(.25, .25, .75);          // Right wall
+  spheres[2].c = Vec(.75, .75, .75);          // Back wall
+  spheres[3].c = Vec(0.0, 0.0, 0.0);          // Front wall
+  spheres[4].c = Vec(.75, .75, .75);          // Bottom wall
+  spheres[5].c = Vec(.75, .75, .75);          // Top wall
+  spheres[6].c = Vec(1.0, 1.0, 1.0) * .999;   // Mirror sphere
+  spheres[7].c = Vec(1.0, 1.0, 1.0) * .999;   // Glass sphere
+}
+
+void randomize_colors(uint32_t seed) {
+  uint32_t state = seed ? seed : 1337U;
+  // Choose distinct vivid hues for Left and Right walls
+  double base_hue = rand_range(state, 0.0, 1.0);
+  spheres[0].c = hsv_to_rgb(
+      std::fmod(base_hue, 1.0),
+      rand_range(state, 0.65, 0.90),
+      rand_range(state, 0.65, 0.88));
+  spheres[1].c = hsv_to_rgb(
+      std::fmod(base_hue + rand_range(state, 0.30, 0.65), 1.0),
+      rand_range(state, 0.65, 0.90),
+      rand_range(state, 0.65, 0.88));
+  // Back wall and Floor get complementary or pastel-vivid colors
+  spheres[2].c = hsv_to_rgb(
+      rand_range(state, 0.0, 1.0),
+      rand_range(state, 0.25, 0.70),
+      rand_range(state, 0.65, 0.88));
+  spheres[4].c = hsv_to_rgb(
+      rand_range(state, 0.0, 1.0),
+      rand_range(state, 0.25, 0.65),
+      rand_range(state, 0.65, 0.88));
+  // Ceiling stays bright with a gentle tint
+  spheres[5].c = hsv_to_rgb(
+      rand_range(state, 0.0, 1.0),
+      rand_range(state, 0.10, 0.35),
+      rand_range(state, 0.75, 0.92));
+  // Mirror sphere and Glass sphere get distinct reflective/refractive tints
+  spheres[6].c = hsv_to_rgb(
+      rand_range(state, 0.0, 1.0),
+      rand_range(state, 0.45, 0.85),
+      rand_range(state, 0.85, 0.999));
+  spheres[7].c = hsv_to_rgb(
+      rand_range(state, 0.0, 1.0),
+      rand_range(state, 0.45, 0.85),
+      rand_range(state, 0.88, 0.999));
+}
+
+// Writes 7 RGB triples (21 bytes, 0..255 gamma-corrected) for:
+// [Left Wall, Right Wall, Back Wall, Floor, Ceiling, Mirror Sphere, Glass Sphere]
+void get_sphere_colors(uint8_t* out_rgb) {
+  int indices[] = {0, 1, 2, 4, 5, 6, 7};
+  for (int i = 0; i < 7; ++i) {
+    const Vec& c = spheres[indices[i]].c;
+    out_rgb[i * 3 + 0] = static_cast<uint8_t>(toInt(c.x));
+    out_rgb[i * 3 + 1] = static_cast<uint8_t>(toInt(c.y));
+    out_rgb[i * 3 + 2] = static_cast<uint8_t>(toInt(c.z));
+  }
+}
+
+// Renders `samples_per_subpixel` samples per 2x2 subpixel across the full frame.
+// If `subpixel_accum` (width * height * 12 doubles) is non-null, accumulates into it
+// and normalizes by `total_samples_per_subpixel` for progressive refinement.
+void render_samples(
+    uint8_t* out_rgba,
+    double* subpixel_accum,
+    int width,
+    int height,
+    int samples_per_subpixel,
+    int total_samples_per_subpixel,
+    uint32_t pass_seed) {
+  int samps = samples_per_subpixel < 1 ? 1 : samples_per_subpixel;
+  double inv_total_samps = 1.0 / static_cast<double>(
+      total_samples_per_subpixel < 1 ? samps : total_samples_per_subpixel);
+
+  Ray cam(Vec(50, 52, 295.6), Vec(0, -0.042612, -1).norm());
+  Vec cx = Vec(width * .5135 / height);
+  Vec cy = (cx % cam.d).norm() * .5135;
+
+  for (int y = 0; y < height; y++) {
+    uint16_t Xi[3] = {
+        static_cast<uint16_t>((pass_seed * 131U + y * 17U) & 0xFFFFU),
+        static_cast<uint16_t>(((pass_seed >> 16) + y * 257U) & 0xFFFFU),
+        static_cast<uint16_t>(y * y * y + pass_seed * 977U)};
+    for (int x = 0; x < width; x++) {
+      int i = (height - y - 1) * width + x;
+      Vec pixel_radiance(0.0, 0.0, 0.0);
+      for (int sy = 0; sy < 2; sy++) {
+        for (int sx = 0; sx < 2; sx++) {
+          Vec r(0.0, 0.0, 0.0);
+          for (int s = 0; s < samps; s++) {
+            double r1 = 2.0 * next_erand48(Xi);
+            double dx =
+                r1 < 1.0 ? std::sqrt(r1) - 1.0 : 1.0 - std::sqrt(2.0 - r1);
+            double r2 = 2.0 * next_erand48(Xi);
+            double dy =
+                r2 < 1.0 ? std::sqrt(r2) - 1.0 : 1.0 - std::sqrt(2.0 - r2);
+            Vec d = cx * (((sx + .5 + dx) / 2.0 + x) / width - .5) +
+                    cy * (((sy + .5 + dy) / 2.0 + y) / height - .5) + cam.d;
+            r = r + radiance(Ray(cam.o + d * 140.0, d.norm()), 0, Xi);
+          }
+          if (subpixel_accum != nullptr) {
+            int sub_idx = (i * 4 + (sy * 2 + sx)) * 3;
+            double acc_x = (subpixel_accum[sub_idx + 0] += r.x);
+            double acc_y = (subpixel_accum[sub_idx + 1] += r.y);
+            double acc_z = (subpixel_accum[sub_idx + 2] += r.z);
+            pixel_radiance =
+                pixel_radiance +
+                Vec(clamp(acc_x * inv_total_samps),
+                    clamp(acc_y * inv_total_samps),
+                    clamp(acc_z * inv_total_samps)) *
+                    .25;
+          } else {
+            pixel_radiance =
+                pixel_radiance +
+                Vec(clamp(r.x * inv_total_samps),
+                    clamp(r.y * inv_total_samps),
+                    clamp(r.z * inv_total_samps)) *
+                    .25;
+          }
+        }
+      }
+      int rgba_idx = i * 4;
+      out_rgba[rgba_idx + 0] = static_cast<uint8_t>(toInt(pixel_radiance.x));
+      out_rgba[rgba_idx + 1] = static_cast<uint8_t>(toInt(pixel_radiance.y));
+      out_rgba[rgba_idx + 2] = static_cast<uint8_t>(toInt(pixel_radiance.z));
+      out_rgba[rgba_idx + 3] = 255;
+    }
+  }
+}
+
+}  // extern "C"
