+import initSmallpt from './smallpt.js';
+
+let wasmPromise = null;
+let activeJobId = 0;
+
+function getWasm() {
+  if (!wasmPromise) {
+    wasmPromise = initSmallpt();
+  }
+  return wasmPromise;
+}
+
+function readSpherePalette(wasm) {
+  const paletteBytes = 21;
+  const ptr = wasm._malloc(paletteBytes);
+  try {
+    wasm._get_sphere_colors(ptr);
+    const raw = new Uint8Array(wasm.HEAPU8.buffer, ptr, paletteBytes);
+    const names = [
+      'Left Wall Sphere',
+      'Right Wall Sphere',
+      'Back Wall Sphere',
+      'Floor Sphere',
+      'Ceiling Sphere',
+      'Mirror Sphere',
+      'Glass Sphere',
+    ];
+    return names.map((name, i) => ({
+      name,
+      r: raw[i * 3 + 0],
+      g: raw[i * 3 + 1],
+      b: raw[i * 3 + 2],
+    }));
+  } finally {
+    wasm._free(ptr);
+  }
+}
+
+async function runProgressiveRender({
+  jobId,
+  width,
+  height,
+  targetSamplesPerSubpixel,
+  randomize,
+  reset,
+  seed,
+}) {
+  const wasm = await getWasm();
+  if (jobId !== activeJobId) return;
+
+  if (reset) {
+    wasm._reset_colors();
+  } else if (randomize) {
+    wasm._randomize_colors(seed >>> 0);
+  }
+
+  const palette = readSpherePalette(wasm);
+  self.postMessage({ type: 'palette', jobId, palette });
+
+  const rgbaByteLength = width * height * 4;
+  const accumDoubles = width * height * 12;
+  const accumByteLength = accumDoubles * 8;
+
+  const rgbaPtr = wasm._malloc(rgbaByteLength);
+  const accumPtr = wasm._malloc(accumByteLength);
+
+  try {
+    // Zero out the subpixel accumulation buffer in Wasm linear memory
+    wasm.HEAPU8.fill(0, accumPtr, accumPtr + accumByteLength);
+
+    let completedSubpixelSamples = 0;
+    let passIndex = 0;
+    const startTime = performance.now();
+
+    // Progressive schedule: fast 1-sample preview first, then larger passes
+    while (completedSubpixelSamples < targetSamplesPerSubpixel) {
+      if (jobId !== activeJobId) return;
+
+      const remaining = targetSamplesPerSubpixel - completedSubpixelSamples;
+      const step =
+        passIndex === 0
+          ? 1
+          : passIndex === 1
+            ? Math.min(3, remaining)
+            : Math.min(4, remaining);
+
+      completedSubpixelSamples += step;
+      passIndex += 1;
+      const passSeed = ((seed >>> 0) + passIndex * 0x9e3779b9) >>> 0;
+
+      wasm._render_samples(
+        rgbaPtr,
+        accumPtr,
+        width,
+        height,
+        step,
+        completedSubpixelSamples,
+        passSeed,
+      );
+
