+import React, { useEffect, useRef, useState, useCallback } from 'react';
+
+interface PaletteItem {
+  index: number;
+  name: string;
+  rgb: string;
+  r: number;
+  g: number;
+  b: number;
+}
+
+interface RenderResult {
+  id: number;
+  status: 'done' | 'error';
+  pixels?: Uint8ClampedArray;
+  width?: number;
+  height?: number;
+  samples?: number;
+  elapsedMs?: number;
+  palette?: PaletteItem[];
+  error?: string;
+}
+
+const DEFAULT_WIDTH = 320;
+const DEFAULT_HEIGHT = 240;
+
+export default function SmallptPathTracer() {
+  const canvasRef = useRef<HTMLCanvasElement | null>(null);
+  const workerRef = useRef<Worker | null>(null);
+  const requestIdRef = useRef<number>(0);
+
+  const [isRendering, setIsRendering] = useState<boolean>(true);
+  const [samplesPerSubpixel, setSamplesPerSubpixel] = useState<number>(8);
+  const [elapsedMs, setElapsedMs] = useState<number | null>(null);
+  const [totalSamplesPerPixel, setTotalSamplesPerPixel] = useState<number>(32);
+  const [palette, setPalette] = useState<PaletteItem[]>([]);
+  const [errorMsg, setErrorMsg] = useState<string | null>(null);
+  const [renderCount, setRenderCount] = useState<number>(0);
+
+  const triggerRender = useCallback(
+    (action: 'default' | 'randomize' | 'reset', sppOverride?: number) => {
+      const worker = workerRef.current;
+      if (!worker) return;
+
+      const id = ++requestIdRef.current;
+      const samples = sppOverride ?? samplesPerSubpixel;
+      setIsRendering(true);
+      setErrorMsg(null);
+
+      // Generate a fresh random seed using crypto.getRandomValues when available
+      let seed = Date.now();
