+        const buf = new Uint32Array(1);
+        crypto.getRandomValues(buf);
+        seed = buf[0];
+      }
+
+      worker.postMessage({
+        id,
+        action,
+        width: DEFAULT_WIDTH,
+        height: DEFAULT_HEIGHT,
+        samples,
+        seed,
+      });
+    },
+    [samplesPerSubpixel],
+  );
+
+  useEffect(() => {
+    const worker = new Worker(
+      new URL('../wasm/smallpt.worker.ts', import.meta.url),
