+    workerRef.current = worker;
+
+    worker.onmessage = (event: MessageEvent<RenderResult>) => {
+      const data = event.data;
+      if (data.id !== requestIdRef.current) return;
+
+      if (data.status === 'error') {
+        setErrorMsg(data.error ?? 'Unknown WebAssembly rendering error');
+        setIsRendering(false);
+        return;
+      }
+
+      if (data.pixels && data.width && data.height && canvasRef.current) {
+        const ctx = canvasRef.current.getContext('2d');
+        if (ctx) {
+          const imgData = new ImageData(
+            new Uint8ClampedArray(data.pixels),
+            data.width,
+            data.height,
+          );
+          ctx.putImageData(imgData, 0, 0);
+        }
+      }
+
+      if (typeof data.elapsedMs === 'number') {
+        setElapsedMs(data.elapsedMs);
+      }
+      if (typeof data.samples === 'number') {
+        setTotalSamplesPerPixel(data.samples);
+      }
+      if (data.palette) {
+        setPalette(data.palette);
+      }
+      setRenderCount((c) => c + 1);
+      setIsRendering(false);
+    };
+
+    worker.onerror = (err) => {
+      setErrorMsg(err.message || 'Worker failed to initialize WebAssembly module');
+      setIsRendering(false);
+    };
+
+    // Perform initial render with classic Cornell box colors on mount
+    const initialId = ++requestIdRef.current;
+    worker.postMessage({
+      id: initialId,
+      action: 'reset',
+      width: DEFAULT_WIDTH,
+      height: DEFAULT_HEIGHT,
+      samples: 8,
+      seed: 1,
+    });
+
+    return () => {
+      worker.terminate();
+      workerRef.current = null;
+    };
+  }, []);
+
+  const handleRandomize = () => {
+    triggerRender('randomize');
+  };
+
+  const handleReset = () => {
+    triggerRender('reset');
+  };
