+        <div className="flex flex-wrap items-center gap-3">
+          <label className="flex items-center gap-2 text-xs text-gray-300 bg-gray-800 px-3 py-2 rounded-lg border border-gray-700">
+            <span>Quality:</span>
+            <select
+              value={samplesPerSubpixel}
