+            data-testid="randomize-colors-btn"
+            className="inline-flex items-center gap-2 bg-amber-400 hover:bg-amber-300 disabled:bg-amber-400/50 text-gray-950 font-bold text-sm px-4 py-2.5 rounded-lg shadow transition cursor-pointer disabled:cursor-wait"
+          >
+            {isRendering ? (
+              <>
+                <span className="w-4 h-4 border-2 border-gray-950 border-t-transparent rounded-full animate-spin" />
