+            </h3>
+            <dl className="grid grid-cols-2 gap-3 text-sm">
+              <div className="bg-gray-900/80 p-2.5 rounded border border-gray-800">
+                <dt className="text-xs text-gray-400">Resolution</dt>
+                <dd className="font-mono font-semibold text-white mt-0.5">
+                  {DEFAULT_WIDTH} &times; {DEFAULT_HEIGHT} px
+                </dd>
+              </div>
+              <div className="bg-gray-900/80 p-2.5 rounded border border-gray-800">
+                <dt className="text-xs text-gray-400">Samples / Pixel</dt>
+                <dd className="font-mono font-semibold text-amber-400 mt-0.5">
+                  {totalSamplesPerPixel} SPP (2&times;2 subpx)
+                </dd>
+              </div>
+              <div className="bg-gray-900/80 p-2.5 rounded border border-gray-800">
+                <dt className="text-xs text-gray-400">Execution Time</dt>
+                <dd
+                  data-testid="render-elapsed-ms"
