+
+          {errorMsg && (
+            <div
+              role="alert"
+              className="bg-red-950/80 border border-red-700 text-red-200 px-4 py-3 rounded-lg text-xs"
+            >
+              <strong>Error:</strong> {errorMsg}
+            </div>
+          )}
+        </div>
+      </div>
+    </section>
+  );
+}
