@@ -0,0 +1,242 @@
+// smallpt, a Path Tracer by Kevin Beason, 2008
+// Modified to compile to WebAssembly via Emscripten and support randomized sphere colors.
+
+#include <cmath>
+#include <cstdlib>
+#include <cstdint>
+#include <emscripten/emscripten.h>
+
+struct Vec {
+  double x, y, z;
+  Vec(double x_ = 0, double y_ = 0, double z_ = 0) : x(x_), y(y_), z(z_) {}
+  Vec operator+(const Vec &b) const { return Vec(x + b.x, y + b.y, z + b.z); }
+  Vec operator-(const Vec &b) const { return Vec(x - b.x, y - b.y, z - b.z); }
+  Vec operator*(double b) const { return Vec(x * b, y * b, z * b); }
+  Vec mult(const Vec &b) const { return Vec(x * b.x, y * b.y, z * b.z); }
+  Vec &norm() { return *this = *this * (1.0 / std::sqrt(x * x + y * y + z * z)); }
+  double dot(const Vec &b) const { return x * b.x + y * b.y + z * b.z; }
+  Vec operator%(const Vec &b) const {
+    return Vec(y * b.z - z * b.y, z * b.x - x * b.z, x * b.y - y * b.x);
+  }
+};
+
+struct Ray {
+  Vec o, d;
+  Ray(Vec o_, Vec d_) : o(o_), d(d_) {}
+};
+
+enum Refl_t { DIFF, SPEC, REFR }; // material types, used in radiance()
+
+struct Sphere {
+  double rad;  // radius
+  Vec p, e, c; // position, emission, color
+  Refl_t refl; // reflection type (DIFFuse, SPECular, REFRactive)
+  Sphere(double rad_, Vec p_, Vec e_, Vec c_, Refl_t refl_)
+      : rad(rad_), p(p_), e(e_), c(c_), refl(refl_) {}
+  double intersect(const Ray &r) const { // returns distance, 0 if nohit
+    Vec op = p - r.o; // Solve t^2*d.d + 2*t*(o-p).d + (o-p).(o-p)-R^2 = 0
+    double t, eps = 1e-4, b = op.dot(r.d), det = b * b - op.dot(op) + rad * rad;
+    if (det < 0)
+      return 0;
+    else
+      det = std::sqrt(det);
+    return (t = b - det) > eps ? t : ((t = b + det) > eps ? t : 0);
+  }
+};
+
+static Sphere spheres[] = {
+    // Scene: radius, position, emission, color, material
+    Sphere(1e5, Vec(1e5 + 1, 40.8, 81.6), Vec(), Vec(.75, .25, .25), DIFF),   // Left
+    Sphere(1e5, Vec(-1e5 + 99, 40.8, 81.6), Vec(), Vec(.25, .25, .75), DIFF), // Rght
+    Sphere(1e5, Vec(50, 40.8, 1e5), Vec(), Vec(.75, .75, .75), DIFF),         // Back
+    Sphere(1e5, Vec(50, 40.8, -1e5 + 170), Vec(), Vec(), DIFF),               // Frnt
+    Sphere(1e5, Vec(50, 1e5, 81.6), Vec(), Vec(.75, .75, .75), DIFF),         // Botm
+    Sphere(1e5, Vec(50, -1e5 + 81.6, 81.6), Vec(), Vec(.75, .75, .75), DIFF), // Top
+    Sphere(16.5, Vec(27, 16.5, 47), Vec(), Vec(1, 1, 1) * .999, SPEC),        // Mirr
+    Sphere(16.5, Vec(73, 16.5, 78), Vec(), Vec(1, 1, 1) * .999, REFR),        // Glas
+    Sphere(600, Vec(50, 681.6 - .27, 81.6), Vec(12, 12, 12), Vec(), DIFF)     // Lite
+};
+
+static inline double clamp(double x) { return x < 0 ? 0 : x > 1 ? 1 : x; }
+static inline uint8_t toInt(double x) {
+  return static_cast<uint8_t>(std::pow(clamp(x), 1.0 / 2.2) * 255.0 + 0.5);
+}
+
+static inline bool intersect(const Ray &r, double &t, int &id) {
+  double n = sizeof(spheres) / sizeof(Sphere), d, inf = t = 1e20;
+  for (int i = int(n); i--;)
+    if ((d = spheres[i].intersect(r)) && d < t) {
+      t = d;
+      id = i;
+    }
+  return t < inf;
+}
+
+static Vec radiance(Ray r, int depth, unsigned short *Xi) {
+  Vec acc(0, 0, 0);
+  Vec mask(1, 1, 1);
+
+  for (int d = depth; d < 100; ++d) {
+    double t;   // distance to intersection
+    int id = 0; // id of intersected object
+    if (!intersect(r, t, id))
+      break;
+    const Sphere &obj = spheres[id]; // the hit object
+    Vec x = r.o + r.d * t;
+    Vec n = (x - obj.p).norm();
+    Vec nl = n.dot(r.d) < 0 ? n : n * -1;
+    Vec f = obj.c;
+    double p = f.x > f.y && f.x > f.z ? f.x : f.y > f.z ? f.y : f.z; // max refl
+
+    acc = acc + mask.mult(obj.e);
+
+    if (d + 1 > 5) {
+      if (erand48(Xi) < p)
+        f = f * (1.0 / p);
+      else
+        break; // R.R.
+    }
+
+    if (obj.refl == DIFF) { // Ideal DIFFUSE reflection
+      double r1 = 2.0 * M_PI * erand48(Xi), r2 = erand48(Xi), r2s = std::sqrt(r2);
+      Vec w = nl;
+      Vec u = ((std::fabs(w.x) > .1 ? Vec(0, 1) : Vec(1)) % w).norm();
+      Vec v = w % u;
+      Vec dir = (u * std::cos(r1) * r2s + v * std::sin(r1) * r2s + w * std::sqrt(1 - r2)).norm();
+      mask = mask.mult(f);
+      r = Ray(x, dir);
+    } else if (obj.refl == SPEC) { // Ideal SPECULAR reflection
+      mask = mask.mult(f);
+      r = Ray(x, r.d - n * 2.0 * n.dot(r.d));
+    } else { // Ideal dielectric REFRACTION
+      Ray reflRay(x, r.d - n * 2.0 * n.dot(r.d));
+      bool into = n.dot(nl) > 0; // Ray from outside going in?
+      double nc = 1.0, nt = 1.5, nnt = into ? nc / nt : nt / nc, ddn = r.d.dot(nl), cos2t;
+      if ((cos2t = 1.0 - nnt * nnt * (1.0 - ddn * ddn)) < 0) { // Total internal reflection
+        mask = mask.mult(f);
+        r = reflRay;
+      } else {
+        Vec tdir = (r.d * nnt - n * ((into ? 1 : -1) * (ddn * nnt + std::sqrt(cos2t)))).norm();
+        double a = nt - nc, b = nt + nc, R0 = a * a / (b * b),
+               c = 1.0 - (into ? -ddn : tdir.dot(n));
+        double Re = R0 + (1.0 - R0) * c * c * c * c * c, Tr = 1.0 - Re,
+               P = .25 + .5 * Re, RP = Re / P, TP = Tr / (1.0 - P);
+        if (d + 1 > 2) {
+          if (erand48(Xi) < P) {
+            mask = mask.mult(f) * RP;
+            r = reflRay;
+          } else {
+            mask = mask.mult(f) * TP;
+            r = Ray(x, tdir);
+          }
+        } else {
+          // For shallow bounces (d <= 1), recurse once on both reflection and refraction
+          // as in original smallpt, which is bounded to at most 2 levels deep.
+          Vec branch = radiance(reflRay, d + 1, Xi) * Re + radiance(Ray(x, tdir), d + 1, Xi) * Tr;
+          acc = acc + mask.mult(f.mult(branch));
+          break;
+        }
+      }
+    }
+  }
+  return acc;
+}
+
+extern "C" {
+
+EMSCRIPTEN_KEEPALIVE
+void set_sphere_color(int index, double r, double g, double b) {
+  int count = static_cast<int>(sizeof(spheres) / sizeof(Sphere));
+  if (index >= 0 && index < count) {
+    spheres[index].c = Vec(clamp(r), clamp(g), clamp(b));
+  }
+}
+
+EMSCRIPTEN_KEEPALIVE
+void reset_default_colors() {
+  spheres[0].c = Vec(.75, .25, .25);       // Left wall
+  spheres[1].c = Vec(.25, .25, .75);       // Right wall
+  spheres[2].c = Vec(.75, .75, .75);       // Back wall
+  spheres[3].c = Vec(0, 0, 0);             // Front wall
+  spheres[4].c = Vec(.75, .75, .75);       // Floor
+  spheres[5].c = Vec(.75, .75, .75);       // Ceiling
+  spheres[6].c = Vec(1, 1, 1) * .999;      // Mirror sphere
+  spheres[7].c = Vec(1, 1, 1) * .999;      // Glass sphere
+  spheres[8].c = Vec(0, 0, 0);             // Light
+}
+
+EMSCRIPTEN_KEEPALIVE
+void randomize_sphere_colors(uint32_t seed) {
+  unsigned short Xi[3] = {
+      static_cast<unsigned short>(seed & 0xFFFF),
+      static_cast<unsigned short>((seed >> 16) & 0xFFFF),
+      static_cast<unsigned short>((seed ^ 0xA5A5) & 0xFFFF)};
+  // Warm up PRNG
+  for (int i = 0; i < 8; ++i) {
+    erand48(Xi);
+  }
+  // Randomize colors of visible walls and spheres (indices 0, 1, 2, 4, 5, 6, 7)
+  int indices[] = {0, 1, 2, 4, 5, 6, 7};
+  for (int idx : indices) {
+    if (idx == 6 || idx == 7) {
+      // Keep mirror and glass spheres bright/tinted so reflections & refractions stay vivid
+      double r = 0.35 + 0.649 * erand48(Xi);
+      double g = 0.35 + 0.649 * erand48(Xi);
+      double b = 0.35 + 0.649 * erand48(Xi);
+      spheres[idx].c = Vec(r, g, b);
+    } else {
+      double r = 0.15 + 0.75 * erand48(Xi);
+      double g = 0.15 + 0.75 * erand48(Xi);
+      double b = 0.15 + 0.75 * erand48(Xi);
+      spheres[idx].c = Vec(r, g, b);
+    }
+  }
+}
+
+EMSCRIPTEN_KEEPALIVE
+void get_sphere_colors(double *out_rgb) {
+  int count = static_cast<int>(sizeof(spheres) / sizeof(Sphere));
+  for (int i = 0; i < count; ++i) {
+    out_rgb[i * 3 + 0] = spheres[i].c.x;
+    out_rgb[i * 3 + 1] = spheres[i].c.y;
+    out_rgb[i * 3 + 2] = spheres[i].c.z;
+  }
+}
+
+EMSCRIPTEN_KEEPALIVE
+void render_frame(uint8_t *out_rgba, int w, int h, int samps) {
+  if (samps < 1)
+    samps = 1;
+  Ray cam(Vec(50, 52, 295.6), Vec(0, -0.042612, -1).norm()); // cam pos, dir
+  Vec cx = Vec(w * .5135 / h);
+  Vec cy = (cx % cam.d).norm() * .5135;
+
+  for (int y = 0; y < h; y++) { // Loop over image rows
+    for (int x = 0; x < w; x++) { // Loop cols
+      unsigned short Xi[3] = {0, 0, static_cast<unsigned short>(y * y * y + x)};
+      Vec c(0, 0, 0);
+      for (int sy = 0; sy < 2; sy++) {     // 2x2 subpixel rows
+        for (int sx = 0; sx < 2; sx++) {   // 2x2 subpixel cols
+          Vec r(0, 0, 0);
+          for (int s = 0; s < samps; s++) {
+            double r1 = 2.0 * erand48(Xi), dx = r1 < 1 ? std::sqrt(r1) - 1 : 1 - std::sqrt(2 - r1);
+            double r2 = 2.0 * erand48(Xi), dy = r2 < 1 ? std::sqrt(r2) - 1 : 1 - std::sqrt(2 - r2);
+            Vec d = cx * (((sx + .5 + dx) / 2 + x) / w - .5) +
+                    cy * (((sy + .5 + dy) / 2 + y) / h - .5) + cam.d;
