+import initSmallpt from './smallpt.js';
+
+let wasmPromise: Promise<any> | null = null;
+
+function getWasm() {
+  if (!wasmPromise) {
+    wasmPromise = initSmallpt();
+  }
+  return wasmPromise;
+}
+
+const SPHERE_NAMES = [
+  'Left Wall',
+  'Right Wall',
+  'Back Wall',
+  'Front Wall',
+  'Floor',
+  'Ceiling',
+  'Mirror Sphere',
+  'Glass Sphere',
+  'Light',
+];
+
+function readSpherePalette(wasm: any) {
+  const count = 9;
+  const byteLength = count * 3 * 8; // 9 spheres * 3 doubles * 8 bytes
+  const ptr = wasm._malloc(byteLength);
+  try {
+    wasm._get_sphere_colors(ptr);
+    const f64 = new Float64Array(wasm.HEAPF64.buffer, ptr, count * 3);
+    const palette = [];
+    for (let i = 0; i < count; i++) {
+      if (i === 3 || i === 8) continue; // skip front black wall and emissive light
+      const r = Math.round(f64[i * 3 + 0] * 255);
+      const g = Math.round(f64[i * 3 + 1] * 255);
+      const b = Math.round(f64[i * 3 + 2] * 255);
+      palette.push({
+        index: i,
+        name: SPHERE_NAMES[i],
+        rgb: `rgb(${r}, ${g}, ${b})`,
+        r,
+        g,
+        b,
+      });
+    }
+    return palette;
+  } finally {
+    wasm._free(ptr);
+  }
+}
+
+self.addEventListener('message', async (event: MessageEvent) => {
+  const { id, action, width = 320, height = 240, samples = 8, seed = Date.now(), customColors } = event.data;
+
+  try {
+    const wasm = await getWasm();
+
+    if (action === 'reset') {
+      wasm._reset_default_colors();
+    } else if (action === 'randomize') {
+      wasm._randomize_sphere_colors(seed >>> 0);
+      if (Array.isArray(customColors)) {
+        for (const c of customColors) {
+          wasm._set_sphere_color(c.index, c.r, c.g, c.b);
+        }
+      }
+    }
+
+    const palette = readSpherePalette(wasm);
+    const byteLength = width * height * 4;
+    const ptr = wasm._malloc(byteLength);
+
+    const startTime = performance.now();
+    try {
+      wasm._render_frame(ptr, width, height, samples);
+      const elapsedMs = Math.round(performance.now() - startTime);
+
+      // Read fresh wasm.HEAPU8 after Wasm execution in case memory grew
+      const pixels = new Uint8ClampedArray(
+        wasm.HEAPU8.buffer,
+        ptr,
+        byteLength,
+      ).slice();
+
+      self.postMessage(
+        {
+          id,
+          status: 'done',
+          pixels,
+          width,
+          height,
+          samples: samples * 4, // 2x2 subpixels * samples
+          elapsedMs,
+          palette,
+        },
+        [pixels.buffer],
+      );
+    } finally {
+      wasm._free(ptr);
+    }
+  } catch (err) {
+    const message = err instanceof Error ? err.message : String(err);
+    self.postMessage({
+      id,
+      status: 'error',
+      error: message,
+    });
+  }
+});

