+  const hg = gamma(g).toString(16).padStart(2, '0');
+  const hb = gamma(b).toString(16).padStart(2, '0');
+  return `#${hr}${hg}${hb}`;
+}
+
+export default function SmallptPathTracer() {
+  const canvasRef = useRef<HTMLCanvasElement | null>(null);
+  const wasmModRef = useRef<any>(null);
+  const animFrameRef = useRef<number | null>(null);
+  const isRenderingRef = useRef<boolean>(false);
+
+  const [width] = useState<number>(320);
+  const [height] = useState<number>(240);
+  const [targetSpp, setTargetSpp] = useState<number>(64);
+  const [currentSpp, setCurrentSpp] = useState<number>(0);
+  const [status, setStatus] = useState<'loading' | 'rendering' | 'done' | 'error'>('loading');
+  const [elapsedMs, setElapsedMs] = useState<number>(0);
+  const [sphereColors, setSphereColors] = useState<SphereColorInfo[]>([]);
+  const [renderRunCount, setRenderRunCount] = useState<number>(1);
+  const startTimeRef = useRef<number>(0);
+
+  const readSphereColors = useCallback((mod: any) => {
+    const colors: SphereColorInfo[] = SPHERE_METADATA.map((meta) => {
+      const r = mod._get_sphere_color_channel(meta.index, 0);
+      const g = mod._get_sphere_color_channel(meta.index, 1);
+      const b = mod._get_sphere_color_channel(meta.index, 2);
+      return {
+        ...meta,
+        rgb: [r, g, b],
+      };
+    });
+    setSphereColors(colors);
+  }, []);
+
+  const drawBufferToCanvas = useCallback((mod: any, w: number, h: number) => {
+    const canvas = canvasRef.current;
+    if (!canvas) return;
+    const ctx = canvas.getContext('2d');
+    if (!ctx) return;
+
+    const ptr = mod._get_rgba_buffer();
+    if (!ptr) return;
+
+    const byteLength = w * h * 4;
+    const pixelSlice = new Uint8ClampedArray(
+      mod.HEAPU8.buffer,
+      ptr,
+      byteLength
+    );
+    const imgData = new ImageData(new Uint8ClampedArray(pixelSlice), w, h);
+    ctx.putImageData(imgData, 0, 0);
+  }, []);
+
+  const startProgressiveRender = useCallback(
+    (mod: any, w: number, h: number, maxSpp: number) => {
+      if (animFrameRef.current !== null) {
+        cancelAnimationFrame(animFrameRef.current);
+      }
+
+      mod._init_scene(w, h);
+      readSphereColors(mod);
+      setCurrentSpp(0);
+      setElapsedMs(0);
+      setStatus('rendering');
+      isRenderingRef.current = true;
+      startTimeRef.current = performance.now();
+
+      const step = () => {
+        if (!isRenderingRef.current) return;
+        // 1 pass = 4 subpixel samples (2x2 subpixels per pixel)
+        const spp = mod._render_samples(1);
+        drawBufferToCanvas(mod, w, h);
+        setCurrentSpp(spp);
+        setElapsedMs(Math.round(performance.now() - startTimeRef.current));
+
+        if (spp < maxSpp) {
+          animFrameRef.current = requestAnimationFrame(step);
+        } else {
+          isRenderingRef.current = false;
+          setStatus('done');
+        }
+      };
+
+      animFrameRef.current = requestAnimationFrame(step);
+    },
+    [drawBufferToCanvas, readSphereColors]
+  );
+
+  useEffect(() => {
+    let cancelled = false;
+
+    async function loadWasm() {
+      try {
+        const baseUrl = import.meta.env.BASE_URL || '/';
+        const normalizedBase = baseUrl.endsWith('/') ? baseUrl : `${baseUrl}/`;
+        const jsUrl = `${normalizedBase}wasm/smallpt.js`;
+        const wasmUrl = `${normalizedBase}wasm/smallpt.wasm`;
+
+        const factoryModule = await import(/* @vite-ignore */ jsUrl);
+        const createSmallptModule = factoryModule.default || factoryModule;
+
+        const mod = await createSmallptModule({
+          locateFile: (path: string) => {
+            if (path.endsWith('.wasm')) return wasmUrl;
+            return path;
+          },
+        });
+
+        if (cancelled) return;
+        wasmModRef.current = mod;
+        startProgressiveRender(mod, width, height, targetSpp);
+      } catch (err) {
+        console.error('Failed to load smallpt WebAssembly module:', err);
+        if (!cancelled) setStatus('error');
+      }
+    }
+
+    loadWasm();
+
+    return () => {
+      cancelled = true;
+      isRenderingRef.current = false;
+      if (animFrameRef.current !== null) {
+        cancelAnimationFrame(animFrameRef.current);
+      }
+    };
+  }, [width, height, targetSpp, startProgressiveRender]);
+
+  const handleRandomizeColors = () => {
+    const mod = wasmModRef.current;
+    if (!mod) return;
+    const seed = Math.floor(Math.random() * 0xffffffff) >>> 0;
+    mod._randomize_sphere_colors(seed);
+    setRenderRunCount((c) => c + 1);
+    startProgressiveRender(mod, width, height, targetSpp);
+  };
+
+  const handleResetDefaultColors = () => {
+    const mod = wasmModRef.current;
+    if (!mod) return;
+    mod._reset_default_colors();
+    setRenderRunCount((c) => c + 1);
+    startProgressiveRender(mod, width, height, targetSpp);
+  };
+
+  const progressPct = Math.min(100, Math.round((currentSpp / targetSpp) * 100));
+
+  return (
+    <section
+      id="smallpt-wasm-demo"
+      className="bg-white border border-gray-200 shadow-sm rounded-lg p-6 md:p-8 my-6"
+    >
+      <div className="flex flex-col md:flex-row md:items-center md:justify-between border-b border-gray-200 pb-4 mb-6 gap-4">
+        <div>
+          <div className="flex items-center gap-2">
+            <span className="inline-block bg-amber-500 text-white text-xs font-bold uppercase tracking-wider px-2.5 py-0.5 rounded">
+              WebAssembly Interactive
+            </span>
+            <span className="text-xs text-gray-500 font-mono">
+              C++ → Emscripten Wasm
+            </span>
+          </div>
+          <h2 className="text-2xl md:text-3xl font-brand text-gray-900 mt-1">
+            smallpt: Global Illumination Path Tracer in WebAssembly
+          </h2>
+          <p className="text-sm text-gray-600 mt-1">
+            Kevin Beason&apos;s 99-line C++ Monte Carlo path tracer compiled to client-side WebAssembly, rendering the Cornell box with diffuse, mirror, and dielectric glass spheres in real time.
+          </p>
+        </div>
+
+        <div className="flex flex-wrap items-center gap-3">
+          <button
+            id="randomize-sphere-colors-btn"
+            type="button"
+            onClick={handleRandomizeColors}
+            disabled={status === 'loading' || status === 'error'}
+            className="bg-amber-600 hover:bg-amber-500 active:bg-amber-700 disabled:bg-gray-300 text-white font-semibold text-sm px-4 py-2.5 rounded-md shadow-sm transition-colors cursor-pointer flex items-center gap-2"
+          >
+            <svg
+              xmlns="http://www.w3.org/2000/svg"
+              fill="none"
+              viewBox="0 0 24 24"
+              strokeWidth={2}
+              stroke="currentColor"
+              className="w-4 h-4"
+            >
+              <path
+                strokeLinecap="round"
+                strokeLinejoin="round"
+                d="M16.023 9.348h4.992v-.001M2.985 19.644v-4.992m0 0h4.992m-4.993 0 3.181 3.183a8.25 8.25 0 0 0 13.803-3.7M4.031 9.865a8.25 8.25 0 0 1 13.803-3.7l3.181 3.182m0-4.991v4.99"
+              />
+            </svg>
+            Randomize Sphere Colors &amp; Re-run
+          </button>
+
+          <button
+            id="reset-sphere-colors-btn"
+            type="button"
+            onClick={handleResetDefaultColors}
+            disabled={status === 'loading' || status === 'error'}
+            className="bg-gray-800 hover:bg-gray-700 disabled:bg-gray-300 text-white font-semibold text-sm px-3.5 py-2.5 rounded-md shadow-sm transition-colors cursor-pointer"
+          >
+            Reset Classic Cornell Box
+          </button>
+        </div>
+      </div>
+
+      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">
+        {/* Left column: Canvas Output */}
+        <div className="lg:col-span-7 flex flex-col items-center">
+          <div className="relative w-full max-w-[640px] aspect-[4/3] bg-black rounded-lg overflow-hidden shadow-md border border-gray-800">
+            <canvas
+              id="smallpt-canvas"
+              ref={canvasRef}
+              width={width}
+              height={height}
+              className="w-full h-full object-contain"
+              style={{ imageRendering: 'auto' }}
+            />
+            {status === 'loading' && (
+              <div className="absolute inset-0 flex items-center justify-center bg-black/75 text-white text-sm font-mono">
+                Initializing WebAssembly Path Tracer...
+              </div>
+            )}
+            {status === 'error' && (
+              <div className="absolute inset-0 flex items-center justify-center bg-red-950/90 text-red-200 text-sm p-4 text-center">
+                Error loading WebAssembly module.
+              </div>
+            )}
+          </div>
+
+          {/* Progress Bar */}
+          <div className="w-full max-w-[640px] mt-3">
+            <div className="flex justify-between text-xs font-mono text-gray-600 mb-1">
+              <span>
+                Status:{' '}
+                <strong className="text-gray-900 uppercase">{status}</strong> (Run #{renderRunCount})
+              </span>
+              <span>
+                {currentSpp} / {targetSpp} SPP ({progressPct}%) • {(elapsedMs / 1000).toFixed(2)}s
+              </span>
+            </div>
+            <div className="w-full bg-gray-200 h-2 rounded-full overflow-hidden">
+              <div
+                className="bg-amber-500 h-full transition-all duration-150"
+                style={{ width: `${progressPct}%` }}
+              />
+            </div>
+          </div>
+        </div>
+
+        {/* Right column: Sphere Colors & Controls */}
+        <div className="lg:col-span-5 flex flex-col justify-between space-y-5">
+          <div className="bg-gray-50 border border-gray-200 rounded-lg p-4">
+            <h3 className="text-sm font-bold uppercase tracking-wider text-gray-700 mb-3">
+              Active Scene Sphere Colors
+            </h3>
+            <div className="grid grid-cols-1 sm:grid-cols-2 gap-2.5">
+              {sphereColors.map((sphere) => {
+                const hex = toDisplayHex(sphere.rgb[0], sphere.rgb[1], sphere.rgb[2]);
+                return (
+                  <div
+                    key={sphere.index}
+                    className="flex items-center gap-2.5 bg-white p-2 rounded border border-gray-200 shadow-2xs"
+                  >
+                    <span
+                      className="w-6 h-6 rounded-full border border-gray-300 flex-shrink-0"
+                      style={{ backgroundColor: hex }}
+                      title={`Linear RGB: (${sphere.rgb.map((n) => n.toFixed(2)).join(', ')})`}
+                    />
+                    <div className="min-w-0 flex-1">
+                      <div className="text-xs font-semibold text-gray-900 truncate">
+                        {sphere.name}
+                      </div>
+                      <div className="text-[11px] text-gray-500 font-mono">
+                        {sphere.material} • {hex}
+                      </div>
+                    </div>
+                  </div>
+                );
+              })}
+            </div>
+          </div>
+
+          <div className="bg-gray-50 border border-gray-200 rounded-lg p-4 space-y-3">
+            <div className="flex items-center justify-between">
+              <label
+                htmlFor="spp-select"
+                className="text-xs font-bold uppercase tracking-wider text-gray-700"
+              >
+                Target Samples Per Pixel (SPP)
+              </label>
+              <select
+                id="spp-select"
+                value={targetSpp}
+                onChange={(e) => setTargetSpp(Number(e.target.value))}
+                className="text-xs font-mono bg-white border border-gray-300 rounded px-2.5 py-1 text-gray-800"
+              >
+                <option value={16}>16 SPP (Fast Preview)</option>
+                <option value={32}>32 SPP (Balanced)</option>
+                <option value={64}>64 SPP (High Quality)</option>
+                <option value={128}>128 SPP (Ultra Smooth)</option>
+              </select>
+            </div>
+            <p className="text-xs text-gray-600 leading-relaxed">
+              <strong>Features simulated in Wasm:</strong> Monte Carlo path tracing, Russian roulette termination, 2×2 tent filter anti-aliasing, soft area lighting, diffuse color bleeding, ideal mirror reflection, and Fresnel dielectric glass caustics.
+            </p>
+          </div>
+        </div>
+      </div>
+    </section>
+  );
+}
