--- /dev/null
+++ b/src/wasm/smallpt.cpp
@@ -0,0 +1,273 @@
+// smallpt, a Path Tracer by Kevin Beason, 2008
+// Modified to compile to WebAssembly (Emscripten) for client-side browser rendering
+// with progressive sample accumulation and randomized sphere colors.
+
+#include <math.h>
+#include <stdlib.h>
+#include <stdio.h>
+#include <stdint.h>
+
+#ifdef __EMSCRIPTEN__
+#include <emscripten/emscripten.h>
+#else
+#define EMSCRIPTEN_KEEPALIVE
+#endif
+
+struct Vec {
+  double x, y, z; // position, also color (r,g,b)
+  Vec(double x_ = 0, double y_ = 0, double z_ = 0) { x = x_; y = y_; z = z_; }
+  Vec operator+(const Vec &b) const { return Vec(x + b.x, y + b.y, z + b.z); }
+  Vec operator-(const Vec &b) const { return Vec(x - b.x, y - b.y, z - b.z); }
+  Vec operator*(double b) const { return Vec(x * b, y * b, z * b); }
+  Vec mult(const Vec &b) const { return Vec(x * b.x, y * b.y, z * b.z); }
+  Vec& norm() { return *this = *this * (1.0 / sqrt(x * x + y * y + z * z)); }
+  double dot(const Vec &b) const { return x * b.x + y * b.y + z * b.z; }
+  Vec operator%(Vec &b) { return Vec(y * b.z - z * b.y, z * b.x - x * b.z, x * b.y - y * b.x); }
+};
+
+struct Ray {
+  Vec o, d;
+  Ray(Vec o_, Vec d_) : o(o_), d(d_) {}
+};
+
+enum Refl_t { DIFF, SPEC, REFR }; // material types, used in radiance()
+
+struct Sphere {
+  double rad;  // radius
+  Vec p, e, c; // position, emission, color
+  Refl_t refl; // reflection type (DIFFuse, SPECular, REFRactive)
+  Sphere(double rad_, Vec p_, Vec e_, Vec c_, Refl_t refl_) :
+    rad(rad_), p(p_), e(e_), c(c_), refl(refl_) {}
+  double intersect(const Ray &r) const { // returns distance, 0 if nohit
+    Vec op = p - r.o; // Solve t^2*d.d + 2*t*(o-p).d + (o-p).(o-p)-R^2 = 0
+    double t, eps = 1e-4, b = op.dot(r.d), det = b * b - op.dot(op) + rad * rad;
+    if (det < 0) return 0; else det = sqrt(det);
+    return (t = b - det) > eps ? t : ((t = b + det) > eps ? t : 0);
+  }
+};
+
+// Original Cornell box scene with 9 spheres
+Sphere spheres[] = {
+  Sphere(1e5, Vec( 1e5+1,40.8,81.6), Vec(),Vec(.75,.25,.25),DIFF),//Left
+  Sphere(1e5, Vec(-1e5+99,40.8,81.6),Vec(),Vec(.25,.25,.75),DIFF),//Rght
+  Sphere(1e5, Vec(50,40.8, 1e5),     Vec(),Vec(.75,.75,.75),DIFF),//Back
+  Sphere(1e5, Vec(50,40.8,-1e5+170), Vec(),Vec(),           DIFF),//Frnt
+  Sphere(1e5, Vec(50, 1e5, 81.6),    Vec(),Vec(.75,.75,.75),DIFF),//Botm
+  Sphere(1e5, Vec(50,-1e5+81.6,81.6),Vec(),Vec(.75,.75,.75),DIFF),//Top
+  Sphere(16.5,Vec(27,16.5,47),       Vec(),Vec(1,1,1)*.999, SPEC),//Mirr
+  Sphere(16.5,Vec(73,16.5,78),       Vec(),Vec(1,1,1)*.999, REFR),//Glas
+  Sphere(600, Vec(50,681.6-.27,81.6),Vec(12,12,12),  Vec(), DIFF) //Lite
+};
+
+inline double clamp(double x) { return x < 0 ? 0 : x > 1 ? 1 : x; }
+inline int toInt(double x) { return int(pow(clamp(x), 1 / 2.2) * 255 + .5); }
+
+inline bool intersect(const Ray &r, double &t, int &id) {
+  double n = sizeof(spheres) / sizeof(Sphere), d, inf = t = 1e20;
+  for (int i = int(n); i--;) if ((d = spheres[i].intersect(r)) && d < t) { t = d; id = i; }
+  return t < inf;
+}
+
+Vec radiance(const Ray &r_, int depth_, unsigned short *Xi) {
+  Ray r = r_;
+  int depth = depth_;
+  Vec acc_color(0, 0, 0);
+  Vec throughput(1, 1, 1);
+
+  while (true) {
+    double t;
+    int id = 0;
+    if (!intersect(r, t, id)) return acc_color;
+    const Sphere &obj = spheres[id];
+    Vec x = r.o + r.d * t;
+    Vec n = (x - obj.p).norm();
+    Vec nl = n.dot(r.d) < 0 ? n : n * -1;
+    Vec f = obj.c;
+    double p = f.x > f.y && f.x > f.z ? f.x : f.y > f.z ? f.y : f.z; // max refl
+
+    acc_color = acc_color + throughput.mult(obj.e);
+
+    if (++depth > 5) {
+      if (erand48(Xi) < p && p > 0) {
+        f = f * (1.0 / p);
+      } else {
+        return acc_color; // R.R.
+      }
+    }
+    if (depth > 30) return acc_color;
+
+    throughput = throughput.mult(f);
+
+    if (obj.refl == DIFF) { // Ideal DIFFUSE reflection
+      double r1 = 2 * M_PI * erand48(Xi), r2 = erand48(Xi), r2s = sqrt(r2);
+      Vec w = nl, u = ((fabs(w.x) > .1 ? Vec(0, 1) : Vec(1)) % w).norm(), v = w % u;
+      Vec d = (u * cos(r1) * r2s + v * sin(r1) * r2s + w * sqrt(1 - r2)).norm();
+      r = Ray(x, d);
+    } else if (obj.refl == SPEC) { // Ideal SPECULAR reflection
+      r = Ray(x, r.d - n * 2 * n.dot(r.d));
+    } else { // Ideal dielectric REFRACTION
+      Ray reflRay(x, r.d - n * 2 * n.dot(r.d));
+      bool into = n.dot(nl) > 0; // Ray from outside going in?
+      double nc = 1, nt = 1.5, nnt = into ? nc / nt : nt / nc, ddn = r.d.dot(nl), cos2t;
+      if ((cos2t = 1 - nnt * nnt * (1 - ddn * ddn)) < 0) { // Total internal reflection
+        r = reflRay;
+      } else {
+        Vec tdir = (r.d * nnt - n * ((into ? 1 : -1) * (ddn * nnt + sqrt(cos2t)))).norm();
+        double a = nt - nc, b = nt + nc, R0 = a * a / (b * b), c = 1 - (into ? -ddn : tdir.dot(n));
+        double Re = R0 + (1 - R0) * c * c * c * c * c, Tr = 1 - Re, P = .25 + .5 * Re, RP = Re / P, TP = Tr / (1 - P);
+        if (erand48(Xi) < P) {
+          throughput = throughput * RP;
+          r = reflRay;
+        } else {
+          throughput = throughput * TP;
+          r = Ray(x, tdir);
+        }
+      }
+    }
+  }
+}
+
+static int g_w = 0;
+static int g_h = 0;
+static int g_passes = 0;
+static Vec *g_accum = NULL;
+static uint8_t *g_rgba = NULL;
+
+extern "C" {
+
+EMSCRIPTEN_KEEPALIVE
+void reset_default_colors() {
+  spheres[0].c = Vec(.75, .25, .25);      // Left wall
+  spheres[1].c = Vec(.25, .25, .75);      // Right wall
+  spheres[2].c = Vec(.75, .75, .75);      // Back wall
+  spheres[3].c = Vec(0, 0, 0);            // Front wall
+  spheres[4].c = Vec(.75, .75, .75);      // Bottom floor
+  spheres[5].c = Vec(.75, .75, .75);      // Top ceiling
+  spheres[6].c = Vec(1, 1, 1) * .999;     // Mirror sphere
+  spheres[7].c = Vec(1, 1, 1) * .999;     // Glass sphere
+}
+
+EMSCRIPTEN_KEEPALIVE
+void set_sphere_color(int index, double r, double g, double b) {
+  if (index >= 0 && index < 9) {
+    spheres[index].c = Vec(r, g, b);
+  }
+}
+
+EMSCRIPTEN_KEEPALIVE
+double get_sphere_color_channel(int index, int channel) {
+  if (index < 0 || index >= 9) return 0.0;
+  if (channel == 0) return spheres[index].c.x;
+  if (channel == 1) return spheres[index].c.y;
+  if (channel == 2) return spheres[index].c.z;
+  return 0.0;
+}
+
+EMSCRIPTEN_KEEPALIVE
+void randomize_sphere_colors(unsigned int seed) {
+  unsigned short Xi[3] = {
+    (unsigned short)(seed & 0xFFFF),
+    (unsigned short)((seed >> 16) & 0xFFFF),
+    (unsigned short)((seed * 31337 + 12345) & 0xFFFF)
+  };
+  // Randomize Left Wall (0), Right Wall (1), Back Wall (2), Floor (4), Mirror (6), Glass (7)
+  // Keep vibrant, aesthetically pleasing colors in [0.15, 0.90] for diffuse walls
+  spheres[0].c = Vec(0.15 + 0.75 * erand48(Xi), 0.15 + 0.75 * erand48(Xi), 0.15 + 0.75 * erand48(Xi));
+  spheres[1].c = Vec(0.15 + 0.75 * erand48(Xi), 0.15 + 0.75 * erand48(Xi), 0.15 + 0.75 * erand48(Xi));
+  spheres[2].c = Vec(0.25 + 0.65 * erand48(Xi), 0.25 + 0.65 * erand48(Xi), 0.25 + 0.65 * erand48(Xi));
+  spheres[4].c = Vec(0.30 + 0.60 * erand48(Xi), 0.30 + 0.60 * erand48(Xi), 0.30 + 0.60 * erand48(Xi));
+  spheres[5].c = Vec(0.55 + 0.35 * erand48(Xi), 0.55 + 0.35 * erand48(Xi), 0.55 + 0.35 * erand48(Xi));
+  // Tint the mirror and glass spheres with bright pastel/vivid tints [0.55, 0.999]
+  spheres[6].c = Vec(0.50 + 0.499 * erand48(Xi), 0.50 + 0.499 * erand48(Xi), 0.50 + 0.499 * erand48(Xi));
+  spheres[7].c = Vec(0.50 + 0.499 * erand48(Xi), 0.50 + 0.499 * erand48(Xi), 0.50 + 0.499 * erand48(Xi));
+
+  // Reset accumulator so the new colors render cleanly
+  if (g_accum && g_w > 0 && g_h > 0) {
+    for (int i = 0; i < g_w * g_h; i++) {
+      g_accum[i] = Vec(0, 0, 0);
+    }
+    g_passes = 0;
+  }
+}
+
+EMSCRIPTEN_KEEPALIVE
+uint8_t* init_scene(int w, int h) {
+  if (g_w != w || g_h != h || !g_accum || !g_rgba) {
+    if (g_accum) free(g_accum);
+    if (g_rgba) free(g_rgba);
+    g_w = w;
+    g_h = h;
+    g_accum = (Vec*)malloc(sizeof(Vec) * w * h);
+    g_rgba = (uint8_t*)malloc(sizeof(uint8_t) * w * h * 4);
+  }
+  for (int i = 0; i < w * h; i++) {
+    g_accum[i] = Vec(0, 0, 0);
+    g_rgba[i * 4 + 0] = 0;
+    g_rgba[i * 4 + 1] = 0;
+    g_rgba[i * 4 + 2] = 0;
+    g_rgba[i * 4 + 3] = 255;
+  }
+  g_passes = 0;
+  return g_rgba;
+}
+
+EMSCRIPTEN_KEEPALIVE
+int render_samples(int samples_per_subpixel) {
+  if (!g_accum || !g_rgba || g_w <= 0 || g_h <= 0) return 0;
+  if (samples_per_subpixel < 1) samples_per_subpixel = 1;
+
+  int w = g_w;
+  int h = g_h;
+  Ray cam(Vec(50, 52, 295.6), Vec(0, -0.042612, -1).norm()); // cam pos, dir
+  Vec cx = Vec(w * .5135 / h), cy = (cx % cam.d).norm() * .5135, r;
+
+  for (int pass = 0; pass < samples_per_subpixel; pass++) {
+    g_passes++;
+    int p_seed = g_passes;
+    for (int y = 0; y < h; y++) {
+      unsigned short Xi[3] = {
+        (unsigned short)(y + p_seed * 97),
+        (unsigned short)(y * y + p_seed * 7919),
+        (unsigned short)(y * y * y + p_seed * 104729)
+      };
+      for (unsigned short x = 0; x < w; x++) {
+        int idx = (h - y - 1) * w + x;
+        Vec sub_sum(0, 0, 0);
+        for (int sy = 0; sy < 2; sy++) {
+          for (int sx = 0; sx < 2; sx++) {
+            double r1 = 2 * erand48(Xi), dx = r1 < 1 ? sqrt(r1) - 1 : 1 - sqrt(2 - r1);
+            double r2 = 2 * erand48(Xi), dy = r2 < 1 ? sqrt(r2) - 1 : 1 - sqrt(2 - r2);
+            Vec d = cx * (((sx + .5 + dx) / 2 + x) / w - .5) +
+                    cy * (((sy + .5 + dy) / 2 + y) / h - .5) + cam.d;
+            r = radiance(Ray(cam.o + d * 140, d.norm()), 0, Xi);
+            sub_sum = sub_sum + Vec(clamp(r.x), clamp(r.y), clamp(r.z)) * .25;
+          }
+        }
+        g_accum[idx] = g_accum[idx] + sub_sum;
+      }
+    }
+  }
+
+  double inv_passes = 1.0 / (double)g_passes;
+  for (int i = 0; i < w * h; i++) {
+    Vec c = g_accum[i] * inv_passes;
+    g_rgba[i * 4 + 0] = (uint8_t)toInt(c.x);
+    g_rgba[i * 4 + 1] = (uint8_t)toInt(c.y);
+    g_rgba[i * 4 + 2] = (uint8_t)toInt(c.z);
+    g_rgba[i * 4 + 3] = 255;
+  }
+
+  return g_passes * 4; // total spp (since each pass has 2x2=4 subpixel samples)
+}
+
+EMSCRIPTEN_KEEPALIVE
+uint8_t* get_rgba_buffer() {
+  return g_rgba;
+}
+
+EMSCRIPTEN_KEEPALIVE
+int get_total_spp() {
+  return g_passes * 4;
+}
+
+} // extern "C"

