+      <div class="badges" part="badges">
+        <span class="badge badge--featured" data-badge="featured" hidden>Featured</span>
+        <span class="badge badge--seasonal" data-badge="seasonal" hidden>Seasonal</span>
+        <span class="badge badge--iced" data-badge="iced" hidden>Iced</span>
+        <span class="badge badge--custom" data-badge="custom" hidden></span>
+        <span class="badge badge--sold-out" data-badge="sold-out" hidden>Sold Out</span>
+      </div>
+    </div>
+    <div class="body" part="body">
+      <div class="meta-top" part="meta">
