+    this.attachShadow({ mode: 'open' });
+    this.shadowRoot.appendChild(template.content.cloneNode(true));
+
+    this._els = {
+      card: this.shadowRoot.querySelector('.card'),
+      media: this.shadowRoot.querySelector('.media'),
+      img: this.shadowRoot.querySelector('.media img'),
+      metaTop: this.shadowRoot.querySelector('.meta-top'),
+      roast: this.shadowRoot.querySelector('[data-el="roast"]'),
+      rating: this.shadowRoot.querySelector('[data-el="rating"]'),
+      name: this.shadowRoot.querySelector('[data-el="name"]'),
+      description: this.shadowRoot.querySelector('[data-el="description"]'),
+      stats: this.shadowRoot.querySelector('.stats'),
+      price: this.shadowRoot.querySelector('[data-el="price"]'),
+      calories: this.shadowRoot.querySelector('[data-el="calories"]'),
+      cta: this.shadowRoot.querySelector('[data-el="cta"]'),
+      badgeFeatured: this.shadowRoot.querySelector('[data-badge="featured"]'),
+      badgeSeasonal: this.shadowRoot.querySelector('[data-badge="seasonal"]'),
+      badgeIced: this.shadowRoot.querySelector('[data-badge="iced"]'),
+      badgeCustom: this.shadowRoot.querySelector('[data-badge="custom"]'),
+      badgeSoldOut: this.shadowRoot.querySelector('[data-badge="sold-out"]'),
+    };
+
+    this._onCtaClick = this._onCtaClick.bind(this);
+    this._isConnected = false;
+  }
+
+  /* ==========================================================================
+   * Lifecycle Callbacks
+   * ========================================================================== */
+
+  connectedCallback() {
+    this._isConnected = true;
+
+    // Upgrade any properties that may have been set on the instance before
+    // the custom element definition was registered.
