+  // String properties: name, description, href, cta, image, roast, badge
+  get name() {
+    return this.getAttribute('name') ?? DEFAULTS.name;
+  }
+  set name(val) {
+    this._reflectString('name', val);
+  }
+
+  get description() {
+    return this.getAttribute('description') ?? DEFAULTS.description;
+  }
+  set description(val) {
+    this._reflectString('description', val);
+  }
+
+  get href() {
+    return this.getAttribute('href') ?? DEFAULTS.href;
+  }
+  set href(val) {
+    this._reflectString('href', val);
+  }
+
+  get cta() {
+    return this.getAttribute('cta') ?? DEFAULTS.cta;
+  }
+  set cta(val) {
+    this._reflectString('cta', val);
+  }
+
+  get image() {
+    return this.getAttribute('image') ?? DEFAULTS.image;
+  }
+  set image(val) {
+    this._reflectString('image', val);
+  }
+
+  get roast() {
+    return this.getAttribute('roast') ?? DEFAULTS.roast;
+  }
+  set roast(val) {
+    this._reflectString('roast', val);
+  }
+
+  get badge() {
+    return this.getAttribute('badge') ?? DEFAULTS.badge;
+  }
+  set badge(val) {
