+  }
+  set price(val) {
+    this._reflectNumeric('price', val);
+  }
+
+  get calories() {
+    return this._parseNumeric('calories', DEFAULTS.calories);
+  }
+  set calories(val) {
+    this._reflectNumeric('calories', val);
+  }
+
+  get rating() {
+    return this._parseNumeric('rating', DEFAULTS.rating);
+  }
+  set rating(val) {
+    this._reflectNumeric('rating', val);
+  }
+
+  // Boolean properties: seasonal, featured, iced, soldOut (sold-out)
