+    return this.hasAttribute('seasonal');
+  }
+  set seasonal(val) {
+    this._reflectBoolean('seasonal', val);
+  }
+
+  get featured() {
+    return this.hasAttribute('featured');
+  }
+  set featured(val) {
+    this._reflectBoolean('featured', val);
+  }
+
+  get iced() {
+    return this.hasAttribute('iced');
+  }
+  set iced(val) {
+    this._reflectBoolean('iced', val);
+  }
+
+  get soldOut() {
+    return this.hasAttribute('sold-out');
+  }
+  set soldOut(val) {
+    this._reflectBoolean('sold-out', val);
+  }
+
+  _reflectString(attr, val) {
+    if (val === null || val === undefined) {
+      this.removeAttribute(attr);
+    } else {
+      const str = String(val);
+      if (this.getAttribute(attr) !== str) {
+        this.setAttribute(attr, str);
+      }
+    }
+  }
