+          rating: this.rating,
+          roast: this.roast,
+          seasonal: this.seasonal,
+          featured: this.featured,
+          iced: this.iced,
+          soldOut: this.soldOut,
+          href: this.href,
+        },
+      })
+    );
+  }
+
+  _render() {
+    const {
+      media,
+      img,
+      metaTop,
+      roast,
+      rating,
+      name,
+      description,
+      stats,
+      price,
+      calories,
+      cta,
+      badgeFeatured,
+      badgeSeasonal,
+      badgeIced,
+      badgeCustom,
+      badgeSoldOut,
+    } = this._els;
+
+    // Title & Description
+    name.textContent = this.name;
+    description.textContent = this.description;
+    description.hidden = !this.description;
+
+    // Image & Media container
+    if (this.image) {
+      media.hidden = false;
+      if (img.getAttribute('src') !== this.image) {
+        img.setAttribute('src', this.image);
+      }
+      img.setAttribute('alt', this.name);
+    } else {
+      media.hidden = true;
+      img.removeAttribute('src');
+    }
+
+    // Badges (boolean & string)
+    badgeFeatured.hidden = !this.featured;
+    badgeSeasonal.hidden = !this.seasonal;
+    badgeIced.hidden = !this.iced;
+    badgeSoldOut.hidden = !this.soldOut;
+
+    if (this.badge) {
+      badgeCustom.textContent = this.badge;
+      badgeCustom.hidden = false;
+    } else {
+      badgeCustom.textContent = '';
+      badgeCustom.hidden = true;
+    }
+
+    // Top metadata (roast string + numeric rating)
+    if (this.roast) {
+      roast.textContent = `${this.roast} Roast`;
+      roast.hidden = false;
+    } else {
+      roast.textContent = '';
+      roast.hidden = true;
+    }
+
+    const hasRating = this.hasAttribute('rating') && this.rating > 0;
+    if (hasRating) {
+      rating.textContent = `★ ${this.rating.toFixed(1)}`;
+      rating.setAttribute('aria-label', `Rated ${this.rating.toFixed(1)} out of 5`);
+      rating.hidden = false;
+    } else {
+      rating.textContent = '';
+      rating.hidden = true;
+    }
+    metaTop.hidden = roast.hidden && rating.hidden;
+
+    // Numeric stats (price & calories)
+    const hasPrice = this.hasAttribute('price') && this.price > 0;
+    if (hasPrice) {
+      price.textContent = `$${this.price.toFixed(2)}`;
+      price.hidden = false;
+    } else {
+      price.textContent = '';
+      price.hidden = true;
+    }
+
+    const hasCalories = this.hasAttribute('calories') && this.calories > 0;
+    if (hasCalories) {
+      calories.textContent = `${Math.round(this.calories)} cal`;
+      calories.hidden = false;
+    } else {
+      calories.textContent = '';
+      calories.hidden = true;
+    }
+    stats.hidden = price.hidden && calories.hidden;
+
+    // Call to action link
+    cta.textContent = this.soldOut ? 'Sold Out' : this.cta;
