+  <script type="module">
+    /**
+     * Accurately determines visibility state history using the Performance API.
+     */
+    function getVisibilityInfo() {
+      const entries = performance.getEntriesByType('visibility-state');
+
+      if (entries.length > 0) {
+        const firstEntry = entries[0];
+        const initiallyBackgrounded = firstEntry.name === 'hidden';
+
+        let timeBackgrounded = null;
+        for (const entry of entries) {
+          if (entry.name === 'hidden') {
+            timeBackgrounded = entry.startTime;
+            break;
+          }
+        }
+
+        return {
+          initiallyBackgrounded,
+          timeBackgrounded,
+          timestamp: timeBackgrounded ?? firstEntry.startTime,
+          note: 'Measured via VisibilityStateEntry on the performance timeline. Older document.visibilityState fallback checks are unreliable for async scripts because the user may foreground the tab before the script finishes downloading and executing.'
+        };
+      }
+
+      return getFallbackVisibilityInfo();
+    }
+
+    /**
+     * Fallback implementation using document.visibilityState.
+     * This approach is prone to race conditions if the script loads asynchronously.
+     */
+    function getFallbackVisibilityInfo() {
+      let initiallyBackgrounded = document.visibilityState === 'hidden';
+      let timeBackgrounded = initiallyBackgrounded ? 0 : null;
+
+      document.addEventListener('visibilitychange', () => {
+        if (document.visibilityState === 'hidden' && timeBackgrounded === null) {
+          timeBackgrounded = performance.now();
+        }
+      });
+
+      return {
+        get initiallyBackgrounded() {
+          return initiallyBackgrounded;
+        },
+        get timeBackgrounded() {
+          return timeBackgrounded;
+        },
+        timestamp: timeBackgrounded ?? performance.now(),
+        note: 'Fallback document.visibilityState check is unreliable for async scripts because a background tab can be foregrounded before the script executes, and performance.now() on visibilitychange lacks the internal precision of VisibilityStateEntry.startTime.'
+      };
+    }
+
+    let visibilityInfo;
+    if ('VisibilityStateEntry' in window) {
+      visibilityInfo = getVisibilityInfo();
+    } else {
+      visibilityInfo = getFallbackVisibilityInfo();
+    }
+
+    console.log(visibilityInfo);
+  </script>
+
