+        const resizeObserver = new ResizeObserver(clampCurrentPosition);
+        resizeObserver.observe(draggable);
+      }
+
+      // Single-pointer reposition controls & help toggle
+      const repositionToggleBtn = document.getElementById('reposition-toggle-btn');
+      const repositionDrawer = document.getElementById('reposition-drawer');
+      const helpToggleBtn = document.getElementById('help-toggle-btn');
+      const helpDrawer = document.getElementById('keyboard-help-drawer');
+      const collapseToggleBtn = document.getElementById('collapse-toggle-btn');
+      const quickOrderBody = document.getElementById('quick-order-body');
+
+      repositionToggleBtn?.addEventListener('click', () => {
+        const isExpanded = repositionToggleBtn.getAttribute('aria-expanded') === 'true';
+        repositionToggleBtn.setAttribute('aria-expanded', String(!isExpanded));
+        repositionDrawer.hidden = isExpanded;
+      });
+
+      helpToggleBtn?.addEventListener('click', () => {
+        const isExpanded = helpToggleBtn.getAttribute('aria-expanded') === 'true';
+        helpToggleBtn.setAttribute('aria-expanded', String(!isExpanded));
+        helpDrawer.hidden = isExpanded;
+      });
+
+      collapseToggleBtn?.addEventListener('click', () => {
+        const isExpanded = collapseToggleBtn.getAttribute('aria-expanded') === 'true';
+        collapseToggleBtn.setAttribute('aria-expanded', String(!isExpanded));
+        quickOrderBody.hidden = isExpanded;
+        collapseToggleBtn.textContent = isExpanded ? '+' : '\u2212';
+        collapseToggleBtn.setAttribute(
+          'aria-label',
+          isExpanded ? 'Expand quick order panel' : 'Minimize quick order panel'
+        );
+        clampCurrentPosition();
+      });
+
+      repositionDrawer?.addEventListener('click', (event) => {
+        const btn = event.target.closest('[data-move-action]');
+        if (!btn) return;
+
+        const rect = draggable.getBoundingClientRect();
+        const maxLeft = Math.max(0, window.innerWidth - draggable.offsetWidth);
+        const maxTop = Math.max(0, window.innerHeight - draggable.offsetHeight);
+        const action = btn.dataset.moveAction;
+
+        const actions = {
+          'dock-left': [0, rect.top, 'docked left'],
+          'dock-right': [maxLeft, rect.top, 'docked right'],
+          'dock-top': [rect.left, 0, 'docked top'],
+          'dock-bottom': [rect.left, maxTop, 'docked bottom'],
+          'move-left': [rect.left - NUDGE_STEP, rect.top, 'moved left'],
+          'move-right': [rect.left + NUDGE_STEP, rect.top, 'moved right'],
+          'move-up': [rect.left, rect.top - NUDGE_STEP, 'moved up'],
+          'move-down': [rect.left, rect.top + NUDGE_STEP, 'moved down'],
+        };
+
+        const target = actions[action];
+        if (!target) return;
+
+        moveTo(target[0], target[1]);
+        announceMove(target[2]);
+      });
+
+      // Interactive Coffee Cart state and controls
+      const cupSizeSelect = document.getElementById('cup-size-select');
+      const milkOptionSelect = document.getElementById('milk-option-select');
+      const cartItemsList = document.getElementById('cart-items-list');
+      const cartCountBadge = document.getElementById('cart-count-badge');
+      const summaryItemCount = document.getElementById('summary-item-count');
+      const summarySubtotal = document.getElementById('summary-subtotal');
+      const summaryTotal = document.getElementById('summary-total');
+      const clearCartBtn = document.getElementById('clear-cart-btn');
+      const submitOrderBtn = document.getElementById('submit-quick-order-btn');
+      const orderFeedback = document.getElementById('order-feedback');
+
+      const quantities = {
+        'maple-oat-latte': 1,
+        'dark-roast-espresso': 0,
+        'cold-brew': 1,
+      };
+
+      function updateCartUI() {
+        const sizeUpcharge = Number.parseFloat(cupSizeSelect.value) || 0;
+        let totalCount = 0;
+        let totalAmount = 0;
+
+        for (const itemEl of cartItemsList.querySelectorAll('[data-item-id]')) {
+          const id = itemEl.dataset.itemId;
+          const basePrice = Number.parseFloat(itemEl.dataset.basePrice) || 0;
+          const qty = quantities[id] ?? 0;
+          totalCount += qty;
+          totalAmount += qty * (basePrice + sizeUpcharge);
+
+          const display = itemEl.querySelector('[data-qty-display]');
+          if (display) display.textContent = String(qty);
+
+          const minusBtn = itemEl.querySelector('[data-qty-delta="-1"]');
+          if (minusBtn) minusBtn.disabled = qty <= 0;
+        }
+
+        const formattedTotal = `$${totalAmount.toFixed(2)}`;
+        cartCountBadge.textContent = String(totalCount);
+        summaryItemCount.textContent = String(totalCount);
+        summarySubtotal.textContent = formattedTotal;
+        summaryTotal.textContent = formattedTotal;
+        submitOrderBtn.disabled = totalCount === 0;
+      }
+
+      cartItemsList.addEventListener('click', (event) => {
+        const btn = event.target.closest('[data-qty-delta]');
+        if (!btn) return;
+        const itemEl = btn.closest('[data-item-id]');
+        if (!itemEl) return;
+
+        const id = itemEl.dataset.itemId;
+        const delta = Number.parseInt(btn.dataset.qtyDelta, 10) || 0;
+        quantities[id] = Math.max(0, (quantities[id] ?? 0) + delta);
+        orderFeedback.hidden = true;
+        updateCartUI();
+      });
+
+      document.querySelectorAll('[data-quick-add]').forEach((btn) => {
+        btn.addEventListener('click', () => {
+          const id = btn.dataset.quickAdd;
+          if (id in quantities) {
+            quantities[id] += 1;
+            if (quickOrderBody.hidden) {
+              collapseToggleBtn.click();
+            }
+            orderFeedback.hidden = false;
+            orderFeedback.textContent = 'Added to Quick Order Cart!';
+            updateCartUI();
+          }
+        });
+      });
+
+      cupSizeSelect.addEventListener('change', updateCartUI);
+      milkOptionSelect.addEventListener('change', () => {
+        orderFeedback.hidden = true;
+      });
+
+      clearCartBtn.addEventListener('click', () => {
+        for (const key of Object.keys(quantities)) {
+          quantities[key] = 0;
+        }
+        orderFeedback.hidden = true;
+        updateCartUI();
+      });
+
+      submitOrderBtn.addEventListener('click', () => {
+        const count = Number.parseInt(summaryItemCount.textContent, 10) || 0;
+        if (count <= 0) return;
+        const sizeLabel = cupSizeSelect.options[cupSizeSelect.selectedIndex].text.split(' ')[0];
+        const milkLabel = milkOptionSelect.value;
+        orderFeedback.hidden = false;
+        orderFeedback.textContent = `Order queued: ${count} ${sizeLabel} drink(s) with ${milkLabel} (${summaryTotal.textContent}). Ready in ~5 mins!`;
+      });
+
+      updateCartUI();
+    })();
+  </script>
