+        window.addEventListener('pointerup', stopDrag);
+      }
+
+      // Interactive Cart Logic
+      const quantities = {
+        'maple-oat-latte': 1,
+        'dark-roast-espresso': 0,
+        'cold-brew': 1
+      };
+
+      const sizeSelect = document.getElementById('cup-size-select');
+      const milkSelect = document.getElementById('milk-option-select');
+      const countBadge = document.getElementById('cart-count-badge');
+      const totalPriceEl = document.getElementById('cart-total-price');
+      const statusMsg = document.getElementById('order-status-msg');
+      const toggleBtn = document.getElementById('toggle-cart-panel');
+      const clearBtn = document.getElementById('clear-cart-btn');
+      const checkoutBtn = document.getElementById('place-quick-order-btn');
+
+      function updateCartUI() {
+        const sizeSurcharge = parseFloat(sizeSelect ? sizeSelect.value : '0') || 0;
+        let totalItems = 0;
+        let totalCost = 0;
+
+        document.querySelectorAll('.cart-item').forEach((itemEl) => {
+          const id = itemEl.getAttribute('data-item-id');
+          const basePrice = parseFloat(itemEl.getAttribute('data-base-price')) || 0;
+          const qty = quantities[id] || 0;
+          const qtyEl = itemEl.querySelector('[data-item-qty]');
+          if (qtyEl) {
+            qtyEl.textContent = String(qty);
+          }
+          totalItems += qty;
+          totalCost += qty * (basePrice + sizeSurcharge);
+        });
+
+        if (countBadge) {
+          countBadge.textContent = totalItems === 1 ? '1 item' : totalItems + ' items';
+        }
+        if (totalPriceEl) {
+          totalPriceEl.textContent = '$' + totalCost.toFixed(2);
+        }
+      }
+
+      document.querySelectorAll('.cart-item').forEach((itemEl) => {
+        const id = itemEl.getAttribute('data-item-id');
+        itemEl.querySelectorAll('[data-qty-action]').forEach((btn) => {
+          btn.addEventListener('click', () => {
+            const action = btn.getAttribute('data-qty-action');
+            if (action === 'increase') {
+              quantities[id] = (quantities[id] || 0) + 1;
+            } else if (action === 'decrease') {
+              quantities[id] = Math.max(0, (quantities[id] || 0) - 1);
+            }
+            if (statusMsg) statusMsg.classList.remove('visible');
+            updateCartUI();
+          });
+        });
+      });
+
+      document.querySelectorAll('[data-quick-add]').forEach((btn) => {
+        btn.addEventListener('click', () => {
+          const id = btn.getAttribute('data-quick-add');
+          if (id in quantities) {
+            quantities[id] += 1;
+            if (panel && panel.classList.contains('is-minimized')) {
+              panel.classList.remove('is-minimized');
+              if (toggleBtn) {
+                toggleBtn.setAttribute('aria-expanded', 'true');
+                toggleBtn.innerHTML = '&minus;';
+              }
+            }
+            updateCartUI();
+          }
+        });
+      });
+
+      if (sizeSelect) {
+        sizeSelect.addEventListener('change', updateCartUI);
+      }
+      if (milkSelect) {
+        milkSelect.addEventListener('change', () => {
+          if (statusMsg) statusMsg.classList.remove('visible');
+        });
+      }
+
+      if (clearBtn) {
+        clearBtn.addEventListener('click', () => {
+          Object.keys(quantities).forEach((k) => {
+            quantities[k] = 0;
+          });
+          if (statusMsg) statusMsg.classList.remove('visible');
+          updateCartUI();
+        });
+      }
+
+      if (checkoutBtn) {
+        checkoutBtn.addEventListener('click', () => {
+          const totalItems = Object.values(quantities).reduce((a, b) => a + b, 0);
+          if (!statusMsg) return;
+          if (totalItems === 0) {
+            statusMsg.textContent = 'Add at least one coffee to place a quick order.';
+            statusMsg.classList.add('visible');
+            return;
+          }
+          const milk = milkSelect ? milkSelect.value : 'Standard';
+          statusMsg.textContent = 'Order queued (' + totalItems + 'x, ' + milk + ')! Ready in ~5 mins.';
+          statusMsg.classList.add('visible');
+        });
+      }
+
+      if (toggleBtn && panel) {
+        toggleBtn.addEventListener('click', () => {
+          const isMin = panel.classList.toggle('is-minimized');
+          toggleBtn.setAttribute('aria-expanded', String(!isMin));
+          toggleBtn.innerHTML = isMin ? '+' : '&minus;';
+        });
+      }
+
+      updateCartUI();
+    })();
+  </script>
 </body>

 </html>

