+
+    <!-- VIEW: Top News -->
+    <div
+        id="view-top-news"
+        data-spa-view="top-news"
+        data-spa-title="Top News - The DevTools Times"
+        tabindex="-1"
+        aria-hidden={initialView === 'top-news' ? 'false' : 'true'}
+        inert={initialView !== 'top-news' ? true : undefined}
+        class={`spa-view ${initialView === 'top-news' ? '' : 'inactive'}`}
+    >
