+
+        const hash = window.location.hash.replace(/^#/, '').toLowerCase();
+        if (VALID_VIEWS.has(hash)) {
+            return hash;
+        }
+
+        const path = window.location.pathname.replace(/\/+$/, '');
+        if (path.endsWith('/multimedia')) return 'multimedia';
+        if (path.endsWith('/reports')) return 'reports';
+        if (path.endsWith('/category/politics')) return 'politics';
+        if (path.endsWith('/category/world')) return 'world';
+        if (path.endsWith('/category/top-news')) return 'top-news';
+
+        const params = new URLSearchParams(window.location.search);
+        const sectionParam = params.get('section')?.toLowerCase();
+        if (sectionParam && VALID_VIEWS.has(sectionParam)) {
+            return sectionParam;
+        }
+
+        const baseUrl = getBaseUrl().replace(/\/+$/, '');
+        if (path === baseUrl || path === '') {
+            return 'home';
+        }
+
+        return null;
+    }
+
+    function switchToView(viewId: string, options: { pushState?: boolean; moveFocus?: boolean } = {}) {
+        const { pushState = false, moveFocus = true } = options;
+        if (!VALID_VIEWS.has(viewId)) return;
+
+        const activeView = document.getElementById(`view-${viewId}`);
+        if (!activeView) return;
+
+        // Hide all inactive SPA views while preserving their rendered DOM & state via content-visibility: hidden
+        document.querySelectorAll<HTMLElement>('.spa-view').forEach((view) => {
+            if (view !== activeView) {
+                view.classList.add('inactive');
+                view.setAttribute('aria-hidden', 'true');
+                view.setAttribute('inert', 'inert');
+            }
+        });
+
+        // Show target view
+        activeView.classList.remove('inactive');
+        activeView.setAttribute('aria-hidden', 'false');
+        activeView.removeAttribute('inert');
+
+        const nextTitle = activeView.dataset.spaTitle;
+        if (nextTitle) {
+            document.title = nextTitle;
+        }
+
+        if (pushState) {
+            const targetUrl = getUrlForView(viewId);
+            if (window.location.pathname + window.location.hash !== targetUrl) {
+                window.history.pushState({ spaView: viewId }, '', targetUrl);
+            }
+        }
+
+        if (moveFocus) {
+            // Move focus to the new view to ensure a logical tab-order
+            activeView.focus({ preventScroll: true });
+        }
+
+        window.dispatchEvent(new CustomEvent('spa-view-changed', { detail: { viewId } }));
+    }
+
+    function initSpaNavigation() {
+        const root = document.getElementById('spa-views-root');
+        if (!root) return;
+
+        const initialFromUrl = resolveViewFromLocation();
+        if (initialFromUrl) {
+            switchToView(initialFromUrl, { pushState: false, moveFocus: false });
+        }
+    }
+
+    // Listen for custom navigation events from React components (BottomNav, FlyoutMenu)
+    window.addEventListener('spa-navigate', (e: Event) => {
+        const detail = (e as CustomEvent<{ viewId: string; pushState?: boolean }>).detail;
+        if (detail?.viewId) {
+            switchToView(detail.viewId, { pushState: detail.pushState ?? true, moveFocus: true });
+        }
+    });
+
+    // Intercept clicks on any [data-spa-nav] link (such as logo or section links) when SPA views exist on the page
+    document.addEventListener(
+        'click',
+        (e: MouseEvent) => {
+            if (e.defaultPrevented || e.button !== 0 || e.metaKey || e.ctrlKey || e.shiftKey || e.altKey) {
+                return;
+            }
+            const target = (e.target as Element | null)?.closest<HTMLAnchorElement>('a[data-spa-nav]');
+            if (!target) return;
+
+            const viewId = target.dataset.spaNav;
+            if (viewId && document.getElementById(`view-${viewId}`)) {
+                e.preventDefault();
+                e.stopPropagation();
+                switchToView(viewId, { pushState: true, moveFocus: true });
+            }
+        },
+        { capture: true }
+    );
+
+    window.addEventListener('popstate', () => {
+        const viewId = resolveViewFromLocation();
+        if (viewId) {
+            switchToView(viewId, { pushState: false, moveFocus: true });
+        }
+    });
+
+    window.addEventListener('hashchange', () => {
+        const viewId = resolveViewFromLocation();
+        if (viewId) {
+            switchToView(viewId, { pushState: false, moveFocus: true });
+        }
+    });
+
+    document.addEventListener('astro:page-load', initSpaNavigation);
+    initSpaNavigation();
+</script>
