+import React, { useState, useEffect, useCallback, Activity } from 'react';
+import FlyoutMenu from './FlyoutMenu';
+import BookmarkButton from './BookmarkButton';
+import AdSlotBanner from './AdSlotBanner';
+import { BookOpenIcon } from '@heroicons/react/24/outline';
+
+export interface SerializedArticle {
+  id: string;
+  slug: string;
+  data: {
+    title: string;
+    summary: string;
+    author: string;
+    date: string;
+    category: string;
+    image: string;
+    imageSrc: string;
+    image_caption?: string;
+    readingTime?: number;
+  };
+}
+
+export interface SerializedItem {
+  id: string;
+  slug: string;
+  body?: string;
+  data: {
+    title: string;
+    description: string;
+    publishDate: string;
+    category: string;
+  };
+}
+
+export type ViewId = string;
+
+interface SpaSectionRouterProps {
+  baseUrl?: string;
+  initialView?: ViewId;
+  categories?: string[];
+  articles: SerializedArticle[];
+  reports: SerializedItem[];
+  multimedia: SerializedItem[];
+  initialReadingList?: string[];
+  topArticle?: SerializedArticle;
+  topStories?: SerializedArticle[];
+  topNewsArticles?: SerializedArticle[];
+  worldNewsArticles?: SerializedArticle[];
+  politicsArticles?: SerializedArticle[];
+}
+
+const SECTION_TABS = [
+  { id: 'home', label: 'All Sections', path: '' },
+  { id: 'top-news', label: 'Top News', path: 'section/top-news' },
+  { id: 'world', label: 'World', path: 'section/world' },
+  { id: 'politics', label: 'Politics', path: 'category/politics' },
+  { id: 'multimedia', label: 'Multimedia', path: 'multimedia' },
+  { id: 'reports', label: 'Reports', path: 'reports' },
+];
+
+const GROUPED_CATEGORIES: Record<string, string[]> = {
+  'News & Politics': ['news', 'National', 'Politics', 'Economy', 'Labor', 'Business'],
+  'Arts & Culture': ['Culture', 'Media'],
+  'Science & Tech': ['science'],
+  'Lifestyle & Sports': ['lifestyle', 'sports', 'Urban Development'],
+};
+
+function capitalize(str: string): string {
+  if (!str) return '';
+  return str.charAt(0).toUpperCase() + str.slice(1);
+}
+
+function resolveViewFromLocation(baseUrl: string, defaultView: string = 'home'): string {
+  if (typeof window === 'undefined') return defaultView;
+  const url = new URL(window.location.href);
+  const sectionParam = url.searchParams.get('section') || url.searchParams.get('view');
+  if (sectionParam) {
+    const lower = sectionParam.toLowerCase();
+    if (lower === 'all' || lower === 'home') return 'home';
+    if (lower === 'top-news' || lower === 'top news' || lower === 'topnews') return 'top-news';
+    if (lower === 'world') return 'world';
+    if (lower === 'politics') return 'politics';
+    if (lower === 'multimedia') return 'multimedia';
+    if (lower === 'reports') return 'reports';
+    return `category:${decodeURIComponent(lower)}`;
+  }
+
+  let pathname = url.pathname;
+  const cleanBase = baseUrl.replace(/\/$/, '');
+  if (cleanBase && pathname.startsWith(cleanBase)) {
+    pathname = pathname.slice(cleanBase.length);
+  }
+  pathname = pathname.replace(/^\/+|\/+$/g, '');
+
+  if (!pathname) return defaultView;
+  if (pathname === 'multimedia') return 'multimedia';
+  if (pathname === 'reports') return 'reports';
+  if (pathname === 'section/top-news' || pathname === 'top-news') return 'top-news';
+  if (pathname === 'section/world' || pathname === 'world') return 'world';
+  if (pathname === 'section/politics') return 'politics';
+
+  if (pathname.startsWith('category/')) {
+    const cat = decodeURIComponent(pathname.slice('category/'.length)).toLowerCase();
+    if (cat === 'top-news' || cat === 'top news') return 'top-news';
+    if (cat === 'world') return 'world';
+    if (cat === 'politics') return 'politics';
+    return `category:${cat}`;
+  }
+
+  return defaultView;
+}
+
+function getUrlForView(baseUrl: string, viewId: string): string {
+  const base = baseUrl.endsWith('/') ? baseUrl : `${baseUrl}/`;
+  if (viewId === 'home') return base;
+  if (viewId === 'top-news') return `${base}?section=top-news`;
+  if (viewId === 'world') return `${base}?section=world`;
+  if (viewId === 'politics') return `${base}category/politics`;
+  if (viewId === 'multimedia') return `${base}multimedia`;
+  if (viewId === 'reports') return `${base}reports`;
+  if (viewId.startsWith('category:')) {
+    const cat = viewId.slice('category:'.length);
+    return `${base}category/${encodeURIComponent(cat)}`;
+  }
+  return base;
+}
