+                {article.data.readingTime} Min.
+              </span>
+              <BookmarkButton slug={article.id} initialIsBookmarked={isBookmarked} />
+            </div>
+          </div>
+          <div className="lg:col-span-2">
+            <a href={`${baseUrl}articles/${article.id}`}>
+              <img
+                src={article.data.imageSrc}
+                alt={article.data.title}
+                width={800}
+                height={533}
+                className="w-full h-auto object-cover"
+              />
+            </a>
+          </div>
+        </div>
+      </div>
+    );
+  }
+
+  return (
+    <article className="flex flex-col h-full group">
+      <a href={`${baseUrl}articles/${article.id}`}>
+        <img
+          src={article.data.imageSrc}
+          alt={article.data.title}
+          width={400}
+          height={225}
+          className="w-full object-cover rounded-md flex-shrink-0 aspect-[16/9]"
+        />
+      </a>
+      <div className="flex flex-col flex-grow mt-3">
+        <a
+          href={`${baseUrl}category/${article.data.category.toLowerCase()}`}
+          onClick={(e) => onNavigateCategory(article.data.category, e)}
+          className="text-amber-800 text-sm font-brand tracking-widest hover:underline"
+        >
+          {capitalizedCategory}
+        </a>
+        <a href={`${baseUrl}articles/${article.id}`} className="flex flex-col flex-grow">
+          <h3 className="text-lg md:text-xl font-brand text-gray-800 group-hover:text-amber-400 transition-colors flex-grow">
+            {article.data.title}
+          </h3>
+          <p className="text-gray-600 mt-1">{article.data.summary}</p>
+        </a>
+        <div className="flex justify-between text-gray-500 mt-2 pt-2 border-t-1 border-gray-100">
+          <span className="text-sm font-medium flex items-center">
+            <BookOpenIcon className="w-4 h-4 inline-block mr-1 -mt-px" />
+            {article.data.readingTime} Min.
+          </span>
+          <BookmarkButton slug={article.id} initialIsBookmarked={isBookmarked} />
+        </div>
+      </div>
+    </article>
+  );
+};
+
+const TopStoryTeaserGridView: React.FC<{
