+---
+import Layout from '../../layouts/Layout.astro';
+import { getCollection } from 'astro:content';
+import SpaSectionRouter from '../../components/SpaSectionRouter';
+import { serializeHomePageData, serializeCollectionItems } from '../../utils/spaData';
+
+const { section } = Astro.params;
+const lowerSection = (section || 'home').toLowerCase();
+
+const rawArticles = await getCollection('articles');
+const rawReports = await getCollection('reports');
+const rawMultimedia = await getCollection('multimedia');
+
+const {
+    articles,
+    topArticle,
+    topStories,
+    topNewsArticles,
+    worldNewsArticles,
+    politicsArticles,
+} = await serializeHomePageData(rawArticles);
+
+const reports = serializeCollectionItems(rawReports);
+const multimedia = serializeCollectionItems(rawMultimedia);
+const categories = [...new Set(rawArticles.map((article) => article.data.category))];
+const readingList = (await Astro.session?.get('readingList')) || [];
+const baseUrl = import.meta.env.BASE_URL;
+
+const initialView =
+    lowerSection === 'top-news' || lowerSection === 'top news'
+        ? 'top-news'
+        : lowerSection === 'world'
+        ? 'world'
+        : lowerSection === 'politics'
+        ? 'politics'
+        : lowerSection === 'multimedia'
+        ? 'multimedia'
+        : lowerSection === 'reports'
+        ? 'reports'
+        : 'home';
+
+const titleMap: Record<string, string> = {
+    'top-news': 'Top News | The DevTools Times',
+    'world': 'World | The DevTools Times',
+    'politics': 'Politics | The DevTools Times',
+    'multimedia': 'Multimedia | The DevTools Times',
+    'reports': 'Reports | The DevTools Times',
+};
+---
+
+<Layout title={titleMap[initialView] || 'The DevTools Times'}>
+    <SpaSectionRouter
+        client:load
+        baseUrl={baseUrl}
+        initialView={initialView}
+        categories={categories}
+        articles={articles}
+        reports={reports}
+        multimedia={multimedia}
+        initialReadingList={readingList}
+        topArticle={topArticle}
+        topStories={topStories}
+        topNewsArticles={topNewsArticles}
+        worldNewsArticles={worldNewsArticles}
+        politicsArticles={politicsArticles}
+    />
+</Layout>
