--- /dev/null
+++ b/src/utils/spaData.ts
@@ -0,0 +1,82 @@
+import type { CollectionEntry } from 'astro:content';
+import { getArticleImage } from './images';
+import type { SerializedArticle, SerializedItem } from '../components/SpaSectionRouter';
+
+export async function serializeArticle(article: CollectionEntry<'articles'>): Promise<SerializedArticle> {
+  const imageMetaOrUrl = await getArticleImage(article);
+  const imageSrc = typeof imageMetaOrUrl === 'string' ? imageMetaOrUrl : imageMetaOrUrl.src;
+
+  return {
+    id: article.id,
+    slug: article.slug || article.id,
+    data: {
+      title: article.data.title,
+      summary: article.data.summary,
+      author: article.data.author,
+      date: article.data.date instanceof Date ? article.data.date.toISOString() : String(article.data.date),
+      category: article.data.category,
+      image: article.data.image,
+      imageSrc,
+      image_caption: article.data.image_caption,
+      readingTime: article.data.readingTime,
+    },
+  };
+}
+
+export async function serializeHomePageData(articles: CollectionEntry<'articles'>[]) {
+  const sorted = [...articles].sort((a, b) => b.data.date.valueOf() - a.data.date.valueOf());
+  const serializedAll = await Promise.all(sorted.map(serializeArticle));
+
+  const topArticle = serializedAll[0];
+  const topStories = serializedAll.slice(1, 4);
+  const topNewsArticles = serializedAll.slice(4, 8);
+  const worldNewsArticles = serializedAll.slice(8, 11);
+  const politicsArticles = [...serializedAll.slice(11, 15)];
+
+  // Preserve the fake What's new in DevTools post in politicsArticles[2]
+  if (politicsArticles.length >= 3) {
+    politicsArticles[2] = {
+      id: 'public-transit-overhaul',
+      slug: 'public-transit-overhaul',
+      data: {
+        title: "What's new in DevTools",
+        summary:
+          'Learn about what is new in Chrome DevTools 144: from request conditions to performance debugging, we got you covered.',
+        author: 'Chrome DevTools Team',
+        date: new Date('2025-09-16T00:00:00.000Z').toISOString(),
+        category: 'Web Development',
+        image:
+          'https://cinemai-1026410574114.us-central1.run.app/cinemai/_next/image?url=%2Fcinemai%2F_next%2Fstatic%2Fmedia%2Fthumbnail-wndt-139-141.45ba64a6.jpg&w=3840&q=75',
+        imageSrc:
+          'https://cinemai-1026410574114.us-central1.run.app/cinemai/_next/image?url=%2Fcinemai%2F_next%2Fstatic%2Fmedia%2Fthumbnail-wndt-139-141.45ba64a6.jpg&w=3840&q=75',
+        image_caption: '',
+        readingTime: 3,
+      },
+    };
+  }
+
+  return {
+    articles: serializedAll,
+    topArticle,
+    topStories,
+    topNewsArticles,
+    worldNewsArticles,
+    politicsArticles,
+  };
+}
+
+export function serializeCollectionItems(
+  items: (CollectionEntry<'reports'> | CollectionEntry<'multimedia'>)[]
+): SerializedItem[] {
+  return items.map((item) => ({
+    id: item.id,
+    slug: (item as any).slug || item.id,
+    body: item.body,
+    data: {
+      title: item.data.title,
+      description: item.data.description,
+      publishDate: item.data.publishDate,
+      category: item.data.category,
+    },
+  }));
+}

