+  <meta charset="utf-8">
+  <meta name="viewport" content="width=device-width, initial-scale=1.0">
+  <title>Nexus Cloud — Ship Faster, Experiment Confidently</title>
+  <link rel="preconnect" href="https://cdn.example.com">
+
+  <!--
+    MANDATORY: Load the experimentation script in <head> with both `async` and `blocking="render"`.
+    - `async`: Prevents parser-blocking, allowing the browser to continue building the DOM in parallel.
+    - `blocking="render"`: Holds first paint until the script executes, ensuring experiment changes
+      are applied before the user sees any content (zero flicker).
+  -->
+  <script
+    src="https://cdn.example.com/experiment-sdk.js"
+    async
+    blocking="render"
+  ></script>
+
+  <script>
+    // Feature-detect blocking="render" support and apply a lightweight anti-flicker fallback
+    // only in browsers that do not support it natively (e.g., Firefox).
+    if (!Object.hasOwn(HTMLScriptElement.prototype, 'blocking')) {
+      document.documentElement.classList.add('ab-loading');
+
+      // Fallback timeout so the page never remains blank indefinitely if the CDN stalls.
+      setTimeout(() => {
+        document.documentElement.classList.remove('ab-loading');
+      }, 4000);
+    }
+
+    // Expose initialization hook for the experiment SDK to reveal the page immediately in fallback browsers.
+    window.onExperimentReady = function onExperimentReady() {
+      document.documentElement.classList.remove('ab-loading');
+    };
+  </script>
+
+  <style>
+    /* Fallback anti-flicker rule applied only when blocking="render" is unsupported */
+    .ab-loading {
+      opacity: 0 !important;
+    }
