+      };
+
+      const validateStep = (stepIndex) => {
+        const stepEl = steps[stepIndex];
+        if (!stepEl) return true;
+        const controls = [...stepEl.querySelectorAll('input, select, textarea')];
+        let firstInvalid = null;
+
+        for (const control of controls) {
+          control.setCustomValidity('');
+          if (!control.checkValidity()) {
+            if (!firstInvalid) firstInvalid = control;
+          }
+          if (control.name === 'favorite_roast') {
+            syncAria(control, false, true);
+          }
+        }
+
+        if (firstInvalid) {
+          firstInvalid.focus();
+          announceError(firstInvalid);
+          return false;
+        }
+        return true;
+      };
+
+      const goToStep = (targetIndex) => {
+        if (targetIndex < 0 || targetIndex >= steps.length) return;
+        currentStepIndex = targetIndex;
+
+        steps.forEach((stepEl, idx) => {
+          const isActive = idx === targetIndex;
+          stepEl.hidden = !isActive;
+          if (isActive) {
+            stepEl.removeAttribute('inert');
+          } else {
+            stepEl.setAttribute('inert', '');
+          }
+        });
+
+        trackerItems.forEach((item, idx) => {
+          const labelSpan = item.querySelector('.step-label');
+          const badgeSpan = item.querySelector('.step-badge');
+          if (idx < targetIndex) {
+            item.classList.add('step-done');
+            item.removeAttribute('aria-current');
+            if (labelSpan) labelSpan.textContent = `${stepLabels[idx]} (completed)`;
+            if (badgeSpan) badgeSpan.textContent = '✓';
+          } else if (idx === targetIndex) {
+            item.classList.remove('step-done');
+            item.setAttribute('aria-current', 'step');
+            if (labelSpan) labelSpan.textContent = stepLabels[idx];
+            if (badgeSpan) badgeSpan.textContent = String(idx + 1);
+          } else {
+            item.classList.remove('step-done');
+            item.removeAttribute('aria-current');
+            if (labelSpan) labelSpan.textContent = stepLabels[idx];
+            if (badgeSpan) badgeSpan.textContent = String(idx + 1);
+          }
+        });
+
+        if (progressBar) {
+          progressBar.value = targetIndex + 1;
+          progressBar.textContent = `Step ${targetIndex + 1} of ${steps.length}`;
+        }
+
+        if (targetIndex === 2) {
+          updateSummary();
+        }
+
+        const activeHeading = steps[targetIndex].querySelector('.step-heading');
+        if (activeHeading) {
+          activeHeading.focus();
+        }
+      };
+
+      document.getElementById('next-to-step-2')?.addEventListener('click', () => {
+        if (validateStep(0)) goToStep(1);
+      });
+
+      document.getElementById('back-to-step-1')?.addEventListener('click', () => {
+        goToStep(0);
+      });
+
+      document.getElementById('next-to-step-3')?.addEventListener('click', () => {
+        if (validateStep(1)) goToStep(2);
+      });
+
+      document.getElementById('back-to-step-2')?.addEventListener('click', () => {
+        goToStep(1);
+      });
