+            duration: attr.longestScript.entry.duration,
+            forcedStyleAndLayoutDuration:
+              attr.longestScript.entry.forcedStyleAndLayoutDuration || 0,
+            pauseDuration: attr.longestScript.entry.pauseDuration || 0,
+            windowAttribution: attr.longestScript.entry.windowAttribution || 'self',
+          }
+        : null;
+
+      return {
+        name: metric.name,
+        id: metric.id,
+        value: metric.value,
+        delta: metric.delta,
+        rating: metric.rating,
+        navigationType: metric.navigationType,
+        isSlowInteraction: metric.value > SLOW_INTERACTION_THRESHOLD_MS,
+        page: window.location.pathname,
+        timestamp: Date.now(),
+        attribution: {
+          interactionTarget: attr.interactionTarget || '',
+          interactionType: attr.interactionType || '',
+          interactionTime,
+          nextPaintTime,
+          loadState: attr.loadState || '',
+          // Interaction sub-part phases
+          phases: {
+            inputDelay,
+            processingDuration,
+            presentationDelay,
+            totalScriptDuration: attr.totalScriptDuration ?? 0,
+            totalStyleAndLayoutDuration: attr.totalStyleAndLayoutDuration ?? 0,
+            totalPaintDuration: attr.totalPaintDuration ?? 0,
