+      /**
+       * Wait until the browser finishes painting the visual updates scheduled in the current frame.
+       * First rAF runs right before style/layout/paint of the next frame;
+       * Second rAF runs immediately on the frame after the paint has been committed.
+       */
+      function afterNextPaint(callback) {
+        requestAnimationFrame(function (raf1Timestamp) {
+          requestAnimationFrame(function (raf2Timestamp) {
+            callback(performance.now(), raf1Timestamp, raf2Timestamp);
+          });
+        });
+      }
+
+      function formatMs(val) {
+        return val.toFixed(2) + ' ms';
+      }
+
+      function computeAverage(list) {
+        if (!list || list.length === 0) return 0;
+        const total = list.reduce(function (acc, item) { return acc + item.duration; }, 0);
+        return total / list.length;
+      }
+
+      /**
+       * Record a completed paint timing measurement, create User Timing marks/measures,
+       * update the on-page monitoring dashboard, and emit custom events.
+       */
+      function recordPaintMetric(entryData) {
+        metricsState.seq += 1;
+        const id = metricsState.seq;
+        const duration = Math.max(0.01, Number(entryData.duration));
+        const record = {
+          id: id,
+          category: entryData.category,
+          type: entryData.type || (entryData.category === 'view-switch' ? 'view-switch' : 'click'),
+          target: entryData.target,
+          view: entryData.view || metricsState.currentView,
+          fromView: entryData.fromView || null,
+          toView: entryData.toView || entryData.view || metricsState.currentView,
+          startTime: entryData.startTime,
+          prePaintTime: entryData.prePaintTime,
+          paintTime: entryData.paintTime,
+          duration: duration,
+          timestamp: Date.now()
+        };
+
+        metricsState.entries.push(record);
+        if (metricsState.byCategory[record.category]) {
+          metricsState.byCategory[record.category].push(record);
+        }
+
+        // User Timing API: performance.mark & performance.measure
+        try {
+          const safeTarget = String(record.target).replace(/[^a-zA-Z0-9_-]/g, '_');
+          const startMark = 'dg-' + record.category + '-' + safeTarget + '-' + id + '-start';
+          const endMark = 'dg-' + record.category + '-' + safeTarget + '-' + id + '-paint-end';
+          const measureName = record.category + ':' + record.target;
+
+          performance.mark(startMark, { startTime: record.startTime });
+          performance.mark(endMark, { startTime: record.paintTime });
+          performance.measure(measureName, {
+            start: startMark,
+            end: endMark,
+            detail: record
+          });
+        } catch (err) {
+          // Fallback for environments with basic User Timing implementation
+          try {
+            performance.measure(record.category + ':' + record.target);
+          } catch (_) {}
+        }
+
+        updateDashboardUI(record);
+
+        console.info(
+          '[DailyGrind PerfMonitor] ' +
+          record.category + ' ("' + record.target + '") finished painting in ' +
+          formatMs(record.duration),
+          record
+        );
+
+        try {
+          window.dispatchEvent(new CustomEvent('perf-metric', { detail: record }));
+          window.dispatchEvent(new CustomEvent('paint-complete', { detail: record }));
+        } catch (_) {}
