+
+    function updateCounts() {
+      for (const col of columns) {
+        const status = col.dataset.status;
+        const countEl = col.querySelector(`[data-count-for="${status}"]`);
+        const list = col.querySelector('.column-list') || col;
+        if (countEl) {
+          countEl.textContent = String(list.querySelectorAll('.card').length);
+        }
+      }
+    }
+
+    function announceMove(card, targetColumn) {
+      if (!announcer || !card || !targetColumn) return;
+      const title = card.querySelector('h3')?.textContent?.trim() || 'Order';
+      const orderId = card.querySelector('.order-id')?.textContent?.trim() || '';
+      const status = statusLabels[targetColumn.dataset.status] || targetColumn.dataset.status;
+      announcer.textContent = '';
+      clearTimeout(announceTimer);
+      announceTimer = setTimeout(() => {
+        announcer.textContent = `Moved ${title} ${orderId} to ${status}.`;
+      }, 150);
+    }
+
+    function getInsertionReference(list, clientY, activeCard) {
+      const siblings = Array.from(list.querySelectorAll('.card')).filter(c => c !== activeCard);
+      for (const sibling of siblings) {
+        const rect = sibling.getBoundingClientRect();
+        const midpoint = rect.top + rect.height / 2;
+        if (clientY < midpoint) {
+          return sibling;
+        }
+      }
+      return null;
+    }
+
+    function moveCardToColumn(card, targetColumn, referenceNode = null, focusSelector = null) {
+      const list = targetColumn.querySelector('.column-list') || targetColumn;
+      const performDOMMove = () => {
+        if ('moveBefore' in Element.prototype && card.parentElement === list) {
+          list.moveBefore(card, referenceNode);
+        } else if (referenceNode) {
+          referenceNode.before(card);
+        } else {
+          list.appendChild(card);
+        }
+        updateCounts();
+        if (focusSelector) {
+          const btnToFocus = card.querySelector(focusSelector);
+          if (btnToFocus && getComputedStyle(btnToFocus).display !== 'none') {
+            btnToFocus.focus({ preventScroll: true });
+          } else {
+            const altDir = focusSelector.includes('next') ? 'prev' : 'next';
+            const fallbackBtn = card.querySelector(`.move-btn[data-dir="${altDir}"]`);
+            fallbackBtn?.focus({ preventScroll: true });
+          }
+        }
+      };
+
+      if (document.startViewTransition) {
+        document.startViewTransition(() => performDOMMove());
+      } else {
