+        if (!card) return;
+
+        const list = column.querySelector('.column-list') || column;
+        const referenceNode = getInsertionReference(list, event.clientY, card);
+        if (card.parentElement === list && referenceNode === card.nextElementSibling) {
+          return;
+        }
+        moveCardToColumn(card, column, referenceNode);
