+            customer: 'Marcus Vance',
+            drink: 'Caramel Macchiato',
+            size: '16oz Grande',
+            notes: 'Extra caramel crosshatch, blonde roast',
+            time: '6m ago'
+          }
+        ]
+      };
+
+      let nextOrderNumber = 107;
+      let draggedOrderId = null;
+      let draggedSourceStatus = null;
+
+      // Isolated column renderer Registry: each column manages its own DOM subtree independently
+      const columnRenderers = {};
+
+      function createCardElement(order, status) {
+        const card = document.createElement('div');
+        card.className = 'card';
+        card.draggable = true;
+        card.id = 'order-' + order.id;
+        card.dataset.orderId = order.id;
+        card.dataset.status = status;
+
+        const statusIndex = COLUMNS.indexOf(status);
+        const prevStatus = statusIndex > 0 ? COLUMNS[statusIndex - 1] : null;
+        const nextStatus = statusIndex < COLUMNS.length - 1 ? COLUMNS[statusIndex + 1] : null;
+
+        const topRow = document.createElement('div');
+        topRow.className = 'order-card-top';
+
+        const idBadge = document.createElement('span');
+        idBadge.className = 'order-id';
+        idBadge.textContent = '#' + order.id;
+
+        const timeLabel = document.createElement('span');
+        timeLabel.className = 'order-time';
+        timeLabel.textContent = order.time;
+
+        topRow.appendChild(idBadge);
+        topRow.appendChild(timeLabel);
+
+        const drinkTitle = document.createElement('h3');
+        drinkTitle.textContent = order.drink;
+
+        const customerEl = document.createElement('div');
+        customerEl.className = 'order-customer';
+        customerEl.textContent = 'For: ' + order.customer;
+
+        const notesEl = document.createElement('div');
+        notesEl.className = 'order-notes';
+        notesEl.textContent = order.notes || 'Standard preparation';
+
+        const footerEl = document.createElement('div');
+        footerEl.className = 'order-footer';
+
+        const sizeBadge = document.createElement('span');
+        sizeBadge.className = 'order-size-badge';
+        sizeBadge.textContent = order.size;
+
+        const actionsEl = document.createElement('div');
+        actionsEl.className = 'order-actions';
+
+        if (prevStatus) {
+          const prevBtn = document.createElement('button');
+          prevBtn.type = 'button';
+          prevBtn.className = 'order-move-btn';
+          prevBtn.title = 'Move back to ' + prevStatus;
+          prevBtn.textContent = '←';
+          prevBtn.addEventListener('click', function (e) {
+            e.stopPropagation();
+            moveOrder(order.id, status, prevStatus);
+          });
+          actionsEl.appendChild(prevBtn);
+        }
+
+        if (nextStatus) {
+          const nextBtn = document.createElement('button');
+          nextBtn.type = 'button';
+          nextBtn.className = 'order-move-btn';
+          nextBtn.title = 'Advance to ' + nextStatus;
+          nextBtn.textContent = '→';
+          nextBtn.addEventListener('click', function (e) {
+            e.stopPropagation();
+            moveOrder(order.id, status, nextStatus);
+          });
+          actionsEl.appendChild(nextBtn);
+        }
+
+        footerEl.appendChild(sizeBadge);
+        footerEl.appendChild(actionsEl);
+
+        card.appendChild(topRow);
+        card.appendChild(drinkTitle);
+        card.appendChild(customerEl);
+        card.appendChild(notesEl);
+        card.appendChild(footerEl);
+
+        // Card Drag Events
+        card.addEventListener('dragstart', function (e) {
+          draggedOrderId = order.id;
+          draggedSourceStatus = status;
+          card.classList.add('dragging');
+          if (e.dataTransfer) {
+            e.dataTransfer.effectAllowed = 'move';
+            e.dataTransfer.setData('text/plain', order.id);
+            e.dataTransfer.setData('application/x-order-source', status);
+          }
+        });
+
+        card.addEventListener('dragend', function () {
+          card.classList.remove('dragging');
+          draggedOrderId = null;
+          draggedSourceStatus = null;
+          document.querySelectorAll('.board-column.drag-over').forEach(function (col) {
+            col.classList.remove('drag-over');
+          });
+        });
+
+        return card;
+      }
+
+      // Initialize isolated column controller for a single status column
+      function initIsolatedColumn(status) {
+        const columnEl = document.querySelector('.board-column[data-status="' + status + '"]');
+        const cardsContainer = columnEl.querySelector('[data-cards-for="' + status + '"]');
+        const countBadge = columnEl.querySelector('[data-count-for="' + status + '"]');
+
+        let renderCount = 0;
+
+        // Render only this specific column's cards and count badge without touching sibling columns
+        function renderColumn() {
+          const orders = columnState[status] || [];
+          countBadge.textContent = String(orders.length);
+
+          // Reconcile cards container exclusively for this column
+          cardsContainer.replaceChildren();
+
+          if (orders.length === 0) {
+            const emptyEl = document.createElement('div');
+            emptyEl.className = 'empty-column-placeholder';
+            emptyEl.textContent = 'No ' + status + ' orders right now';
+            cardsContainer.appendChild(emptyEl);
+          } else {
+            const fragment = document.createDocumentFragment();
+            orders.forEach(function (order) {
+              fragment.appendChild(createCardElement(order, status));
+            });
+            cardsContainer.appendChild(fragment);
+          }
+
+          renderCount += 1;
+          columnEl.dataset.renderCount = String(renderCount);
+        }
+
+        // Column Drag & Drop listeners
+        columnEl.addEventListener('dragover', function (e) {
+          e.preventDefault();
+          if (e.dataTransfer) {
+            e.dataTransfer.dropEffect = 'move';
+          }
+          if (!columnEl.classList.contains('drag-over')) {
+            columnEl.classList.add('drag-over');
+          }
+        });
+
+        columnEl.addEventListener('dragenter', function (e) {
+          e.preventDefault();
+          columnEl.classList.add('drag-over');
+        });
+
+        columnEl.addEventListener('dragleave', function (e) {
+          if (!columnEl.contains(e.relatedTarget)) {
+            columnEl.classList.remove('drag-over');
+          }
+        });
+
+        columnEl.addEventListener('drop', function (e) {
+          e.preventDefault();
+          columnEl.classList.remove('drag-over');
+
+          let orderId = draggedOrderId;
+          let sourceStatus = draggedSourceStatus;
+
+          if (e.dataTransfer) {
+            const transferredId = e.dataTransfer.getData('text/plain');
+            const transferredSource = e.dataTransfer.getData('application/x-order-source');
+            if (transferredId) {
+              orderId = transferredId;
+            }
+            if (transferredSource) {
+              sourceStatus = transferredSource;
+            }
+          }
+
+          // Fallback lookup if dragstart dataTransfer was synthesized without source status
+          if (orderId && !sourceStatus) {
+            for (const col of COLUMNS) {
+              if (columnState[col].some(function (o) { return o.id === orderId; })) {
+                sourceStatus = col;
+                break;
+              }
+            }
+          }
+
+          if (!orderId || !sourceStatus) {
+            return;
+          }
+
+          // Compute drop insertion index based on pointer Y position relative to cards in target column
+          const targetIndex = getDropInsertionIndex(cardsContainer, e.clientY);
+          moveOrder(orderId, sourceStatus, status, targetIndex);
+        });
+
+        columnRenderers[status] = renderColumn;
+        renderColumn();
+      }
+
+      function getDropInsertionIndex(container, clientY) {
+        const cardElements = Array.from(container.querySelectorAll('.card:not(.dragging)'));
+        if (cardElements.length === 0 || typeof clientY !== 'number' || clientY === 0) {
+          return undefined;
+        }
+        for (let i = 0; i < cardElements.length; i++) {
+          const box = cardElements[i].getBoundingClientRect();
+          const midpoint = box.top + box.height / 2;
+          if (clientY < midpoint) {
+            return i;
+          }
+        }
+        return cardElements.length;
+      }
+
+      // Move an order between columns (or reorder within a column) while keeping column rendering isolated
+      function moveOrder(orderId, fromStatus, toStatus, targetIndex) {
+        if (!columnState[fromStatus] || !columnState[toStatus]) {
+          return false;
+        }
+
+        const sourceList = columnState[fromStatus];
+        const orderIdx = sourceList.findIndex(function (o) { return o.id === orderId; });
+        if (orderIdx === -1) {
+          return false;
+        }
+
+        // If dropped in the same column at the exact same position, avoid unnecessary re-render
+        if (fromStatus === toStatus) {
+          if (targetIndex === undefined || targetIndex === orderIdx || targetIndex === orderIdx + 1) {
+            return false;
+          }
+          const [movedOrder] = sourceList.splice(orderIdx, 1);
+          const adjustedIndex = targetIndex > orderIdx ? targetIndex - 1 : targetIndex;
+          sourceList.splice(adjustedIndex, 0, movedOrder);
+          // Re-render only this single column
+          columnRenderers[toStatus]();
+          return true;
+        }
+
+        // Remove from source column state and insert into target column state
+        const [movedOrder] = sourceList.splice(orderIdx, 1);
+        movedOrder.time = 'Updated just now';
+
+        const targetList = columnState[toStatus];
+        if (typeof targetIndex === 'number' && targetIndex >= 0 && targetIndex <= targetList.length) {
+          targetList.splice(targetIndex, 0, movedOrder);
+        } else {
+          targetList.push(movedOrder);
+        }
+
+        // Render ONLY the affected columns (fromStatus and toStatus); untouched column is never re-rendered
+        columnRenderers[fromStatus]();
+        columnRenderers[toStatus]();
+        return true;
+      }
+
+      // Initialize all 3 columns independently
+      COLUMNS.forEach(initIsolatedColumn);
+
+      // Handle adding a new order into the Queued column (isolated render of 'queued' column only)
+      const addOrderForm = document.getElementById('add-order-form');
+      if (addOrderForm) {
+        addOrderForm.addEventListener('submit', function (e) {
+          e.preventDefault();
+          const customerInput = document.getElementById('order-customer-input');
+          const drinkInput = document.getElementById('order-drink-input');
+          const sizeInput = document.getElementById('order-size-input');
+          const notesInput = document.getElementById('order-notes-input');
+
+          const customer = customerInput.value.trim();
+          if (!customer) return;
+
+          const newOrder = {
+            id: 'ORD-' + nextOrderNumber++,
+            customer: customer,
+            drink: drinkInput.value,
+            size: sizeInput.value,
+            notes: notesInput.value.trim() || 'Standard preparation',
+            time: 'Just now'
+          };
+
+          columnState.queued.push(newOrder);
+          // Only re-render the 'queued' column!
+          columnRenderers.queued();
+
+          customerInput.value = '';
+          notesInput.value = '';
+        });
+      }
+    })();
+  </script>
 </body>

