+        typeof CSS.supports === 'function' &&
+        CSS.supports('anchor-name', '--tooltip-anchor');
+
+      const cards = document.querySelectorAll('.card');
+
+      function positionFallback(btn, tooltip) {
+        if (supportsAnchor) return;
+        const top = btn.offsetTop + btn.offsetHeight + 8;
+        const left = btn.offsetLeft + btn.offsetWidth / 2;
+        tooltip.style.top = top + 'px';
+        tooltip.style.left = left + 'px';
+      }
+
+      cards.forEach(function (card) {
+        const btn = card.querySelector('.btn');
+        const tooltip = card.querySelector('.tooltip');
+        if (!btn || !tooltip) return;
+
+        positionFallback(btn, tooltip);
+
+        function showTooltip() {
+          positionFallback(btn, tooltip);
+          tooltip.classList.remove('is-dismissed');
+          tooltip.classList.add('is-visible');
+          tooltip.setAttribute('aria-hidden', 'false');
+        }
+
+        function hideTooltip() {
+          tooltip.classList.remove('is-visible');
+          tooltip.classList.remove('is-dismissed');
+          tooltip.setAttribute('aria-hidden', 'true');
+        }
+
+        btn.addEventListener('mouseenter', showTooltip);
+        btn.addEventListener('focus', showTooltip);
+
+        btn.addEventListener('mouseleave', function () {
+          if (document.activeElement !== btn) {
+            hideTooltip();
+          }
+        });
+
+        btn.addEventListener('blur', function () {
+          if (!btn.matches(':hover')) {
+            hideTooltip();
+          }
+        });
+
+        tooltip.addEventListener('mouseleave', function () {
+          if (document.activeElement !== btn && !btn.matches(':hover')) {
+            hideTooltip();
+          }
+        });
+      });
+
+      window.addEventListener('resize', function () {
+        if (supportsAnchor) return;
+        cards.forEach(function (card) {
+          const btn = card.querySelector('.btn');
+          const tooltip = card.querySelector('.tooltip');
+          if (btn && tooltip) {
+            positionFallback(btn, tooltip);
+          }
+        });
+      });
+
+      document.addEventListener('keydown', function (event) {
+        if (event.key === 'Escape') {
+          document.querySelectorAll('.card .tooltip').forEach(function (tooltip) {
+            tooltip.classList.remove('is-visible');
+            tooltip.classList.add('is-dismissed');
+            tooltip.setAttribute('aria-hidden', 'true');
+          });
+        }
+      });
