+        return sorted;
+      }
+
+      function createDrinkCardElement(item) {
+        const card = document.createElement('div');
+        card.className = 'card menu-card';
+        card.setAttribute('data-id', item.id);
+        card.setAttribute('data-category', item.category);
+        card.setAttribute('data-price', item.price.toFixed(2));
+
+        const badge = document.createElement('span');
+        badge.className = 'card-badge';
+        badge.textContent = item.category;
+
+        const title = document.createElement('h3');
+        title.textContent = item.name;
+
+        const desc = document.createElement('p');
+        desc.textContent = item.description;
+
+        const priceEl = document.createElement('div');
+        priceEl.className = 'card-price price';
+        priceEl.textContent = formatPrice(item.price);
+
+        const addBtn = document.createElement('button');
+        addBtn.type = 'button';
+        addBtn.className = 'btn add-to-order-btn';
+        addBtn.setAttribute('data-drink-id', item.id);
+        addBtn.textContent = 'Add to Order';
+        addBtn.addEventListener('click', () => {
+          addDrinkToOrder(item);
+        });
+
+        card.appendChild(badge);
+        card.appendChild(title);
+        card.appendChild(desc);
+        card.appendChild(priceEl);
+        card.appendChild(addBtn);
+
+        return card;
+      }
+
+      function renderMenu() {
+        const items = getFilteredAndSortedItems();
+        menuListEl.replaceChildren();
+
+        if (!filterState.groupByCategory) {
+          const grid = document.createElement('div');
+          grid.className = 'grid';
+          items.forEach(item => {
+            grid.appendChild(createDrinkCardElement(item));
+          });
+          menuListEl.appendChild(grid);
+          return;
+        }
+
+        // Group by Category mode: render all 3 categories cleanly even when filtered categories have 0 matches
+        const categoryList = filterState.reverse ? [...CATEGORIES].reverse() : [...CATEGORIES];
+        const groupedWrapper = document.createElement('div');
+        groupedWrapper.className = 'grouped-menu';
+
+        CATEGORIES.forEach(cat => {
+          const catItems = items.filter(item => item.category === cat.key);
+
+          const section = document.createElement('section');
+          section.className = 'category-group category-section';
+          section.setAttribute('data-category-group', cat.key);
+          section.setAttribute('data-category', cat.key);
+          section.setAttribute('data-count', String(catItems.length));
+
+          const header = document.createElement('div');
+          header.className = 'category-group-header';
+
+          const heading = document.createElement('h3');
+          heading.textContent = `${cat.label} (${catItems.length})`;
+
+          const countBadge = document.createElement('span');
+          countBadge.className = 'category-count';
+          countBadge.textContent = `${catItems.length} ${catItems.length === 1 ? 'item' : 'items'}`;
+
+          header.appendChild(heading);
+          header.appendChild(countBadge);
+          section.appendChild(header);
+
+          if (catItems.length === 0) {
+            const emptyMsg = document.createElement('p');
+            emptyMsg.className = 'empty-category-msg';
+            emptyMsg.textContent = `No matching drinks in ${cat.label} (0 items).`;
+            section.appendChild(emptyMsg);
+          } else {
+            const grid = document.createElement('div');
+            grid.className = 'grid';
+            catItems.forEach(item => {
+              grid.appendChild(createDrinkCardElement(item));
+            });
+            section.appendChild(grid);
+          }
+
+          groupedWrapper.appendChild(section);
+        });
+
+        menuListEl.appendChild(groupedWrapper);
+      }
+
+      function dispatchFilterChangeEvent() {
+        const detail = {
+          category: filterState.category,
+          sort: filterState.sort,
+          reverse: Boolean(filterState.reverse),
+          groupByCategory: Boolean(filterState.groupByCategory),
+          group: Boolean(filterState.groupByCategory),
+          grouped: Boolean(filterState.groupByCategory)
+        };
+        const event = new CustomEvent('daily-grind:filter-change', {
+          bubbles: true,
+          cancelable: false,
+          detail
+        });
+        menuControlsEl.dispatchEvent(event);
+      }
+
+      function handleControlChange() {
+        filterState.category = VALID_CATEGORIES.includes(categorySelectEl.value)
+          ? categorySelectEl.value
+          : 'all';
+        filterState.sort = normalizeSortValue(sortSelectEl.value);
+        filterState.reverse = Boolean(reverseToggleEl.checked);
+        filterState.groupByCategory = Boolean(groupToggleEl.checked);
+        filterState.group = Boolean(groupToggleEl.checked);
+
+        syncUrlWithState();
+        renderMenu();
+        dispatchFilterChangeEvent();
+      }
+
+      function addDrinkToOrder(drink) {
+        const selectedMilk = milkSelectEl.value || 'Whole';
+        const noteText = (customerNoteEl.value || '').trim();
+        const nowIso = new Date().toISOString();
+
+        const orderEntry = {
+          orderItemId: 'order-' + Date.now() + '-' + Math.random().toString(36).slice(2, 7),
+          drinkId: drink.id,
+          name: drink.name,
+          category: drink.category,
+          price: drink.price,
+          timestamp: nowIso,
+          addedAt: nowIso,
+          options: {
+            milk: selectedMilk,
+            note: noteText,
+            customizations: {
+              milk: selectedMilk,
+              customerNote: noteText
+            }
+          }
+        };
+
+        activeDraftOrder.push(orderEntry);
+        renderDraftOrder();
+      }
+
+      function renderDraftOrder() {
+        draftOrderListEl.replaceChildren();
+
+        if (activeDraftOrder.length === 0) {
+          const emptyLi = document.createElement('li');
+          emptyLi.className = 'draft-order-empty';
+          emptyLi.textContent = 'Your draft order is empty.';
+          draftOrderListEl.appendChild(emptyLi);
+          draftOrderCountEl.textContent = '0';
+          draftOrderTotalEl.textContent = '$0.00';
+          return;
+        }
+
+        let total = 0;
+
+        activeDraftOrder.forEach((item, index) => {
+          total += Number(item.price) || 0;
+
+          const li = document.createElement('li');
+          li.className = 'draft-order-item order-item';
+          li.setAttribute('data-order-item-id', item.orderItemId);
+          li.setAttribute('data-drink-id', item.drinkId);
+
+          const header = document.createElement('div');
+          header.className = 'order-item-header';
+
+          const titleSpan = document.createElement('span');
+          titleSpan.className = 'order-item-name';
+          titleSpan.textContent = item.name;
+
+          const priceSpan = document.createElement('span');
+          priceSpan.className = 'order-item-price';
+          priceSpan.textContent = formatPrice(item.price);
+
+          header.appendChild(titleSpan);
+          header.appendChild(priceSpan);
+
+          const meta = document.createElement('div');
+          meta.className = 'order-item-meta';
+
+          const milkLine = document.createElement('span');
+          milkLine.className = 'order-item-milk';
+          milkLine.textContent = `Milk: ${item.options.milk}`;
+
+          const noteLine = document.createElement('span');
+          noteLine.className = 'order-item-note';
+          noteLine.textContent = item.options.note
+            ? `Note: ${item.options.note}`
+            : 'Note: None';
+
+          const timeLine = document.createElement('time');
+          timeLine.className = 'order-item-timestamp timestamp';
+          timeLine.setAttribute('datetime', item.timestamp);
+          timeLine.textContent = `Added: ${item.timestamp}`;
+
+          meta.appendChild(milkLine);
+          meta.appendChild(noteLine);
+          meta.appendChild(timeLine);
+
+          // Allow inline editing of an active order item's nested options so users/tests can verify snapshot isolation
+          const itemControls = document.createElement('div');
+          itemControls.className = 'order-item-controls';
+
+          const inlineMilkSelect = document.createElement('select');
+          inlineMilkSelect.setAttribute('aria-label', `Change milk for ${item.name}`);
