+            opt.value = optVal;
+            opt.textContent = optVal;
+            if (item.options.milk === optVal) opt.selected = true;
+            inlineMilkSelect.appendChild(opt);
+          });
+          inlineMilkSelect.addEventListener('change', (e) => {
+            item.options.milk = e.target.value;
+            item.options.customizations.milk = e.target.value;
+            renderDraftOrder();
+          });
+
+          const inlineNoteInput = document.createElement('input');
+          inlineNoteInput.type = 'text';
+          inlineNoteInput.value = item.options.note || '';
+          inlineNoteInput.placeholder = 'Update note';
+          inlineNoteInput.setAttribute('aria-label', `Change note for ${item.name}`);
+          inlineNoteInput.addEventListener('input', (e) => {
+            item.options.note = e.target.value;
+            item.options.customizations.customerNote = e.target.value;
+            noteLine.textContent = item.options.note
+              ? `Note: ${item.options.note}`
+              : 'Note: None';
+          });
+
+          const removeBtn = document.createElement('button');
+          removeBtn.type = 'button';
+          removeBtn.className = 'btn btn-secondary remove-order-item-btn';
+          removeBtn.style.padding = '4px 8px';
+          removeBtn.style.fontSize = '0.75rem';
+          removeBtn.textContent = 'Remove';
+          removeBtn.addEventListener('click', () => {
+            activeDraftOrder.splice(index, 1);
+            renderDraftOrder();
+          });
+
+          itemControls.appendChild(inlineMilkSelect);
+          itemControls.appendChild(inlineNoteInput);
+          itemControls.appendChild(removeBtn);
+
+          li.appendChild(header);
+          li.appendChild(meta);
+          li.appendChild(itemControls);
+
+          draftOrderListEl.appendChild(li);
+        });
+
+        draftOrderCountEl.textContent = String(activeDraftOrder.length);
+        draftOrderTotalEl.textContent = formatPrice(total);
+      }
+
+      function saveOrderSnapshot() {
+        savedOrderSnapshot = deepClone(activeDraftOrder);
+        snapshotStatusEl.textContent = `Snapshot saved (${savedOrderSnapshot.length} ${savedOrderSnapshot.length === 1 ? 'item' : 'items'}).`;
+      }
+
+      function restoreOrderSnapshot() {
+        if (savedOrderSnapshot === null) {
+          snapshotStatusEl.textContent = 'No snapshot available to restore.';
+          return;
+        }
+        // Deep-clone again on restore so subsequent mutations after restore still cannot taint the saved snapshot
+        activeDraftOrder = deepClone(savedOrderSnapshot);
+        renderDraftOrder();
+        snapshotStatusEl.textContent = `Snapshot restored (${activeDraftOrder.length} ${activeDraftOrder.length === 1 ? 'item' : 'items'}).`;
+      }
+
+      function clearDraftOrder() {
+        activeDraftOrder = [];
+        renderDraftOrder();
+      }
+
+      // Expose state helper for external verification if needed
+      window.DailyGrindApp = {
+        getMenuItems: () => MENU_ITEMS,
+        getFilterState: () => ({ ...filterState }),
+        getActiveOrder: () => activeDraftOrder,
+        getSavedSnapshot: () => savedOrderSnapshot,
+        saveSnapshot: saveOrderSnapshot,
+        restoreSnapshot: restoreOrderSnapshot,
+        clearOrder: clearDraftOrder
+      };
+
+      // Event Listeners
+      categorySelectEl.addEventListener('change', handleControlChange);
+      sortSelectEl.addEventListener('change', handleControlChange);
+      reverseToggleEl.addEventListener('change', handleControlChange);
+      groupToggleEl.addEventListener('change', handleControlChange);
+
+      saveSnapshotBtn.addEventListener('click', saveOrderSnapshot);
+      restoreSnapshotBtn.addEventListener('click', restoreOrderSnapshot);
+      clearOrderBtn.addEventListener('click', clearDraftOrder);
+
+      window.addEventListener('popstate', () => {
+        readStateFromUrl();
+        syncControlsWithState();
+        renderMenu();
+        dispatchFilterChangeEvent();
+      });
+
+      // Initialize on load
+      readStateFromUrl();
+      syncControlsWithState();
+      syncUrlWithState();
+      renderMenu();
+      renderDraftOrder();
+      dispatchFilterChangeEvent();
+    })();
+  </script>
+
