+  <script>
+    (() => {
+      const form = document.getElementById('feedback-form');
+      const textarea = document.getElementById('feedback-message');
+      const detectBtn = document.getElementById('detect-language-btn');
+      const resultEl = document.getElementById('detection-result');
+
+      const languageNames = typeof Intl !== 'undefined' && typeof Intl.DisplayNames === 'function'
+        ? new Intl.DisplayNames(['en'], { type: 'language' })
+        : null;
+
+      function formatLanguageTag(tag) {
+        if (!tag) return 'Unknown';
+        if (languageNames) {
+          try {
+            const name = languageNames.of(tag);
+            if (name && name.toLowerCase() !== tag.toLowerCase()) {
+              return `${name} (${tag})`;
+            }
+          } catch {
+            // Fall back to raw tag
+          }
+        }
+        return tag;
+      }
+
+      function showResult(message, isError = false) {
+        if (isError) {
+          resultEl.dataset.state = 'error';
+        } else {
+          delete resultEl.dataset.state;
+        }
+        resultEl.textContent = message;
+      }
+
+      let detectorPromise = null;
+
+      async function initAvailability() {
+        if (!('LanguageDetector' in self)) {
+          detectBtn.disabled = true;
+          showResult('Client-side language detection is not supported in this browser.', true);
+          return;
+        }
+
+        try {
+          const availability = await self.LanguageDetector.availability();
+          if (availability === 'unavailable') {
+            detectBtn.disabled = true;
+            showResult('Language detection model is unavailable on this device.', true);
+          }
+        } catch {
+          detectBtn.disabled = true;
+          showResult('Unable to verify language detector availability in this browser.', true);
+        }
+      }
+
+      initAvailability();
+
+      textarea.addEventListener('input', () => {
+        textarea.setCustomValidity('');
+        textarea.removeAttribute('aria-invalid');
+      });
+
+      async function handleDetect() {
+        const text = textarea.value.trim();
+        if (!text) {
+          textarea.setCustomValidity('Please enter a feedback message to detect its language.');
+          textarea.setAttribute('aria-invalid', 'true');
+          showResult('Please enter a message before detecting the language.', true);
+          textarea.focus();
+          return;
+        }
+
+        if (!('LanguageDetector' in self)) {
+          detectBtn.disabled = true;
+          showResult('Client-side language detection is not supported in this browser.', true);
+          return;
+        }
+
+        detectBtn.disabled = true;
+
+        try {
+          const availability = await self.LanguageDetector.availability();
+          if (availability === 'unavailable') {
+            showResult('Language detection model is unavailable on this device.', true);
+            return;
+          }
+
+          if (!detectorPromise) {
+            detectorPromise = self.LanguageDetector.create({
+              monitor(m) {
+                m.addEventListener('downloadprogress', (e) => {
+                  const pct = Math.round((e.loaded || 0) * 100);
+                  console.log(`Downloaded ${pct}%`);
+                });
+              },
+            });
+          }
+
+          const detector = await detectorPromise;
+          const results = await detector.detect(text);
+
+          if (!results || results.length === 0) {
+            showResult('Could not determine the language of the message.', true);
+            return;
+          }
+
+          const topResult = results[0];
+          const readableLang = formatLanguageTag(topResult.detectedLanguage);
+          const confidencePct = (topResult.confidence * 100).toFixed(1);
+          textarea.setAttribute('lang', topResult.detectedLanguage);
+          showResult(`Detected language: ${readableLang} — ${confidencePct}% confidence`);
+        } catch (err) {
+          detectorPromise = null;
+          showResult(`Language detection failed: ${err && err.message ? err.message : 'Unknown error'}`, true);
+        } finally {
+          if ('LanguageDetector' in self) {
+            detectBtn.disabled = false;
+          }
+        }
+      }
+
+      detectBtn.addEventListener('click', handleDetect);
+
+      form.addEventListener('submit', (e) => {
+        e.preventDefault();
+        handleDetect();
+      });
+    })();
+  </script>
