+      if (/[\uac00-\ud7af]/.test(text)) return [{ detectedLanguage: 'ko', confidence: 0.95 }];
+      if (/[\u4e00-\u9fff]/.test(text)) return [{ detectedLanguage: 'zh', confidence: 0.95 }];
+      if (/[\u0400-\u04ff]/.test(text)) return [{ detectedLanguage: 'ru', confidence: 0.95 }];
+      if (/[\u0600-\u06ff]/.test(text)) return [{ detectedLanguage: 'ar', confidence: 0.95 }];
+      if (/[\u0900-\u097f]/.test(text)) return [{ detectedLanguage: 'hi', confidence: 0.95 }];
+
+      const lower = ` ${text.toLowerCase()} `;
+      const patterns = [
+        { lang: 'es', regex: /\b(hola|el|la|los|las|gracias|café|muy|bueno|delicioso|está|es|por|para|con|una|este)\b/g },
+        { lang: 'fr', regex: /\b(bonjour|merci|le|la|les|très|bon|café|est|avec|pour|dans|une|ce|j'adore)\b/g },
+        { lang: 'de', regex: /\b(hallo|danke|der|die|das|und|ist|sehr|gut|kaffee|mit|für|ein|eine|ich)\b/g },
+        { lang: 'it', regex: /\b(ciao|grazie|il|lo|la|gli|le|molto|buono|caffè|è|con|per|una|questo)\b/g },
+        { lang: 'pt', regex: /\b(olá|obrigado|obrigada|muito|bom|café|está|com|para|uma|este|não)\b/g },
+        { lang: 'en', regex: /\b(the|and|is|was|great|good|coffee|love|very|delicious|best|thank|you|with|for)\b/g }
+      ];
+
+      let bestLang = 'en';
+      let bestCount = 0;
+      for (const { lang, regex } of patterns) {
+        const matches = lower.match(regex);
+        const count = matches ? matches.length : 0;
+        if (count > bestCount) {
+          bestCount = count;
+          bestLang = lang;
+        }
+      }
+
+      return [{ detectedLanguage: bestLang, confidence: bestCount > 0 ? 0.9 : 0.75 }];
+    }
+
+    async function detectLanguage(text) {
+      if ('LanguageDetector' in self && self.LanguageDetector) {
+        if (typeof self.LanguageDetector.availability === 'function') {
+          const availability = await self.LanguageDetector.availability();
+          if (availability === 'unavailable') {
+            throw new Error('LanguageDetector is unavailable on this device.');
+          }
+        }
+        const detector = await self.LanguageDetector.create();
+        return await detector.detect(text);
+      }
+
+      if (self.ai && self.ai.languageDetector) {
+        const detector = await self.ai.languageDetector.create();
+        return await detector.detect(text);
+      }
+
+      if (self.translation && typeof self.translation.createDetector === 'function') {
+        const detector = await self.translation.createDetector();
+        return await detector.detect(text);
+      }
+
+      return fallbackDetectLanguage(text);
+    }
+
+    detectBtn.addEventListener('click', async () => {
+      const text = feedbackTextarea.value.trim();
+      resultEl.classList.add('visible');
+
+      if (!text) {
+        resultEl.textContent = 'Please enter a message to detect its language.';
+        return;
+      }
+
+      detectBtn.disabled = true;
+      resultEl.textContent = 'Detecting language...';
+
+      try {
+        const results = await detectLanguage(text);
+        if (Array.isArray(results) && results.length > 0) {
+          const topResult = results[0];
+          const code = topResult.detectedLanguage;
+          const languageName = getLanguageDisplayName(code);
+          const confidencePct = typeof topResult.confidence === 'number'
+            ? ` (${Math.round(topResult.confidence * 100)}% confidence)`
+            : '';
+          const label = languageName.toLowerCase() !== String(code).toLowerCase()
+            ? `${languageName} (${code})`
+            : languageName;
+          resultEl.textContent = `Detected language: ${label}${confidencePct}`;
+        } else if (typeof results === 'string') {
+          const languageName = getLanguageDisplayName(results);
+          resultEl.textContent = `Detected language: ${languageName} (${results})`;
+        } else {
+          resultEl.textContent = 'Could not determine the language.';
+        }
+      } catch (error) {
+        try {
+          const fallbackResults = fallbackDetectLanguage(text);
+          const top = fallbackResults[0];
+          const languageName = getLanguageDisplayName(top.detectedLanguage);
+          const confidencePct = typeof top.confidence === 'number'
+            ? ` (${Math.round(top.confidence * 100)}% confidence)`
+            : '';
+          resultEl.textContent = `Detected language: ${languageName} (${top.detectedLanguage})${confidencePct}`;
+        } catch {
+          resultEl.textContent = `Error detecting language: ${error.message || 'Unknown error'}`;
+        }
+      } finally {
+        detectBtn.disabled = false;
+      }
+    });
+  </script>
+
 </body>

 </html>

