+        ]);
+        progressEl.value = 1;
+        downloadStatusEl.textContent = 'Model downloaded and ready';
+      }
+
+      updateContextUsage(baseSession);
+      return baseSession;
+    }
+
+    function destroySessionSafely(session) {
+      if (!session) return;
+      try {
+        session.destroy();
+      } catch (err) {
+        console.warn('Error destroying session:', err);
+      }
+    }
+
+    function cleanupAllSessions() {
+      for (const clone of activeClones) {
+        destroySessionSafely(clone);
+      }
+      activeClones.clear();
+
+      if (baseSession) {
+        destroySessionSafely(baseSession);
+        baseSession = null;
+      }
+      updateContextUsage(null);
+    }
+
+    // Pre-warm when the user interacts with the AI workspace if the model is already available
+    document.getElementById('barista-section').addEventListener('focusin', async () => {
+      if (baseSession || !('LanguageModel' in self)) return;
+      try {
+        const availability = await LanguageModel.availability();
+        if (availability === 'available') {
+          await ensureBaseSession();
+        }
+      } catch {
+        // Ignore pre-warm errors; user clicks will surface actionable feedback
+      }
+    }, { once: true });
+
+    // 1. Ask the Barista (Streaming response into #barista-answer)
+    askBtn.addEventListener('click', async () => {
+      const promptText = questionInput.value.trim() || 'Tell me about the Maple Oat Latte and Cold Brew.';
