+        const fallbackResponse = {
+          score: 5,
+          category: feedbackText.toLowerCase().includes('cold brew') ? 'Cold Brew' : 'Maple Oat Latte',
+          error: err && err.message ? err.message : 'Fallback structured result used.',
+        };
+        sentimentOutputEl.textContent = JSON.stringify(fallbackResponse, null, 2);
+      } finally {
+        if (analyzerSession) {
+          activeClones.delete(analyzerSession);
+          destroySessionSafely(analyzerSession);
+        }
+        updateContextUsage(baseSession);
+        sentimentOutputEl.setAttribute('aria-busy', 'false');
+        sentimentBtn.disabled = false;
+      }
+    });
