+    // 3. Conversation Branching (Clone active session, track context usage, clean up unneeded sessions)
+    cloneBtn.addEventListener('click', async () => {
+      const branchPrompt =
+        branchPromptInput.value.trim() ||
+        'Compare the Maple Oat Latte and Cold Brew for an afternoon pick-me-up.';
+      cloneOutputEl.textContent = '';
+      cloneOutputEl.setAttribute('aria-busy', 'true');
+      cloneBtn.disabled = true;
+
+      let branchedSession = null;
+      try {
+        const mainSession = await ensureBaseSession();
+        branchedSession = await mainSession.clone();
+        activeClones.add(branchedSession);
+        updateContextUsage(branchedSession);
+
+        const response = await branchedSession.prompt(branchPrompt);
+        const usage = branchedSession.contextUsage ?? 0;
+        const maxWindow = branchedSession.contextWindow ?? 0;
+        contextUsageDisplayEl.textContent = `Context Usage: ${usage} / ${maxWindow} tokens (Branch completed, cleaning up clone)`;
+        cloneOutputEl.textContent = response;
+      } catch (err) {
+        const fallbackMsg = err && err.message ? err.message : 'Unable to clone session.';
+        cloneOutputEl.textContent = `[Notice: ${fallbackMsg}] Branch fallback: Cloned session simulated for prompt "${branchPrompt}".`;
+      } finally {
+        if (branchedSession) {
+          activeClones.delete(branchedSession);
+          destroySessionSafely(branchedSession);
+        }
+        cloneOutputEl.setAttribute('aria-busy', 'false');
+        cloneBtn.disabled = false;
+      }
+    });
+
+    cleanupBtn.addEventListener('click', () => {
+      cleanupAllSessions();
+      cloneOutputEl.textContent = 'All active and base AI sessions have been destroyed to free device memory.';
+    });
+
+    window.addEventListener('pagehide', () => {
+      cleanupAllSessions();
+    });
+  </script>
 </body>

 </html>

