+import React, { useState, useEffect, useRef, useCallback } from 'react';
+
+export type LnaPermissionName = 'local-network' | 'loopback-network';
+export type TargetAddressSpace = 'local' | 'loopback';
+export type PermissionStateValue = PermissionState | 'unsupported';
+export type ConnectionStatus = 'idle' | 'connecting' | 'connected' | 'error';
+
+/**
+ * Cross-browser permission check for the granular Local Network Access permissions.
+ * Never falls back to querying 'local-network-access', which crashes older Chrome versions.
+ */
+export async function queryLnaPermissionSafe(
+  permissionName: LnaPermissionName,
+  onChange?: (state: PermissionState) => void
+): Promise<{ state: PermissionState; statusObj: PermissionStatus | null }> {
+  if (typeof navigator === 'undefined' || !navigator.permissions?.query) {
+    return { state: 'prompt', statusObj: null };
+  }
+  try {
+    const status = await navigator.permissions.query({
+      name: permissionName as PermissionName,
+    });
+    if (onChange) {
+      status.addEventListener('change', () => {
+        onChange(status.state);
+      });
+    }
+    return { state: status.state, statusObj: status };
+  } catch {
+    // Unrecognized permission name; proceed on user gesture
+    return { state: 'prompt', statusObj: null };
+  }
+}
+
+/**
+ * Connects to a local network device (e.g., hardware test device on RFC 1918 Wi-Fi LAN) over HTTP.
+ * Explicitly declares targetAddressSpace: 'local' for Mixed Content exemption and post-DNS verification.
+ */
+export async function fetchLocalDeviceDiagnostics(
+  deviceUrl = 'http://192.168.1.100:8080/api/diagnostics'
+): Promise<unknown> {
+  const request = new Request(deviceUrl, {
+    method: 'GET',
+    mode: 'cors',
+    // MANDATORY: Declare 'local' when targeting RFC 1918 / .local LAN addresses
+    targetAddressSpace: 'local',
+  } as RequestInit);
+
+  const response = await fetch(request);
+  if (!response.ok) {
+    throw new Error(`Hardware test device responded with HTTP ${response.status}`);
+  }
+  return response.json();
+}
+
+/**
+ * Connects to a local companion CLI daemon running on the user's loopback interface (127.0.0.1).
+ * Explicitly declares targetAddressSpace: 'loopback' for Mixed Content exemption and post-DNS verification.
+ */
+export async function fetchLoopbackCompanionCli(
+  daemonUrl = 'http://127.0.0.1:45678/health'
+): Promise<unknown> {
+  const request = new Request(daemonUrl, {
+    method: 'GET',
+    mode: 'cors',
+    // MANDATORY: Declare 'loopback' when targeting 127.0.0.1, [::1], or localhost
+    targetAddressSpace: 'loopback',
+  } as RequestInit);
+
+  const response = await fetch(request);
+  if (!response.ok) {
+    throw new Error(`Companion CLI responded with HTTP ${response.status}`);
+  }
+  return response.json();
+}
+
+/**
+ * Opens a WebSocket stream to a local network device or loopback companion CLI.
+ * Only subprotocol strings are passed as the second argument (never a targetAddressSpace options object).
+ */
+export function openDiagnosticsWebSocket(
+  wsUrl: string,
+  protocols: string[] = ['v1.diagnostics']
+): WebSocket {
+  return new WebSocket(wsUrl, protocols);
+}
+
+interface EndpointPanelProps {
+  title: string;
+  subtitle: string;
+  permissionName: LnaPermissionName;
+  addressSpace: TargetAddressSpace;
+  defaultHttpUrl: string;
+  defaultWsUrl: string;
+  description: string;
+  remediationSettingLabel: string;
+}
+
+function EndpointPanel({
+  title,
+  subtitle,
+  permissionName,
+  addressSpace,
+  defaultHttpUrl,
+  defaultWsUrl,
+  description,
+  remediationSettingLabel,
+}: EndpointPanelProps) {
+  const [permissionState, setPermissionState] = useState<PermissionState>('prompt');
+  const [httpUrl, setHttpUrl] = useState(defaultHttpUrl);
+  const [wsUrl, setWsUrl] = useState(defaultWsUrl);
+  const [status, setStatus] = useState<ConnectionStatus>('idle');
+  const [wsStatus, setWsStatus] = useState<ConnectionStatus>('idle');
+  const [resultText, setResultText] = useState<string | null>(null);
+  const [errorText, setErrorText] = useState<string | null>(null);
+  const [wsLogs, setWsLogs] = useState<string[]>([]);
+  const wsRef = useRef<WebSocket | null>(null);
+  const autoConnectedRef = useRef(false);
+
+  const runHttpProbe = useCallback(
+    async (targetUrl: string) => {
+      setStatus('connecting');
+      setErrorText(null);
+      try {
+        const data =
+          addressSpace === 'local'
+            ? await fetchLocalDeviceDiagnostics(targetUrl)
+            : await fetchLoopbackCompanionCli(targetUrl);
+        setResultText(JSON.stringify(data, null, 2));
+        setStatus('connected');
+      } catch (err) {
+        const message =
+          err instanceof Error ? err.message : 'Network connection failed (TypeError).';
+        setErrorText(
+          `${message} Ensure the ${
+            addressSpace === 'local'
+              ? 'hardware test device is powered on, connected to the same Wi-Fi LAN'
+              : 'companion CLI daemon is running locally on 127.0.0.1'
+          }, responds with CORS headers (Access-Control-Allow-Origin), and is allowed in browser ${remediationSettingLabel} permissions.`
+        );
+        setStatus('error');
+      }
+    },
+    [addressSpace, remediationSettingLabel]
+  );
+
+  useEffect(() => {
+    let active = true;
+    queryLnaPermissionSafe(permissionName, (newState) => {
+      if (active) {
+        setPermissionState(newState);
+      }
+    }).then(({ state }) => {
+      if (!active) return;
+      setPermissionState(state);
+      // Only auto-connect without user gesture when permission is already 'granted'
+      if (state === 'granted' && !autoConnectedRef.current) {
+        autoConnectedRef.current = true;
+        runHttpProbe(defaultHttpUrl);
+      }
+    });
+
+    return () => {
+      active = false;
+      if (wsRef.current) {
+        wsRef.current.close();
+      }
+    };
+  }, [permissionName, defaultHttpUrl, runHttpProbe]);
+
+  const handleConnectClick = async (e: React.FormEvent) => {
+    e.preventDefault();
+    await runHttpProbe(httpUrl);
+    // Refresh permission state after user-initiated request
+    const { state } = await queryLnaPermissionSafe(permissionName);
+    setPermissionState(state);
+  };
+
+  const handleToggleWebSocket = () => {
+    if (wsRef.current && wsStatus === 'connected') {
+      wsRef.current.close();
+      wsRef.current = null;
+      setWsStatus('idle');
+      return;
+    }
+
+    try {
+      setWsStatus('connecting');
+      const socket = openDiagnosticsWebSocket(wsUrl, ['v1.telemetry']);
+      wsRef.current = socket;
+
+      socket.addEventListener('open', () => {
+        setWsStatus('connected');
+        setWsLogs((prev) => [...prev.slice(-4), `Connected to ${wsUrl}`]);
+      });
+
+      socket.addEventListener('message', (event) => {
+        setWsLogs((prev) => [...prev.slice(-4), String(event.data)]);
+      });
+
+      socket.addEventListener('error', () => {
+        setWsStatus('error');
+        setWsLogs((prev) => [
+          ...prev.slice(-4),
+          `WebSocket stream failed for ${wsUrl}. Verify endpoint & ${permissionName} permission.`,
+        ]);
+      });
+
+      socket.addEventListener('close', () => {
+        setWsStatus((prev) => (prev === 'error' ? 'error' : 'idle'));
+      });
+    } catch (err) {
+      setWsStatus('error');
+      setWsLogs((prev) => [
+        ...prev.slice(-4),
+        err instanceof Error ? err.message : 'WebSocket connection error',
+      ]);
+    }
+  };
+
+  const badgeColors: Record<PermissionState, string> = {
+    granted: 'bg-emerald-100 text-emerald-800 border-emerald-300',
+    prompt: 'bg-amber-100 text-amber-800 border-amber-300',
+    denied: 'bg-red-100 text-red-800 border-red-300',
+  };
+
+  return (
+    <div className="border border-gray-200 rounded-lg p-4 bg-gray-50 flex flex-col justify-between space-y-3">
+      <div>
+        <div className="flex items-start justify-between gap-2">
+          <div>
+            <h3 className="font-bold text-gray-900 text-sm flex items-center gap-1.5">
+              <span>{title}</span>
+              <code className="text-[11px] font-mono bg-gray-200 text-gray-800 px-1.5 py-0.5 rounded">
+                {addressSpace}
+              </code>
+            </h3>
+            <p className="text-xs text-gray-600 mt-0.5">{subtitle}</p>
+          </div>
+          <span
+            data-permission-status={permissionName}
+            className={`text-[11px] font-semibold uppercase tracking-wide px-2 py-0.5 rounded border ${badgeColors[permissionState]}`}
+          >
+            {permissionName}: {permissionState}
+          </span>
+        </div>
+
+        <p className="text-xs text-gray-700 mt-2 leading-relaxed">{description}</p>
+
+        {/* Actionable remediation banner when permission is denied */}
+        <div
+          data-remediation={permissionName}
+          hidden={permissionState !== 'denied'}
+          className="mt-2 p-2.5 bg-red-50 border border-red-200 rounded text-xs text-red-800"
+        >
+          <p className="font-semibold">Permission Blocked ({permissionName})</p>
+          <p className="mt-1">
+            Browser access to the <code>{addressSpace}</code> address space is currently denied. To
+            connect, open your browser&apos;s <strong>Site settings</strong> (click the tune/lock icon
+            in the address bar), set <strong>{remediationSettingLabel}</strong> to{' '}
+            <strong>Allow</strong>, and retry below.
+          </p>
+        </div>
+
+        <form onSubmit={handleConnectClick} className="mt-3 space-y-2">
+          <div>
+            <label
+              htmlFor={`input-${permissionName}`}
+              className="block text-[11px] font-semibold uppercase tracking-wider text-gray-600 mb-1"
+            >
+              HTTP Diagnostics Endpoint (<code>targetAddressSpace: &apos;{addressSpace}&apos;</code>)
+            </label>
+            <div className="flex gap-2">
+              <input
+                id={`input-${permissionName}`}
+                type="url"
+                value={httpUrl}
+                onChange={(e) => setHttpUrl(e.target.value)}
+                required
+                className="flex-1 min-w-0 text-xs font-mono bg-white border border-gray-300 rounded px-2.5 py-1.5 text-gray-900 focus:outline-none focus:ring-2 focus:ring-amber-400"
+              />
+              <button
+                type="submit"
+                disabled={status === 'connecting'}
+                className="bg-gray-900 hover:bg-gray-700 disabled:bg-gray-400 text-white text-xs font-semibold px-3 py-1.5 rounded whitespace-nowrap transition-colors cursor-pointer"
+              >
+                {status === 'connecting' ? 'Connecting…' : 'Connect'}
+              </button>
+            </div>
+          </div>
+        </form>
+
+        {/* Optional Live WebSocket Telemetry Stream */}
+        <div className="mt-2.5 pt-2.5 border-t border-gray-200">
+          <label
+            htmlFor={`ws-${permissionName}`}
+            className="block text-[11px] font-semibold uppercase tracking-wider text-gray-600 mb-1"
+          >
+            Live Telemetry Stream (WebSocket <code>ws://</code>)
+          </label>
+          <div className="flex gap-2">
+            <input
+              id={`ws-${permissionName}`}
+              type="text"
+              value={wsUrl}
+              onChange={(e) => setWsUrl(e.target.value)}
+              className="flex-1 min-w-0 text-xs font-mono bg-white border border-gray-300 rounded px-2.5 py-1.5 text-gray-900 focus:outline-none focus:ring-2 focus:ring-amber-400"
+            />
+            <button
+              type="button"
+              onClick={handleToggleWebSocket}
+              className="bg-amber-600 hover:bg-amber-500 text-white text-xs font-semibold px-3 py-1.5 rounded whitespace-nowrap transition-colors cursor-pointer"
+            >
+              {wsStatus === 'connected' ? 'Disconnect WS' : 'Stream WS'}
+            </button>
+          </div>
+        </div>
+      </div>
+
+      {/* Status & Output Log */}
+      <div className="pt-2">
+        {errorText && (
+          <div
+            role="alert"
+            className="p-2 bg-amber-50 border border-amber-200 rounded text-xs text-amber-900 font-mono break-words"
+          >
+            {errorText}
+          </div>
+        )}
+        {resultText && (
+          <pre
+            role="region"
+            aria-label={`${title} JSON response`}
+            tabIndex={0}
+            className="p-2 bg-gray-900 text-emerald-300 rounded text-xs font-mono overflow-x-auto max-h-28"
+          >
+            <code>{resultText}</code>
+          </pre>
+        )}
+        {wsLogs.length > 0 && (
+          <div className="mt-1.5 p-2 bg-gray-100 border border-gray-200 rounded text-[11px] font-mono text-gray-700 space-y-0.5">
+            {wsLogs.map((entry, idx) => (
+              <div key={idx}>{entry}</div>
+            ))}
+          </div>
+        )}
+      </div>
+    </div>
+  );
+}
+
+interface DeveloperDiagnosticsWidgetProps {
+  compact?: boolean;
+}
+
+export default function DeveloperDiagnosticsWidget({
+  compact = false,
+}: DeveloperDiagnosticsWidgetProps) {
+  const dialogRef = useRef<HTMLDialogElement | null>(null);
+  const [isSecure, setIsSecure] = useState<boolean>(true);
+
+  useEffect(() => {
+    if (typeof window !== 'undefined') {
+      setIsSecure(window.isSecureContext);
+    }
+  }, []);
+
+  const openModal = () => {
+    dialogRef.current?.showModal();
+  };
+
+  const closeModal = () => {
+    dialogRef.current?.close();
+  };
+
+  const widgetContent = (
+    <div className="space-y-4 text-left">
+      {!isSecure && (
+        <div
+          role="alert"
+          className="p-3 bg-red-50 border border-red-300 rounded text-xs text-red-900"
+        >
+          <strong>Insecure Context Warning:</strong> Local Network Access permissions (
+          <code>local-network</code> and <code>loopback-network</code>) require a Secure Context (
+          <code>https://</code>) and are denied automatically on insecure <code>http://</code>{' '}
+          top-level origins.
+        </div>
+      )}
+
+      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
+        <EndpointPanel
+          title="Hardware Test Device (Wi-Fi LAN)"
+          subtitle="Private RFC 1918 LAN / .local mDNS endpoint"
+          permissionName="local-network"
+          addressSpace="local"
+          defaultHttpUrl="http://192.168.1.100:8080/api/diagnostics"
+          defaultWsUrl="ws://192.168.1.100:8080/stream"
+          description="Connects from your browser to a hardware test rig on your private Wi-Fi LAN (e.g. 192.168.1.x). Gated on the granular 'local-network' permission and explicit user action."
+          remediationSettingLabel="Local network"
+        />
+
+        <EndpointPanel
+          title="Local Companion CLI (Loopback)"
+          subtitle="Localhost / 127.0.0.1 developer daemon"
+          permissionName="loopback-network"
+          addressSpace="loopback"
+          defaultHttpUrl="http://127.0.0.1:45678/health"
+          defaultWsUrl="ws://127.0.0.1:45678/events"
+          description="Connects from your browser to the DevTools Times companion CLI running on your own machine (127.0.0.1). Gated on the granular 'loopback-network' permission and explicit user action."
+          remediationSettingLabel="Loopback network"
+        />
+      </div>
+
+      <details className="text-xs text-gray-600 bg-gray-100 rounded p-2.5 border border-gray-200">
+        <summary className="font-semibold text-gray-800 cursor-pointer">
+          Local Development &amp; LNA Testing Guide
+        </summary>
+        <div className="mt-2 space-y-1.5 leading-relaxed">
+          <p>
+            When testing from <code>http://localhost</code>, the origin is already in the{' '}
+            <code>loopback</code> address space. To test public-to-local and public-to-loopback LNA
+            permission prompts locally, launch Chromium with{' '}
+            <code>
+              --ip-address-space-overrides=127.0.0.1:11224=public,[::1]:11224=public
+            </code>{' '}
+            or toggle <strong>Local network</strong> and <strong>Loopback network</strong> in
+            Browser Site Settings.
+          </p>
+        </div>
+      </details>
+    </div>
+  );
+
+  if (compact) {
+    return (
+      <>
+        <button
+          type="button"
+          onClick={openModal}
+          className="inline-flex items-center gap-1.5 bg-amber-100 hover:bg-amber-200 text-amber-950 border border-amber-300 text-xs font-semibold py-1.5 px-2.5 rounded transition-colors cursor-pointer"
+          aria-label="Open Developer Diagnostics Connection Widget"
+        >
+          <span className="w-2 h-2 rounded-full bg-amber-500 animate-pulse" aria-hidden="true" />
+          <span>Dev Diagnostics (LAN / CLI)</span>
+        </button>
+
+        <dialog
+          ref={dialogRef}
+          {...({ closedby: 'any' } as React.DialogHTMLAttributes<HTMLDialogElement>)}
+          className="w-full max-w-4xl rounded-xl bg-white p-0 shadow-2xl border border-gray-300 backdrop:bg-black/50 m-auto"
+          aria-labelledby="diagnostics-dialog-title"
+        >
+          <div className="p-5 md:p-6">
+            <div className="flex items-start justify-between gap-4 border-b border-gray-200 pb-3 mb-4">
+              <div>
+                <span className="text-[11px] font-bold uppercase tracking-widest text-amber-800">
+                  The DevTools Times Lab
+                </span>
+                <h2 id="diagnostics-dialog-title" className="text-xl font-brand text-gray-900">
+                  Developer Diagnostics Connection Widget
+                </h2>
+              </div>
+              <form method="dialog">
+                <button
+                  type="submit"
+                  onClick={closeModal}
+                  className="text-gray-500 hover:text-gray-900 text-xs font-semibold border border-gray-300 rounded px-2.5 py-1 cursor-pointer"
+                >
+                  Close
+                </button>
+              </form>
+            </div>
+
+            {widgetContent}
+          </div>
+        </dialog>
+      </>
+    );
+  }
+
+  return (
+    <section
+      aria-labelledby="diagnostics-widget-heading"
+      className="bg-white border border-gray-300 rounded-lg p-5 md:p-6 shadow-sm my-6"
+    >
+      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-gray-200 pb-3 mb-4">
+        <div>
+          <span className="text-xs font-brand tracking-widest text-amber-800 uppercase">
+            Interactive Hardware &amp; CLI Bridge
+          </span>
+          <h2 id="diagnostics-widget-heading" className="text-2xl font-brand text-gray-900">
+            Developer Diagnostics Connection Widget
+          </h2>
+        </div>
+        <span className="text-xs text-gray-500 font-mono">
+          Local Network Access (local-network &amp; loopback-network)
+        </span>
+      </div>
+      {widgetContent}
+    </section>
+  );
+}
