@@ -0,0 +1,614 @@
+import React, { useState, useEffect, useCallback } from 'react';
+
+export type AddressSpaceTarget = 'local' | 'loopback';
+export type GranularPermissionName = 'local-network' | 'loopback-network' | 'local-network-access';
+export type ConnectionStatus = 'idle' | 'connecting' | 'connected' | 'error';
+
+interface EndpointState {
+  url: string;
+  targetAddressSpace: AddressSpaceTarget;
+  permissionName: 'local-network' | 'loopback-network';
+  permissionState: PermissionState | 'unsupported' | 'checking';
+  resolvedPermissionName: string;
+  status: ConnectionStatus;
+  responsePreview: string | null;
+  errorMessage: string | null;
+  lastChecked: string | null;
+}
+
+interface LogEntry {
+  id: string;
+  timestamp: string;
+  target: 'lan' | 'cli' | 'system';
+  message: string;
+  level: 'info' | 'success' | 'warn' | 'error';
+}
+
+interface Props {
+  variant?: 'inline' | 'header';
+}
+
+async function queryGranularPermission(
+  primaryName: 'local-network' | 'loopback-network',
+  onChangeCallback: (state: PermissionState, resolvedName: string) => void
+): Promise<{ state: PermissionState | 'unsupported'; resolvedName: string }> {
+  if (typeof navigator === 'undefined' || !navigator.permissions?.query) {
+    return { state: 'unsupported', resolvedName: primaryName };
+  }
+
+  // Query granular permission ('local-network' or 'loopback-network') first,
+  // falling back to legacy 'local-network-access' if the browser hasn't split permissions yet.
+  const candidates: GranularPermissionName[] = [primaryName, 'local-network-access'];
+
+  for (const name of candidates) {
+    try {
+      const status = await navigator.permissions.query({
+        name: name as PermissionName,
+      });
+      status.onchange = () => {
+        onChangeCallback(status.state, name);
+      };
+      return { state: status.state, resolvedName: name };
+    } catch {
+      // Try next fallback candidate
+    }
+  }
+
+  return { state: 'unsupported', resolvedName: primaryName };
+}
+
+export async function connectWithTargetAddressSpace(
+  url: string,
+  targetAddressSpace: AddressSpaceTarget,
+  options: RequestInit = {}
+): Promise<Response> {
+  return fetch(url, {
+    method: 'GET',
+    mode: 'cors',
+    ...options,
+    targetAddressSpace,
+  });
+}
+
+export default function DeveloperDiagnosticsWidget({ variant = 'inline' }: Props) {
+  const [isFlyoutOpen, setIsFlyoutOpen] = useState(false);
+  const [isSecure, setIsSecure] = useState<boolean>(true);
+
+  // 1. Hardware test device on private Wi-Fi LAN (192.168.1.x -> targetAddressSpace: 'local', permission: 'local-network')
+  const [lanDevice, setLanDevice] = useState<EndpointState>({
+    url: 'http://192.168.1.100:8080/diagnostics',
+    targetAddressSpace: 'local',
+    permissionName: 'local-network',
+    permissionState: 'checking',
+    resolvedPermissionName: 'local-network',
+    status: 'idle',
+    responsePreview: null,
+    errorMessage: null,
+    lastChecked: null,
+  });
+
+  // 2. Local companion CLI on user's machine (127.0.0.1 -> targetAddressSpace: 'loopback', permission: 'loopback-network')
+  const [localCli, setLocalCli] = useState<EndpointState>({
+    url: 'http://127.0.0.1:4321/status',
+    targetAddressSpace: 'loopback',
+    permissionName: 'loopback-network',
+    permissionState: 'checking',
+    resolvedPermissionName: 'loopback-network',
+    status: 'idle',
+    responsePreview: null,
+    errorMessage: null,
+    lastChecked: null,
+  });
+
+  const [logs, setLogs] = useState<LogEntry[]>([]);
+
+  const appendLog = useCallback(
+    (target: LogEntry['target'], message: string, level: LogEntry['level'] = 'info') => {
+      const entry: LogEntry = {
+        id: `${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
+        timestamp: new Date().toLocaleTimeString(),
+        target,
+        message,
+        level,
+      };
+      setLogs((prev) => [entry, ...prev].slice(0, 20));
+    },
+    []
+  );
+
+  const refreshPermissions = useCallback(async () => {
+    const lanPerm = await queryGranularPermission('local-network', (newState, resolvedName) => {
+      setLanDevice((prev) => ({
+        ...prev,
+        permissionState: newState,
+        resolvedPermissionName: resolvedName,
+      }));
+      appendLog('lan', `Permission '${resolvedName}' changed to '${newState}'`, 'info');
+    });
+
+    setLanDevice((prev) => ({
+      ...prev,
+      permissionState: lanPerm.state,
+      resolvedPermissionName: lanPerm.resolvedName,
+    }));
+
+    const cliPerm = await queryGranularPermission('loopback-network', (newState, resolvedName) => {
+      setLocalCli((prev) => ({
+        ...prev,
+        permissionState: newState,
+        resolvedPermissionName: resolvedName,
+      }));
+      appendLog('cli', `Permission '${resolvedName}' changed to '${newState}'`, 'info');
+    });
+
+    setLocalCli((prev) => ({
+      ...prev,
+      permissionState: cliPerm.state,
+      resolvedPermissionName: cliPerm.resolvedName,
+    }));
+  }, [appendLog]);
+
+  useEffect(() => {
+    if (typeof window !== 'undefined') {
+      setIsSecure(window.isSecureContext);
+    }
+    refreshPermissions();
+  }, [refreshPermissions]);
+
+  const handleConnectLanDevice = async (e?: React.FormEvent) => {
+    if (e) e.preventDefault();
+    const targetUrl = lanDevice.url.trim();
+    setLanDevice((prev) => ({
+      ...prev,
+      status: 'connecting',
+      errorMessage: null,
+      responsePreview: null,
+    }));
+    appendLog(
+      'lan',
+      `Connecting to LAN hardware device at ${targetUrl} with { targetAddressSpace: 'local' }...`,
+      'info'
+    );
+
+    try {
+      const response = await connectWithTargetAddressSpace(targetUrl, 'local');
+      const text = await response.text();
+      setLanDevice((prev) => ({
+        ...prev,
+        status: response.ok ? 'connected' : 'error',
+        responsePreview: text ? text.slice(0, 300) : `HTTP ${response.status} ${response.statusText}`,
+        errorMessage: response.ok ? null : `HTTP ${response.status}: ${response.statusText}`,
+        lastChecked: new Date().toLocaleTimeString(),
+      }));
+      appendLog(
+        'lan',
+        `LAN device responded with HTTP ${response.status}`,
+        response.ok ? 'success' : 'warn'
+      );
+    } catch (err: any) {
+      const msg =
+        err instanceof Error
+          ? err.message
+          : 'Network error or blocked by Local Network Access (local-network permission).';
+      setLanDevice((prev) => ({
+        ...prev,
+        status: 'error',
+        errorMessage: `${msg} Ensure the device at ${targetUrl} is reachable on your private LAN, 'local-network' permission is granted, and CORS headers are enabled.`,
+        lastChecked: new Date().toLocaleTimeString(),
+      }));
+      appendLog('lan', `LAN connection failed: ${msg}`, 'error');
+    } finally {
+      refreshPermissions();
+    }
+  };
+
+  const handleConnectLocalCli = async (e?: React.FormEvent) => {
+    if (e) e.preventDefault();
+    const targetUrl = localCli.url.trim();
+    setLocalCli((prev) => ({
+      ...prev,
+      status: 'connecting',
+      errorMessage: null,
+      responsePreview: null,
+    }));
+    appendLog(
+      'cli',
+      `Connecting to local companion CLI at ${targetUrl} with { targetAddressSpace: 'loopback' }...`,
+      'info'
+    );
+
+    try {
+      const response = await connectWithTargetAddressSpace(targetUrl, 'loopback');
+      const text = await response.text();
+      setLocalCli((prev) => ({
+        ...prev,
+        status: response.ok ? 'connected' : 'error',
+        responsePreview: text ? text.slice(0, 300) : `HTTP ${response.status} ${response.statusText}`,
+        errorMessage: response.ok ? null : `HTTP ${response.status}: ${response.statusText}`,
+        lastChecked: new Date().toLocaleTimeString(),
+      }));
+      appendLog(
+        'cli',
+        `Companion CLI responded with HTTP ${response.status}`,
+        response.ok ? 'success' : 'warn'
+      );
+    } catch (err: any) {
+      const msg =
+        err instanceof Error
+          ? err.message
+          : 'Network error or blocked by Local Network Access (loopback-network permission).';
+      setLocalCli((prev) => ({
+        ...prev,
+        status: 'error',
+        errorMessage: `${msg} Ensure your companion CLI is listening on ${targetUrl}, 'loopback-network' ("Apps on device") permission is granted, and CORS headers are enabled.`,
+        lastChecked: new Date().toLocaleTimeString(),
+      }));
+      appendLog('cli', `Companion CLI connection failed: ${msg}`, 'error');
+    } finally {
+      refreshPermissions();
+    }
+  };
+
+  const handleConnectBoth = async () => {
+    await Promise.all([handleConnectLanDevice(), handleConnectLocalCli()]);
+  };
+
+  const renderPermissionBadge = (
+    permissionName: 'local-network' | 'loopback-network',
+    state: EndpointState['permissionState']
+  ) => {
+    const colorMap: Record<EndpointState['permissionState'], string> = {
+      granted: 'bg-emerald-100 text-emerald-800 border-emerald-300',
+      prompt: 'bg-amber-100 text-amber-800 border-amber-300',
+      denied: 'bg-red-100 text-red-800 border-red-300',
+      checking: 'bg-gray-100 text-gray-600 border-gray-300',
+      unsupported: 'bg-gray-100 text-gray-600 border-gray-300',
+    };
+
+    return (
+      <span
+        data-testid={`permission-badge-${permissionName}`}
+        className={`inline-flex items-center gap-1.5 text-xs font-mono px-2 py-0.5 rounded border ${colorMap[state]}`}
+      >
+        <span className="font-semibold">{permissionName}:</span>
+        <span>{state}</span>
+      </span>
+    );
+  };
+
+  const renderStatusBadge = (status: ConnectionStatus) => {
+    const styles: Record<ConnectionStatus, string> = {
+      idle: 'bg-gray-100 text-gray-700',
+      connecting: 'bg-blue-100 text-blue-800 animate-pulse',
+      connected: 'bg-emerald-100 text-emerald-800',
+      error: 'bg-red-100 text-red-800',
+    };
+    const labels: Record<ConnectionStatus, string> = {
+      idle: 'Disconnected',
+      connecting: 'Connecting...',
+      connected: 'Connected',
+      error: 'Unreachable / Blocked',
+    };
+    return (
+      <span className={`text-xs font-semibold px-2 py-0.5 rounded ${styles[status]}`}>
+        {labels[status]}
+      </span>
+    );
+  };
+
+  const widgetContent = (
+    <section
+      aria-label="Developer Diagnostics Connection Widget"
+      data-testid="developer-diagnostics-widget"
+      className="bg-slate-50 border border-slate-300 rounded-lg p-4 md:p-5 shadow-xs font-inter text-left"
+    >
+      <div className="flex flex-wrap items-center justify-between gap-3 border-b border-slate-200 pb-3 mb-4">
+        <div>
+          <div className="flex items-center gap-2">
+            <span className="inline-block w-2.5 h-2.5 rounded-full bg-amber-500"></span>
+            <h2 className="text-base md:text-lg font-bold text-slate-900">
+              Developer Diagnostics Connection Widget
+            </h2>
+            <span className="text-xs font-mono bg-slate-200 text-slate-800 px-2 py-0.5 rounded">
+              Local Network Access (LNA)
+            </span>
+          </div>
+          <p className="text-xs text-slate-600 mt-1">
+            Connect directly from your browser to a private Wi-Fi LAN hardware test device (
+            <code className="font-mono text-slate-800">targetAddressSpace: &apos;local&apos;</code>)
+            and a local companion CLI on your machine (
+            <code className="font-mono text-slate-800">
+              targetAddressSpace: &apos;loopback&apos;
+            </code>
+            ).
+          </p>
+        </div>
+
+        <div className="flex items-center gap-2">
+          <span
+            className={`text-xs px-2 py-1 rounded border font-mono ${
+              isSecure
+                ? 'bg-emerald-50 text-emerald-800 border-emerald-200'
+                : 'bg-amber-50 text-amber-800 border-amber-200'
+            }`}
+          >
+            Secure Context: {isSecure ? 'Yes' : 'No (HTTPS required for LNA)'}
+          </span>
+          <button
+            type="button"
+            onClick={refreshPermissions}
+            className="text-xs font-semibold bg-white border border-slate-300 hover:bg-slate-100 text-slate-700 px-2.5 py-1.5 rounded cursor-pointer"
+          >
+            Check Permissions
+          </button>
+          <button
+            type="button"
+            onClick={handleConnectBoth}
+            data-testid="connect-both-button"
+            className="text-xs font-semibold bg-slate-900 hover:bg-slate-800 text-white px-3 py-1.5 rounded cursor-pointer"
+          >
+            Connect Both
+          </button>
+        </div>
+      </div>
+
+      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
+        {/* Card 1: Private Wi-Fi LAN Hardware Test Device */}
+        <form
+          onSubmit={handleConnectLanDevice}
+          data-testid="lan-device-card"
+          className="bg-white border border-slate-200 rounded-md p-4 flex flex-col justify-between"
+        >
+          <div>
+            <div className="flex items-start justify-between gap-2 mb-2">
+              <div>
+                <h3 className="text-sm font-bold text-slate-900">
+                  1. Hardware Test Device (Private Wi-Fi LAN)
+                </h3>
+                <p className="text-xs text-slate-500">
+                  Private subnet device (e.g. <code className="font-mono">192.168.1.x</code>,{' '}
+                  <code className="font-mono">10.0.0.x</code>, or{' '}
+                  <code className="font-mono">.local</code>)
+                </p>
+              </div>
+              {renderStatusBadge(lanDevice.status)}
+            </div>
+
+            <div className="flex flex-wrap items-center gap-2 my-2">
+              {renderPermissionBadge('local-network', lanDevice.permissionState)}
+              <span className="text-xs font-mono bg-blue-50 text-blue-800 border border-blue-200 px-2 py-0.5 rounded">
+                targetAddressSpace: &quot;local&quot;
+              </span>
+            </div>
+
+            <label
+              htmlFor="lan-device-url-input"
+              className="block text-xs font-semibold text-slate-700 mt-3 mb-1"
+            >
+              LAN Hardware Endpoint URL
+            </label>
+            <div className="flex gap-2">
+              <input
+                id="lan-device-url-input"
+                data-testid="lan-device-url-input"
+                type="url"
+                value={lanDevice.url}
+                onChange={(e) =>
+                  setLanDevice((prev) => ({ ...prev, url: e.target.value }))
+                }
+                placeholder="http://192.168.1.100:8080/diagnostics"
+                className="flex-1 text-xs font-mono px-2.5 py-1.5 border border-slate-300 rounded focus:outline-none focus:ring-2 focus:ring-amber-400"
+              />
+              <button
+                type="submit"
+                data-testid="connect-lan-button"
+                disabled={lanDevice.status === 'connecting'}
+                className="bg-amber-500 hover:bg-amber-600 disabled:opacity-50 text-slate-950 font-semibold text-xs px-3 py-1.5 rounded whitespace-nowrap cursor-pointer"
+              >
+                {lanDevice.status === 'connecting' ? 'Connecting...' : 'Connect LAN Device'}
+              </button>
+            </div>
+
+            {lanDevice.responsePreview && (
+              <div
+                data-testid="lan-response-preview"
+                className="mt-3 p-2 bg-emerald-50 border border-emerald-200 rounded text-xs font-mono text-emerald-900 break-all"
+              >
+                {lanDevice.responsePreview}
+              </div>
+            )}
+
+            {lanDevice.errorMessage && (
+              <div
+                data-testid="lan-error-message"
+                className="mt-3 p-2 bg-red-50 border border-red-200 rounded text-xs text-red-800"
+              >
+                {lanDevice.errorMessage}
+              </div>
+            )}
+          </div>
+
+          <div className="mt-3 pt-2 border-t border-slate-100 flex items-center justify-between text-[11px] text-slate-500">
+            <span>
+              Permission API: <code className="font-mono">name: &apos;local-network&apos;</code>
+            </span>
+            {lanDevice.lastChecked && <span>Last attempt: {lanDevice.lastChecked}</span>}
+          </div>
+        </form>
+
+        {/* Card 2: Local Companion CLI on Loopback (127.0.0.1) */}
+        <form
+          onSubmit={handleConnectLocalCli}
+          data-testid="local-cli-card"
+          className="bg-white border border-slate-200 rounded-md p-4 flex flex-col justify-between"
+        >
+          <div>
+            <div className="flex items-start justify-between gap-2 mb-2">
+              <div>
+                <h3 className="text-sm font-bold text-slate-900">
+                  2. Local Companion CLI (Loopback Machine)
+                </h3>
+                <p className="text-xs text-slate-500">
+                  Local host service (<code className="font-mono">127.0.0.1</code>,{' '}
+                  <code className="font-mono">[::1]</code>, or{' '}
+                  <code className="font-mono">localhost</code>)
+                </p>
+              </div>
+              {renderStatusBadge(localCli.status)}
+            </div>
+
+            <div className="flex flex-wrap items-center gap-2 my-2">
+              {renderPermissionBadge('loopback-network', localCli.permissionState)}
+              <span className="text-xs font-mono bg-purple-50 text-purple-800 border border-purple-200 px-2 py-0.5 rounded">
+                targetAddressSpace: &quot;loopback&quot;
+              </span>
+            </div>
+
+            <label
+              htmlFor="local-cli-url-input"
+              className="block text-xs font-semibold text-slate-700 mt-3 mb-1"
+            >
+              Local Companion CLI Endpoint URL
+            </label>
+            <div className="flex gap-2">
+              <input
+                id="local-cli-url-input"
+                data-testid="local-cli-url-input"
+                type="url"
+                value={localCli.url}
+                onChange={(e) =>
+                  setLocalCli((prev) => ({ ...prev, url: e.target.value }))
+                }
+                placeholder="http://127.0.0.1:4321/status"
+                className="flex-1 text-xs font-mono px-2.5 py-1.5 border border-slate-300 rounded focus:outline-none focus:ring-2 focus:ring-amber-400"
+              />
+              <button
+                type="submit"
+                data-testid="connect-cli-button"
+                disabled={localCli.status === 'connecting'}
+                className="bg-slate-800 hover:bg-slate-700 disabled:opacity-50 text-white font-semibold text-xs px-3 py-1.5 rounded whitespace-nowrap cursor-pointer"
+              >
+                {localCli.status === 'connecting' ? 'Connecting...' : 'Connect Local CLI'}
+              </button>
+            </div>
+
+            {localCli.responsePreview && (
+              <div
+                data-testid="cli-response-preview"
+                className="mt-3 p-2 bg-emerald-50 border border-emerald-200 rounded text-xs font-mono text-emerald-900 break-all"
+              >
+                {localCli.responsePreview}
+              </div>
+            )}
+
+            {localCli.errorMessage && (
+              <div
+                data-testid="cli-error-message"
+                className="mt-3 p-2 bg-red-50 border border-red-200 rounded text-xs text-red-800"
+              >
+                {localCli.errorMessage}
+              </div>
+            )}
+          </div>
+
+          <div className="mt-3 pt-2 border-t border-slate-100 flex items-center justify-between text-[11px] text-slate-500">
+            <span>
+              Permission API: <code className="font-mono">name: &apos;loopback-network&apos;</code>
+            </span>
+            {localCli.lastChecked && <span>Last attempt: {localCli.lastChecked}</span>}
+          </div>
+        </form>
+      </div>
+
+      {/* Activity Log */}
+      {logs.length > 0 && (
+        <div
+          data-testid="diagnostics-log"
+          className="mt-4 bg-slate-900 text-slate-100 rounded p-3 text-xs font-mono max-h-36 overflow-y-auto"
+        >
+          <div className="flex items-center justify-between text-slate-400 pb-1.5 mb-1.5 border-b border-slate-800">
+            <span>Connection Telemetry Log</span>
+            <button
+              type="button"
+              onClick={() => setLogs([])}
+              className="text-[11px] text-slate-400 hover:text-white cursor-pointer"
+            >
+              Clear
+            </button>
+          </div>
+          <ul className="space-y-1">
+            {logs.map((entry) => (
+              <li key={entry.id} className="flex items-start gap-2">
+                <span className="text-slate-500 shrink-0">[{entry.timestamp}]</span>
+                <span className="uppercase text-[10px] px-1 rounded bg-slate-800 text-amber-400 shrink-0">
+                  {entry.target}
+                </span>
+                <span
+                  className={
+                    entry.level === 'error'
+                      ? 'text-red-400'
+                      : entry.level === 'success'
+                        ? 'text-emerald-400'
+                        : 'text-slate-200'
+                  }
+                >
+                  {entry.message}
+                </span>
+              </li>
+            ))}
+          </ul>
+        </div>
+      )}
+    </section>
+  );
+
+  if (variant === 'header') {
+    return (
+      <>
+        <button
+          type="button"
+          onClick={() => setIsFlyoutOpen(true)}
+          data-testid="open-diagnostics-modal-button"
+          className="inline-flex items-center gap-1.5 text-xs font-semibold text-slate-800 bg-amber-100 hover:bg-amber-200 border border-amber-300 px-2.5 py-1 rounded cursor-pointer"
+          title="Open Developer Diagnostics (LAN & Local CLI Connection)"
+        >
+          <span className="w-2 h-2 rounded-full bg-amber-500"></span>
+          <span>Dev Diagnostics</span>
+        </button>
+
+        {isFlyoutOpen && (
+          <div
+            className="fixed inset-0 bg-black/40 backdrop-blur-xs z-[99999] flex justify-center items-start p-4 pt-[10vh]"
+            onClick={() => setIsFlyoutOpen(false)}
+          >
+            <div
+              className="bg-white rounded-lg shadow-2xl w-full max-w-4xl relative p-2"
+              onClick={(e) => e.stopPropagation()}
+            >
+              <button
+                type="button"
+                onClick={() => setIsFlyoutOpen(false)}
+                aria-label="Close Developer Diagnostics"
+                className="absolute -top-3 -right-3 bg-white rounded-full p-1.5 shadow-md text-gray-600 hover:text-amber-500 cursor-pointer z-10"
+              >
+                <svg
+                  xmlns="http://www.w3.org/2000/svg"
+                  className="h-5 w-5"
+                  fill="none"
+                  viewBox="0 0 24 24"
+                  stroke="currentColor"
+                  strokeWidth={2}
+                >
+                  <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
+                </svg>
+              </button>
+              {widgetContent}
+            </div>
+          </div>
+        )}
+      </>
+    );
+  }
+
+  return widgetContent;
+}
