+      gap: 0.4rem;
+      font-family: inherit;
+      font-size: 0.9rem;
+      font-weight: 600;
+      cursor: pointer;
+      border-radius: 5px;
+      transition: background 0.2s, color 0.2s, border-color 0.2s;
+    }
+
+    .nav-trigger {
+      background: rgba(255, 255, 255, 0.12);
+      color: white;
+      border: 1px solid rgba(255, 255, 255, 0.28);
+      padding: 6px 12px;
+    }
+
+    .nav-trigger:hover,
+    .nav-trigger[aria-expanded="true"],
+    .nav-trigger:focus-visible {
+      background: var(--accent);
+      color: var(--text);
+      border-color: var(--accent);
+    }
+
+    .card-trigger {
+      background: var(--primary);
+      color: white;
+      border: 1px solid var(--primary);
+      padding: 10px 18px;
+      margin-top: 15px;
+    }
+
+    .card-trigger:hover,
+    .card-trigger[aria-expanded="true"],
+    .card-trigger:focus-visible {
+      background: #3e2723;
+      border-color: var(--accent);
+      box-shadow: 0 0 0 2px rgba(255, 171, 64, 0.35);
+    }
+
+    .trigger:focus:not(:focus-visible) {
+      outline: none;
+    }
+
+    .trigger:focus-visible {
+      outline: 2px solid var(--accent);
+      outline-offset: 2px;
+    }
+
+    /* Popup Menu Styling & Positioning */
+    [popover]:has(> [focusgroup~="menu"]) {
+      margin: 0;
+      padding: 0.35rem;
+      border: 1px solid var(--border);
+      border-radius: 8px;
+      background: var(--surface);
+      color: var(--text);
+      box-shadow: 0 8px 24px rgba(62, 39, 35, 0.18);
+      min-inline-size: 13.5rem;
+    }
+
+    @supports (position-area: block-end) {
+      /* Top-level menus sit below their trigger, flipping when they would overflow. */
+      [popover]:has(> [focusgroup~="menu"]) {
+        position-area: block-end span-inline-end;
+        position-try-fallbacks: flip-block, flip-inline, flip-block flip-inline;
+        inset: auto;
+      }
+
+      /* A popover directly inside a menu is a submenu: beside its parent item, flipping when it would overflow. */
+      [focusgroup~="menu"] > [popover] {
+        position-area: inline-end span-block-end;
+        position-try-fallbacks: flip-inline, flip-block, --below;
+      }
+
+      /* Last resort for narrow viewports: directly below the trigger, indented, so the submenu never covers its trigger. */
+      @position-try --below {
+        position-area: block-end span-inline-end;
+        margin-inline-start: 1rem;
+        min-inline-size: 0;
+        max-inline-size: calc(100% - 1rem);
+      }
+    }
+
+    @supports not (position-area: block-end) {
+      [popover]:has(> [focusgroup~="menu"]) {
+        position: fixed;
+        inset: auto;
+        margin: 0;
+      }
+    }
+
+    /* Safe triangle for submenus */
+    [focusgroup~="menu"] > [popover] {
+      overflow: visible;
+    }
+
+    [focusgroup~="menu"] > [popover][data-bridge]::before {
+      content: "";
