+          price: '$5.25',
+          image: 'https://images.unsplash.com/photo-1572442388796-11668a67e53d?auto=format&fit=crop&w=900&q=80',
+          alt: 'Spiced Chai Cortado topped with cinnamon dust',
+          description: 'A balanced 1:1 marriage of bold espresso and micro-foamed milk infused with freshly crushed green cardamom, ginger root, Ceylon cinnamon, and star anise.',
+          calories: '130 kcal',
+          caffeine: '140 mg',
+          serving: '6 oz Gibraltar Glass',
+          tags: ['Fresh Crushed Cardamom', 'Ceylon Cinnamon', '1:1 Espresso & Milk', 'Artisanal Spice Infusion'],
+          href: '/menu/seasonal'
+        },
+        'toasted-hazelnut-mocha': {
+          title: 'Toasted Hazelnut Mocha',
+          badge: 'Barista Favorite',
+          price: '$6.15',
+          image: 'https://images.unsplash.com/photo-1578314675249-a6910f80cc4e?auto=format&fit=crop&w=900&q=80',
+          alt: 'Toasted Hazelnut Mocha with dark chocolate drizzle',
+          description: 'Single-origin 70% dark chocolate ganache melted directly into hot espresso, swirled with house-made roasted Oregon hazelnut praline and topped with cocoa nibs.',
+          calories: '260 kcal',
+          caffeine: '155 mg',
+          serving: '12 oz / 16 oz',
+          tags: ['70% Dark Cacao Ganache', 'Roasted Oregon Hazelnut', 'Crunchy Cocoa Nibs', 'Velvet Steamed Milk'],
+          href: '/menu/seasonal'
+        }
+      };
+
+      const carousel = document.getElementById('drinks-carousel');
+      const cards = Array.from(carousel.querySelectorAll('.card'));
+      const prevBtn = document.getElementById('carousel-prev');
+      const nextBtn = document.getElementById('carousel-next');
+      const dotsContainer = document.getElementById('carousel-dots');
+
+      // Build pagination dots
+      const dots = cards.map((card, index) => {
+        const dot = document.createElement('button');
+        dot.type = 'button';
+        dot.className = 'carousel-dot';
+        dot.setAttribute('role', 'tab');
+        const drinkTitle = card.querySelector('h3')?.textContent || `Drink ${index + 1}`;
+        dot.setAttribute('aria-label', `Scroll to ${drinkTitle}`);
+        dot.setAttribute('aria-selected', index === 0 ? 'true' : 'false');
+        dot.addEventListener('click', () => {
+          scrollToCard(index);
+        });
+        dotsContainer.appendChild(dot);
+        return dot;
+      });
+
+      function getActiveCardIndex() {
+        const scrollLeft = carousel.scrollLeft;
+        let closestIndex = 0;
+        let minDistance = Infinity;
+        cards.forEach((card, index) => {
+          const offset = card.offsetLeft - carousel.offsetLeft;
+          const dist = Math.abs(scrollLeft - offset);
+          if (dist < minDistance) {
+            minDistance = dist;
+            closestIndex = index;
+          }
+        });
+        return closestIndex;
+      }
+
+      function scrollToCard(index) {
+        const clamped = Math.max(0, Math.min(cards.length - 1, index));
+        const targetCard = cards[clamped];
+        if (!targetCard) return;
+        const left = targetCard.offsetLeft - carousel.offsetLeft;
+        carousel.scrollTo({ left, behavior: 'smooth' });
+      }
+
+      function updateCarouselState() {
+        const activeIndex = getActiveCardIndex();
+        dots.forEach((dot, idx) => {
+          dot.setAttribute('aria-selected', idx === activeIndex ? 'true' : 'false');
+        });
+        const maxScroll = carousel.scrollWidth - carousel.clientWidth;
+        prevBtn.disabled = carousel.scrollLeft <= 6;
+        nextBtn.disabled = carousel.scrollLeft >= maxScroll - 6;
+      }
+
+      prevBtn.addEventListener('click', () => {
+        scrollToCard(getActiveCardIndex() - 1);
+      });
+
+      nextBtn.addEventListener('click', () => {
+        scrollToCard(getActiveCardIndex() + 1);
+      });
+
+      carousel.addEventListener('scroll', () => {
+        window.requestAnimationFrame(updateCarouselState);
+      }, { passive: true });
+
+      window.addEventListener('resize', updateCarouselState);
+      updateCarouselState();
+
+      // Keyboard navigation on the carousel track and within cards
+      carousel.addEventListener('keydown', (e) => {
+        if (e.key === 'ArrowRight') {
+          e.preventDefault();
+          scrollToCard(getActiveCardIndex() + 1);
+        } else if (e.key === 'ArrowLeft') {
+          e.preventDefault();
+          scrollToCard(getActiveCardIndex() - 1);
+        } else if (e.key === 'Home') {
+          e.preventDefault();
+          scrollToCard(0);
+        } else if (e.key === 'End') {
+          e.preventDefault();
+          scrollToCard(cards.length - 1);
+        }
+      });
+
+      // Pointer drag-to-swipe support for desktop and touch
+      let isPointerDown = false;
+      let hasDragged = false;
+      let startX = 0;
+      let startScrollLeft = 0;
+
+      carousel.addEventListener('pointerdown', (e) => {
+        if (e.target.closest('button, a')) return;
+        isPointerDown = true;
+        hasDragged = false;
+        startX = e.clientX;
+        startScrollLeft = carousel.scrollLeft;
+        carousel.classList.add('is-dragging');
+      });
+
+      window.addEventListener('pointermove', (e) => {
+        if (!isPointerDown) return;
+        const dx = e.clientX - startX;
+        if (Math.abs(dx) > 5) {
+          hasDragged = true;
+        }
+        carousel.scrollLeft = startScrollLeft - dx;
+      });
+
+      function endPointerDrag() {
+        if (!isPointerDown) return;
+        isPointerDown = false;
+        carousel.classList.remove('is-dragging');
+        if (hasDragged) {
+          scrollToCard(getActiveCardIndex());
+        }
+      }
+
+      window.addEventListener('pointerup', endPointerDrag);
+      window.addEventListener('pointercancel', endPointerDrag);
+
+      // Detail Modal Expanding from Trigger Button
+      const modal = document.getElementById('drink-detail-modal');
+      const backdrop = document.getElementById('detail-backdrop');
+      const closeBtn = document.getElementById('detail-close-btn');
+      const dismissBtn = document.getElementById('detail-dismiss-btn');
+      const detailImage = document.getElementById('detail-image');
+      const detailBadge = document.getElementById('detail-badge');
+      const detailTitle = document.getElementById('detail-title');
+      const detailPrice = document.getElementById('detail-price');
+      const detailDesc = document.getElementById('detail-description');
+      const detailCalories = document.getElementById('detail-calories');
+      const detailCaffeine = document.getElementById('detail-caffeine');
+      const detailServing = document.getElementById('detail-serving');
+      const detailTags = document.getElementById('detail-tags');
+      const detailOrderLink = document.getElementById('detail-order-link');
+
+      let activeTriggerBtn = null;
+      let closeTimeoutId = null;
+
+      function computeMorphTransform(triggerEl) {
+        if (!triggerEl) {
+          return 'translate(-50%, -50%) scale(0.2)';
+        }
+        const btnRect = triggerEl.getBoundingClientRect();
+        const modalWidth = Math.min(560, window.innerWidth - 32);
+        const modalHeight = modal.offsetHeight || 480;
+        const modalLeft = (window.innerWidth - modalWidth) / 2;
+        const modalTop = (window.innerHeight - modalHeight) / 2;
+
+        const btnCenterX = btnRect.left + btnRect.width / 2;
+        const btnCenterY = btnRect.top + btnRect.height / 2;
+        const modalCenterX = modalLeft + modalWidth / 2;
+        const modalCenterY = modalTop + modalHeight / 2;
+
+        const deltaX = btnCenterX - modalCenterX;
+        const deltaY = btnCenterY - modalCenterY;
+        const scaleX = Math.max(0.08, btnRect.width / modalWidth);
+        const scaleY = Math.max(0.06, btnRect.height / modalHeight);
+
+        return `translate(calc(-50% + ${deltaX.toFixed(1)}px), calc(-50% + ${deltaY.toFixed(1)}px)) scale(${scaleX.toFixed(3)}, ${scaleY.toFixed(3)})`;
+      }
+
+      function populateModal(drinkId) {
+        const data = DRINK_DATA[drinkId];
+        if (!data) return;
+        detailImage.src = data.image;
+        detailImage.alt = data.alt;
+        detailBadge.textContent = data.badge;
+        detailTitle.textContent = data.title;
+        detailPrice.textContent = data.price;
+        detailDesc.textContent = data.description;
+        detailCalories.textContent = data.calories;
+        detailCaffeine.textContent = data.caffeine;
+        detailServing.textContent = data.serving;
+        detailOrderLink.href = data.href;
+
+        detailTags.innerHTML = '';
+        data.tags.forEach((tag) => {
+          const span = document.createElement('span');
+          span.className = 'detail-tag';
+          span.textContent = tag;
+          detailTags.appendChild(span);
+        });
+      }
+
+      function openDetailModal(triggerBtn) {
+        const drinkId = triggerBtn.getAttribute('data-drink-id');
+        if (!drinkId || !DRINK_DATA[drinkId]) return;
+
+        if (closeTimeoutId) {
+          clearTimeout(closeTimeoutId);
+          closeTimeoutId = null;
+        }
+
+        if (activeTriggerBtn && activeTriggerBtn !== triggerBtn) {
+          activeTriggerBtn.setAttribute('aria-expanded', 'false');
+        }
+        activeTriggerBtn = triggerBtn;
+        activeTriggerBtn.setAttribute('aria-expanded', 'true');
+
+        populateModal(drinkId);
+
+        // Position modal directly over the trigger button before animating open
+        modal.style.transition = 'none';
+        modal.style.transformOrigin = 'center center';
+        modal.style.transform = computeMorphTransform(triggerBtn);
+        modal.style.borderRadius = '28px';
+        modal.style.opacity = '0';
+        modal.setAttribute('aria-hidden', 'false');
+        backdrop.setAttribute('aria-hidden', 'false');
+
+        // Force layout calculation so the browser registers the starting button rect
+        void modal.offsetWidth;
+
+        modal.style.transition = '';
+        backdrop.classList.add('is-open');
+        modal.classList.add('is-open');
+        modal.style.transform = 'translate(-50%, -50%) scale(1, 1)';
+        modal.style.borderRadius = '16px';
+        modal.style.opacity = '1';
+
+        closeBtn.focus({ preventScroll: true });
+      }
+
+      function closeDetailModal() {
+        if (!modal.classList.contains('is-open')) return;
+
+        const targetBtn = activeTriggerBtn;
+        if (targetBtn) {
+          targetBtn.setAttribute('aria-expanded', 'false');
+          modal.style.transform = computeMorphTransform(targetBtn);
+          modal.style.borderRadius = '28px';
+        } else {
+          modal.style.transform = 'translate(-50%, -50%) scale(0.2)';
+        }
+
+        modal.style.opacity = '0';
+        modal.classList.remove('is-open');
+        backdrop.classList.remove('is-open');
+        modal.setAttribute('aria-hidden', 'true');
+        backdrop.setAttribute('aria-hidden', 'true');
+
+        if (targetBtn) {
+          targetBtn.focus({ preventScroll: true });
+        }
+
+        closeTimeoutId = window.setTimeout(() => {
+          activeTriggerBtn = null;
+        }, 380);
+      }
+
+      document.querySelectorAll('.view-details-btn').forEach((btn) => {
+        btn.addEventListener('click', () => {
+          openDetailModal(btn);
+        });
+      });
+
+      closeBtn.addEventListener('click', closeDetailModal);
+      dismissBtn.addEventListener('click', closeDetailModal);
+      backdrop.addEventListener('click', closeDetailModal);
+
+      // Trap Tab focus inside modal & close on Escape
+      document.addEventListener('keydown', (e) => {
+        if (!modal.classList.contains('is-open')) return;
+
+        if (e.key === 'Escape') {
+          e.preventDefault();
+          closeDetailModal();
+          return;
+        }
+
+        if (e.key === 'Tab') {
+          const focusables = Array.from(
+            modal.querySelectorAll('a[href], button:not(:disabled), [tabindex]:not([tabindex="-1"])')
+          );
+          if (focusables.length === 0) return;
+          const first = focusables[0];
+          const last = focusables[focusables.length - 1];
+
+          if (e.shiftKey && document.activeElement === first) {
+            e.preventDefault();
+            last.focus();
+          } else if (!e.shiftKey && document.activeElement === last) {
+            e.preventDefault();
+            first.focus();
+          }
+        }
+      });
+    })();
+  </script>
 </body>

 </html>

