+
+// POST /api/register/options
+export async function optionsFetch({ promotion = false } = {}) {
+  const user = loadUserFromStore();
+  const existingCredentials = loadCredentialsFromStore();
+  const options = {
+    challenge: generateRandomBase64Url(32),
+    rp: {
+      id: SERVER_RP_ID,
+      name: "The Daily Grind Coffee Co."
+    },
+    user: {
+      id: user.passkeyUserId,
+      name: user.name,
+      displayName: user.displayName
+    },
+    pubKeyCredParams: [
