+
+// POST /api/register/verify
+export async function registerVerifyFetch(encodedResponse) {
+  const user = loadUserFromStore();
+  const credentials = loadCredentialsFromStore();
+  const credId = encodedResponse?.id || generateRandomBase64Url(24);
+  const aaguid = encodedResponse?.aaguid || "ea9b8d66-4d01-1d21-3ce4-b6b48cb575d4";
+  const providerMeta = lookupProviderByAaguid(aaguid);
+
+  const newCred = {
+    id: credId,
+    passkeyUserId: user.passkeyUserId,
+    credentialPublicKey: encodedResponse?.response?.publicKey || generateRandomBase64Url(48),
+    credentialType: "public-key",
+    credentialDeviceType: encodedResponse?.authenticatorAttachment === "cross-platform" ? "singleDevice" : "multiDevice",
+    credentialBackedUp: encodedResponse?.authenticatorAttachment !== "cross-platform",
+    aaguid,
+    providerIcon: providerMeta.providerIcon,
+    name: encodedResponse?.customName || providerMeta.name,
+    transports: encodedResponse?.response?.transports || ["internal", "hybrid"],
+    registeredAt: Date.now(),
+    lastUsedAt: Date.now(),
+    counter: 0
+  };
+
+  const nextCredentials = [newCred, ...credentials];
+  saveCredentialsToStore(nextCredentials);
+  return createJsonResponse(newCred, 201);
+}
