+    const method = (init.method || (input instanceof Request ? input.method : "GET")).toUpperCase();
+
+    if (url.pathname === "/api/credentials" && method === "GET") {
+      return listFetch();
+    }
+    if (url.pathname.startsWith("/api/credential/")) {
+      const id = decodeURIComponent(url.pathname.slice("/api/credential/".length));
+      if (method === "PUT") {
+        const body = init.body ? JSON.parse(init.body) : {};
+        return renameCredentialFetch(id, body);
+      }
+      if (method === "DELETE") {
+        return deleteFetch(id);
+      }
+    }
+    if (url.pathname === "/api/user" && method === "PUT") {
+      const body = init.body ? JSON.parse(init.body) : {};
+      return updateUserFetch(body);
+    }
+    if (url.pathname === "/api/register/options" && method === "POST") {
+      const body = init.body ? JSON.parse(init.body) : {};
+      const opts = await optionsFetch(body);
+      return createJsonResponse(opts);
+    }
+    if (url.pathname === "/api/register/verify" && method === "POST") {
+      const body = init.body ? JSON.parse(init.body) : {};
+      return registerVerifyFetch(body);
+    }
+    return nativeFetch(input, init);
+  };
+}
