+import {
+  listFetch,
+  renameCredentialFetch,
+  updateUserFetch,
+  deleteFetch,
+  optionsFetch,
+  registerVerifyFetch,
+  resetDemoCredentialsFetch
+} from "./api.js";
+import { lookupProviderByAaguid, FALLBACK_KEY_ICON } from "./aaguids.js";
+
+// Conditionally load invokers-polyfill only in browsers lacking native support
+if (typeof HTMLButtonElement !== "undefined" && !("commandForElement" in HTMLButtonElement.prototype)) {
+  import("https://esm.run/invokers-polyfill").catch(() => {});
+}
+
+// Conditionally load webauthn-polyfills if PublicKeyCredential lacks getClientCapabilities or parseCreationOptionsFromJSON
+if (
+  typeof window !== "undefined" &&
+  window.PublicKeyCredential &&
+  (!PublicKeyCredential.getClientCapabilities || !PublicKeyCredential.parseCreationOptionsFromJSON)
+) {
+  import("https://esm.sh/webauthn-polyfills@0.1.7").catch(() => {});
+}
+
+// Valid unpadded Base64URL: non-empty, [A-Za-z0-9_-] only, no '=' padding, length % 4 !== 1
+export function isValidBase64Url(value) {
+  return (
+    typeof value === "string" &&
+    value.length > 0 &&
+    value.length % 4 !== 1 &&
+    /^[A-Za-z0-9_-]+$/.test(value)
+  );
+}
+
+const dateFormatter = new Intl.DateTimeFormat("en-US", {
+  year: "numeric",
+  month: "short",
+  day: "numeric"
+});
+
+function formatTimestamp(epochMs) {
+  if (!epochMs || typeof epochMs !== "number") return null;
+  try {
+    return dateFormatter.format(new Date(epochMs));
+  } catch {
+    return null;
+  }
+}
+
+let currentState = {
+  rpId: "",
+  userId: "",
+  user: null,
+  credentials: [],
+  activeCredentialIdForRename: null,
+  activeCredentialIdForDelete: null
+};
+
+function announceStatus(message) {
+  const statusRegion = document.getElementById("account-status-banner");
+  const statusText = document.getElementById("account-status-text");
+  if (!statusRegion || !statusText) return;
+  statusText.textContent = message;
+  statusRegion.hidden = false;
+}
+
+function updateSignalSyncLog(signalType, details) {
+  const syncBadge = document.getElementById("authenticator-sync-status");
+  if (!syncBadge) return;
+  const supported =
+    typeof window !== "undefined" &&
+    Boolean(window.PublicKeyCredential && PublicKeyCredential[signalType]);
+  syncBadge.textContent = supported
+    ? `Browser authenticator synced (${signalType})`
+    : `Server synced (${signalType} ready when supported by browser)`;
+  syncBadge.dataset.lastSignal = `${signalType}:${details}`;
+}
+
+export async function syncAcceptedCredentials(rpId, userId, currentCredentialsList) {
+  const credentialIds = currentCredentialsList.map((c) => c.id);
+  updateSignalSyncLog("signalAllAcceptedCredentials", `${credentialIds.length} keys`);
+
+  if (!window.PublicKeyCredential || !PublicKeyCredential.signalAllAcceptedCredentials) {
+    return;
+  }
+
+  if (!rpId || !isValidBase64Url(userId) || !credentialIds.every(isValidBase64Url)) {
+    console.warn(
+      "SignalAllAcceptedCredentials skipped: server rpId and valid unpadded Base64URL userId and credential IDs are required."
+    );
+    return;
+  }
+
+  try {
+    await PublicKeyCredential.signalAllAcceptedCredentials({
+      rpId, // Always use the server-provided rpId; DO NOT use window.location.hostname
+      userId, // Base64URL-encoded user ID from the server
+      allAcceptedCredentialIds: credentialIds
+    });
+  } catch (e) {
+    // Use console.warn instead of console.error so passive sync failures do not fail Lighthouse errors-in-console
+    console.warn("SignalAllAcceptedCredentials sync warning:", e);
+  }
+}
+
+export async function syncCurrentUserDetails(rpId, userId, updatedName, updatedDisplayName) {
+  updateSignalSyncLog("signalCurrentUserDetails", updatedDisplayName);
+
+  if (!window.PublicKeyCredential || !PublicKeyCredential.signalCurrentUserDetails) {
+    return;
+  }
+
+  if (!rpId || !isValidBase64Url(userId)) {
+    console.warn(
+      "SignalCurrentUserDetails skipped: server rpId and valid unpadded Base64URL userId are required."
+    );
+    return;
+  }
+
+  try {
+    await PublicKeyCredential.signalCurrentUserDetails({
+      rpId, // Always use the server-provided rpId; DO NOT use window.location.hostname
+      userId, // Base64URL-encoded user ID from the server
+      name: updatedName,
+      displayName: updatedDisplayName
+    });
+  } catch (e) {
+    console.warn("SignalCurrentUserDetails sync warning:", e);
+  }
+}
+
+async function isPasskeySupported() {
+  if (!window.PublicKeyCredential || !PublicKeyCredential.getClientCapabilities) {
+    return false;
+  }
+  try {
+    const capabilities = await PublicKeyCredential.getClientCapabilities();
+    return Boolean(capabilities.passkeyPlatformAuthenticator);
+  } catch {
+    return false;
+  }
+}
+
+async function checkAndGateCreatePasskeyButton() {
+  const createButton = document.getElementById("create-passkey");
+  const fallbackNotice = document.getElementById("passkey-capability-fallback");
+  if (!createButton) return;
+
+  const supported = await isPasskeySupported();
+  if (!supported) {
+    createButton.hidden = true;
+    if (fallbackNotice) {
+      fallbackNotice.hidden = false;
+    }
+  } else {
+    createButton.hidden = false;
+    if (fallbackNotice) {
+      fallbackNotice.hidden = true;
+    }
+  }
+}
+
+function renderUserProfile(user) {
+  if (!user) return;
+  const displayNameInput = document.getElementById("account-display-name");
+  const usernameInput = document.getElementById("account-username");
+  const headerName = document.getElementById("profile-summary-name");
+  const headerEmail = document.getElementById("profile-summary-email");
+  const headerTier = document.getElementById("profile-summary-tier");
+
+  if (displayNameInput && document.activeElement !== displayNameInput) {
+    displayNameInput.value = user.displayName || "";
+  }
+  if (usernameInput && document.activeElement !== usernameInput) {
+    usernameInput.value = user.name || "";
+  }
+  if (headerName) headerName.textContent = user.displayName || "Coffee Lover";
+  if (headerEmail) headerEmail.textContent = user.name || "";
+  if (headerTier) {
+    headerTier.textContent = `${user.rewardsTier || "Rewards Member"} • ${user.points ?? 0} pts`;
+  }
+}
+
+function createPasskeyRowElement(cred) {
+  const providerMeta = lookupProviderByAaguid(cred.aaguid);
+  const displayName = cred.name || providerMeta.name || "Unknown passkey provider";
+  const iconSrc = cred.providerIcon || providerMeta.providerIcon || FALLBACK_KEY_ICON;
+  const registeredDateStr = formatTimestamp(cred.registeredAt) || "Unknown date";
+  const lastUsedDateStr = formatTimestamp(cred.lastUsedAt);
+
+  const li = document.createElement("li");
+  li.className = "passkey-item";
+  li.dataset.credentialId = cred.id;
+
+  const mainInfo = document.createElement("div");
+  mainInfo.className = "passkey-item-main";
+
+  const iconWrapper = document.createElement("div");
+  iconWrapper.className = "passkey-provider-icon-wrap";
+  const img = document.createElement("img");
+  img.className = "passkey-provider-icon";
+  img.src = iconSrc;
+  img.alt = "";
+  img.width = 28;
+  img.height = 28;
+  iconWrapper.append(img);
+
+  const details = document.createElement("div");
+  details.className = "passkey-details";
+
+  const titleRow = document.createElement("div");
+  titleRow.className = "passkey-title-row";
+
+  const nameHeading = document.createElement("h3");
+  nameHeading.className = "passkey-name";
+  nameHeading.id = `passkey-name-${cred.id}`;
+  nameHeading.textContent = displayName;
+  titleRow.append(nameHeading);
+
+  const badge = document.createElement("span");
+  badge.className = "passkey-badge";
+  badge.textContent = cred.credentialBackedUp ? "Synced" : "Device-bound";
+  titleRow.append(badge);
+
+  const metaList = document.createElement("dl");
+  metaList.className = "passkey-meta";
+
+  const regGroup = document.createElement("div");
+  regGroup.className = "passkey-meta-pair";
+  const regDt = document.createElement("dt");
+  regDt.textContent = "Registered:";
+  const regDd = document.createElement("dd");
+  const regTime = document.createElement("time");
+  if (cred.registeredAt) {
+    regTime.dateTime = new Date(cred.registeredAt).toISOString();
+  }
+  regTime.textContent = registeredDateStr;
+  regDd.append(regTime);
+  regGroup.append(regDt, regDd);
+
+  const usedGroup = document.createElement("div");
+  usedGroup.className = "passkey-meta-pair";
+  const usedDt = document.createElement("dt");
+  usedDt.textContent = "Last used:";
+  const usedDd = document.createElement("dd");
+  if (lastUsedDateStr && cred.lastUsedAt) {
+    const usedTime = document.createElement("time");
+    usedTime.dateTime = new Date(cred.lastUsedAt).toISOString();
+    usedTime.textContent = lastUsedDateStr;
+    usedDd.append(usedTime);
+  } else {
+    usedDd.textContent = "Never used";
+  }
+  usedGroup.append(usedDt, usedDd);
+
+  const providerGroup = document.createElement("div");
+  providerGroup.className = "passkey-meta-pair";
+  const provDt = document.createElement("dt");
+  provDt.textContent = "Provider:";
+  const provDd = document.createElement("dd");
+  provDd.textContent = providerMeta.name;
+  providerGroup.append(provDt, provDd);
+
+  metaList.append(regGroup, usedGroup, providerGroup);
+  details.append(titleRow, metaList);
+  mainInfo.append(iconWrapper, details);
+
+  const actions = document.createElement("div");
+  actions.className = "passkey-actions";
+
+  const renameBtn = document.createElement("button");
+  renameBtn.type = "button";
+  renameBtn.className = "btn-secondary passkey-action-btn";
+  renameBtn.setAttribute("command", "show-modal");
+  renameBtn.setAttribute("commandfor", "rename-passkey-dialog");
+  renameBtn.dataset.action = "rename";
+  renameBtn.dataset.credentialId = cred.id;
+  const renameVisible = document.createTextNode("Rename");
+  const renameHidden = document.createElement("span");
+  renameHidden.className = "visually-hidden";
+  renameHidden.textContent = ` ${displayName}`;
+  renameBtn.append(renameVisible, renameHidden);
+  renameBtn.addEventListener("click", () => openRenameModal(cred));
+
+  const deleteBtn = document.createElement("button");
+  deleteBtn.type = "button";
+  deleteBtn.className = "btn-danger-outline passkey-action-btn";
+  deleteBtn.setAttribute("command", "show-modal");
+  deleteBtn.setAttribute("commandfor", "delete-passkey-dialog");
+  deleteBtn.dataset.action = "delete";
+  deleteBtn.dataset.credentialId = cred.id;
+  const deleteVisible = document.createTextNode("Delete");
+  const deleteHidden = document.createElement("span");
+  deleteHidden.className = "visually-hidden";
+  deleteHidden.textContent = ` ${displayName}`;
+  deleteBtn.append(deleteVisible, deleteHidden);
+  deleteBtn.addEventListener("click", () => openDeleteModal(cred));
+
+  actions.append(renameBtn, deleteBtn);
+  li.append(mainInfo, actions);
+
+  return li;
+}
+
+export function renderUI(credentials) {
+  const listContainer = document.getElementById("passkey-list");
+  const emptyState = document.getElementById("passkey-empty-state");
+  const countBadge = document.getElementById("passkey-count-badge");
+
+  if (countBadge) {
+    countBadge.textContent = `${credentials.length} ${credentials.length === 1 ? "passkey" : "passkeys"}`;
+  }
+
+  if (!listContainer) return;
+
+  if (!credentials || credentials.length === 0) {
+    listContainer.replaceChildren();
+    listContainer.hidden = true;
+    if (emptyState) emptyState.hidden = false;
+    return;
+  }
+
+  if (emptyState) emptyState.hidden = true;
+  listContainer.hidden = false;
+
+  const items = credentials.map((cred) => createPasskeyRowElement(cred));
+  listContainer.replaceChildren(...items);
+}
+
+function openRenameModal(cred) {
+  currentState.activeCredentialIdForRename = cred.id;
+  const dialog = document.getElementById("rename-passkey-dialog");
+  const nameInput = document.getElementById("rename-passkey-input");
+  const currentLabel = document.getElementById("rename-passkey-current-label");
+  const errorEl = document.getElementById("rename-passkey-error");
+
+  if (currentLabel) {
+    currentLabel.textContent = cred.name;
+  }
+  if (nameInput) {
+    nameInput.value = cred.name;
+    nameInput.setCustomValidity("");
+    nameInput.removeAttribute("aria-invalid");
+  }
+  if (errorEl) {
+    errorEl.textContent = "";
+    errorEl.hidden = true;
+  }
+  if (dialog && !dialog.open) {
+    dialog.showModal();
+  }
+}
+
+function openDeleteModal(cred) {
+  currentState.activeCredentialIdForDelete = cred.id;
+  const dialog = document.getElementById("delete-passkey-dialog");
+  const targetNameEl = document.getElementById("delete-passkey-target-name");
+
+  if (targetNameEl) {
+    targetNameEl.textContent = cred.name;
+  }
+  if (dialog && !dialog.open) {
+    dialog.showModal();
+  }
+}
+
+export async function loadManagementPanel() {
+  await checkAndGateCreatePasskeyButton();
+
+  const response = await listFetch();
+  const { rpId, userId, user, credentials } = await response.json();
+
+  currentState.rpId = rpId;
+  currentState.userId = userId;
+  currentState.user = user;
+  currentState.credentials = credentials;
+
+  renderUserProfile(user);
+  renderUI(credentials);
+
+  // Sync accepted credentials on initial load using server-provided rpId and userId
+  await syncAcceptedCredentials(rpId, userId, credentials);
+}
+
+// Renaming a passkey's nickname updates the server record only (does NOT invoke signalCurrentUserDetails)
+export async function performCredentialRename(credentialId, newCredentialName) {
+  const response = await renameCredentialFetch(credentialId, { name: newCredentialName });
+  if (response.ok) {
+    const updatedResponse = await listFetch();
+    const { rpId, userId, credentials } = await updatedResponse.json();
+    currentState.rpId = rpId;
+    currentState.userId = userId;
+    currentState.credentials = credentials;
+    renderUI(credentials);
+    announceStatus(`Passkey renamed to "${newCredentialName}".`);
+    return true;
+  }
+  return false;
+}
