+      const syncBannerEl = document.getElementById('passkey-sync-status');
+      const syncMessageEl = document.getElementById('passkey-sync-message');
+      const syncBtn = document.getElementById('sync-passkeys-btn');
+      const addBtn = document.getElementById('add-passkey-btn');
+
+      function getRpId() {
+        return window.location.hostname || 'localhost';
+      }
+
+      function updateStatusBanner(message, variant) {
+        if (!syncBannerEl || !syncMessageEl) return;
+        syncBannerEl.className = 'sync-banner' + (variant ? ' ' + variant : '');
+        syncMessageEl.textContent = message;
+      }
+
+      function base64UrlEncode(bytes) {
+        let binary = '';
+        const arr = new Uint8Array(bytes);
+        for (let i = 0; i < arr.byteLength; i++) {
+          binary += String.fromCharCode(arr[i]);
+        }
+        return btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
+      }
+
+      function base64UrlDecode(str) {
+        const base64 = str.replace(/-/g, '+').replace(/_/g, '/');
+        const pad = base64.length % 4 === 0 ? '' : '='.repeat(4 - (base64.length % 4));
+        const binary = atob(base64 + pad);
+        const bytes = new Uint8Array(binary.length);
+        for (let i = 0; i < binary.length; i++) {
+          bytes[i] = binary.charCodeAt(i);
+        }
+        return bytes;
+      }
+
+      /**
+       * Synchronize registered credentials with the browser's authenticator using
+       * the WebAuthn Signal API (signalAllAcceptedCredentials & signalUnknownCredential).
+       */
+      async function syncAuthenticatorCredentials(options) {
+        const opts = options || {};
+        const rpId = getRpId();
+        const acceptedIds = passkeys.map(function (pk) { return pk.id; });
+
+        if (typeof window.PublicKeyCredential === 'undefined') {
+          updateStatusBanner(
+            opts.actionLabel
+              ? opts.actionLabel + ' (WebAuthn API unavailable in this environment).'
+              : 'Passkeys ready. Browser WebAuthn API is unavailable in this environment.',
+            'warning'
+          );
+          return;
+        }
+
+        let signaled = false;
+
+        try {
+          if (opts.removedCredentialId && typeof PublicKeyCredential.signalUnknownCredential === 'function') {
+            await PublicKeyCredential.signalUnknownCredential({
+              rpId: rpId,
+              credentialId: opts.removedCredentialId
+            });
+            signaled = true;
+          }
+
+          if (typeof PublicKeyCredential.signalAllAcceptedCredentials === 'function') {
+            await PublicKeyCredential.signalAllAcceptedCredentials({
+              rpId: rpId,
+              userId: currentUser.id,
+              allAcceptedCredentialIds: acceptedIds
+            });
+            signaled = true;
+          }
+
+          if (opts.syncUserDetails && typeof PublicKeyCredential.signalCurrentUserDetails === 'function') {
+            await PublicKeyCredential.signalCurrentUserDetails({
+              rpId: rpId,
+              userId: currentUser.id,
+              name: currentUser.name,
+              displayName: currentUser.displayName
+            });
+            signaled = true;
+          }
+
+          if (signaled) {
+            updateStatusBanner(
+              (opts.actionLabel ? opts.actionLabel + ' — ' : '') +
+              'Browser authenticator synced (' + acceptedIds.length + ' active passkey' + (acceptedIds.length === 1 ? '' : 's') + ').',
+              'synced'
+            );
+          } else {
+            updateStatusBanner(
+              (opts.actionLabel ? opts.actionLabel + ' — ' : '') +
+              'Local passkey list updated (' + acceptedIds.length + ' active). Browser does not support WebAuthn Signal API.',
+              ''
+            );
+          }
+        } catch (err) {
+          console.warn('WebAuthn authenticator signal failed:', err);
+          updateStatusBanner(
+            (opts.actionLabel ? opts.actionLabel + ' — ' : '') +
+            'Updated account passkeys, but browser authenticator sync encountered an error.',
+            'warning'
+          );
+        }
+      }
+
+      async function handleRenamePasskey(credentialId, newName) {
+        const trimmed = (newName || '').trim();
+        if (!trimmed) return;
+
+        passkeys = passkeys.map(function (pk) {
+          if (pk.id === credentialId) {
+            return Object.assign({}, pk, { name: trimmed });
+          }
+          return pk;
+        });
+
+        editingCredentialId = null;
+        savePasskeys(passkeys);
+        renderPasskeys();
+        await syncAuthenticatorCredentials({
+          actionLabel: 'Renamed passkey to "' + trimmed + '"',
+          syncUserDetails: true
+        });
+      }
+
+      async function handleDeletePasskey(credentialId) {
+        const target = passkeys.find(function (pk) { return pk.id === credentialId; });
+        if (!target) return;
+
+        passkeys = passkeys.filter(function (pk) { return pk.id !== credentialId; });
+        if (editingCredentialId === credentialId) {
+          editingCredentialId = null;
+        }
+        savePasskeys(passkeys);
+        renderPasskeys();
+
+        await syncAuthenticatorCredentials({
+          removedCredentialId: credentialId,
+          actionLabel: 'Removed "' + target.name + '" and notified authenticator'
