+            }
+          }
+        }
+
+        const newPasskey = {
+          id: newCredId,
+          name: defaultName,
+          transports: ['internal', 'hybrid'],
+          provider: 'Platform Authenticator',
+          createdAt: today,
+          lastUsedAt: today
+        };
+
+        passkeys.unshift(newPasskey);
+        editingCredentialId = newCredId;
+        savePasskeys(passkeys);
+        renderPasskeys();
+        await syncAuthenticatorCredentials({
+          actionLabel: 'Registered new passkey "' + defaultName + '"'
+        });
+      }
+
+      function renderPasskeys() {
+        if (!listEl) return;
+        listEl.innerHTML = '';
+
+        if (passkeys.length === 0) {
+          const emptyLi = document.createElement('li');
+          emptyLi.className = 'empty-passkeys';
+          emptyLi.textContent = 'You have no registered passkeys. Register a passkey to sign in quickly and securely.';
+          listEl.appendChild(emptyLi);
+          return;
+        }
+
+        passkeys.forEach(function (pk) {
+          const li = document.createElement('li');
+          li.className = 'passkey-item';
+          li.setAttribute('data-credential-id', pk.id);
+
+          const infoDiv = document.createElement('div');
+          infoDiv.className = 'passkey-info';
+
+          const iconDiv = document.createElement('div');
+          iconDiv.className = 'passkey-icon';
+          iconDiv.setAttribute('aria-hidden', 'true');
+          iconDiv.textContent = '🔑';
+
+          const detailsDiv = document.createElement('div');
+          detailsDiv.className = 'passkey-details';
+
+          if (editingCredentialId === pk.id) {
+            const form = document.createElement('form');
+            form.className = 'passkey-rename-form';
+
+            const input = document.createElement('input');
+            input.type = 'text';
+            input.className = 'passkey-rename-input';
+            input.value = pk.name;
+            input.setAttribute('aria-label', 'Passkey name');
+            input.required = true;
+
+            const saveBtn = document.createElement('button');
+            saveBtn.type = 'submit';
+            saveBtn.className = 'btn btn-sm';
+            saveBtn.textContent = 'Save';
+
+            const cancelBtn = document.createElement('button');
+            cancelBtn.type = 'button';
+            cancelBtn.className = 'btn btn-sm btn-outline';
+            cancelBtn.textContent = 'Cancel';
+            cancelBtn.addEventListener('click', function () {
+              editingCredentialId = null;
+              renderPasskeys();
+            });
+
+            form.addEventListener('submit', function (e) {
+              e.preventDefault();
+              handleRenamePasskey(pk.id, input.value);
+            });
+
+            form.appendChild(input);
+            form.appendChild(saveBtn);
+            form.appendChild(cancelBtn);
+            detailsDiv.appendChild(form);
+
+            setTimeout(function () {
+              input.focus();
+              input.select();
+            }, 0);
+          } else {
+            const nameRow = document.createElement('div');
+            nameRow.className = 'passkey-name-row';
+
+            const nameSpan = document.createElement('span');
+            nameSpan.className = 'passkey-name';
+            nameSpan.textContent = pk.name;
+
+            const badgeSpan = document.createElement('span');
+            badgeSpan.className = 'passkey-badge';
+            badgeSpan.textContent = pk.provider || 'Synced Passkey';
+
+            nameRow.appendChild(nameSpan);
+            nameRow.appendChild(badgeSpan);
+            detailsDiv.appendChild(nameRow);
+          }
+
+          const metaDiv = document.createElement('div');
+          metaDiv.className = 'passkey-meta';
+          const shortId = pk.id.length > 16 ? pk.id.slice(0, 8) + '…' + pk.id.slice(-4) : pk.id;
+          metaDiv.textContent = 'Added ' + pk.createdAt + ' • Last used ' + pk.lastUsedAt + ' • ID: ' + shortId;
+          detailsDiv.appendChild(metaDiv);
+
+          infoDiv.appendChild(iconDiv);
+          infoDiv.appendChild(detailsDiv);
+
+          const actionsDiv = document.createElement('div');
+          actionsDiv.className = 'passkey-item-actions';
+
+          if (editingCredentialId !== pk.id) {
+            const renameBtn = document.createElement('button');
+            renameBtn.type = 'button';
+            renameBtn.className = 'btn btn-sm btn-outline';
+            renameBtn.textContent = 'Rename';
+            renameBtn.setAttribute('aria-label', 'Rename ' + pk.name);
+            renameBtn.addEventListener('click', function () {
+              editingCredentialId = pk.id;
+              renderPasskeys();
+            });
+            actionsDiv.appendChild(renameBtn);
+          }
+
+          const deleteBtn = document.createElement('button');
+          deleteBtn.type = 'button';
+          deleteBtn.className = 'btn btn-sm btn-danger';
+          deleteBtn.textContent = 'Delete';
+          deleteBtn.setAttribute('aria-label', 'Delete ' + pk.name);
+          deleteBtn.addEventListener('click', function () {
+            handleDeletePasskey(pk.id);
+          });
+          actionsDiv.appendChild(deleteBtn);
+
+          li.appendChild(infoDiv);
+          li.appendChild(actionsDiv);
+          listEl.appendChild(li);
+        });
+      }
+
+      if (syncBtn) {
+        syncBtn.addEventListener('click', function () {
+          syncAuthenticatorCredentials({
+            actionLabel: 'Manual sync complete',
+            syncUserDetails: true
+          });
+        });
+      }
+
+      if (addBtn) {
+        addBtn.addEventListener('click', function () {
+          handleRegisterPasskey();
+        });
+      }
+
+      renderPasskeys();
+      syncAuthenticatorCredentials();
+    })();
+  </script>
