+import React, { useEffect, useId, useRef, useState } from 'react';
+import 'webauthn-polyfills';
+import aaguidsData from '../data/aaguids.json';
+
+export interface PasskeyCredentialItem {
+  id: string;
+  passkeyUserId: string;
+  credentialPublicKey: string;
+  credentialType: 'public-key';
+  credentialDeviceType: 'singleDevice' | 'multiDevice';
+  credentialBackedUp: boolean;
+  aaguid: string;
+  providerIcon?: string;
+  providerName?: string;
+  name: string;
+  transports: string[];
+  lastUsedAt?: number;
+  registeredAt: number;
+  counter: number;
+}
+
+export interface UserProfile {
+  name: string;
+  displayName: string;
+  subscriptionTier?: string;
+  memberSince?: string;
+}
+
+interface AaguidEntry {
+  name: string;
+  icon_light?: string;
+  icon_dark?: string;
+}
+
+const aaguidRegistry = aaguidsData as Record<string, AaguidEntry>;
+const ZERO_AAGUID = '00000000-0000-0000-0000-000000000000';
+
+// Valid unpadded Base64URL: non-empty, [A-Za-z0-9_-] only, no '=' padding, length % 4 !== 1
+export function isValidBase64Url(value: unknown): value is string {
+  return (
+    typeof value === 'string' &&
+    value.length > 0 &&
+    value.length % 4 !== 1 &&
+    /^[A-Za-z0-9_-]+$/.test(value)
+  );
+}
+
+export function lookupAaguidMetadata(aaguid: string): {
+  providerName: string;
+  providerIcon?: string;
+} {
+  if (!aaguid || aaguid === ZERO_AAGUID) {
+    return {
+      providerName: 'Unknown passkey provider',
+      providerIcon: undefined,
+    };
+  }
+  const provider = aaguidRegistry[aaguid.toLowerCase()];
+  return {
+    providerName: provider?.name || 'Unknown passkey provider',
+    providerIcon: provider?.icon_light,
+  };
+}
+
+function formatTimestamp(epochMs?: number): string {
+  if (!epochMs) return 'Never used';
+  try {
+    return new Intl.DateTimeFormat('en-US', {
+      year: 'numeric',
+      month: 'short',
+      day: 'numeric',
+    }).format(new Date(epochMs));
+  } catch {
+    return new Date(epochMs).toLocaleDateString('en-US');
+  }
+}
+
+async function syncAcceptedCredentials(
+  rpId: string,
+  userId: string,
+  currentCredentialsList: PasskeyCredentialItem[]
+): Promise<{ synced: boolean; message: string }> {
+  const pkc = typeof window !== 'undefined' ? (window.PublicKeyCredential as any) : undefined;
+  if (!pkc || typeof pkc.signalAllAcceptedCredentials !== 'function') {
+    return {
+      synced: false,
+      message: 'Browser Signal API (signalAllAcceptedCredentials) not supported in this browser; server state updated.',
+    };
+  }
+
+  const credentialIds = currentCredentialsList.map((c) => c.id);
+  if (!rpId || !isValidBase64Url(userId) || !credentialIds.every(isValidBase64Url)) {
+    console.warn(
+      'SignalAllAcceptedCredentials skipped: server rpId and valid unpadded Base64URL userId and credential IDs are required.'
+    );
+    return {
+      synced: false,
+      message: 'Skipped authenticator sync due to invalid Base64URL identifier.',
+    };
+  }
+
+  try {
+    await pkc.signalAllAcceptedCredentials({
+      rpId, // Always use the server-provided rpId; DO NOT use window.location.hostname
+      userId, // Base64URL-encoded user ID from the server
+      allAcceptedCredentialIds: credentialIds,
+    });
+    return {
+      synced: true,
+      message: `Synchronized ${credentialIds.length} accepted passkey${credentialIds.length === 1 ? '' : 's'} with browser authenticator (${rpId}).`,
+    };
+  } catch (e) {
+    // Use console.warn instead of console.error so passive sync failures do not fail Lighthouse errors-in-console
+    console.warn('SignalAllAcceptedCredentials sync warning:', e);
+    return {
+      synced: false,
+      message: 'Server updated; passive authenticator signal logged a warning.',
+    };
+  }
+}
+
+async function syncCurrentUserDetails(
+  rpId: string,
+  userId: string,
+  name: string,
+  displayName: string
+): Promise<{ synced: boolean; message: string }> {
+  const pkc = typeof window !== 'undefined' ? (window.PublicKeyCredential as any) : undefined;
+  if (!pkc || typeof pkc.signalCurrentUserDetails !== 'function') {
+    return {
+      synced: false,
+      message: 'Account profile saved. Browser Signal API (signalCurrentUserDetails) not available in this browser.',
+    };
+  }
+
+  if (!rpId || !isValidBase64Url(userId)) {
+    console.warn(
+      'SignalCurrentUserDetails skipped: server rpId and valid unpadded Base64URL userId are required.'
+    );
+    return {
+      synced: false,
+      message: 'Skipped authenticator profile sync due to missing rpId or invalid Base64URL userId.',
+    };
+  }
+
+  try {
+    await pkc.signalCurrentUserDetails({
+      rpId, // Always use the server-provided rpId; DO NOT use window.location.hostname
+      userId, // Base64URL-encoded user ID from the server
+      name,
+      displayName,
+    });
+    return {
+      synced: true,
+      message: `Profile updated and synchronized with browser authenticator (${rpId}).`,
+    };
+  } catch (e) {
+    console.warn('SignalCurrentUserDetails sync warning:', e);
+    return {
+      synced: false,
+      message: 'Profile updated on server; passive authenticator sync logged a warning.',
+    };
+  }
+}
+
+export default function PasskeyManagement() {
+  const baseUrl = import.meta.env.BASE_URL || '/';
+  const apiBase = baseUrl.endsWith('/') ? `${baseUrl}api` : `${baseUrl}/api`;
+
+  const [credentials, setCredentials] = useState<PasskeyCredentialItem[]>([]);
+  const [rpId, setRpId] = useState<string>('');
+  const [userId, setUserId] = useState<string>('');
+  const [userProfile, setUserProfile] = useState<UserProfile>({
+    name: 'alex.rivera@devtoolstimes.dev',
+    displayName: 'Alex Rivera',
+    subscriptionTier: 'Digital All-Access Subscriber',
+    memberSince: 'March 2024',
+  });
+
+  // Account profile form state
+  const [accountNameInput, setAccountNameInput] = useState('alex.rivera@devtoolstimes.dev');
+  const [accountDisplayNameInput, setAccountDisplayNameInput] = useState('Alex Rivera');
+  const [accountSaving, setAccountSaving] = useState(false);
+
+  // Loading & feedback status
+  const [loading, setLoading] = useState(true);
+  const [statusBanner, setStatusBanner] = useState<{
+    type: 'success' | 'info' | 'error';
