diff --git a/src/pages/api/credential/[id].ts b/src/pages/api/credential/[id].ts
new file mode 100644
index 0000000..8eaa571
--- /dev/null
+++ b/src/pages/api/credential/[id].ts
@@ -0,0 +1,95 @@
+import type { APIRoute } from 'astro';
+import {
+  deleteCredentialById,
+  findCredentialById,
+  getRpId,
+  getUserAccount,
+  getUserCredentials,
+  isValidBase64Url,
+  updateCredentialName,
+} from '../../../utils/passkeyStore';
+
+export const PUT: APIRoute = async ({ params, request, session, url }) => {
+  const id = params.id;
+  if (!id || !isValidBase64Url(id)) {
+    return new Response(JSON.stringify({ error: 'Valid Base64URL credential ID is required.' }), {
+      status: 400,
+      headers: { 'Content-Type': 'application/json' },
+    });
+  }
+
+  let body: { name?: string };
+  try {
+    body = await request.json();
+  } catch {
+    return new Response(JSON.stringify({ error: 'Invalid JSON request body.' }), {
+      status: 400,
+      headers: { 'Content-Type': 'application/json' },
+    });
+  }
+
+  const name = typeof body?.name === 'string' ? body.name.trim() : '';
+  if (!name) {
+    return new Response(JSON.stringify({ error: 'A display name is required.' }), {
+      status: 400,
+      headers: { 'Content-Type': 'application/json' },
+    });
+  }
+
+  const user = await getUserAccount(session);
+  const existing = await findCredentialById(id, session);
+  if (!existing || existing.passkeyUserId !== user.passkeyUserId) {
+    return new Response(JSON.stringify({ error: 'Credential not found.' }), {
+      status: 404,
+      headers: { 'Content-Type': 'application/json' },
+    });
+  }
+
+  const updated = await updateCredentialName(id, name, session);
+  return new Response(
+    JSON.stringify({
+      ...updated,
+      rpId: getRpId(url),
+      userId: user.passkeyUserId,
+    }),
+    {
+      status: 200,
+      headers: { 'Content-Type': 'application/json' },
+    }
+  );
+};
+
+export const DELETE: APIRoute = async ({ params, session, url }) => {
+  const id = params.id;
+  if (!id || !isValidBase64Url(id)) {
+    return new Response(JSON.stringify({ error: 'Valid Base64URL credential ID is required.' }), {
+      status: 400,
+      headers: { 'Content-Type': 'application/json' },
+    });
+  }
+
+  const user = await getUserAccount(session);
+  const existing = await findCredentialById(id, session);
+  if (!existing || existing.passkeyUserId !== user.passkeyUserId) {
+    return new Response(JSON.stringify({ error: 'Credential not found.' }), {
+      status: 404,
+      headers: { 'Content-Type': 'application/json' },
+    });
+  }
+
+  await deleteCredentialById(id, session);
+  const credentials = await getUserCredentials(session);
+
+  return new Response(
+    JSON.stringify({
+      success: true,
+      rpId: getRpId(url),
+      userId: user.passkeyUserId,
+      credentials,
+    }),
+    {
+      status: 200,
+      headers: { 'Content-Type': 'application/json' },
+    }
+  );
+};
