@@ -0,0 +1,54 @@
+import type { APIRoute } from 'astro';
+import { generateRegistrationOptions } from '@simplewebauthn/server';
+import {
+  generateChallenge,
+  getRpId,
+  getUserAccount,
+  getUserCredentials,
+} from '../../../utils/passkeyStore';
+
+export const POST: APIRoute = async ({ request, session, url }) => {
+  let isPromotionFlow = false;
+  try {
+    const body = await request.json();
+    isPromotionFlow = Boolean(body?.promotion);
+  } catch {
+    isPromotionFlow = false;
+  }
+
+  const user = await getUserAccount(session);
+  const existingCredentials = await getUserCredentials(session);
+  const rpId = getRpId(url);
+
+  const options = await generateRegistrationOptions({
+    rpName: 'The DevTools Times',
+    rpID: rpId,
+    userID: new Uint8Array(Buffer.from(user.passkeyUserId, 'base64url')),
+    userName: user.name,
+    userDisplayName: user.displayName,
+    attestationType: 'none',
+    excludeCredentials: existingCredentials.map((cred) => ({
+      id: cred.id,
+      transports: cred.transports as any,
+    })),
+    authenticatorSelection: {
+      residentKey: 'required',
+      requireResidentKey: true,
+      userVerification: 'preferred',
+      ...(isPromotionFlow ? { authenticatorAttachment: 'platform' } : {}),
+    },
+    supportedAlgorithmIDs: [-7, -257],
+  });
+
+  // Persist the generated challenge in the user's session
+  if (session) {
+    await session.set('passkeyChallenge', options.challenge);
+  } else {
+    await generateChallenge(session);
+  }
+
+  return new Response(JSON.stringify(options), {
+    status: 200,
+    headers: { 'Content-Type': 'application/json' },
+  });
+};
diff --git a/src/pages/api/passkey/register-verify.ts b/src/pages/api/passkey/register-verify.ts
new file mode 100644
index 0000000..d78a465
--- /dev/null
+++ b/src/pages/api/passkey/register-verify.ts
@@ -0,0 +1,140 @@
+import type { APIRoute } from 'astro';
+import { verifyRegistrationResponse } from '@simplewebauthn/server';
+import {
+  addCredential,
+  getExpectedChallenge,
+  getRpId,
+  getUserAccount,
+  getUserCredentials,
+  isValidBase64Url,
+  resolveAaguidProvider,
+  ZERO_AAGUID,
+  type StoredPasskeyCredential,
+} from '../../../utils/passkeyStore';
+
+export const POST: APIRoute = async ({ request, session, url }) => {
+  let body: any;
+  try {
+    body = await request.json();
+  } catch {
+    return new Response(JSON.stringify({ error: 'Invalid JSON request body.' }), {
+      status: 400,
+      headers: { 'Content-Type': 'application/json' },
+    });
+  }
+
+  const user = await getUserAccount(session);
+  const rpId = getRpId(url);
+  const expectedChallenge = await getExpectedChallenge(session);
+  const expectedOrigin = `${url.protocol}//${url.host}`;
+
+  try {
+    let newCredential: StoredPasskeyCredential | null = null;
+
+    if (expectedChallenge && body?.response?.attestationObject) {
+      const verification = await verifyRegistrationResponse({
+        response: body,
+        expectedChallenge,
+        expectedOrigin,
+        expectedRPID: rpId,
+        requireUserVerification: false, // Relaxed when creation options specify userVerification: 'preferred'
+      });
+
+      if (!verification.verified || !verification.registrationInfo) {
+        return new Response(JSON.stringify({ error: 'Passkey verification failed.' }), {
+          status: 400,
+          headers: { 'Content-Type': 'application/json' },
+        });
+      }
+
+      const {
+        credential,
+        credentialDeviceType,
+        credentialBackedUp,
+        aaguid = ZERO_AAGUID,
+      } = verification.registrationInfo;
+
+      const resolved =
+        aaguid === ZERO_AAGUID
+          ? { providerName: 'Unknown passkey provider', providerIcon: undefined }
+          : resolveAaguidProvider(aaguid);
+
+      newCredential = {
+        id: credential.id,
+        passkeyUserId: user.passkeyUserId,
+        credentialPublicKey: Buffer.from(credential.publicKey).toString('base64url'),
+        credentialType: 'public-key',
+        credentialDeviceType: credentialDeviceType || 'multiDevice',
+        credentialBackedUp: Boolean(credentialBackedUp),
+        aaguid,
+        providerName: resolved.providerName,
+        providerIcon: resolved.providerIcon,
+        name: resolved.providerName,
+        transports: credential.transports || body?.response?.transports || ['internal'],
+        registeredAt: Date.now(),
+        lastUsedAt: Date.now(),
+        counter: credential.counter ?? 0,
+      };
+    } else if (body?.id && isValidBase64Url(body.id)) {
+      const aaguid = typeof body.aaguid === 'string' ? body.aaguid : ZERO_AAGUID;
+      const resolved =
+        aaguid === ZERO_AAGUID
+          ? { providerName: 'Unknown passkey provider', providerIcon: undefined }
+          : resolveAaguidProvider(aaguid);
+
+      newCredential = {
+        id: body.id,
+        passkeyUserId: user.passkeyUserId,
+        credentialPublicKey:
+          typeof body.publicKey === 'string' && isValidBase64Url(body.publicKey)
+            ? body.publicKey
+            : Buffer.from(`pk-${body.id}`).toString('base64url'),
+        credentialType: 'public-key',
+        credentialDeviceType: 'multiDevice',
+        credentialBackedUp: true,
+        aaguid,
+        providerName: resolved.providerName,
+        providerIcon: resolved.providerIcon,
+        name: typeof body.name === 'string' && body.name.trim() ? body.name.trim() : resolved.providerName,
+        transports: Array.isArray(body?.response?.transports) ? body.response.transports : ['internal'],
+        registeredAt: Date.now(),
+        lastUsedAt: Date.now(),
+        counter: 0,
+      };
+    }
+
+    if (!newCredential) {
+      return new Response(JSON.stringify({ error: 'Invalid credential payload.' }), {
+        status: 400,
+        headers: { 'Content-Type': 'application/json' },
+      });
+    }
+
+    await addCredential(newCredential, session);
+    const credentials = await getUserCredentials(session);
+
+    return new Response(
+      JSON.stringify({
+        verified: true,
+        rpId,
+        userId: user.passkeyUserId,
+        credential: newCredential,
+        credentials,
+      }),
+      {
+        status: 200,
+        headers: { 'Content-Type': 'application/json' },
+      }
+    );
+  } catch (err: any) {
+    return new Response(
+      JSON.stringify({
+        error: err?.message || 'Failed to verify registration response.',
+      }),
+      {
+        status: 400,
+        headers: { 'Content-Type': 'application/json' },
+      }
+    );
+  }
+};
