+import type { APIRoute } from 'astro';
+import { getRpId, getUserAccount, updateUserAccount } from '../../utils/passkeyStore';
+
+export const GET: APIRoute = async ({ session, url }) => {
+  const user = await getUserAccount(session);
+  return new Response(
+    JSON.stringify({
+      ...user,
+      rpId: getRpId(url),
+      userId: user.passkeyUserId,
+    }),
+    {
+      status: 200,
+      headers: { 'Content-Type': 'application/json' },
+    }
+  );
+};
+
+export const PUT: APIRoute = async ({ request, session, url }) => {
+  let body: { name?: string; displayName?: string };
+  try {
+    body = await request.json();
+  } catch {
+    return new Response(JSON.stringify({ error: 'Invalid JSON request body.' }), {
+      status: 400,
+      headers: { 'Content-Type': 'application/json' },
+    });
+  }
+
+  const name = typeof body?.name === 'string' ? body.name.trim() : undefined;
+  const displayName = typeof body?.displayName === 'string' ? body.displayName.trim() : undefined;
+
+  if (!name && !displayName) {
+    return new Response(
+      JSON.stringify({ error: 'Please provide an updated username or display name.' }),
+      {
+        status: 400,
+        headers: { 'Content-Type': 'application/json' },
+      }
+    );
+  }
+
+  const updatedUser = await updateUserAccount({ name, displayName }, session);
+  return new Response(
+    JSON.stringify({
+      ...updatedUser,
+      rpId: getRpId(url),
+      userId: updatedUser.passkeyUserId,
+    }),
+    {
+      status: 200,
+      headers: { 'Content-Type': 'application/json' },
+    }
+  );
+};
