diff --git a/src/utils/passkeyStore.ts b/src/utils/passkeyStore.ts
new file mode 100644
index 0000000..908692b
--- /dev/null
+++ b/src/utils/passkeyStore.ts
@@ -0,0 +1,285 @@
+import crypto from 'node:crypto';
+import aaguidsData from '../data/aaguids.json';
+
+export interface StoredPasskeyCredential {
+  id: string; // Base64URL-encoded credential ID (unique lookup key)
+  passkeyUserId: string; // Associated application user ID (Base64URL-encoded)
+  credentialPublicKey: string; // Base64URL-encoded public key used to verify assertion signatures
+  credentialType: 'public-key';
+  credentialDeviceType: 'singleDevice' | 'multiDevice';
+  credentialBackedUp: boolean;
+  aaguid: string; // Authenticator Attestation GUID
+  providerIcon?: string; // Provider icon derived from the AAGUID registry
+  providerName?: string; // Provider name derived from the AAGUID registry
+  name: string; // Custom display name or provider name derived from AAGUID registry
+  transports: string[]; // Array of transport names (e.g. 'internal', 'hybrid')
+  lastUsedAt?: number; // Optional epoch timestamp of last sign-in
+  registeredAt: number; // Registration epoch timestamp
+  counter: number; // Authenticator sign-in signature counter
+}
+
+export interface UserAccount {
+  id: string;
+  passkeyUserId: string; // Valid unpadded Base64URL string
+  name: string; // Account username / email
+  displayName: string; // Reader display name
+  subscriptionTier: string;
+  memberSince: string;
+}
+
+interface AaguidEntry {
+  name: string;
+  icon_light?: string;
+  icon_dark?: string;
+}
+
+const aaguids = aaguidsData as Record<string, AaguidEntry>;
+
+export const ZERO_AAGUID = '00000000-0000-0000-0000-000000000000';
+
+export function resolveAaguidProvider(aaguid: string): {
+  providerName: string;
+  providerIcon?: string;
+} {
+  if (!aaguid || aaguid === ZERO_AAGUID) {
+    return {
+      providerName: 'Unknown passkey provider',
+      providerIcon: undefined,
+    };
+  }
+  const entry = aaguids[aaguid.toLowerCase()];
+  return {
+    providerName: entry?.name || 'Unknown passkey provider',
+    providerIcon: entry?.icon_light,
+  };
+}
+
+export function isValidBase64Url(value: unknown): value is string {
+  return (
+    typeof value === 'string' &&
+    value.length > 0 &&
+    value.length % 4 !== 1 &&
+    /^[A-Za-z0-9_-]+$/.test(value)
+  );
+}
+
+export function getRpId(url?: URL): string {
+  if (process.env.RP_ID) {
+    return process.env.RP_ID;
+  }
+  if (url?.hostname) {
+    return url.hostname;
+  }
+  return 'localhost';
+}
+
+// Default signed-in reader profile with valid unpadded Base64URL passkeyUserId
+const DEFAULT_USER_ID = Buffer.from('devtools-reader-alex-rivera-01').toString('base64url');
+
+const DEFAULT_USER: UserAccount = {
+  id: 'reader-01',
+  passkeyUserId: DEFAULT_USER_ID,
+  name: 'alex.rivera@devtoolstimes.dev',
+  displayName: 'Alex Rivera',
+  subscriptionTier: 'Digital All-Access Subscriber',
+  memberSince: 'March 2024',
+};
+
+function createSeedCredentials(passkeyUserId: string): StoredPasskeyCredential[] {
+  const gpm = resolveAaguidProvider('ea9b8d66-4d01-1d21-3ce4-b6b48cb575d4');
+  const apple = resolveAaguidProvider('fbfc3007-154e-4ecc-8c0b-6e020557d7bd');
+  const onePass = resolveAaguidProvider('bada5566-a7aa-401f-bd96-45619a55120d');
+
+  return [
+    {
+      id: Buffer.from('dtt-cred-gpm-workstation-2026-01').toString('base64url'),
+      passkeyUserId,
+      credentialPublicKey: Buffer.from('mock-public-key-gpm-0001').toString('base64url'),
+      credentialType: 'public-key',
+      credentialDeviceType: 'multiDevice',
+      credentialBackedUp: true,
+      aaguid: 'ea9b8d66-4d01-1d21-3ce4-b6b48cb575d4',
+      providerName: gpm.providerName,
+      providerIcon: gpm.providerIcon,
+      name: gpm.providerName,
+      transports: ['internal', 'hybrid'],
+      registeredAt: 1768471200000, // Jan 15, 2026
+      lastUsedAt: 1795089600000, // Nov 19, 2026
+      counter: 14,
+    },
+    {
+      id: Buffer.from('dtt-cred-apple-macbook-pro-2026-02').toString('base64url'),
+      passkeyUserId,
+      credentialPublicKey: Buffer.from('mock-public-key-apple-0002').toString('base64url'),
+      credentialType: 'public-key',
+      credentialDeviceType: 'multiDevice',
+      credentialBackedUp: true,
+      aaguid: 'fbfc3007-154e-4ecc-8c0b-6e020557d7bd',
+      providerName: apple.providerName,
+      providerIcon: apple.providerIcon,
+      name: 'MacBook Pro — iCloud Keychain',
+      transports: ['internal'],
+      registeredAt: 1775210400000, // Apr 3, 2026
+      lastUsedAt: 1794657600000, // Nov 14, 2026
+      counter: 6,
+    },
+    {
+      id: Buffer.from('dtt-cred-1password-vault-2026-03').toString('base64url'),
+      passkeyUserId,
+      credentialPublicKey: Buffer.from('mock-public-key-1password-0003').toString('base64url'),
+      credentialType: 'public-key',
+      credentialDeviceType: 'multiDevice',
+      credentialBackedUp: true,
+      aaguid: 'bada5566-a7aa-401f-bd96-45619a55120d',
+      providerName: onePass.providerName,
+      providerIcon: onePass.providerIcon,
+      name: onePass.providerName,
+      transports: ['internal', 'hybrid'],
+      registeredAt: 1781949600000, // Jun 20, 2026
+      lastUsedAt: undefined,
+      counter: 0,
+    },
+  ];
+}
+
+// Global in-memory store across server requests when session isn't provided
+const globalStore = globalThis as unknown as {
+  __dttUser?: UserAccount;
+  __dttCredentials?: StoredPasskeyCredential[];
+  __dttCurrentChallenge?: string;
+};
+
+function getGlobalUser(): UserAccount {
+  if (!globalStore.__dttUser) {
+    globalStore.__dttUser = { ...DEFAULT_USER };
+  }
+  return globalStore.__dttUser;
+}
+
+function getGlobalCredentials(): StoredPasskeyCredential[] {
+  if (!globalStore.__dttCredentials) {
+    globalStore.__dttCredentials = createSeedCredentials(getGlobalUser().passkeyUserId);
+  }
+  return globalStore.__dttCredentials;
+}
+
+export async function getUserAccount(session?: any): Promise<UserAccount> {
+  if (session) {
+    const sessionUser = await session.get('userAccount');
+    if (sessionUser && isValidBase64Url(sessionUser.passkeyUserId)) {
+      return sessionUser;
+    }
+    const initial = { ...getGlobalUser() };
+    await session.set('userAccount', initial);
+    return initial;
+  }
+  return getGlobalUser();
+}
+
+export async function updateUserAccount(
+  updates: { name?: string; displayName?: string },
+  session?: any
+): Promise<UserAccount> {
+  const current = await getUserAccount(session);
+  const updated: UserAccount = {
+    ...current,
+    name: typeof updates.name === 'string' && updates.name.trim() ? updates.name.trim() : current.name,
+    displayName:
+      typeof updates.displayName === 'string' && updates.displayName.trim()
+        ? updates.displayName.trim()
+        : current.displayName,
+  };
+  globalStore.__dttUser = updated;
+  if (session) {
+    await session.set('userAccount', updated);
+  }
+  return updated;
+}
+
+export async function getUserCredentials(session?: any): Promise<StoredPasskeyCredential[]> {
+  const user = await getUserAccount(session);
+  if (session) {
+    const sessionCreds = await session.get('passkeyCredentials');
+    if (Array.isArray(sessionCreds)) {
+      return sessionCreds;
+    }
+    const seeded = createSeedCredentials(user.passkeyUserId);
+    await session.set('passkeyCredentials', seeded);
+    return seeded;
+  }
+  return getGlobalCredentials();
+}
+
+export async function saveUserCredentials(
+  credentials: StoredPasskeyCredential[],
+  session?: any
+): Promise<void> {
+  globalStore.__dttCredentials = credentials;
+  if (session) {
+    await session.set('passkeyCredentials', credentials);
+  }
+}
+
+export async function findCredentialById(
+  id: string,
+  session?: any
+): Promise<StoredPasskeyCredential | undefined> {
+  const creds = await getUserCredentials(session);
+  return creds.find((c) => c.id === id);
+}
+
+export async function updateCredentialName(
+  id: string,
+  name: string,
+  session?: any
+): Promise<StoredPasskeyCredential | null> {
+  const creds = await getUserCredentials(session);
+  const idx = creds.findIndex((c) => c.id === id);
+  if (idx === -1) return null;
+
+  const updated: StoredPasskeyCredential = {
+    ...creds[idx],
+    name: name.trim(),
+  };
+  const nextCreds = [...creds];
+  nextCreds[idx] = updated;
+  await saveUserCredentials(nextCreds, session);
+  return updated;
+}
+
+export async function deleteCredentialById(id: string, session?: any): Promise<boolean> {
+  const creds = await getUserCredentials(session);
+  const nextCreds = creds.filter((c) => c.id !== id);
+  if (nextCreds.length === creds.length) {
+    return false;
+  }
+  await saveUserCredentials(nextCreds, session);
+  return true;
+}
+
+export async function addCredential(
+  credential: StoredPasskeyCredential,
+  session?: any
+): Promise<StoredPasskeyCredential> {
+  const creds = await getUserCredentials(session);
+  const nextCreds = [credential, ...creds.filter((c) => c.id !== credential.id)];
+  await saveUserCredentials(nextCreds, session);
+  return credential;
+}
+
+export async function generateChallenge(session?: any): Promise<string> {
+  const challenge = crypto.randomBytes(32).toString('base64url');
+  globalStore.__dttCurrentChallenge = challenge;
+  if (session) {
+    await session.set('passkeyChallenge', challenge);
+  }
+  return challenge;
+}
+
+export async function getExpectedChallenge(session?: any): Promise<string | undefined> {
+  if (session) {
+    const ch = await session.get('passkeyChallenge');
+    if (ch) return ch;
+  }
+  return globalStore.__dttCurrentChallenge;
+}

