@@ -0,0 +1,181 @@
+import type { APIRoute } from 'astro';
+
+export interface PasskeyItem {
+  id: string;
+  name: string;
+  createdAt: string;
+  lastUsedAt: string | null;
+  deviceType: string;
+  backedUp: boolean;
+}
+
+export interface AccountUser {
+  userId: string;
+  username: string;
+  displayName: string;
+  subscriptionPlan: string;
+}
+
+const DEFAULT_USER: AccountUser = {
+  userId: 'dXNlci1kZXZ0b29scy1yZWFkZXItMDE',
+  username: 'alex.rivera@devtoolstimes.dev',
+  displayName: 'Alex Rivera',
+  subscriptionPlan: 'Digital All-Access Subscriber',
+};
+
+const DEFAULT_PASSKEYS: PasskeyItem[] = [
+  {
+    id: 'cGFzc2tleS1tYWNib29rLXByby10b3VjaGlkLTAx',
+    name: 'MacBook Pro (Touch ID)',
+    createdAt: '2026-08-14T10:20:00Z',
+    lastUsedAt: '2026-11-19T18:42:00Z',
+    deviceType: 'Platform Authenticator · macOS',
+    backedUp: true,
+  },
+  {
+    id: 'cGFzc2tleS1waXhlbC05LXByby1iaW9tZXRyaWMtMDI',
+    name: 'Pixel 9 Pro (Google Password Manager)',
+    createdAt: '2026-09-03T14:15:00Z',
+    lastUsedAt: '2026-11-15T09:12:00Z',
+    deviceType: 'Multi-device Passkey · Android',
+    backedUp: true,
+  },
+  {
+    id: 'cGFzc2tleS15dWJpa2V5LTVjLW5mYy1zZWN1cml0eS0wMw',
+    name: 'YubiKey 5C NFC (Backup Key)',
+    createdAt: '2026-06-21T08:00:00Z',
+    lastUsedAt: '2026-10-01T11:30:00Z',
+    deviceType: 'Roaming Hardware Security Key',
+    backedUp: false,
+  },
+];
+
+async function getState(session: any) {
+  let user: AccountUser = (await session?.get('accountUser')) || DEFAULT_USER;
+  let passkeys: PasskeyItem[] = (await session?.get('passkeys')) || DEFAULT_PASSKEYS;
+  return { user, passkeys };
+}
+
+export const GET: APIRoute = async ({ session }) => {
+  const { user, passkeys } = await getState(session);
+  return new Response(
+    JSON.stringify({
+      user,
+      passkeys,
+      allAcceptedCredentialIds: passkeys.map((pk) => pk.id),
+    }),
+    {
+      headers: { 'Content-Type': 'application/json' },
+    }
+  );
+};
+
+export const POST: APIRoute = async ({ request, session }) => {
+  const body = await request.json();
+  const { action } = body;
+  let { user, passkeys } = await getState(session);
+
+  if (action === 'rename-passkey' || action === 'update-passkey') {
+    const { id, name } = body;
+    if (!id || !name || typeof name !== 'string' || !name.trim()) {
+      return new Response(JSON.stringify({ error: 'Valid credential id and display name are required' }), {
+        status: 400,
+        headers: { 'Content-Type': 'application/json' },
+      });
+    }
+    passkeys = passkeys.map((pk) => (pk.id === id ? { ...pk, name: name.trim() } : pk));
+    await session?.set('passkeys', passkeys);
+  } else if (action === 'delete-passkey' || action === 'remove-passkey') {
+    const { id } = body;
+    if (!id) {
+      return new Response(JSON.stringify({ error: 'Credential id is required' }), {
+        status: 400,
+        headers: { 'Content-Type': 'application/json' },
+      });
+    }
+    passkeys = passkeys.filter((pk) => pk.id !== id);
+    await session?.set('passkeys', passkeys);
+  } else if (action === 'update-user' || action === 'update-profile') {
+    const { username, displayName } = body;
+    if (!displayName || typeof displayName !== 'string' || !displayName.trim()) {
+      return new Response(JSON.stringify({ error: 'Display name is required' }), {
+        status: 400,
+        headers: { 'Content-Type': 'application/json' },
+      });
+    }
+    user = {
+      ...user,
+      username: username && typeof username === 'string' && username.trim() ? username.trim() : user.username,
+      displayName: displayName.trim(),
+    };
+    await session?.set('accountUser', user);
+  } else if (action === 'register-passkey' || action === 'add-passkey') {
+    const { id, name, deviceType, backedUp } = body;
+    const newPasskey: PasskeyItem = {
+      id: id || `cGFzc2tleS1kZXZpY2Ut${Date.now().toString(36)}`,
+      name: (name && name.trim()) || 'New Passkey Authenticator',
+      createdAt: new Date().toISOString(),
+      lastUsedAt: new Date().toISOString(),
+      deviceType: deviceType || 'Platform Authenticator · Current Browser',
+      backedUp: backedUp ?? true,
+    };
+    passkeys = [newPasskey, ...passkeys];
+    await session?.set('passkeys', passkeys);
+  } else if (action === 'reset-demo') {
+    user = DEFAULT_USER;
+    passkeys = DEFAULT_PASSKEYS;
+    await session?.set('accountUser', user);
+    await session?.set('passkeys', passkeys);
+  } else {
+    return new Response(JSON.stringify({ error: 'Unsupported action' }), {
+      status: 400,
+      headers: { 'Content-Type': 'application/json' },
+    });
+  }
+
+  return new Response(
+    JSON.stringify({
+      user,
+      passkeys,
+      allAcceptedCredentialIds: passkeys.map((pk) => pk.id),
+    }),
+    {
+      headers: { 'Content-Type': 'application/json' },
+    }
+  );
+};
+
+export const PATCH: APIRoute = POST;
+
+export const DELETE: APIRoute = async ({ request, session, url }) => {
+  let id = url.searchParams.get('id');
+  if (!id) {
+    try {
+      const body = await request.json();
+      id = body.id;
+    } catch {
+      // ignore
+    }
+  }
+  if (!id) {
+    return new Response(JSON.stringify({ error: 'Credential id is required' }), {
+      status: 400,
+      headers: { 'Content-Type': 'application/json' },
+    });
+  }
+
+  let { user, passkeys } = await getState(session);
+  passkeys = passkeys.filter((pk) => pk.id !== id);
+  await session?.set('passkeys', passkeys);
+
+  return new Response(
+    JSON.stringify({
+      user,
+      passkeys,
+      allAcceptedCredentialIds: passkeys.map((pk) => pk.id),
+    }),
+    {
+      headers: { 'Content-Type': 'application/json' },
+    }
+  );
+};
