+
+function loadUsers() {
+  try {
+    const raw = localStorage.getItem(STORAGE_KEY_USERS);
+    if (raw) return JSON.parse(raw);
+  } catch (e) {
+    console.warn("Storage read warning:", e);
+  }
+  const initial = getInitialUsers();
+  saveUsers(initial);
+  return initial;
+}
+
+function saveUsers(users) {
+  try {
+    localStorage.setItem(STORAGE_KEY_USERS, JSON.stringify(users));
+  } catch (e) {
+    console.warn("Storage write warning:", e);
+  }
+}
+
+function loadCredentials() {
+  try {
+    const raw = localStorage.getItem(STORAGE_KEY_CREDS);
+    if (raw) {
+      const parsed = JSON.parse(raw);
+      if (Array.isArray(parsed) && parsed.every((c) => isValidBase64Url(c.id) && isValidBase64Url(c.passkeyUserId))) {
+        return parsed;
+      }
+    }
+  } catch (e) {
+    console.warn("Storage read warning:", e);
+  }
+  const initial = getInitialCredentials();
+  saveCredentials(initial);
+  return initial;
+}
+
+function saveCredentials(creds) {
+  try {
+    localStorage.setItem(STORAGE_KEY_CREDS, JSON.stringify(creds));
+  } catch (e) {
+    console.warn("Storage write warning:", e);
+  }
+}
+
+function loadSession() {
+  try {
+    const raw = localStorage.getItem(STORAGE_KEY_SESSION);
+    if (raw) return JSON.parse(raw);
+  } catch (e) {
+    console.warn("Session read warning:", e);
+  }
+  const defaultSession = {
+    activeUserId: "ZGFpbHktZ3JpbmQtdXNlci0x",
+    challenge: null,
+    expectedUserVerification: "preferred",
+    isConditionalCreate: false,
+    reauthenticatedAt: null
+  };
+  saveSession(defaultSession);
+  return defaultSession;
+}
+
+function saveSession(session) {
+  try {
+    localStorage.setItem(STORAGE_KEY_SESSION, JSON.stringify(session));
+  } catch (e) {
+    console.warn("Session write warning:", e);
+  }
+}
+
+export function resolveAaguidMetadata(aaguid) {
+  const zeroAaguid = "00000000-0000-0000-0000-000000000000";
+  if (!aaguid || aaguid === zeroAaguid) {
+    return {
+      aaguid: zeroAaguid,
+      name: "Passkey on this device",
+      providerIcon: undefined
+    };
+  }
+  const provider = AAGUID_REGISTRY[aaguid];
+  return {
+    aaguid,
+    name: provider?.name || "Unknown passkey provider",
+    providerIcon: provider?.icon_light
+  };
+}
+
+// Simulated Server Route Dispatcher
+async function handleApiRequest(urlStr, options = {}) {
+  const url = new URL(urlStr, window.location.origin);
+  const path = url.pathname;
+  const method = (options.method || "GET").toUpperCase();
+  let body = {};
+  if (options.body && typeof options.body === "string") {
+    try {
+      body = JSON.parse(options.body);
+    } catch {
+      body = {};
+    }
+  } else if (options.body && typeof options.body === "object") {
+    body = options.body;
+  }
+
+  const users = loadUsers();
+  const credentials = loadCredentials();
+  const session = loadSession();
+  const activeUser = users.find((u) => u.passkeyUserId === session.activeUserId) || users[0];
+
+  const jsonResponse = (data, status = 200) =>
+    new Response(JSON.stringify(data), {
+      status,
+      headers: { "Content-Type": "application/json" }
+    });
+
+  // 1. GET /api/credentials - List user credentials alongside rpId and Base64URL userId
+  if (path === "/api/credentials" && method === "GET") {
+    const userCreds = credentials.filter((c) => c.passkeyUserId === activeUser.passkeyUserId);
+    return jsonResponse({
+      rpId: RP_ID,
+      userId: activeUser.passkeyUserId,
+      user: activeUser,
+      credentials: userCreds
+    });
+  }
+
+  // 2. PUT /api/credential/:id - Rename passkey nickname
+  if (path.startsWith("/api/credential/") && method === "PUT") {
+    const id = decodeURIComponent(path.replace("/api/credential/", ""));
+    const credIndex = credentials.findIndex(
+      (c) => c.id === id && c.passkeyUserId === activeUser.passkeyUserId
+    );
+    if (credIndex === -1) {
+      return jsonResponse({ error: "Credential not found." }, 404);
+    }
+    const newName = (body.name || "").trim();
+    if (!newName) {
+      return jsonResponse({ error: "Credential name cannot be empty." }, 400);
+    }
+    credentials[credIndex].name = newName;
+    saveCredentials(credentials);
+    return jsonResponse(credentials[credIndex]);
+  }
+
+  // 3. DELETE /api/credential/:id - Delete a saved passkey
+  if (path.startsWith("/api/credential/") && method === "DELETE") {
+    const id = decodeURIComponent(path.replace("/api/credential/", ""));
+    const credIndex = credentials.findIndex(
+      (c) => c.id === id && c.passkeyUserId === activeUser.passkeyUserId
+    );
+    if (credIndex === -1) {
+      return jsonResponse({ error: "Credential not found." }, 404);
+    }
+    credentials.splice(credIndex, 1);
+    saveCredentials(credentials);
+    return jsonResponse({ success: true, rpId: RP_ID, userId: activeUser.passkeyUserId });
+  }
+
+  // 4. PUT /api/user - Update user account details (name / displayName) and return rpId + userId
+  if (path === "/api/user" && method === "PUT") {
+    const updatedName = (body.name ?? activeUser.name).trim();
+    const updatedDisplayName = (body.displayName ?? activeUser.displayName).trim();
+    if (!updatedName || !updatedDisplayName) {
+      return jsonResponse({ error: "Username and display name are required." }, 400);
+    }
+    activeUser.name = updatedName;
+    activeUser.displayName = updatedDisplayName;
+    if (body.defaultBrew) {
+      activeUser.defaultBrew = String(body.defaultBrew).trim();
+    }
+    saveUsers(users);
+    return jsonResponse({
+      ...activeUser,
+      rpId: RP_ID,
+      userId: activeUser.passkeyUserId
+    });
+  }
+
+  // 5. POST /api/register/options - Generate passkey creation options
+  if (path === "/api/register/options" && method === "POST") {
+    const isPromotionFlow = Boolean(body.promotion || body.conditional);
+    const isConditional = Boolean(body.conditional);
+    const challenge = generateChallengeBase64Url(32);
+
+    // If registering a brand-new customer account from the registration form
+    let targetUser = activeUser;
+    if (body.username && body.displayName) {
+      const existing = users.find((u) => u.name.toLowerCase() === String(body.username).toLowerCase());
+      if (existing) {
+        targetUser = existing;
+      } else {
+        const newPasskeyUserId = generateChallengeBase64Url(18); // Valid unpadded Base64URL string (len 24)
+        targetUser = {
+          id: `user-${users.length + 1}`,
+          passkeyUserId: newPasskeyUserId,
+          name: String(body.username).trim(),
+          displayName: String(body.displayName).trim(),
+          rewardsPoints: 100,
+          defaultBrew: "Dark Roast Espresso",
+          savedCardLast4: "8819"
+        };
+        users.push(targetUser);
+        saveUsers(users);
+      }
+      session.activeUserId = targetUser.passkeyUserId;
+    }
+
+    const userExistingCredentials = credentials.filter(
+      (c) => c.passkeyUserId === targetUser.passkeyUserId
+    );
+
+    session.challenge = challenge;
+    session.expectedUserVerification = "preferred";
+    session.isConditionalCreate = isConditional;
+    saveSession(session);
+
+    const creationOptions = {
+      challenge,
+      rp: { id: RP_ID, name: RP_NAME },
+      user: {
+        id: targetUser.passkeyUserId,
+        name: targetUser.name,
+        displayName: targetUser.displayName
+      },
+      pubKeyCredParams: [
+        { type: "public-key", alg: -7 },
+        { type: "public-key", alg: -257 }
+      ],
+      excludeCredentials: userExistingCredentials.map((cred) => ({
+        type: "public-key",
+        id: cred.id,
+        transports: cred.transports
+      })),
+      authenticatorSelection: {
+        residentKey: "required",
+        requireResidentKey: true,
+        userVerification: "preferred",
+        ...(isPromotionFlow && { authenticatorAttachment: "platform" })
+      }
+    };
+
+    return jsonResponse(creationOptions);
+  }
+
+  // 6. POST /api/register/verify - Verify newly created passkey attestation
+  if (path === "/api/register/verify" && method === "POST") {
+    const credentialId = body.id;
+    if (!credentialId || !isValidBase64Url(credentialId)) {
+      return jsonResponse({ error: "Invalid Base64URL credential ID." }, 400);
+    }
+    if (!session.challenge) {
+      return jsonResponse({ error: "No active registration challenge in session." }, 400);
+    }
+
+    // Relax User Presence (requireUserPresence: false) ONLY for conditional create;
+    // relax requireUserVerification: false when expectedUserVerification === "preferred"
+    const requireUserPresence = !session.isConditionalCreate;
+    const requireUserVerification = session.expectedUserVerification === "required";
+
+    // Look up AAGUID metadata (checking for 00000000-0000-0000-0000-000000000000 first)
+    const rawAaguid = body.aaguid || "ea9b8d66-4d01-1d21-3ce4-b6b48cb575d4";
+    const aaguidMeta = resolveAaguidMetadata(rawAaguid);
+    const now = Date.now();
+
+    const newCredential = {
+      id: credentialId,
+      passkeyUserId: activeUser.passkeyUserId,
+      credentialPublicKey: body.response?.attestationObject || "pQECAyYgASFYIJV8c2FtcGxlcHVibGlja2V5ZGF0YVdFQg",
+      credentialType: "public-key",
+      credentialDeviceType: "multiDevice",
+      credentialBackedUp: true,
+      aaguid: aaguidMeta.aaguid,
+      providerIcon: aaguidMeta.providerIcon,
+      name: body.customName || aaguidMeta.name,
+      transports: body.response?.transports || ["internal", "hybrid"],
+      registeredAt: now,
+      lastUsedAt: now,
+      counter: 0
+    };
+
+    credentials.push(newCredential);
+    saveCredentials(credentials);
+
+    session.challenge = null;
+    session.isConditionalCreate = false;
+    saveSession(session);
+
+    return jsonResponse({
+      verified: true,
+      rpId: RP_ID,
+      userId: activeUser.passkeyUserId,
+      requireUserPresence,
+      requireUserVerification,
+      credential: newCredential
+    });
+  }
+
+  // 7. POST /api/auth/options - Generate discoverable passkey authentication options
+  if (path === "/api/auth/options" && method === "POST") {
+    const challenge = generateChallengeBase64Url(32);
+    session.challenge = challenge;
+    session.expectedUserVerification = "preferred";
+    saveSession(session);
+
+    const requestOptions = {
+      challenge,
+      rpId: RP_ID,
+      allowCredentials: [], // Empty array for discoverable credentials
+      userVerification: "preferred"
+    };
+    return jsonResponse(requestOptions);
+  }
+
+  // 8. POST /api/auth/verify - Verify passkey authentication assertion
+  if (path === "/api/auth/verify" && method === "POST") {
+    const credentialId = body.id;
+    const storedCredential = credentials.find((c) => c.id === credentialId);
+    if (!storedCredential) {
+      // Return explicit HTTP 404 when credential is not found so client triggers signalUnknownCredential
+      return jsonResponse({ error: "Credential not found on server.", rpId: RP_ID }, 404);
+    }
+
+    const requireUserVerification = session.expectedUserVerification === "required";
+    storedCredential.lastUsedAt = Date.now();
+    storedCredential.counter = (storedCredential.counter || 0) + 1;
+    saveCredentials(credentials);
+
+    const matchedUser =
+      users.find((u) => u.passkeyUserId === storedCredential.passkeyUserId) || activeUser;
+    session.activeUserId = matchedUser.passkeyUserId;
+    session.challenge = null;
+    saveSession(session);
+
+    return jsonResponse({
+      verified: true,
+      rpId: RP_ID,
+      userId: matchedUser.passkeyUserId,
+      requireUserVerification,
+      user: matchedUser,
+      credential: storedCredential
+    });
+  }
+
+  // 9. POST /api/reauth/options - Step-up reauthentication options constrained to signed-in user's credentials
+  if (path === "/api/reauth/options" && method === "POST") {
+    const userPasskeys = credentials.filter((c) => c.passkeyUserId === activeUser.passkeyUserId);
+    const challenge = generateChallengeBase64Url(32);
+    session.challenge = challenge;
+    session.expectedUserVerification = "preferred";
+    saveSession(session);
+
+    const options = {
+      challenge,
+      rpId: RP_ID,
+      userVerification: "preferred",
+      // Strictly constrain allowCredentials to the active signed-in user's registered passkeys
+      allowCredentials: userPasskeys.map((cred) => ({
+        type: "public-key",
+        id: cred.id,
+        transports: cred.transports
+      }))
+    };
+    return jsonResponse(options);
+  }
+
+  // 10. POST /api/reauth/verify - Verify step-up reauthentication & strict account ownership
+  if (path === "/api/reauth/verify" && method === "POST") {
+    const credentialId = body.id;
+    const storedCredential = credentials.find((c) => c.id === credentialId);
+    if (!storedCredential) {
+      return jsonResponse({ error: "Credential not found.", rpId: RP_ID }, 404);
+    }
+    // Verify Account Ownership: storedCredential.passkeyUserId must strictly match active signed-in user
+    if (storedCredential.passkeyUserId !== activeUser.passkeyUserId) {
+      return jsonResponse(
+        { error: "Credential does not belong to the active signed-in user." },
+        403
+      );
+    }
+
+    storedCredential.lastUsedAt = Date.now();
+    storedCredential.counter = (storedCredential.counter || 0) + 1;
+    saveCredentials(credentials);
+
+    session.challenge = null;
+    session.reauthenticatedAt = Date.now();
+    saveSession(session);
+
+    return jsonResponse({
+      verified: true,
+      rpId: RP_ID,
+      userId: activeUser.passkeyUserId,
+      reauthenticatedAt: session.reauthenticatedAt
+    });
+  }
+
+  return null;
+}
+
+// Install transparent window.fetch interceptor for /api/* routes so direct fetch("/api/...") calls work seamlessly
+const nativeFetch = window.fetch ? window.fetch.bind(window) : null;
+if (nativeFetch) {
+  window.fetch = async function (input, init) {
+    const urlStr = typeof input === "string" ? input : input?.url || "";
+    if (urlStr.startsWith("/api/") || urlStr.includes("/api/")) {
+      const mockRes = await handleApiRequest(urlStr, init);
+      if (mockRes) return mockRes;
+    }
+    return nativeFetch(input, init);
+  };
+}
+
+// Exported API Client Helpers matching modern-web-guidance patterns
+export async function optionsFetch(params = {}) {
+  const isRegister =
+    "promotion" in params || "conditional" in params || "username" in params || "isRegistration" in params;
+  const endpoint = isRegister ? "/api/register/options" : "/api/auth/options";
+  const res = await fetch(endpoint, {
+    method: "POST",
+    headers: { "Content-Type": "application/json" },
+    body: JSON.stringify(params)
+  });
+  return res.json();
+}
