+      console.warn("SignalCurrentUserDetails sync warning:", e);
+    }
+  }
+}
+
+// ============================================================================
+// 4. PASSKEY REAUTHENTICATION (STEP-UP VERIFICATION FOR SENSITIVE ACTIONS)
+// ============================================================================
+
+function showTransactionSuccessUI(actionLabel = "Sensitive account action verified") {
+  const statusEl = document.getElementById("reauth-result-box");
+  if (statusEl) {
+    statusEl.hidden = false;
+    statusEl.textContent = `Identity verified via passkey! Completed: ${actionLabel} at ${formatTimestamp(
+      Date.now()
+    )}.`;
+  }
+  const reauthDialog = document.getElementById("reauth-dialog");
+  if (reauthDialog && reauthDialog.open) {
+    reauthDialog.close("verified");
+  }
+  setAccountStatus(`Passkey reauthentication succeeded: ${actionLabel}.`, "success");
+}
+
+export async function triggerButtonReauth(actionLabel = "Confirm Coffee Wallet Auto-Reload ($50.00)") {
+  if (!window.PublicKeyCredential) {
+    setAccountStatus("Passkey reauthentication is unavailable in this browser.", "error");
+    return;
+  }
+
+  // Abort any background suggestion flows to avoid passkey prompt collisions
+  reauthAbortController.abort();
+  reauthAbortController = new AbortController();
+  autofillAbortController.abort();
+  autofillAbortController = new AbortController();
+
+  const optionsResponse = await fetch("/api/reauth/options", {
+    method: "POST"
+  });
+  const optionsJSON = await optionsResponse.json();
+  const publicKey =
+    PublicKeyCredential.parseRequestOptionsFromJSON(optionsJSON);
+
+  try {
+    const credential = await navigator.credentials.get({
+      publicKey,
+      signal: reauthAbortController.signal
+    });
+
+    if (credential) {
+      const encodedCredential = credential.toJSON();
+      const verifyResponse = await fetch("/api/reauth/verify", {
+        method: "POST",
+        headers: { "Content-Type": "application/json" },
+        body: JSON.stringify(encodedCredential)
+      });
+
+      if (verifyResponse.ok) {
+        showTransactionSuccessUI(actionLabel);
+      } else if (
+        verifyResponse.status === 404 &&
+        PublicKeyCredential.signalUnknownCredential
+      ) {
