+          rpId: publicKey.rpId, // Always use server-provided rpId; DO NOT use window.location.hostname
+          credentialId: encodedCredential.id
+        });
+        setAccountStatus(
+          "Passkey no longer recognized during reauthentication.",
+          "error"
+        );
+      } else {
+        setAccountStatus(
+          "Reauthentication failed: credential does not belong to the signed-in account.",
+          "error"
+        );
+      }
+    }
+  } catch (err) {
+    if (err.name === "NotAllowedError") {
+      console.log("User cancelled reauthentication.");
+      setAccountStatus("Reauthentication cancelled.", "info");
+    }
+  }
+}
+
+// ============================================================================
+// 5. DOM EVENT WIRING & INITIALIZATION
+// ============================================================================
+
+function setupPasswordToggles() {
+  const toggleButtons = document.querySelectorAll("[data-toggle-password]");
+  for (const btn of toggleButtons) {
+    btn.addEventListener("click", () => {
+      const targetId = btn.getAttribute("data-toggle-password");
+      const input = document.getElementById(targetId);
+      if (!input) return;
+      const isShowing = input.type === "text";
+      input.type = isShowing ? "password" : "text";
+      btn.setAttribute("aria-pressed", String(!isShowing));
+      btn.textContent = isShowing ? "Show" : "Hide";
+    });
+  }
+}
+
+function wireAccountInteractions() {
+  setupPasswordToggles();
+
+  // 1. Sign-In Form (Password login + automatic Conditional Create passkey promotion)
+  const signinForm = document.getElementById("signin-form");
+  if (signinForm) {
+    signinForm.addEventListener("submit", async (e) => {
+      e.preventDefault();
+      if (!signinForm.checkValidity()) {
+        const firstInvalid = signinForm.querySelector(":invalid");
+        if (firstInvalid) firstInvalid.focus();
+        return;
+      }
+      const usernameVal = document.getElementById("username")?.value?.trim();
+      setAccountStatus(
+        `Signed in as ${usernameVal}. Checking if your device can silently upgrade you to a passkey...`,
+        "success"
+      );
+      await loadManagementPanel();
+      // Immediately after a successful password sign-in, attempt Conditional Create
+      await triggerConditionalCreate(autofillAbortController);
+    });
+  }
+
+  // 2. Explicit "Sign in with passkey" button
+  const passkeySigninBtn = document.getElementById("passkey-signin-btn");
+  if (passkeySigninBtn) {
+    passkeySigninBtn.addEventListener("click", () => {
+      triggerButtonAuthentication();
+    });
+  }
+
+  // 3. Customer Registration Form (New Account + Passkey Creation)
+  const registerForm = document.getElementById("customer-registration-form");
+  if (registerForm) {
+    registerForm.addEventListener("submit", async (e) => {
+      e.preventDefault();
+      if (!registerForm.checkValidity()) {
+        const firstInvalid = registerForm.querySelector(":invalid");
+        if (firstInvalid) firstInvalid.focus();
+        return;
+      }
+      const displayName = document.getElementById("reg-full-name")?.value?.trim();
+      const username = document.getElementById("reg-email")?.value?.trim();
+      await registerPasskey(true, { username, displayName });
+    });
+  }
+
+  // 4. Dedicated "Register with Passkey" button inside Registration card
+  const registerPasskeyBtn = document.getElementById("register-passkey-btn");
+  if (registerPasskeyBtn) {
+    registerPasskeyBtn.addEventListener("click", async () => {
+      const displayName =
+        document.getElementById("reg-full-name")?.value?.trim() || "Alex Rivera";
+      const username =
+        document.getElementById("reg-email")?.value?.trim() ||
+        "alex.rivera@dailygrind.coffee";
+      await registerPasskey(true, { username, displayName });
+    });
+  }
+
+  // 5. Management Panel "Create passkey" button (omits authenticatorAttachment so security keys work too)
+  const createPasskeyBtn = document.getElementById("create-passkey");
+  if (createPasskeyBtn) {
+    createPasskeyBtn.addEventListener("click", async () => {
+      await registerPasskey(false);
+    });
+  }
+
+  // 6. Profile Update Form (triggers PUT /api/user + signalCurrentUserDetails)
+  const profileForm = document.getElementById("profile-update-form");
+  if (profileForm) {
+    profileForm.addEventListener("submit", async (e) => {
+      e.preventDefault();
+      if (!profileForm.checkValidity()) {
+        const firstInvalid = profileForm.querySelector(":invalid");
+        if (firstInvalid) firstInvalid.focus();
+        return;
+      }
+      const updatedName = document.getElementById("profile-username")?.value?.trim();
+      const updatedDisplayName = document
+        .getElementById("profile-display-name")
+        ?.value?.trim();
+      const defaultBrew = document.getElementById("profile-default-brew")?.value;
+      await performUserRename(updatedName, updatedDisplayName, defaultBrew);
+    });
+  }
+
+  // 7. Reauthentication Buttons (Direct Button + Step-Up Dialog Modal)
+  const reauthBtn = document.getElementById("reauth-btn");
+  if (reauthBtn) {
+    reauthBtn.addEventListener("click", () => {
+      triggerButtonReauth("Confirm $50.00 Coffee Wallet Auto-Reload");
+    });
+  }
+
+  const openReauthDialogBtn = document.getElementById("open-reauth-modal-btn");
+  const reauthDialog = document.getElementById("reauth-dialog");
+  const dialogReauthConfirmBtn = document.getElementById("dialog-reauth-confirm-btn");
+
+  if (openReauthDialogBtn && reauthDialog) {
+    openReauthDialogBtn.addEventListener("click", () => {
+      if (typeof reauthDialog.showModal === "function") {
+        reauthDialog.showModal();
+      }
+    });
+  }
+
+  if (dialogReauthConfirmBtn) {
+    dialogReauthConfirmBtn.addEventListener("click", () => {
+      triggerButtonReauth("Export Saved Payment Methods & Rewards History");
+    });
+  }
+}
+
+window.addEventListener("DOMContentLoaded", async () => {
+  wireAccountInteractions();
+  await gatePasskeyCreationUI();
+  await loadManagementPanel();
+  await initializeConditionalAutofill();
+});
