+import { UAParser } from 'ua-parser-js';
+import { compare } from 'compare-versions';
+export class isVersion {
+    constructor(ua) {
+        Object.defineProperty(this, "iOS174To183", {
+            enumerable: true,
+            configurable: true,
+            writable: true,
+            value: void 0
+        });
+        Object.defineProperty(this, "safari174To183", {
+            enumerable: true,
+            configurable: true,
+            writable: true,
+            value: void 0
+        });
+        Object.defineProperty(this, "iOS18OrLater", {
+            enumerable: true,
+            configurable: true,
+            writable: true,
+            value: void 0
+        });
+        Object.defineProperty(this, "desktopBlink128OrLater", {
+            enumerable: true,
+            configurable: true,
+            writable: true,
+            value: void 0
+        });
+        Object.defineProperty(this, "desktopBlink135OrLater", {
+            enumerable: true,
+            configurable: true,
+            writable: true,
+            value: void 0
+        });
+        const { browser, engine, os } = UAParser(ua);
+        if (!browser?.version || !browser?.name) {
+            throw new Error('Browser version not found.');
+        }
+        if (!engine?.version || !engine?.name) {
+            throw new Error('Engine version not found.');
+        }
+        if (!os?.version || !os?.name) {
+            throw new Error('OS version not found.');
+        }
+        // Between iOS 17.4 (inclusive) and 18.3 (inclusive), defined by version >= '17.4' and version < '18.4'
+        this.iOS174To183 = os.name === 'iOS' &&
+            compare(os.version, '17.4', '>=') &&
+            compare(os.version, '18.4', '<');
+        // Between macOS Safari 17.4 and 18.3
+        this.safari174To183 = os.name === 'Mac OS' &&
+            browser.name === 'Safari' &&
+            compare(browser.version, '17.4', '>=') &&
+            compare(browser.version, '18.4', '<');
+        // iOS 18 or later
+        this.iOS18OrLater = os.name === 'iOS' && compare(os.version, '18', '>=');
+        // Blink 128 or later
+        this.desktopBlink128OrLater = engine.name === 'Blink' &&
+            ['Mac OS', 'Windows', 'Linux', 'Chrome OS'].includes(os.name) &&
+            compare(engine.version, '128', '>=');
+        // Blink 135 or later
+        this.desktopBlink135OrLater = engine.name === 'Blink' &&
+            ['macOS', 'Windows', 'Linux', 'Chrome OS'].includes(os.name) &&
+            compare(engine.version, '135', '>=');
+    }
+}
