+import React, { useState } from 'react';
+import {
+  authenticateWithPasskey,
+  saveStoredUser,
+  type AuthenticatedUser,
+} from '../utils/webauthn-client';
+
+interface ReauthModalProps {
+  isOpen: boolean;
+  user: AuthenticatedUser;
+  actionTitle: string;
+  actionDescription?: string;
+  onSuccess: (updatedUser: AuthenticatedUser) => void;
+  onCancel: () => void;
+}
+
+export default function ReauthModal({
+  isOpen,
+  user,
+  actionTitle,
+  actionDescription,
+  onSuccess,
+  onCancel,
+}: ReauthModalProps) {
+  const [mode, setMode] = useState<'passkey' | 'password'>('passkey');
+  const [password, setPassword] = useState('');
+  const [loading, setLoading] = useState(false);
+  const [error, setError] = useState<string | null>(null);
+
+  if (!isOpen) return null;
+
+  const handlePasskeyReauth = async () => {
+    setError(null);
+    setLoading(true);
+    try {
+      const { user: verifiedUser } = await authenticateWithPasskey({
+        username: user.username,
+        purpose: 'reauthentication',
+      });
+      onSuccess(verifiedUser);
+    } catch (err: any) {
+      if (err?.name === 'NotAllowedError') {
+        setError('Passkey verification was cancelled or timed out. Please try again.');
+      } else {
+        setError(err?.message || 'Could not verify your passkey.');
+      }
+    } finally {
+      setLoading(false);
+    }
+  };
+
+  const handlePasswordReauth = async (e: React.FormEvent) => {
+    e.preventDefault();
+    setError(null);
+    if (!password || password.length < 4) {
+      setError('Please enter your account password to confirm your identity.');
+      return;
+    }
+    setLoading(true);
+    try {
+      const refreshedUser: AuthenticatedUser = {
+        ...user,
+        lastReauthAt: Date.now(),
+      };
+      saveStoredUser(refreshedUser);
+      setPassword('');
+      onSuccess(refreshedUser);
+    } finally {
+      setLoading(false);
+    }
+  };
+
+  return (
+    <div
+      className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-xs p-4"
+      role="dialog"
+      aria-modal="true"
+      aria-labelledby="reauth-modal-title"
+    >
+      <div className="bg-white border border-gray-200 rounded-xl shadow-xl max-w-md w-full p-6 relative">
+        <div className="flex items-start justify-between mb-4">
+          <div className="flex items-center space-x-3">
+            <div className="w-10 h-10 rounded-full bg-amber-100 text-amber-800 flex items-center justify-center flex-shrink-0">
+              <svg
+                xmlns="http://www.w3.org/2000/svg"
+                fill="none"
+                viewBox="0 0 24 24"
+                strokeWidth={1.8}
+                stroke="currentColor"
+                className="w-5 h-5"
+              >
+                <path
+                  strokeLinecap="round"
+                  strokeLinejoin="round"
+                  d="M16.5 10.5V6.75a4.5 4.5 0 1 0-9 0v3.75m-.75 11.25h10.5a2.25 2.25 0 0 0 2.25-2.25v-6.75a2.25 2.25 0 0 0-2.25-2.25H6.75a2.25 2.25 0 0 0-2.25 2.25v6.75a2.25 2.25 0 0 0 2.25 2.25Z"
+                />
+              </svg>
+            </div>
+            <div>
+              <h3 id="reauth-modal-title" className="text-lg font-bold text-gray-900">
+                Verify it&apos;s you
+              </h3>
+              <p className="text-xs text-gray-500">Reauthentication required for security</p>
+            </div>
+          </div>
+          <button
+            type="button"
+            onClick={onCancel}
+            aria-label="Close reauthentication dialog"
+            className="text-gray-400 hover:text-gray-600 p-1"
+          >
+            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
+              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
+            </svg>
+          </button>
+        </div>
+
+        <div className="mb-4 p-3 bg-gray-50 border border-gray-200 rounded-lg text-sm text-gray-700">
+          <p className="font-semibold text-gray-900">{actionTitle}</p>
+          <p className="text-xs text-gray-600 mt-0.5">
+            {actionDescription ||
+              `To protect your account (${user.username}), please confirm your identity with a passkey before continuing.`}
+          </p>
+        </div>
+
+        {error && (
+          <div className="mb-4 p-3 text-sm text-red-700 bg-red-100 border border-red-200 rounded-lg" role="alert">
+            {error}
+          </div>
+        )}
+
+        {mode === 'passkey' ? (
+          <div className="space-y-3">
+            <button
+              type="button"
+              onClick={handlePasskeyReauth}
+              disabled={loading}
+              className="w-full py-2.5 px-4 rounded-md shadow-xs text-sm font-semibold text-white bg-gray-900 hover:bg-gray-800 flex items-center justify-center space-x-2 disabled:opacity-60 cursor-pointer"
+            >
+              <svg
+                xmlns="http://www.w3.org/2000/svg"
+                fill="none"
+                viewBox="0 0 24 24"
+                strokeWidth={1.8}
+                stroke="currentColor"
+                className="w-5 h-5"
+              >
+                <path
+                  strokeLinecap="round"
+                  strokeLinejoin="round"
+                  d="M15.75 5.25a3 3 0 0 1 3 3m3 0a6 6 0 0 1-7.029 5.912c-.563-.097-1.159.026-1.563.43L10.5 17.25H8.25v2.25H6v2.25H2.25v-2.818c0-.597.237-1.17.659-1.591l6.499-6.499c.404-.404.527-1 .43-1.563A6 6 0 1 1 21.75 8.25Z"
+                />
+              </svg>
+              <span>{loading ? 'Waiting for passkey...' : 'Verify with Passkey'}</span>
+            </button>
+
+            <div className="flex items-center justify-between pt-2 text-xs text-gray-500">
+              <button
+                type="button"
+                onClick={() => {
+                  setError(null);
+                  setMode('password');
+                }}
+                className="text-gray-700 hover:underline font-medium"
+              >
+                Use password instead
