--- /dev/null
+++ b/src/pages/api/passkeys/auth-options.ts
@@ -0,0 +1,66 @@
+import type { APIRoute } from 'astro';
+import {
+  generateChallenge,
+  getRpIdFromRequest,
+  getUserByUsername,
+} from '../../../utils/passkey-store';
+
+export const POST: APIRoute = async ({ request }) => {
+  try {
+    const body = await request.json().catch(() => ({}));
+    const { username, purpose = 'authentication', knownCredentialIds = [] } = body || {};
+
+    const rpId = getRpIdFromRequest(request);
+    const user = username ? getUserByUsername(username) : undefined;
+    const challenge = generateChallenge(
+      purpose === 'reauthentication' ? 'reauthentication' : 'authentication',
+      user?.id,
+      user?.username
+    );
+
+    const allowCredentials: Array<{
+      id: string;
+      type: 'public-key';
+      transports?: string[];
+    }> = [];
+
+    if (user && user.passkeys.length > 0) {
+      for (const pk of user.passkeys) {
+        allowCredentials.push({
+          id: pk.id,
+          type: 'public-key',
+          transports: pk.transports,
+        });
+      }
+    }
+
+    if (Array.isArray(knownCredentialIds)) {
+      for (const id of knownCredentialIds) {
+        if (typeof id === 'string' && !allowCredentials.some((c) => c.id === id)) {
+          allowCredentials.push({
+            id,
+            type: 'public-key',
+            transports: ['internal', 'hybrid'],
+          });
+        }
+      }
+    }
+
+    return new Response(
+      JSON.stringify({
+        challenge,
+        rpId,
+        timeout: 60000,
+        userVerification: 'required',
+        // For discoverable credentials (usernameless sign-in), allowCredentials is empty
+        allowCredentials: username ? allowCredentials : [],
+      }),
+      { status: 200, headers: { 'Content-Type': 'application/json' } }
+    );
+  } catch (err: any) {
+    return new Response(
+      JSON.stringify({ error: err?.message || 'Failed to generate authentication options' }),
+      { status: 500, headers: { 'Content-Type': 'application/json' } }
+    );
+  }
+};
diff --git a/src/pages/api/passkeys/auth-verify.ts b/src/pages/api/passkeys/auth-verify.ts
