+import type { APIRoute } from 'astro';
+import { getOrCreateUser, getUserByUsername } from '../../../utils/passkey-store';
+
+export const GET: APIRoute = async ({ url }) => {
+  const username = url.searchParams.get('username') || 'editor';
+  const user = getUserByUsername(username) || getOrCreateUser(username);
+
+  return new Response(
+    JSON.stringify({
+      user: {
+        id: user.id,
+        username: user.username,
+        displayName: user.displayName,
+        email: user.email,
+        passkeys: user.passkeys,
+      },
+    }),
+    { status: 200, headers: { 'Content-Type': 'application/json' } }
+  );
+};
+
+export const PATCH: APIRoute = async ({ request }) => {
+  try {
+    const body = await request.json();
+    const { username, credentialId, name, displayName, email } = body || {};
+
+    if (!username) {
+      return new Response(JSON.stringify({ error: 'Username is required' }), {
+        status: 400,
+        headers: { 'Content-Type': 'application/json' },
+      });
+    }
+
+    const user = getOrCreateUser(username);
+
+    if (displayName !== undefined) user.displayName = displayName;
+    if (email !== undefined) user.email = email;
+
+    if (credentialId && typeof name === 'string' && name.trim()) {
+      const pk = user.passkeys.find((p) => p.id === credentialId);
+      if (!pk) {
+        return new Response(JSON.stringify({ error: 'Passkey not found' }), {
+          status: 404,
+          headers: { 'Content-Type': 'application/json' },
+        });
+      }
+      pk.name = name.trim();
+    }
+
+    return new Response(
+      JSON.stringify({
+        user: {
+          id: user.id,
+          username: user.username,
+          displayName: user.displayName,
+          email: user.email,
+          passkeys: user.passkeys,
+        },
+      }),
+      { status: 200, headers: { 'Content-Type': 'application/json' } }
+    );
+  } catch (err: any) {
+    return new Response(
+      JSON.stringify({ error: err?.message || 'Failed to update passkey' }),
+      { status: 500, headers: { 'Content-Type': 'application/json' } }
+    );
+  }
+};
+
+export const DELETE: APIRoute = async ({ request }) => {
+  try {
+    const body = await request.json();
+    const { username, credentialId } = body || {};
+
+    if (!username || !credentialId) {
+      return new Response(
+        JSON.stringify({ error: 'Username and credentialId are required' }),
+        { status: 400, headers: { 'Content-Type': 'application/json' } }
+      );
+    }
+
+    const user = getOrCreateUser(username);
+    user.passkeys = user.passkeys.filter((pk) => pk.id !== credentialId);
+
+    return new Response(
+      JSON.stringify({
+        deleted: true,
+        user: {
+          id: user.id,
+          username: user.username,
+          displayName: user.displayName,
+          email: user.email,
+          passkeys: user.passkeys,
+        },
+      }),
+      { status: 200, headers: { 'Content-Type': 'application/json' } }
+    );
+  } catch (err: any) {
+    return new Response(
+      JSON.stringify({ error: err?.message || 'Failed to delete passkey' }),
+      { status: 500, headers: { 'Content-Type': 'application/json' } }
+    );
+  }
+};
