+import type { APIRoute } from 'astro';
+import {
+  generateChallenge,
+  getOrCreateUser,
+  getRpIdFromRequest,
+} from '../../../utils/passkey-store';
+
+export const POST: APIRoute = async ({ request }) => {
+  try {
+    const body = await request.json();
+    const { username, displayName, email, authenticatorAttachment } = body || {};
+
+    if (!username || typeof username !== 'string' || !username.trim()) {
+      return new Response(
+        JSON.stringify({ error: 'Username is required to register a passkey.' }),
+        { status: 400, headers: { 'Content-Type': 'application/json' } }
+      );
+    }
+
+    const user = getOrCreateUser(username, { displayName, email });
+    const challenge = generateChallenge('registration', user.id, user.username);
+    const rpId = getRpIdFromRequest(request);
+
+    const options = {
+      challenge,
+      rp: {
+        name: 'The DevTools Times',
+        id: rpId,
+      },
+      user: {
+        id: user.id,
+        name: user.username,
+        displayName: user.displayName || user.username,
+      },
+      pubKeyCredParams: [
+        { alg: -7, type: 'public-key' },   // ES256
+        { alg: -257, type: 'public-key' }, // RS256
+        { alg: -8, type: 'public-key' },   // EdDSA
+      ],
+      timeout: 60000,
+      attestation: 'none',
+      excludeCredentials: user.passkeys.map((pk) => ({
+        id: pk.id,
+        type: 'public-key',
+        transports: pk.transports,
+      })),
+      authenticatorSelection: {
+        residentKey: 'required',
+        requireResidentKey: true,
+        userVerification: 'required',
+        ...(authenticatorAttachment ? { authenticatorAttachment } : {}),
+      },
+    };
+
+    return new Response(JSON.stringify(options), {
+      status: 200,
+      headers: { 'Content-Type': 'application/json' },
+    });
+  } catch (err: any) {
+    return new Response(
+      JSON.stringify({ error: err?.message || 'Failed to generate registration options' }),
+      { status: 500, headers: { 'Content-Type': 'application/json' } }
+    );
+  }
+};
