@@ -0,0 +1,95 @@
+import type { APIRoute } from 'astro';
+import {
+  consumeChallenge,
+  getOrCreateUser,
+  type StoredPasskey,
+} from '../../../utils/passkey-store';
+
+export const POST: APIRoute = async ({ request, session }) => {
+  try {
+    const body = await request.json();
+    const { username, displayName, email, passkeyName, credential } = body || {};
+
+    if (!username || !credential || !credential.id || !credential.response?.clientDataJSON) {
+      return new Response(
+        JSON.stringify({ error: 'Invalid passkey registration payload.' }),
+        { status: 400, headers: { 'Content-Type': 'application/json' } }
+      );
+    }
+
+    // Parse clientDataJSON to verify type === 'webauthn.create' and challenge
+    const clientDataStr = Buffer.from(credential.response.clientDataJSON, 'base64url').toString('utf8');
+    const clientData = JSON.parse(clientDataStr);
+
+    if (clientData.type !== 'webauthn.create') {
+      return new Response(
+        JSON.stringify({ error: 'Invalid WebAuthn clientData type. Expected webauthn.create.' }),
+        { status: 400, headers: { 'Content-Type': 'application/json' } }
+      );
+    }
+
+    const challengeRecord = consumeChallenge(clientData.challenge);
+    if (!challengeRecord || challengeRecord.purpose !== 'registration') {
+      return new Response(
+        JSON.stringify({ error: 'Invalid or expired passkey registration challenge.' }),
+        { status: 400, headers: { 'Content-Type': 'application/json' } }
+      );
+    }
+
+    const user = getOrCreateUser(username, { displayName, email });
+
+    // Prevent duplicate credential IDs
+    const existingIdx = user.passkeys.findIndex((pk) => pk.id === credential.id);
+    const nowIso = new Date().toISOString();
+
+    const newPasskey: StoredPasskey = {
+      id: credential.id,
+      name: passkeyName || `Passkey (${new Date().toLocaleDateString()})`,
+      publicKey: credential.response.publicKey || '',
+      algorithm: credential.response.algorithm ?? -7,
+      transports: Array.isArray(credential.response.transports)
+        ? credential.response.transports
+        : ['internal', 'hybrid'],
+      createdAt: nowIso,
+      lastUsedAt: nowIso,
+      backedUp: true,
+      deviceType: credential.authenticatorAttachment === 'cross-platform' ? 'singleDevice' : 'multiDevice',
+    };
+
+    if (existingIdx >= 0) {
+      user.passkeys[existingIdx] = newPasskey;
+    } else {
+      user.passkeys.push(newPasskey);
+    }
+
+    if (session) {
+      await session.set('user', {
+        id: user.id,
+        username: user.username,
+        displayName: user.displayName,
+        email: user.email,
+        lastReauthAt: Date.now(),
+      });
+    }
+
+    return new Response(
+      JSON.stringify({
+        verified: true,
+        passkey: newPasskey,
+        user: {
+          id: user.id,
+          username: user.username,
+          displayName: user.displayName,
+          email: user.email,
+          passkeys: user.passkeys,
+        },
+      }),
+      { status: 200, headers: { 'Content-Type': 'application/json' } }
+    );
+  } catch (err: any) {
+    return new Response(
+      JSON.stringify({ error: err?.message || 'Failed to verify passkey registration' }),
+      { status: 500, headers: { 'Content-Type': 'application/json' } }
+    );
+  }
+};
diff --git a/src/utils/passkey-store.ts b/src/utils/passkey-store.ts
new file mode 100644
index 0000000..59bc318
--- /dev/null
+++ b/src/utils/passkey-store.ts
@@ -0,0 +1,152 @@
+import crypto from 'node:crypto';
+
+export interface StoredPasskey {
+  id: string; // base64url encoded credential ID
+  name: string;
+  publicKey: string; // base64url encoded public key
+  algorithm: number; // COSE algorithm identifier (-7 for ES256, -257 for RS256)
+  transports: string[];
+  createdAt: string;
+  lastUsedAt: string | null;
+  aaguid?: string;
+  backedUp?: boolean;
+  deviceType?: 'singleDevice' | 'multiDevice';
+}
+
+export interface UserAccount {
+  id: string; // base64url user handle
+  username: string;
+  displayName: string;
+  email: string;
+  passwordHash?: string;
+  createdAt: string;
+  passkeys: StoredPasskey[];
+}
+
+export interface ChallengeRecord {
+  challenge: string; // base64url encoded
+  userId?: string;
+  username?: string;
+  purpose: 'registration' | 'authentication' | 'reauthentication';
+  expiresAt: number;
+}
+
+// Global in-memory store across module reloads in server process
+const globalStore = globalThis as unknown as {
+  __devtoolsTimesUsers?: Map<string, UserAccount>;
+  __devtoolsTimesChallenges?: Map<string, ChallengeRecord>;
+};
+
+if (!globalStore.__devtoolsTimesUsers) {
+  const defaultUsers = new Map<string, UserAccount>();
+  // Pre-seed a demo user so testing sign-in/account settings works immediately or after registration
+  const demoId = Buffer.from('user-demo-devtools-times').toString('base64url');
+  defaultUsers.set('editor', {
+    id: demoId,
+    username: 'editor',
+    displayName: 'Alex Rivera (Senior Editor)',
+    email: 'alex.rivera@devtoolstimes.example',
+    passwordHash: crypto.createHash('sha256').update('devtools123').digest('hex'),
+    createdAt: new Date(Date.now() - 86400000 * 30).toISOString(),
+    passkeys: [
+      {
+        id: Buffer.from('demo-passkey-credential-id-001').toString('base64url'),
+        name: 'MacBook Pro (Touch ID)',
+        publicKey: Buffer.from('demo-public-key-bytes').toString('base64url'),
+        algorithm: -7,
+        transports: ['internal', 'hybrid'],
+        createdAt: new Date(Date.now() - 86400000 * 14).toISOString(),
+        lastUsedAt: new Date(Date.now() - 3600000 * 5).toISOString(),
+        aaguid: 'adce0002-35bc-c60a-648b-0b25f1f05503',
+        backedUp: true,
+        deviceType: 'multiDevice',
+      },
+    ],
+  });
+  globalStore.__devtoolsTimesUsers = defaultUsers;
+}
+
+if (!globalStore.__devtoolsTimesChallenges) {
+  globalStore.__devtoolsTimesChallenges = new Map<string, ChallengeRecord>();
+}
+
+export const usersStore = globalStore.__devtoolsTimesUsers;
+export const challengesStore = globalStore.__devtoolsTimesChallenges;
+
+export function hashPassword(password: string): string {
+  return crypto.createHash('sha256').update(password).digest('hex');
+}
+
+export function generateChallenge(
+  purpose: ChallengeRecord['purpose'],
+  userId?: string,
+  username?: string
+): string {
+  const challenge = crypto.randomBytes(32).toString('base64url');
+  challengesStore.set(challenge, {
+    challenge,
+    userId,
+    username,
+    purpose,
+    expiresAt: Date.now() + 5 * 60 * 1000, // 5 minutes TTL
+  });
+  return challenge;
+}
+
+export function consumeChallenge(challenge: string): ChallengeRecord | null {
+  const record = challengesStore.get(challenge);
+  if (!record) return null;
+  challengesStore.delete(challenge);
+  if (Date.now() > record.expiresAt) return null;
+  return record;
+}
+
+export function getUserByUsername(username: string): UserAccount | undefined {
+  return usersStore.get(username.trim().toLowerCase());
+}
+
+export function getUserById(userId: string): UserAccount | undefined {
+  for (const user of usersStore.values()) {
+    if (user.id === userId) return user;
+  }
+  return undefined;
+}
+
+export function findUserByCredentialId(credentialId: string): {
+  user: UserAccount;
+  passkey: StoredPasskey;
+} | null {
+  for (const user of usersStore.values()) {
+    const passkey = user.passkeys.find((pk) => pk.id === credentialId);
+    if (passkey) {
+      return { user, passkey };
+    }
+  }
+  return null;
+}
+
+export function getOrCreateUser(
+  username: string,
+  options?: { displayName?: string; email?: string; password?: string }
+): UserAccount {
+  const normalized = username.trim().toLowerCase();
+  let user = usersStore.get(normalized);
+  if (!user) {
+    user = {
+      id: crypto.randomBytes(16).toString('base64url'),
+      username: normalized,
+      displayName: options?.displayName || username.trim(),
+      email: options?.email || `${normalized}@devtoolstimes.example`,
+      passwordHash: options?.password ? hashPassword(options.password) : undefined,
+      createdAt: new Date().toISOString(),
+      passkeys: [],
+    };
+    usersStore.set(normalized, user);
+  }
+  return user;
+}
+
+export function getRpIdFromRequest(request: Request): string {
+  const url = new URL(request.url);
+  return url.hostname || 'localhost';
+}
diff --git a/src/utils/webauthn-client.ts b/src/utils/webauthn-client.ts
new file mode 100644
index 0000000..4095f3c
--- /dev/null
+++ b/src/utils/webauthn-client.ts
@@ -0,0 +1,369 @@
+// Client-side WebAuthn (Passkey) utilities and local persistence fallback
+
+export interface PasskeyCredentialMeta {
+  id: string; // base64url credential ID
+  name: string;
+  publicKey?: string;
+  algorithm?: number;
+  transports: string[];
+  createdAt: string;
+  lastUsedAt: string | null;
+  backedUp?: boolean;
+  deviceType?: 'singleDevice' | 'multiDevice';
+}
+
+export interface AuthenticatedUser {
+  id: string;
+  username: string;
+  displayName: string;
+  email: string;
+  authMethod: 'passkey' | 'password';
+  lastReauthAt: number; // timestamp in ms
+  passkeys: PasskeyCredentialMeta[];
+}
+
+const STORAGE_USER_KEY = 'devtools_times_auth_user';
+const STORAGE_ACCOUNTS_KEY = 'devtools_times_accounts_db';
+export const REAUTH_WINDOW_MS = 5 * 60 * 1000; // 5 minutes fresh authentication window
+
+export function bufferToBase64url(buffer: ArrayBuffer): string {
+  const bytes = new Uint8Array(buffer);
+  let binary = '';
+  for (let i = 0; i < bytes.byteLength; i++) {
+    binary += String.fromCharCode(bytes[i]);
+  }
+  return btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
+}
+
+export function base64urlToBuffer(base64url: string): ArrayBuffer {
+  const padding = '='.repeat((4 - (base64url.length % 4)) % 4);
+  const base64 = (base64url + padding).replace(/-/g, '+').replace(/_/g, '/');
+  const rawData = atob(base64);
+  const outputArray = new Uint8Array(rawData.length);
+  for (let i = 0; i < rawData.length; ++i) {
+    outputArray[i] = rawData.charCodeAt(i);
+  }
+  return outputArray.buffer;
+}
+
+export async function checkPasskeySupport(): Promise<{
+  webauthnSupported: boolean;
+  platformAuthenticatorAvailable: boolean;
+  conditionalMediationAvailable: boolean;
+}> {
+  if (typeof window === 'undefined' || !window.PublicKeyCredential) {
+    return {
+      webauthnSupported: false,
+      platformAuthenticatorAvailable: false,
+      conditionalMediationAvailable: false,
+    };
+  }
+
+  let platformAuthenticatorAvailable = false;
+  let conditionalMediationAvailable = false;
+
+  try {
+    if (typeof PublicKeyCredential.isUserVerifyingPlatformAuthenticatorAvailable === 'function') {
+      platformAuthenticatorAvailable =
+        await PublicKeyCredential.isUserVerifyingPlatformAuthenticatorAvailable();
+    }
+  } catch {
+    platformAuthenticatorAvailable = false;
+  }
+
+  try {
+    if (typeof PublicKeyCredential.isConditionalMediationAvailable === 'function') {
+      conditionalMediationAvailable =
+        await PublicKeyCredential.isConditionalMediationAvailable();
+    }
+  } catch {
+    conditionalMediationAvailable = false;
+  }
+
+  return {
+    webauthnSupported: true,
+    platformAuthenticatorAvailable,
+    conditionalMediationAvailable,
+  };
+}
+
+export function inferPasskeyFriendlyName(): string {
+  if (typeof navigator === 'undefined') return 'Passkey Device';
+  const ua = navigator.userAgent;
+  if (/Macintosh|Mac OS X/i.test(ua)) return 'iCloud Keychain / Mac Touch ID';
+  if (/iPhone|iPad|iPod/i.test(ua)) return 'iCloud Keychain (iOS)';
+  if (/Android/i.test(ua)) return 'Google Password Manager (Android)';
+  if (/Windows/i.test(ua)) return 'Windows Hello';
+  if (/Linux/i.test(ua)) return 'Chrome Profile Passkey (Linux)';
+  return 'Passkey Authenticator';
+}
+
+export function getStoredUser(): AuthenticatedUser | null {
+  if (typeof window === 'undefined') return null;
+  try {
+    const raw = localStorage.getItem(STORAGE_USER_KEY);
+    if (!raw) return null;
+    return JSON.parse(raw) as AuthenticatedUser;
+  } catch {
+    return null;
+  }
+}
+
+export function saveStoredUser(user: AuthenticatedUser | null): void {
+  if (typeof window === 'undefined') return;
+  try {
+    if (!user) {
+      localStorage.removeItem(STORAGE_USER_KEY);
+    } else {
+      localStorage.setItem(STORAGE_USER_KEY, JSON.stringify(user));
+      // Also sync to local accounts registry so passkey IDs persist across sign-out/sign-in
+      const accounts = getLocalAccountsMap();
+      accounts[user.username.toLowerCase()] = user;
+      localStorage.setItem(STORAGE_ACCOUNTS_KEY, JSON.stringify(accounts));
+    }
+    window.dispatchEvent(new CustomEvent('devtools-times:auth-change', { detail: user }));
+  } catch {
+    // ignore storage errors
+  }
