+
+export async function registerPasskeyCredential(
+  params: RegisterPasskeyParams
+): Promise<{ user: AuthenticatedUser; passkey: PasskeyCredentialMeta }> {
+  const baseUrl = import.meta.env.BASE_URL || '/';
+  const optionsRes = await fetch(`${baseUrl}api/passkeys/register-options`, {
+    method: 'POST',
+    headers: { 'Content-Type': 'application/json' },
+    body: JSON.stringify({
+      username: params.username,
+      displayName: params.displayName || params.username,
+      email: params.email,
+      authenticatorAttachment: params.authenticatorAttachment,
+    }),
+  });
+
+  if (!optionsRes.ok) {
+    const errData = await optionsRes.json().catch(() => ({}));
+    throw new Error(errData.error || 'Failed to get passkey registration options');
