+
+export interface AuthenticatePasskeyParams {
+  username?: string;
+  purpose?: 'authentication' | 'reauthentication';
+  mediation?: CredentialMediationRequirement;
+  signal?: AbortSignal;
+}
+
+export async function authenticateWithPasskey(
+  params: AuthenticatePasskeyParams = {}
+): Promise<{ user: AuthenticatedUser; passkeyId: string }> {
+  const baseUrl = import.meta.env.BASE_URL || '/';
+  const localAccounts = getLocalAccountsMap();
+  const knownCredIds: string[] = [];
+
+  if (params.username) {
+    const localAcc = localAccounts[params.username.toLowerCase()];
+    if (localAcc?.passkeys) {
+      for (const pk of localAcc.passkeys) {
+        knownCredIds.push(pk.id);
+      }
+    }
+  }
+
+  const optionsRes = await fetch(`${baseUrl}api/passkeys/auth-options`, {
+    method: 'POST',
+    headers: { 'Content-Type': 'application/json' },
+    body: JSON.stringify({
+      username: params.username,
+      purpose: params.purpose || 'authentication',
+      knownCredentialIds: knownCredIds,
+    }),
+  });
+
+  if (!optionsRes.ok) {
+    const errData = await optionsRes.json().catch(() => ({}));
+    throw new Error(errData.error || 'Failed to initialize passkey authentication');
+  }
+
+  const options = await optionsRes.json();
+
+  if (!window.PublicKeyCredential || !navigator.credentials) {
+    throw new Error('WebAuthn is not supported in this browser environment.');
+  }
+
+  const publicKeyRequestOptions: PublicKeyCredentialRequestOptions = {
+    challenge: base64urlToBuffer(options.challenge),
+    rpId: window.location.hostname || options.rpId,
+    timeout: options.timeout ?? 60000,
+    userVerification: options.userVerification ?? 'required',
+    allowCredentials:
+      options.allowCredentials && options.allowCredentials.length > 0
+        ? options.allowCredentials.map(
+            (cred: { id: string; type: PublicKeyCredentialType; transports?: AuthenticatorTransport[] }) => ({
+              id: base64urlToBuffer(cred.id),
+              type: cred.type,
+              transports: cred.transports,
+            })
+          )
+        : undefined,
+  };
+
+  const credential = (await navigator.credentials.get({
+    publicKey: publicKeyRequestOptions,
+    mediation: params.mediation,
+    signal: params.signal,
+  })) as PublicKeyCredential | null;
+
+  if (!credential) {
+    throw new Error('Passkey verification was cancelled or returned no assertion.');
+  }
+
+  const response = credential.response as AuthenticatorAssertionResponse;
+
+  const verifyRes = await fetch(`${baseUrl}api/passkeys/auth-verify`, {
+    method: 'POST',
+    headers: { 'Content-Type': 'application/json' },
+    body: JSON.stringify({
+      username: params.username,
+      purpose: params.purpose || 'authentication',
+      credential: {
+        id: credential.id,
+        rawId: bufferToBase64url(credential.rawId),
+        type: credential.type,
+        response: {
+          clientDataJSON: bufferToBase64url(response.clientDataJSON),
+          authenticatorData: bufferToBase64url(response.authenticatorData),
+          signature: bufferToBase64url(response.signature),
+          userHandle: response.userHandle ? bufferToBase64url(response.userHandle) : null,
+        },
+      },
+    }),
+  });
+
+  if (!verifyRes.ok) {
+    const errData = await verifyRes.json().catch(() => ({}));
+    throw new Error(errData.error || 'Passkey verification failed');
+  }
+
+  const result = await verifyRes.json();
+  const updatedUser: AuthenticatedUser = {
+    ...result.user,
+    authMethod: 'passkey',
+    lastReauthAt: Date.now(),
+  };
+  saveStoredUser(updatedUser);
+  return { user: updatedUser, passkeyId: credential.id };
+}

