+  <script>
+    (function () {
+      const container = document.getElementById('toast-container');
+      const DEFAULT_DURATION = 4000;
+
+      const ICONS = {
+        success: '☕',
+        info: '✨',
+        warning: '⏱️'
+      };
+
+      function dismissToast(toast) {
+        if (!toast || toast.classList.contains('toast-exit')) return;
+        if (toast._dismissTimer) {
+          clearTimeout(toast._dismissTimer);
+          toast._dismissTimer = null;
+        }
+        toast.classList.remove('toast-visible');
+        toast.classList.add('toast-exit');
+
+        const removeEl = () => {
+          if (toast.parentNode) {
+            toast.parentNode.removeChild(toast);
+          }
+        };
+
+        toast.addEventListener('animationend', removeEl, { once: true });
+        setTimeout(removeEl, 350);
+      }
+
+      function createToast({ title = 'Notification', message = 'Action completed!', type = 'info', duration = DEFAULT_DURATION } = {}) {
+        if (!container) return null;
+
+        const toast = document.createElement('div');
+        toast.className = 'toast';
+        toast.setAttribute('role', 'status');
+        toast.setAttribute('data-type', type);
+
+        const iconSpan = document.createElement('span');
+        iconSpan.className = 'toast-icon';
+        iconSpan.setAttribute('aria-hidden', 'true');
+        iconSpan.textContent = ICONS[type] || '☕';
+
+        const bodyDiv = document.createElement('div');
+        bodyDiv.className = 'toast-body';
+
+        const titleDiv = document.createElement('div');
+        titleDiv.className = 'toast-title';
+        titleDiv.textContent = title;
+
+        const messageDiv = document.createElement('div');
+        messageDiv.className = 'toast-message';
+        messageDiv.textContent = message;
+
+        bodyDiv.appendChild(titleDiv);
+        bodyDiv.appendChild(messageDiv);
+
+        const closeBtn = document.createElement('button');
+        closeBtn.type = 'button';
+        closeBtn.className = 'toast-close';
+        closeBtn.setAttribute('aria-label', 'Dismiss notification');
+        closeBtn.innerHTML = '&times;';
+        closeBtn.addEventListener('click', () => dismissToast(toast));
+
+        const progressDiv = document.createElement('div');
+        progressDiv.className = 'toast-progress';
+        progressDiv.style.animationDuration = duration + 'ms';
+
+        toast.appendChild(iconSpan);
+        toast.appendChild(bodyDiv);
+        toast.appendChild(closeBtn);
+        toast.appendChild(progressDiv);
+
+        container.appendChild(toast);
+
+        requestAnimationFrame(() => {
+          toast.classList.add('toast-visible');
+        });
+
+        let remaining = duration;
+        let startTime = Date.now();
+
+        const startTimer = () => {
+          startTime = Date.now();
+          toast._dismissTimer = setTimeout(() => dismissToast(toast), remaining);
+        };
+
+        toast.addEventListener('mouseenter', () => {
+          if (toast._dismissTimer) {
+            clearTimeout(toast._dismissTimer);
+            toast._dismissTimer = null;
+            remaining -= Date.now() - startTime;
+          }
+        });
+
+        toast.addEventListener('mouseleave', () => {
+          if (!toast.classList.contains('toast-exit') && remaining > 0) {
+            startTimer();
+          }
+        });
+
+        startTimer();
+        return toast;
+      }
+
+      document.addEventListener('click', (event) => {
+        const trigger = event.target.closest('.toast-trigger');
