+      }
+
+      get favorited() {
+        return this.hasAttribute('favorited');
+      }
+
+      set favorited(val) {
+        if (val) {
+          this.setAttribute('favorited', '');
+        } else {
+          this.removeAttribute('favorited');
+        }
+      }
+
+      get expanded() {
+        return this.hasAttribute('expanded');
+      }
+
+      set expanded(val) {
+        if (val) {
+          this.setAttribute('expanded', '');
+        } else {
+          this.removeAttribute('expanded');
+        }
+      }
+
+      toggleFavorite() {
+        this.favorited = !this.favorited;
+        this.dispatchEvent(new CustomEvent('favorite-toggle', {
+          bubbles: true,
+          composed: true,
+          detail: {
+            drinkId: this.getAttribute('drink-id'),
+            name: this.getAttribute('name'),
+            favorited: this.favorited
+          }
+        }));
+      }
+
+      toggleDetails() {
+        this.expanded = !this.expanded;
+        this.dispatchEvent(new CustomEvent('details-toggle', {
+          bubbles: true,
+          composed: true,
+          detail: {
+            drinkId: this.getAttribute('drink-id'),
+            name: this.getAttribute('name'),
+            expanded: this.expanded
+          }
+        }));
+      }
+
+      _syncFavoriteUI() {
+        if (!this._favoriteBtn) return;
+        const isFav = this.favorited;
+        this._favoriteBtn.setAttribute('aria-pressed', String(isFav));
+        const icon = this._favoriteBtn.querySelector('.fav-icon');
+        const label = this._favoriteBtn.querySelector('.fav-label');
+        if (icon) icon.textContent = isFav ? '\u2665' : '\u2661';
+        if (label) label.textContent = isFav ? 'Favorited' : 'Favorite';
+      }
+
+      _syncDetailsUI() {
+        if (!this._detailsBtn || !this._detailsPanel) return;
+        const isExpanded = this.expanded;
+        this._detailsBtn.setAttribute('aria-expanded', String(isExpanded));
+        this._detailsBtn.textContent = isExpanded ? 'Hide Details' : 'View Details';
+        this._detailsPanel.hidden = !isExpanded;
+      }
+    }
+
+    if (!customElements.get('drink-card')) {
+      customElements.define('drink-card', DrinkCard);
+    }
+  </script>
 </body>

 </html>

