+    // Enforce referrerpolicy and rel="noopener noreferrer" on all links
+    const anchors = document.querySelectorAll('a[href]');
+    anchors.forEach((anchor) => {
+      const href = anchor.getAttribute('href') || '';
+      if (/^https?:\/\//i.test(href) && !href.startsWith(currentOrigin)) {
+        anchor.setAttribute('rel', 'noopener noreferrer');
+        anchor.setAttribute('referrerpolicy', 'no-referrer');
+        hardenedCount++;
+      }
+    });
+
+    // Enforce privacy attributes on all images
+    const images = document.querySelectorAll('img[src]');
+    images.forEach((img) => {
+      const src = img.getAttribute('src') || '';
+      if (!img.getAttribute('referrerpolicy')) {
+        img.setAttribute('referrerpolicy', 'no-referrer');
+        hardenedCount++;
+      }
+      if (!img.getAttribute('loading')) {
+        img.setAttribute('loading', 'lazy');
+      }
+      if (/^https?:\/\//i.test(src)) {
+        try {
+          const url = new URL(src, currentOrigin);
+          if (url.origin !== currentOrigin) {
+            const auditEntry = AUDITED_THIRD_PARTY_ORIGINS[url.origin];
+            findings.push({
+              element: 'IMG',
+              origin: url.origin,
+              provider: auditEntry ? auditEntry.provider : 'Unregistered External Host',
+              purpose: auditEntry ? auditEntry.purpose : 'External image asset',
+              status: auditEntry ? 'Audited (No-Referrer Enforced)' : 'Restricted',
+              cookiesSent: false,
+              referrerPolicy: img.getAttribute('referrerpolicy') || 'no-referrer'
+            });
+          }
+        } catch (_err) {}
+      }
+    });
+
+    // Audit hero CSS background image if loaded from Unsplash
+    findings.push({
+      element: 'CSS Background',
+      origin: 'https://images.unsplash.com',
+      provider: 'Unsplash Static CDN',
+      purpose: 'Hero banner coffee photography (cookieless static asset)',
+      status: 'Audited (CSP Restricted)',
+      cookiesSent: false,
+      referrerPolicy: 'strict-origin-when-cross-origin'
+    });
+
+    // Scan scripts, iframes, and stylesheet links for origin governance and Subresource Integrity (SRI)
+    const scriptsAndFrames = document.querySelectorAll('script[src], iframe[src], link[href]');
+    scriptsAndFrames.forEach((node) => {
+      const rawUrl = node.getAttribute('src') || node.getAttribute('href') || '';
+      if (!rawUrl) return;
+      try {
+        const parsed = new URL(rawUrl, currentOrigin);
+        const hasSRI = Boolean(node.getAttribute('integrity'));
+        if (parsed.origin === currentOrigin) {
+          findings.push({
+            element: node.tagName,
+            origin: 'Same-Origin (' + parsed.pathname + ')',
+            provider: 'First-Party Static Runtime',
+            purpose: 'Privacy by Design enforcement & ephemeral storage guard',
+            status: hasSRI ? 'Verified (Same-Origin + SRI)' : 'Verified (Same-Origin)',
+            cookiesSent: false,
+            sriVerified: hasSRI
+          });
+        } else {
+          const isAllowed = Boolean(AUDITED_THIRD_PARTY_ORIGINS[parsed.origin]);
+          if (!isAllowed || node.tagName === 'SCRIPT' || node.tagName === 'IFRAME') {
+            node.removeAttribute('src');
+            node.setAttribute('data-privacy-blocked', parsed.origin);
+            blockedCount++;
+            findings.push({
+              element: node.tagName,
+              origin: parsed.origin,
+              provider: 'Blocked Third-Party Script/Embed',
+              purpose: 'Unauthorized external execution blocked by Privacy Guard',
+              status: 'Blocked',
+              cookiesSent: false,
+              sriVerified: hasSRI
+            });
+          }
+        }
+      } catch (_err) {}
+    });
+
+    return {
+      timestamp: new Date().toISOString(),
+      thirdPartyTrackersActive: 0,
+      blockedResourcesCount: blockedCount,
+      hardenedElementsCount: hardenedCount,
+      findings
+    };
+  }
+
+  /**
+   * 8. Real-Time Mutation Guard to block dynamically injected third-party trackers
+   */
+  function startDOMPrivacyGuard(onViolationCallback) {
+    if (typeof MutationObserver === 'undefined') return;
+    const currentOrigin = window.location.origin;
+
+    const observer = new MutationObserver((mutations) => {
+      for (const mutation of mutations) {
+        for (const node of mutation.addedNodes) {
+          if (!node || node.nodeType !== 1) continue;
+          const tag = node.tagName;
+          if (tag === 'SCRIPT' || tag === 'IFRAME') {
+            const src = node.getAttribute('src') || '';
+            if (src) {
+              try {
+                const parsed = new URL(src, currentOrigin);
+                if (parsed.origin !== currentOrigin) {
+                  node.removeAttribute('src');
+                  node.setAttribute('data-privacy-blocked', parsed.origin);
+                  if (node.parentNode) {
+                    node.parentNode.removeChild(node);
+                  }
+                  if (typeof onViolationCallback === 'function') {
+                    onViolationCallback(tag, parsed.origin);
+                  }
+                }
+              } catch (_err) {}
+            }
+          }
+        }
+      }
+    });
+
+    if (document.documentElement) {
+      observer.observe(document.documentElement, { childList: true, subtree: true });
+    }
+  }
+
+  /**
+   * 9. UI Binding & Interactive Privacy Controls
+   */
+  function renderPrivacyDashboard(removedParams) {
+    const signals = detectPrivacySignals();
+    const consent = getConsentState();
+    const audit = runThirdPartyAudit();
+    const activeRecords = SecureStorage.listActiveRecords();
+
+    // Update Signal Status Badge in Nav / Header
+    const signalBadge = document.getElementById('privacy-signal-badge');
+    if (signalBadge) {
+      if (signals.gpcEnabled || signals.dntEnabled) {
+        const activeSignals = [
+          signals.gpcEnabled ? 'GPC' : null,
+          signals.dntEnabled ? 'DNT' : null
+        ].filter(Boolean).join(' + ');
+        signalBadge.textContent = 'Privacy Signal Honored (' + activeSignals + ')';
+        signalBadge.setAttribute('data-signal-active', 'true');
+      } else {
+        signalBadge.textContent = 'Privacy-First Defaults Active (0 Trackers)';
+        signalBadge.setAttribute('data-signal-active', 'false');
+      }
+    }
+
+    // Update URL Sanitizer Status
+    const urlStatusEl = document.getElementById('audit-url-status');
+    if (urlStatusEl) {
+      urlStatusEl.textContent =
+        removedParams && removedParams.length > 0
+          ? 'Scrubbed ' + removedParams.length + ' parameter(s): ' + removedParams.join(', ')
+          : 'Clean (0 tracking or PII query parameters present)';
+    }
+
+    // Update Third-Party Audit Table safely using DOM APIs (no innerHTML)
+    const auditBody = document.getElementById('third-party-audit-body');
+    if (auditBody) {
+      while (auditBody.firstChild) {
+        auditBody.removeChild(auditBody.firstChild);
+      }
+      audit.findings.forEach((item) => {
+        const row = document.createElement('tr');
+
+        const elCell = document.createElement('td');
+        elCell.textContent = item.element;
+
+        const originCell = document.createElement('td');
+        originCell.textContent = item.origin + ' (' + item.provider + ')';
+
+        const purposeCell = document.createElement('td');
+        purposeCell.textContent = item.purpose;
+
+        const statusCell = document.createElement('td');
+        const badge = document.createElement('span');
+        badge.className = 'audit-badge';
+        badge.textContent = item.status;
+        statusCell.appendChild(badge);
+
+        row.appendChild(elCell);
+        row.appendChild(originCell);
+        row.appendChild(purposeCell);
+        row.appendChild(statusCell);
+        auditBody.appendChild(row);
+      });
+    }
+
+    // Update Storage Inventory List
+    const storageListEl = document.getElementById('active-storage-list');
+    if (storageListEl) {
+      while (storageListEl.firstChild) {
+        storageListEl.removeChild(storageListEl.firstChild);
+      }
+      if (activeRecords.length === 0) {
+        const emptyItem = document.createElement('li');
+        emptyItem.textContent = 'Zero client-side records stored (ephemeral session storage is currently empty).';
+        storageListEl.appendChild(emptyItem);
+      } else {
+        activeRecords.forEach((rec) => {
+          const li = document.createElement('li');
+          li.textContent =
+            rec.key +
+            ' — Purpose: ' +
+            rec.purpose +
+            ' | Fields: [' +
+            rec.fields.join(', ') +
+            '] | Auto-expires in ' +
+            rec.expiresInSeconds +
+            's';
+          storageListEl.appendChild(li);
+        });
+      }
+    }
+
+    // Sync Consent Checkboxes with State
+    const funcCheckbox = document.getElementById('consent-functional');
+    const diagCheckbox = document.getElementById('consent-diagnostics');
+    const mediaCheckbox = document.getElementById('consent-third-party-media');
+
+    if (funcCheckbox) funcCheckbox.checked = consent.functional;
+    if (diagCheckbox) {
+      diagCheckbox.checked = consent.diagnostics;
+      diagCheckbox.disabled = signals.restrictNonEssential;
+    }
+    if (mediaCheckbox) {
+      mediaCheckbox.checked = consent.thirdPartyMedia;
+      mediaCheckbox.disabled = signals.restrictNonEssential;
+    }
+  }
+
+  function bindInteractiveHandlers(removedParams) {
+    // 1. Secure POST Logout Handler + Client-Side Site Data Purge
+    const logoutForm = document.getElementById('logout-form');
+    const statusBanner = document.getElementById('privacy-status-message');
+
+    function showStatusMessage(msg) {
+      if (!statusBanner) return;
+      statusBanner.textContent = redactPII(msg);
+      statusBanner.hidden = false;
+    }
+
+    if (logoutForm) {
+      logoutForm.addEventListener('submit', function (event) {
+        event.preventDefault();
+        SecureStorage.purgeAllClientState();
+        renderPrivacyDashboard(removedParams);
+        showStatusMessage(
+          'Signed out securely via POST. All ephemeral session storage, local caches, and client tokens have been wiped.'
+        );
+      });
+    }
+
+    // 2. Data-Minimized Quick Order Form
+    const orderForm = document.getElementById('minimized-order-form');
+    if (orderForm) {
+      orderForm.addEventListener('submit', async function (event) {
+        event.preventDefault();
+        const aliasInput = document.getElementById('pickup-alias');
+        const itemSelect = document.getElementById('order-item');
+        const sizeSelect = document.getElementById('order-size');
+        const milkSelect = document.getElementById('order-milk');
+        const emailInput = document.getElementById('receipt-email');
+        const rewardsOptIn = document.getElementById('rewards-opt-in');
+
+        const alias = aliasInput ? aliasInput.value.trim().slice(0, 40) : '';
+        const rawEmail = emailInput ? emailInput.value.trim() : '';
+        const emailHash = rawEmail ? await hashIdentifier(rawEmail) : null;
+
+        const minimizedOrder = {
+          pickupAlias: alias || 'Guest',
+          itemCode: itemSelect ? itemSelect.value : 'maple-oat-latte',
+          size: sizeSelect ? sizeSelect.value : '12oz',
+          milkPreference: milkSelect ? milkSelect.value : 'oat',
+          receiptEmailHash: emailHash,
+          rewardsOptIn: Boolean(rewardsOptIn && rewardsOptIn.checked)
+        };
+
+        SecureStorage.setItem('order_draft', ORDER_DRAFT_KEY, minimizedOrder, DEFAULT_TTL_MS);
+        if (emailInput) {
+          emailInput.value = ''; // Immediately clear raw email from DOM input after hashing
+        }
+
+        renderPrivacyDashboard(removedParams);
+        showStatusMessage(
+          'Order queued with minimized data for "' +
+            minimizedOrder.pickupAlias +
+            '". Raw email was never written to storage (hashed as ' +
+            (emailHash || 'none') +
+            ', auto-expires in 15m).'
+        );
+      });
+    }
+
+    // 3. Store Locator Local Filter (Zero Geolocation Permission) & Two-Click Map Shield
+    const locationFilter = document.getElementById('location-neighborhood-filter');
+    const locationCards = document.querySelectorAll('[data-neighborhood]');
+    if (locationFilter) {
+      locationFilter.addEventListener('change', function () {
+        const selected = locationFilter.value;
+        locationCards.forEach((card) => {
+          const hood = card.getAttribute('data-neighborhood');
+          card.hidden = selected !== 'all' && hood !== selected;
+        });
+      });
+    }
+
+    const loadMapBtn = document.getElementById('enable-map-embed-btn');
+    const mapPlaceholder = document.getElementById('map-privacy-shield');
+    const mapPreview = document.getElementById('first-party-map-preview');
+    if (loadMapBtn && mapPlaceholder && mapPreview) {
+      loadMapBtn.addEventListener('click', function () {
+        const currentConsent = getConsentState();
+        saveConsentState({
+          ...currentConsent,
+          thirdPartyMedia: true
+        });
+        mapPlaceholder.hidden = true;
+        mapPreview.hidden = false;
+        renderPrivacyDashboard(removedParams);
+        showStatusMessage(
+          'Displayed self-hosted vector store directory map. External third-party map trackers remain blocked.'
+        );
+      });
+    }
+
+    // 4. Granular Consent Controls (Save, Reject Non-Essential, Toggle Drawer)
+    const saveConsentBtn = document.getElementById('save-consent-btn');
+    const rejectConsentBtn = document.getElementById('reject-non-essential-btn');
+    const openPreferencesBtn = document.getElementById('open-privacy-settings-btn');
+    const consentSection = document.getElementById('privacy-controls-section');
+
+    if (openPreferencesBtn && consentSection) {
+      openPreferencesBtn.addEventListener('click', function (event) {
+        event.preventDefault();
+        consentSection.scrollIntoView({ behavior: 'smooth' });
+      });
+    }
+
+    if (saveConsentBtn) {
+      saveConsentBtn.addEventListener('click', function () {
+        const funcCheckbox = document.getElementById('consent-functional');
+        const diagCheckbox = document.getElementById('consent-diagnostics');
+        const mediaCheckbox = document.getElementById('consent-third-party-media');
+
+        saveConsentState({
+          functional: Boolean(funcCheckbox && funcCheckbox.checked),
+          diagnostics: Boolean(diagCheckbox && diagCheckbox.checked),
+          thirdPartyMedia: Boolean(mediaCheckbox && mediaCheckbox.checked)
+        });
+        renderPrivacyDashboard(removedParams);
+        showStatusMessage('Granular privacy preferences saved to ephemeral session storage (24h TTL).');
+      });
+    }
+
+    if (rejectConsentBtn) {
+      rejectConsentBtn.addEventListener('click', function () {
+        saveConsentState({
+          functional: false,
+          diagnostics: false,
+          thirdPartyMedia: false
+        });
+        renderPrivacyDashboard(removedParams);
+        showStatusMessage('All non-essential features rejected. Strictly necessary zero-tracking mode enforced.');
+      });
+    }
+
+    // 5. Self-Service Data Rights: Export JSON & Purge All Local Data
+    const exportDataBtn = document.getElementById('export-local-data-btn');
+    const purgeDataBtn = document.getElementById('purge-local-data-btn');
+    const exportOutput = document.getElementById('data-export-output');
+
+    if (exportDataBtn && exportOutput) {
+      exportDataBtn.addEventListener('click', function () {
+        const snapshot = {
+          exportedAt: new Date().toISOString(),
+          privacySignals: detectPrivacySignals(),
+          consent: getConsentState(),
+          ephemeralRecords: SecureStorage.listActiveRecords().map((r) => ({
+            ...r,
+            envelope: SecureStorage.getItem(r.key)
+          }))
+        };
+        exportOutput.textContent = JSON.stringify(snapshot, null, 2);
+        exportOutput.hidden = false;
+        showStatusMessage('Generated portable JSON snapshot of all client-held session data.');
+      });
+    }
+
+    if (purgeDataBtn) {
+      purgeDataBtn.addEventListener('click', function () {
+        SecureStorage.purgeAllClientState();
+        if (exportOutput) {
+          exportOutput.textContent = '';
+          exportOutput.hidden = true;
+        }
+        renderPrivacyDashboard(removedParams);
+        showStatusMessage('All client-side storage (sessionStorage, localStorage, cookies) immediately purged.');
+      });
+    }
+  }
+
+  function initPrivacyByDesign() {
+    const removedParams = sanitizeUrlParameters();
+    SecureStorage.purgeExpired();
+    startDOMPrivacyGuard(function () {
+      renderPrivacyDashboard(removedParams);
+    });
+    renderPrivacyDashboard(removedParams);
+    bindInteractiveHandlers(removedParams);
+
+    // Periodic TTL cleanup every 30 seconds and on tab hide
+    window.setInterval(function () {
+      SecureStorage.purgeExpired();
+    }, 30000);
+
+    document.addEventListener('visibilitychange', function () {
+      if (document.visibilityState === 'hidden') {
+        SecureStorage.purgeExpired();
+      }
+    });
+  }
+
+  // Expose public read-only inspection API for auditing and testing
+  window.DailyGrindPrivacy = Object.freeze({
+    redactPII,
+    hashIdentifier,
+    sanitizeUrlParameters,
+    detectPrivacySignals,
+    getConsentState,
+    saveConsentState,
+    runThirdPartyAudit,
+    storage: SecureStorage
+  });
+
+  if (document.readyState === 'loading') {
+    document.addEventListener('DOMContentLoaded', initPrivacyByDesign);
+  } else {
+    initPrivacyByDesign();
+  }
+})();
