+            statusEl.dataset.state = 'error';
+          }
+          return { ok: false, body: payload, error: new Error(serverMessage) };
+        }
+
+        const successMessage =
+          payload && typeof payload.message === 'string' && payload.message.trim()
+            ? payload.message.trim()
+            : 'Thanks for subscribing! Look out for The Daily Grind newsletter in your inbox.';
+        if (statusEl) {
+          statusEl.textContent = successMessage;
+          statusEl.dataset.state = 'success';
+        }
+        return { ok: true, body: payload, error: null };
+      } catch (error) {
+        const reason = error instanceof Error ? error.message : String(error);
+        const blockedMessage = `Unable to send your signup request (${reason}). Outbound connections are restricted to The Daily Grind server, or the network request could not go through.`;
+        if (statusEl) {
+          statusEl.textContent = blockedMessage;
+          statusEl.dataset.state = 'error';
+        }
+        return { ok: false, body: null, error };
+      }
+    }
+
+    window.fetchWithPolicyHandling = fetchWithPolicyHandling;
+
+    newsletterForm.addEventListener('submit', async (event) => {
+      event.preventDefault();
+      hasEditedEmail = true;
+
+      if (!validateEmailField()) {
+        emailInput.focus();
+        return;
+      }
+
+      const email = emailInput.value.trim();
+      const endpoint = newsletterForm.getAttribute('action') || '/api/newsletter';
+
+      submitButton.disabled = true;
+      updateStatus('Subscribing...', '');
+
+      try {
+        const result = await fetchWithPolicyHandling(endpoint, {
+          statusEl: statusElement,
+          method: 'POST',
+          headers: {
+            'Content-Type': 'application/json',
+            Accept: 'application/json',
+          },
+          body: JSON.stringify({ email }),
+        });
+
+        if (result.ok) {
+          newsletterForm.reset();
+          hasEditedEmail = false;
+          emailInput.removeAttribute('aria-invalid');
+        }
+      } finally {
+        submitButton.disabled = false;
+      }
+    });
+  </script>
+
 </body>

