+import { createHash } from 'node:crypto';
+import { readFileSync } from 'node:fs';
+import { createServer } from 'node:http';
+import { dirname, join } from 'node:path';
+import { fileURLToPath } from 'node:url';
+
+const __dirname = dirname(fileURLToPath(import.meta.url));
+const PORT = Number(process.env.PORT) || 11222;
+const INDEX_HTML_PATH = join(__dirname, 'index.html');
+
+const ALLOWLIST_DESTS = new Set([
+  'document',
+  'iframe',
+  'worker',
+  'sharedworker',
+  'serviceworker',
+]);
+
+const ALLOWED_EXTERNAL_PATTERNS = ['https://images.unsplash.com'];
+const REPORT_ENDPOINT_NAME = 'conn-reports';
+const REPORT_ENDPOINT_PATH = '/api/security-reports';
+
+const subscribers = new Set();
+
+// Normalize a config URL or URLPattern string for Connection-Allowlist:
+// - Rewrites ws:// and wss:// to http:// and https:// (WebSocket matching rule).
+// - Strips a bare trailing slash on origin-only URLs (e.g. from new URL(...).href)
+//   so all subpaths on the origin are permitted instead of only "/".
+export function normalizeAllowlistPattern(rawPattern) {
+  const trimmed = String(rawPattern).trim().replace(/^ws(s?):\/\//i, 'http$1://');
+  if (!/^https?:\/\//i.test(trimmed)) {
+    throw new Error(`Pattern must include an http:// or https:// scheme: ${rawPattern}`);
+  }
+  if (/[\s,]/.test(trimmed)) {
+    throw new Error(`Pattern must be a single URLPattern without spaces or commas: ${rawPattern}`);
+  }
+  if (/[()]/.test(trimmed)) {
+    throw new Error(`Custom regex groups are rejected by Connection-Allowlist: ${rawPattern}`);
+  }
+  return trimmed.replace(/^(https?:\/\/[^/?#]+)\/$/i, '$1');
+}
+
+// Build an RFC 9651 Inner List value for Connection-Allowlist or Connection-Allowlist-Report-Only.
+export function buildConnectionAllowlistHeader({
+  allowSelf = true,
+  patterns = [],
+  reportTo,
+  redirects = 'block',
+  webrtc = 'block',
+} = {}) {
+  const items = allowSelf ? ['response-origin'] : [];
+  for (const pattern of patterns) {
+    const raw = String(pattern).trim();
+    if (raw === 'response-origin') {
+      if (!items.includes('response-origin')) items.push('response-origin');
+      continue;
+    }
+    const normalized = normalizeAllowlistPattern(raw);
+    items.push(`"${normalized.replace(/\\/g, '\\\\').replace(/"/g, '\\"')}"`);
+  }
+  let header = `(${items.join(' ')})`;
+  if (redirects === 'allow') header += '; redirects=allow';
+  if (webrtc === 'allow') header += '; webrtc=allow';
+  if (reportTo) {
+    const endpointToken = String(reportTo).trim().replace(/^"+|"+$/g, '');
+    header += `; report-to=${endpointToken}`;
+  }
+  return header;
+}
+
+// Compute SHA-256 CSP hashes for inline <style> and <script> blocks in index.html
+function computeInlineCspHashes(html) {
+  const styleHashes = [];
+  const scriptHashes = [];
+
+  for (const match of html.matchAll(/<style>([\s\S]*?)<\/style>/gi)) {
+    const hash = createHash('sha256').update(match[1], 'utf8').digest('base64');
+    styleHashes.push(`'sha256-${hash}'`);
+  }
+  for (const match of html.matchAll(/<script>([\s\S]*?)<\/script>/gi)) {
+    const hash = createHash('sha256').update(match[1], 'utf8').digest('base64');
+    scriptHashes.push(`'sha256-${hash}'`);
+  }
+
+  return { styleHashes, scriptHashes };
+}
+
+// Build the paired Content-Security-Policy fallback header for browsers without Connection-Allowlist.
+export function buildContentSecurityPolicyHeader({
+  styleHashes = [],
+  scriptHashes = [],
+  reportTo = REPORT_ENDPOINT_NAME,
+} = {}) {
+  const styleSrc = ["'self'", ...styleHashes].join(' ');
+  const scriptSrc = ["'self'", ...scriptHashes, "'report-sample'"].join(' ');
+
+  const directives = [
+    "default-src 'self'",
+    "connect-src 'self'",
+    "img-src 'self' https://images.unsplash.com data:",
+    `style-src ${styleSrc}`,
+    `script-src ${scriptSrc}`,
+    "form-action 'self'",
+    "worker-src 'self'",
+    "object-src 'none'",
+    "base-uri 'self'",
+    "frame-ancestors 'none'",
+  ];
+
+  if (reportTo) {
+    directives.push(`report-to ${reportTo}`);
+  }
+
+  return directives.join('; ');
+}
+
+// Apply Connection-Allowlist, Reporting-Endpoints, and fallback CSP headers on document and worker responses.
+export function setConnectionAllowlistHeaders(res, options = {}) {
+  const {
+    secFetchDest = 'document',
+    patterns = ALLOWED_EXTERNAL_PATTERNS,
+    reportOnlyPatterns,
+    reportEndpointName = REPORT_ENDPOINT_NAME,
+    reportEndpointUrl = REPORT_ENDPOINT_PATH,
+    redirects = 'block',
+    webrtc = 'block',
+    reportOnly = false,
+    styleHashes = [],
+    scriptHashes = [],
+  } = options;
+
+  const setHeader = (name, value) =>
+    typeof res.setHeader === 'function' ? res.setHeader(name, value) : res.headers.set(name, value);
+
+  if (typeof res.appendHeader === 'function') {
+    res.appendHeader('Vary', 'Sec-Fetch-Dest');
+  } else if (typeof res.headers?.append === 'function') {
+    res.headers.append('Vary', 'Sec-Fetch-Dest');
+  } else {
+    setHeader('Vary', 'Sec-Fetch-Dest');
+  }
+
+  if (secFetchDest && !ALLOWLIST_DESTS.has(String(secFetchDest).toLowerCase())) return;
+
+  setHeader('Reporting-Endpoints', `${reportEndpointName}="${reportEndpointUrl}"`);
+  setHeader(
+    reportOnly ? 'Connection-Allowlist-Report-Only' : 'Connection-Allowlist',
+    buildConnectionAllowlistHeader({
+      allowSelf: true,
+      patterns,
+      reportTo: reportEndpointName,
+      redirects,
+      webrtc,
+    }),
+  );
+
+  if (!reportOnly && Array.isArray(reportOnlyPatterns)) {
+    setHeader(
+      'Connection-Allowlist-Report-Only',
+      buildConnectionAllowlistHeader({
+        allowSelf: true,
+        patterns: reportOnlyPatterns,
+        reportTo: reportEndpointName,
+        redirects,
+        webrtc,
+      }),
+    );
+  }
+
+  setHeader(
+    'Content-Security-Policy',
+    buildContentSecurityPolicyHeader({
+      styleHashes,
+      scriptHashes,
+      reportTo: reportEndpointName,
+    }),
+  );
+  setHeader('X-Content-Type-Options', 'nosniff');
+  setHeader('X-Frame-Options', 'DENY');
+  setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
+  setHeader('Permissions-Policy', 'camera=(), geolocation=(), microphone=()');
+  setHeader('Cross-Origin-Opener-Policy', 'same-origin-allow-popups');
+  setHeader('Cross-Origin-Resource-Policy', 'same-origin');
+}
+
+function readRequestBody(req, maxBytes = 16 * 1024) {
+  return new Promise((resolve, reject) => {
+    const chunks = [];
+    let total = 0;
+    req.on('data', (chunk) => {
+      total += chunk.length;
+      if (total > maxBytes) {
+        reject(new Error('Payload too large'));
+        req.destroy();
+        return;
+      }
+      chunks.push(chunk);
+    });
+    req.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')));
+    req.on('error', reject);
+  });
+}
+
+function parseEmailFromBody(rawBody, contentType = '') {
+  if (!rawBody) return '';
+  if (contentType.includes('application/x-www-form-urlencoded')) {
+    const params = new URLSearchParams(rawBody);
+    return (params.get('email') || '').trim();
+  }
+  try {
+    const parsed = JSON.parse(rawBody);
+    return typeof parsed?.email === 'string' ? parsed.email.trim() : '';
+  } catch {
+    const params = new URLSearchParams(rawBody);
+    return (params.get('email') || '').trim();
+  }
+}
+
+function isValidEmail(email) {
+  return typeof email === 'string' && email.length <= 254 && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
+}
+
+export function createAppServer() {
+  return createServer(async (req, res) => {
+    const url = new URL(req.url || '/', `http://${req.headers.host || `localhost:${PORT}`}`);
+    const pathname = url.pathname;
+    const secFetchDest = req.headers['sec-fetch-dest'] || 'document';
+    const proto = req.headers['x-forwarded-proto'] || 'http';
+    const reportEndpointUrl = req.headers.host
+      ? `${proto}://${req.headers.host}${REPORT_ENDPOINT_PATH}`
+      : REPORT_ENDPOINT_PATH;
+
+    // Fetch Metadata resource isolation check for non-navigational cross-site requests
+    const secFetchSite = req.headers['sec-fetch-site'];
+    const secFetchMode = req.headers['sec-fetch-mode'];
+    if (
+      secFetchSite &&
+      !['same-origin', 'same-site', 'none'].includes(secFetchSite) &&
+      !(secFetchSite === 'cross-site' && secFetchMode === 'navigate' && req.method === 'GET')
+    ) {
+      res.writeHead(403, {
+        'Content-Type': 'application/json; charset=utf-8',
+        Vary: 'Sec-Fetch-Dest, Sec-Fetch-Mode, Sec-Fetch-Site',
+      });
+      res.end(JSON.stringify({ ok: false, message: 'Cross-site request forbidden.' }));
+      return;
+    }
+
+    if (req.method === 'GET' && (pathname === '/' || pathname === '/index.html')) {
+      const html = readFileSync(INDEX_HTML_PATH, 'utf8');
+      const { styleHashes, scriptHashes } = computeInlineCspHashes(html);
+
+      setConnectionAllowlistHeaders(res, {
+        secFetchDest,
+        patterns: ALLOWED_EXTERNAL_PATTERNS,
+        reportEndpointName: REPORT_ENDPOINT_NAME,
+        reportEndpointUrl,
+        styleHashes,
+        scriptHashes,
+      });
+
+      res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
+      res.end(html);
+      return;
+    }
+
+    if (
+      req.method === 'POST' &&
+      (pathname === '/api/newsletter' || pathname === '/newsletter' || pathname === '/subscribe')
+    ) {
+      res.setHeader('X-Content-Type-Options', 'nosniff');
+      res.setHeader('Cross-Origin-Resource-Policy', 'same-origin');
+      try {
+        const rawBody = await readRequestBody(req);
+        const email = parseEmailFromBody(rawBody, req.headers['content-type'] || '');
+
+        if (!isValidEmail(email)) {
+          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
+          res.end(
+            JSON.stringify({
+              ok: false,
+              message: 'Please enter a valid email address (for example, alex@example.com).',
+            }),
+          );
+          return;
+        }
+
+        subscribers.add(email.toLowerCase());
+        res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
+        res.end(
+          JSON.stringify({
+            ok: true,
+            email: email.toLowerCase(),
+            message: 'Thanks for subscribing! Look out for The Daily Grind newsletter in your inbox.',
+          }),
+        );
+      } catch {
+        res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
+        res.end(
+          JSON.stringify({
+            ok: false,
+            message: 'Unable to process your signup request. Please try again.',
+          }),
+        );
+      }
+      return;
+    }
+
+    if (req.method === 'POST' && pathname === REPORT_ENDPOINT_PATH) {
+      await readRequestBody(req).catch(() => {});
+      res.writeHead(204);
+      res.end();
+      return;
+    }
+
+    if (req.method === 'GET' && pathname === '/logout') {
+      res.writeHead(200, {
+        'Content-Type': 'text/plain; charset=utf-8',
+        'Clear-Site-Data': '"cookies", "storage", "cache"',
+        'X-Content-Type-Options': 'nosniff',
+      });
+      res.end('Signed out.');
+      return;
+    }
+
+    res.writeHead(404, {
+      'Content-Type': 'application/json; charset=utf-8',
+      'X-Content-Type-Options': 'nosniff',
+    });
+    res.end(JSON.stringify({ ok: false, message: 'Not found' }));
+  });
+}
+
+if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
+  const server = createAppServer();
+  server.listen(PORT, () => {
+    console.log(`Daily Grind server listening on http://localhost:${PORT}`);
+  });
+}

