+const http = require('node:http');
+const fs = require('node:fs');
+const path = require('node:path');
+
+const PORT = Number(process.env.PORT) || 11222;
+const SUBSCRIBERS_FILE = path.join(__dirname, 'subscribers.json');
+
+const CSP_HEADER = [
+  "default-src 'self'",
+  "connect-src 'self'",
+  "img-src 'self' https://images.unsplash.com",
+  "style-src 'self' 'unsafe-inline'",
+  "script-src 'self' 'unsafe-inline'",
+  "font-src 'self'",
+  "object-src 'none'",
+  "base-uri 'self'",
+  "form-action 'self'",
+  "frame-ancestors 'self'"
+].join('; ');
+
+const MIME_TYPES = {
+  '.html': 'text/html; charset=utf-8',
+  '.js': 'application/javascript; charset=utf-8',
+  '.css': 'text/css; charset=utf-8',
+  '.json': 'application/json; charset=utf-8',
+  '.png': 'image/png',
+  '.jpg': 'image/jpeg',
+  '.jpeg': 'image/jpeg',
+  '.svg': 'image/svg+xml',
+  '.ico': 'image/x-icon'
+};
+
+function readSubscribers() {
+  try {
+    if (fs.existsSync(SUBSCRIBERS_FILE)) {
+      const raw = fs.readFileSync(SUBSCRIBERS_FILE, 'utf8');
+      const parsed = JSON.parse(raw);
+      return Array.isArray(parsed) ? parsed : [];
+    }
+  } catch (_) {
+    // ignore read error and start fresh
+  }
+  return [];
+}
+
+function saveSubscriber(email) {
+  const subscribers = readSubscribers();
+  const normalized = email.trim().toLowerCase();
+  if (!subscribers.some((s) => s.email === normalized)) {
+    subscribers.push({ email: normalized, subscribedAt: new Date().toISOString() });
+    try {
+      fs.writeFileSync(SUBSCRIBERS_FILE, JSON.stringify(subscribers, null, 2), 'utf8');
+    } catch (_) {
+      // ignore write error in read-only environments
+    }
+  }
+}
+
+function sendJson(res, statusCode, payload) {
+  res.writeHead(statusCode, {
+    'Content-Type': 'application/json; charset=utf-8',
+    'Content-Security-Policy': CSP_HEADER,
+    'X-Content-Type-Options': 'nosniff'
+  });
+  res.end(JSON.stringify(payload));
+}
+
+function parseBody(req) {
+  return new Promise((resolve, reject) => {
+    let body = '';
+    req.on('data', (chunk) => {
+      body += chunk.toString('utf8');
+      if (body.length > 1e6) {
+        reject(new Error('Payload too large'));
+        req.destroy();
+      }
+    });
+    req.on('end', () => resolve(body));
+    req.on('error', reject);
+  });
+}
+
+function extractEmail(rawBody, contentType = '') {
+  if (!rawBody) return '';
+  if (contentType.includes('application/json')) {
+    try {
+      const parsed = JSON.parse(rawBody);
+      return typeof parsed.email === 'string' ? parsed.email.trim() : '';
+    } catch (_) {
+      return '';
+    }
+  }
+  if (contentType.includes('application/x-www-form-urlencoded')) {
+    const params = new URLSearchParams(rawBody);
+    return (params.get('email') || '').trim();
+  }
+  try {
+    const parsed = JSON.parse(rawBody);
+    if (typeof parsed.email === 'string') return parsed.email.trim();
+  } catch (_) {
+    const params = new URLSearchParams(rawBody);
+    if (params.get('email')) return params.get('email').trim();
+  }
+  return '';
+}
+
+const NEWSLETTER_PATHS = new Set([
+  '/api/newsletter',
+  '/newsletter',
+  '/subscribe',
+  '/api/subscribe'
+]);
+
+const server = http.createServer(async (req, res) => {
+  const parsedUrl = new URL(req.url || '/', `http://${req.headers.host || 'localhost'}`);
+  const pathname = parsedUrl.pathname;
+
+  res.setHeader('Content-Security-Policy', CSP_HEADER);
+  res.setHeader('X-Content-Type-Options', 'nosniff');
+
+  if (req.method === 'POST' && NEWSLETTER_PATHS.has(pathname)) {
+    try {
+      const rawBody = await parseBody(req);
+      const email = extractEmail(rawBody, req.headers['content-type'] || '');
+      const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+
+      if (!email || !emailRegex.test(email)) {
+        return sendJson(res, 400, {
+          ok: false,
+          error: 'Please enter a valid email address.'
+        });
+      }
+
+      saveSubscriber(email);
+      return sendJson(res, 200, {
+        ok: true,
+        message: 'Thanks for subscribing to The Daily Grind newsletter!'
+      });
+    } catch (err) {
+      return sendJson(res, 500, {
+        ok: false,
+        error: 'Unable to process your signup request right now. Please try again.'
+      });
+    }
+  }
+
+  if (req.method === 'GET' && pathname === '/api/newsletter') {
+    const subscribers = readSubscribers();
+    return sendJson(res, 200, { ok: true, count: subscribers.length, subscribers });
+  }
+
+  if (req.method !== 'GET' && req.method !== 'HEAD') {
+    return sendJson(res, 405, { ok: false, error: 'Method not allowed' });
+  }
+
+  let filePath = pathname === '/' ? '/index.html' : pathname;
+  const safeSuffix = path.normalize(filePath).replace(/^(\.\.(\/|\\|$))+/, '');
+  const resolvedPath = path.join(__dirname, safeSuffix);
+
+  if (!resolvedPath.startsWith(__dirname)) {
+    res.writeHead(403, { 'Content-Type': 'text/plain; charset=utf-8' });
+    return res.end('Forbidden');
+  }
+
+  fs.stat(resolvedPath, (err, stats) => {
+    if (err || !stats.isFile()) {
+      res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
+      return res.end('Not Found');
+    }
+
+    const ext = path.extname(resolvedPath).toLowerCase();
+    const contentType = MIME_TYPES[ext] || 'application/octet-stream';
+
+    res.writeHead(200, { 'Content-Type': contentType });
+    if (req.method === 'HEAD') {
+      return res.end();
+    }
+    fs.createReadStream(resolvedPath).pipe(res);
+  });
+});
+
+if (require.main === module) {
+  server.listen(PORT, () => {
+    console.log(`The Daily Grind server listening on http://localhost:${PORT}`);
+  });
+}
+
+module.exports = server;

