+      panel.addEventListener('scrollend', updateClosestSection, { passive: true });
+
+      // Smoothly scroll to section when a TOC link is clicked
+      tocLinks.forEach((link) => {
+        link.addEventListener('click', (event) => {
+          const targetHash = link.getAttribute('href');
