+      function updateActiveOnScroll() {
+        const navEl = document.querySelector('nav');
+        const navHeight = navEl ? navEl.offsetHeight : 68;
+        const scrollPosition = window.scrollY + navHeight + window.innerHeight * 0.25;
+
+        // If scrolled to the very bottom of the page, highlight the last section
+        if (window.innerHeight + Math.ceil(window.scrollY) >= document.documentElement.scrollHeight - 10) {
+          const lastSection = sections[sections.length - 1];
+          if (lastSection) {
+            setActiveSection(lastSection.id);
+            return;
+          }
+        }
+
+        let currentSectionId = '';
+        for (const section of sections) {
+          const top = section.offsetTop;
+          const height = section.offsetHeight;
+          if (scrollPosition >= top && scrollPosition < top + height) {
+            currentSectionId = section.id;
+            break;
+          }
+        }
+
+        // Fallback if between sections or when a section top has passed the sticky nav
+        if (!currentSectionId) {
+          for (const section of sections) {
+            if (window.scrollY + navHeight + 40 >= section.offsetTop) {
+              currentSectionId = section.id;
+            }
+          }
+        }
+
+        setActiveSection(currentSectionId);
+      }
+
+      // Use IntersectionObserver + scroll listener for responsive and accurate scroll-spy
+      if ('IntersectionObserver' in window) {
+        const observer = new IntersectionObserver(
+          () => {
+            updateActiveOnScroll();
+          },
+          {
+            root: null,
+            rootMargin: '-15% 0px -45% 0px',
+            threshold: [0, 0.25, 0.5, 0.75, 1]
+          }
+        );
+
+        sections.forEach((section) => observer.observe(section));
+      }
+
+      window.addEventListener('scroll', updateActiveOnScroll, { passive: true });
+      window.addEventListener('resize', updateActiveOnScroll);
+      window.addEventListener('hashchange', () => {
+        const hashId = window.location.hash.replace('#', '');
+        if (hashId && sections.some((s) => s.id === hashId)) {
+          setActiveSection(hashId);
+        }
+      });
+
+      navLinks.forEach((link) => {
+        link.addEventListener('click', () => {
+          const targetId = link.getAttribute('href').replace('#', '');
+          setActiveSection(targetId);
+        });
+      });
