+        val ? this.setAttribute('drink-title', val) : this.removeAttribute('drink-title');
+      }
+
+      get description() {
+        return this.getAttribute('description') ?? '';
+      }
+      set description(val) {
+        val ? this.setAttribute('description', val) : this.removeAttribute('description');
+      }
+
+      get href() {
