+          return this.getAttribute('limited') !== 'false';
+        }
+        if (this.hasAttribute('badge')) {
+          const val = this.getAttribute('badge');
+          return val !== 'false' && val !== null;
+        }
+        return false;
+      }
+
+      set limited(value) {
+        if (value) {
+          this.setAttribute('limited', '');
+        } else {
+          this.removeAttribute('limited');
+          this.removeAttribute('badge');
+        }
+      }
+
+      get badge() {
+        if (this.hasAttribute('badge')) {
+          const val = this.getAttribute('badge');
+          if (val === 'false' || val === null) return '';
+          return val === '' || val === 'true' ? 'Limited' : val;
+        }
+        if (this.hasAttribute('limited') && this.getAttribute('limited') !== 'false') {
+          const val = this.getAttribute('limited');
+          return val === '' || val === 'true' ? 'Limited' : val;
+        }
+        return '';
+      }
+
+      set badge(value) {
+        if (!value) {
+          this.removeAttribute('badge');
+          this.removeAttribute('limited');
+        } else {
+          this.setAttribute('badge', value === true ? 'Limited' : String(value));
+        }
+      }
