+        if (!this.shadowRoot) return;
+
+        const titleSlot = this.shadowRoot.querySelector('slot[name="title"]');
+        const descSlot = this.shadowRoot.querySelector('slot[name="description"]');
+        const actionLink = this.shadowRoot.querySelector('a.btn');
+        const actionTextSlot = this.shadowRoot.querySelector('slot[name="action-text"]');
+        const badgeSlot = this.shadowRoot.querySelector('slot[name="badge"]');
+
+        if (titleSlot) {
+          titleSlot.textContent = this.title;
+        }
+        if (descSlot) {
+          descSlot.textContent = this.description;
+        }
+        if (actionLink) {
+          actionLink.setAttribute('href', this.href);
+        }
+        if (actionTextSlot) {
+          actionTextSlot.textContent = this.actionText;
+        }
+        if (badgeSlot) {
+          const badgeLabel = this.badge;
+          if (badgeLabel) {
+            if (!this._badgeEl) {
+              this._badgeEl = document.createElement('span');
+              this._badgeEl.className = 'badge';
+              this._badgeEl.setAttribute('part', 'badge');
+            }
+            this._badgeEl.hidden = false;
+            this._badgeEl.style.display = '';
+            this._badgeEl.textContent = badgeLabel;
+            if (this._badgeEl.parentNode !== badgeSlot) {
+              badgeSlot.appendChild(this._badgeEl);
+            }
+          } else if (this._badgeEl) {
