diff --git a/index.html b/index.html
index 66c9173..b5f63d4 100644
--- a/index.html
+++ b/index.html
@@ -135,6 +135,195 @@
       background: #3e2723;
     }

+    /* Brew Strength Customizer Section */
+    .brew-customizer {
+      background: white;
+      padding: 2rem;
+      border-radius: 8px;
+      box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
+      margin-block-end: 2.5rem;
+    }
+
+    .brew-customizer-header {
+      text-align: center;
+      margin-block-end: 1.5rem;
+    }
+
+    .brew-customizer-header h2 {
+      color: var(--primary);
+      margin-block-end: 0.25rem;
+    }
+
+    .brew-slider-field {
+      max-inline-size: 38rem;
+      margin-inline: auto;
+      display: flex;
+      flex-direction: column;
+      gap: 0.5rem;
+    }
+
+    .brew-slider-label-row {
+      display: flex;
+      justify-content: space-between;
+      align-items: baseline;
+      gap: 1rem;
+    }
+
+    .brew-slider-label-row label {
+      font-weight: 600;
+      font-size: 1.1rem;
+      color: var(--primary);
+    }
+
+    .brew-strength-badge {
+      display: inline-block;
+      background: var(--primary);
+      color: white;
+      font-weight: 600;
+      font-size: 0.9rem;
+      padding-block: 0.2rem;
+      padding-inline: 0.75rem;
+      border-radius: 999px;
+    }
+
+    input[type="range"] {
+      --slider-track-size: 0.5rem;
+      --slider-thumb-size: 1.5rem;
+      --slider-track-radius: 999px;
+      --slider-thumb-radius: 50%;
+      --slider-track-color: #8d6e63;
+      --slider-fill-color: var(--primary);
+      --slider-thumb-color: var(--slider-fill-color);
+      --slider-direction: to right;
+
+      &:dir(rtl) {
+        --slider-direction: to left;
+      }
+
+      --attr-min: attr(min type(<number>), 0);
+      --attr-max: attr(max type(<number>), 3);
+      --control-value: attr(value type(<number>), 1);
+      --slider-progress: calc(
+        progress(var(--control-value), var(--attr-min), var(--attr-max)) * 100%
+      );
+
+      appearance: none;
+      inline-size: 100%;
+      block-size: 2.5rem;
+      margin: 0;
+      padding: 0;
+      border: 0;
+      border-radius: 0;
+      background: transparent;
+      font: inherit;
+      font-size: max(1rem, 1em);
+      cursor: pointer;
+    }
+
+    @supports not (opacity: progress(1, 0, 100)) {
+      input[type="range"] {
+        --slider-progress: calc(
+          (var(--control-value) - var(--attr-min)) /
+          (var(--attr-max) - var(--attr-min)) * 100%
+        );
+      }
+    }
+
+    @media (pointer: coarse) {
+      input[type="range"] {
+        min-block-size: 3.25rem;
+      }
+    }
+
+    input[type="range"]:focus-visible {
+      outline: 2px solid var(--slider-fill-color);
+      outline-offset: 4px;
+    }
+
+    /* WebKit/Blink. */
+    input[type="range"]::-webkit-slider-runnable-track {
+      block-size: var(--slider-track-size);
+      border: 0;
+      border-radius: var(--slider-track-radius);
+      background: linear-gradient(
+        var(--slider-direction),
+        var(--slider-fill-color) var(--slider-progress),
+        var(--slider-track-color) var(--slider-progress)
+      );
+    }
+
+    input[type="range"]::-webkit-slider-thumb {
+      -webkit-appearance: none;
+      appearance: none;
+      inline-size: var(--slider-thumb-size);
+      block-size: var(--slider-thumb-size);
+      margin-block-start: calc(
+        (var(--slider-track-size) - var(--slider-thumb-size)) / 2
+      );
+      border: 2px solid var(--light);
+      border-radius: var(--slider-thumb-radius);
+      background: var(--slider-thumb-color);
+      box-shadow: 0 1px 4px rgba(0, 0, 0, 0.25);
+    }
+
+    /* Firefox. */
+    input[type="range"]::-moz-range-track {
+      block-size: var(--slider-track-size);
+      border: 0;
+      border-radius: var(--slider-track-radius);
+      background: var(--slider-track-color);
+    }
+
+    input[type="range"]::-moz-range-progress {
+      block-size: var(--slider-track-size);
+      border-radius: var(--slider-track-radius);
+      background: var(--slider-fill-color);
+    }
+
+    input[type="range"]::-moz-range-thumb {
+      inline-size: var(--slider-thumb-size);
+      block-size: var(--slider-thumb-size);
+      border: 2px solid var(--light);
+      border-radius: var(--slider-thumb-radius);
+      background: var(--slider-thumb-color);
+      box-shadow: 0 1px 4px rgba(0, 0, 0, 0.25);
+    }
+
+    .brew-strength-steps {
+      display: grid;
+      grid-template-columns: repeat(4, 1fr);
+      font-size: 0.875rem;
+      color: var(--text);
+    }
+
+    .brew-strength-step {
+      text-align: center;
+      font-weight: 500;
+      transition: color 0.2s, font-weight 0.2s;
+    }
+
+    .brew-strength-step:first-child {
+      text-align: start;
+    }
+
+    .brew-strength-step:last-child {
+      text-align: end;
+    }
+
+    .brew-strength-step[data-active="true"] {
+      color: var(--primary);
+      font-weight: 700;
