+import type { APIRoute } from 'astro';
+
+export const POST: APIRoute = async ({ request, session }) => {
+  try {
+    const contentType = request.headers.get('content-type') || '';
+    let phone = '';
+    if (contentType.includes('application/json')) {
+      const body = await request.json();
+      phone = String(body.phone || '').trim();
+    } else {
+      const formData = await request.formData();
+      phone = String(formData.get('phone') || '').trim();
+    }
+
+    if (!phone) {
+      return new Response(
+        JSON.stringify({ error: 'Please enter a valid phone number.' }),
+        { status: 400, headers: { 'Content-Type': 'application/json' } }
+      );
+    }
+
+    // Generate a 6-digit one-time passcode
+    const code = Math.floor(100000 + Math.random() * 900000).toString();
+
+    // Extract host domain only (no URL scheme, port, or path) for origin-bound SMS formatting
+    const url = new URL(request.url);
+    const domain = url.hostname || 'example.com';
+
+    // Format origin-bound SMS message: human-readable text first, @<domain> #<otp> on the very last line
+    const smsMessage = `Your verification code is ${code}.\n\n@${domain} #${code}`;
+
+    if (session) {
+      await session.set('pendingOtp', { phone, code });
+    }
+
+    return new Response(
+      JSON.stringify({
+        success: true,
+        phone,
+        smsMessage,
+      }),
+      { status: 200, headers: { 'Content-Type': 'application/json' } }
+    );
+  } catch (err) {
+    return new Response(
+      JSON.stringify({ error: 'Unable to send verification code. Please try again.' }),
+      { status: 500, headers: { 'Content-Type': 'application/json' } }
+    );
+  }
+};
