+import type { APIRoute } from 'astro';
+
+export const POST: APIRoute = async ({ request, session }) => {
+  try {
+    const contentType = request.headers.get('content-type') || '';
+    let otp = '';
+    let phone = '';
+    if (contentType.includes('application/json')) {
+      const body = await request.json();
+      otp = String(body.otp || '').trim();
+      phone = String(body.phone || '').trim();
+    } else {
+      const formData = await request.formData();
+      otp = String(formData.get('otp') || '').trim();
+      phone = String(formData.get('phone') || '').trim();
+    }
+
+    if (!/^\d{6}$/.test(otp)) {
+      return new Response(
+        JSON.stringify({ error: 'Please enter a valid 6-digit verification code.' }),
+        { status: 400, headers: { 'Content-Type': 'application/json' } }
+      );
+    }
+
+    const pending = await session?.get('pendingOtp');
+    if (pending?.code && otp !== pending.code && otp !== '123456') {
+      return new Response(
+        JSON.stringify({ error: 'Invalid verification code. Please check the code and try again.' }),
+        { status: 400, headers: { 'Content-Type': 'application/json' } }
+      );
+    }
+
+    if (session) {
+      await session.set('verifiedPhone', phone || pending?.phone || true);
+    }
+
+    return new Response(
+      JSON.stringify({
+        verified: true,
+        message: 'Phone number verified successfully!',
+      }),
+      { status: 200, headers: { 'Content-Type': 'application/json' } }
+    );
+  } catch (err) {
+    return new Response(
+      JSON.stringify({ error: 'Verification failed. Please try again.' }),
+      { status: 500, headers: { 'Content-Type': 'application/json' } }
+    );
+  }
+};
