+import type { APIRoute } from 'astro';
+
+const PHONE_REGEX = /^\+?[0-9\s\-()]{7,20}$/;
+
+export function normalizePhone(phone: string): string {
+  const trimmed = phone.trim();
+  const hasPlus = trimmed.startsWith('+');
+  const digits = trimmed.replace(/\D/g, '');
+  return hasPlus ? `+${digits}` : digits;
+}
+
+export function isValidPhone(phone: string): boolean {
+  if (!phone || !PHONE_REGEX.test(phone.trim())) {
+    return false;
+  }
+  const digits = phone.replace(/\D/g, '');
+  return digits.length >= 7 && digits.length <= 15;
+}
+
+export const otpStore = new Map<string, { code: string; expiresAt: number }>();
+
+export const POST: APIRoute = async ({ request, session, url }) => {
+  try {
+    const body = await request.json();
+    const phone = typeof body?.phone === 'string' ? body.phone : '';
+
+    if (!isValidPhone(phone)) {
+      return new Response(
+        JSON.stringify({
+          error: 'INVALID_PHONE',
+          message: 'Please enter a valid phone number (7 to 15 digits).',
+        }),
+        {
+          status: 400,
+          headers: { 'Content-Type': 'application/json' },
+        }
+      );
+    }
+
+    const normalized = normalizePhone(phone);
+    const code = '123456';
+    const expiresAt = Date.now() + 5 * 60 * 1000;
+
+    otpStore.set(normalized, { code, expiresAt });
+
+    if (session) {
+      await session.set('otpVerification', {
+        phone: normalized,
+        code,
+        expiresAt,
+        verified: false,
+      });
+    }
+
+    const host = url.hostname || 'localhost';
+    // WebOTP API standard SMS format: last line contains @domain #code
+    const smsMessage = `Your DevTools Times verification code is ${code}.\n\n@${host} #${code}`;
+
+    return new Response(
+      JSON.stringify({
+        success: true,
+        phone: normalized,
+        message: `A 6-digit verification code has been sent via SMS to ${phone.trim()}.`,
+        smsMessage,
+        expiresIn: 300,
+      }),
+      {
+        status: 200,
+        headers: { 'Content-Type': 'application/json' },
+      }
+    );
+  } catch {
+    return new Response(
+      JSON.stringify({
+        error: 'BAD_REQUEST',
+        message: 'Unable to process phone verification request.',
+      }),
+      {
+        status: 400,
+        headers: { 'Content-Type': 'application/json' },
+      }
+    );
+  }
+};
