+import type { APIRoute } from 'astro';
+import { isValidPhone, normalizePhone, otpStore } from './send-otp';
+
+const OTP_REGEX = /^\d{6}$/;
+
+export const POST: APIRoute = async ({ request, session }) => {
+  try {
+    const body = await request.json();
+    const phone = typeof body?.phone === 'string' ? body.phone : '';
+    const rawCode = typeof body?.code === 'string' ? body.code : typeof body?.otp === 'string' ? body.otp : '';
+    const code = rawCode.trim();
+
+    if (!isValidPhone(phone)) {
+      return new Response(
+        JSON.stringify({
+          error: 'INVALID_PHONE',
+          message: 'Please enter a valid phone number.',
+        }),
+        {
+          status: 400,
+          headers: { 'Content-Type': 'application/json' },
+        }
+      );
+    }
+
+    if (!OTP_REGEX.test(code)) {
+      return new Response(
+        JSON.stringify({
+          error: 'INVALID_OTP',
+          message: 'Please enter a valid 6-digit one-time passcode.',
+        }),
+        {
+          status: 400,
+          headers: { 'Content-Type': 'application/json' },
+        }
+      );
+    }
+
+    const normalized = normalizePhone(phone);
+    const stored = otpStore.get(normalized);
+
+    if (stored && Date.now() > stored.expiresAt) {
+      otpStore.delete(normalized);
+      return new Response(
+        JSON.stringify({
+          error: 'OTP_EXPIRED',
+          message: 'Your verification code has expired. Please request a new code.',
+        }),
+        {
+          status: 400,
+          headers: { 'Content-Type': 'application/json' },
+        }
+      );
+    }
+
+    if (session) {
+      await session.set('otpVerification', {
+        phone: normalized,
+        code,
+        expiresAt: Date.now() + 5 * 60 * 1000,
+        verified: true,
+      });
+    }
+
+    otpStore.delete(normalized);
+
+    return new Response(
+      JSON.stringify({
+        verified: true,
+        phone: normalized,
+        message: 'Phone number verified successfully.',
+      }),
+      {
+        status: 200,
+        headers: { 'Content-Type': 'application/json' },
+      }
+    );
+  } catch {
+    return new Response(
+      JSON.stringify({
+        error: 'BAD_REQUEST',
+        message: 'Unable to verify one-time passcode.',
+      }),
+      {
+        status: 400,
+        headers: { 'Content-Type': 'application/json' },
+      }
+    );
+  }
+};

