+          largestUnit: 'millisecond',
+          smallestUnit: 'nanosecond'
+        });
+        const deltaNs = event.instant.epochNanoseconds - prevEvent.instant.epochNanoseconds;
+
+        if (event.instant.epochMilliseconds === prevEvent.instant.epochMilliseconds) {
+          subMsCollisionCount += 1;
+        }
+
+        if (minIntervalNs === null || deltaNs < minIntervalNs) {
+          minIntervalNs = deltaNs;
+          minIntervalPair = `${prevEvent.eventId} → ${event.eventId}`;
+        }
