+        return {
+          ...event,
+          chronologicalRank: index + 1,
+          intervalDuration,
+          untilDuration,
+          intervalNanoseconds: deltaNs,
+          intervalFormatted: formatNanosecondInterval(deltaNs, intervalDuration)
+        };
+      });
