+      const firstInstant = enrichedEvents[0].instant;
+      const lastInstant = enrichedEvents[enrichedEvents.length - 1].instant;
+      const totalSpanDuration = lastInstant.since(firstInstant, {
+        largestUnit: 'second',
+        smallestUnit: 'nanosecond'
