+        `Between ${result.minIntervalPair}`;
+
+      document.getElementById('stat-avg-interval').textContent =
+        `${(Number(result.avgIntervalNs) / 1e6).toFixed(6)} ms (${result.avgIntervalNs.toLocaleString()} ns)`;
+
+      // Render chronological table
+      const rowsHtml = result.events.map((ev) => {
+        const sameMsBadge = ev.chronologicalRank > 1 &&
+          ev.epochMilliseconds === result.events[ev.chronologicalRank - 2].epochMilliseconds
+          ? `<span class="sub-ms" style="margin-left:6px;font-size:0.72rem;">Sub-ms tiebreaker</span>`
+          : '';
+
+        return `
+          <tr data-event-id="${ev.eventId}" data-rank="${ev.chronologicalRank}" data-epoch-ns="${ev.epochNanoseconds.toString()}" data-interval-ns="${ev.intervalNanoseconds.toString()}">
+            <td>
+              <span class="rank-badge">#${ev.chronologicalRank}</span>
+              <span class="raw-order-tag" title="Original arrival position in unsorted batch">(Batch #${ev.rawIndex})</span>
+            </td>
+            <td>
+              <strong>${ev.orderId}</strong> · ${ev.stage}
+              <div style="font-size:0.78rem;color:#6d4c41;">${ev.item} · <code>${ev.eventId}</code></div>
+            </td>
+            <td><span class="service-badge">${ev.service}</span></td>
+            <td>
+              ${formatTimestampWithHighlightedSubMs(ev.instant.toString())}
+              <div class="mono" style="font-size:0.73rem;color:#795548;">epochNs: ${ev.epochNanoseconds.toString()}</div>
+            </td>
+            <td>
+              <span class="interval-pill">${ev.intervalFormatted.headline}</span>
+              ${sameMsBadge}
+              <span class="interval-sub mono">${ev.intervalFormatted.breakdown} · ${ev.intervalFormatted.iso}</span>
+            </td>
+          </tr>
+        `;
+      }).join('');
+
+      const outputEl = document.getElementById('events-output');
+      outputEl.innerHTML = `
+        <div class="table-wrapper">
+          <table class="events-table" aria-label="Chronologically sorted coffee order events">
+            <thead>
+              <tr>
+                <th>Sorted Order</th>
+                <th>Coffee Order Event</th>
