+            darkRoastMode: Boolean(parsed.darkRoastMode),
+            oatMilkDefault: Boolean(parsed.oatMilkDefault),
+            decafRoast: Boolean(parsed.decafRoast)
+          };
+        } catch (err) {
+          return { ...defaultPreferences };
+        }
+      }
+
+      function savePreferences(prefs) {
