+            statusEl.classList.toggle('is-on', isOn);
+          }
+          const itemEl = document.getElementById('pref-item-' + key);
+          if (itemEl) {
+            itemEl.classList.toggle('active-pref', isOn);
+          }
+        });
+
+        // Update active count badge
+        const totalKeys = Object.keys(defaultPreferences).length;
+        const activeCount = Object.values(state).filter(Boolean).length;
+        const countEl = document.getElementById('active-prefs-count');
