+  <script>
+    (function () {
+      const STORAGE_KEY = 'daily_grind_preferences_v1';
+      const defaultPreferences = {
+        darkRoastMode: false,
+        oatMilkDefault: false,
+        decafRoast: false
+      };
+
+      function loadPreferences() {
+        try {
+          const raw = localStorage.getItem(STORAGE_KEY);
+          if (!raw) return { ...defaultPreferences };
+          const parsed = JSON.parse(raw);
+          return {
+            darkRoastMode: Boolean(parsed.darkRoastMode),
+            oatMilkDefault: Boolean(parsed.oatMilkDefault),
+            decafRoast: Boolean(parsed.decafRoast)
+          };
+        } catch (err) {
+          return { ...defaultPreferences };
+        }
+      }
+
+      function savePreferences(prefs) {
+        try {
+          localStorage.setItem(STORAGE_KEY, JSON.stringify(prefs));
+        } catch (err) {
+          // Ignore storage errors in restricted environments
+        }
+      }
+
+      const state = loadPreferences();
+
+      function renderPreferences() {
+        // Apply body classes for visual feedback
+        document.body.classList.toggle('dark-roast-mode', state.darkRoastMode);
+        document.body.classList.toggle('oat-milk-pref-on', state.oatMilkDefault);
+        document.body.classList.toggle('decaf-pref-on', state.decafRoast);
+
+        // Sync all toggle inputs and ARIA attributes
+        const inputs = document.querySelectorAll('input[type="checkbox"][data-pref-key]');
+        inputs.forEach((input) => {
+          const key = input.getAttribute('data-pref-key');
+          const isOn = Boolean(state[key]);
+          input.checked = isOn;
+          input.setAttribute('aria-checked', isOn ? 'true' : 'false');
+        });
+
+        // Update ON/OFF status pills & item containers
+        Object.keys(defaultPreferences).forEach((key) => {
+          const isOn = Boolean(state[key]);
+          const statusEl = document.getElementById('status-' + key);
+          if (statusEl) {
+            statusEl.textContent = isOn ? 'ON' : 'OFF';
+            statusEl.classList.toggle('is-on', isOn);
+          }
+          const itemEl = document.getElementById('pref-item-' + key);
+          if (itemEl) {
+            itemEl.classList.toggle('active-pref', isOn);
+          }
+        });
+
+        // Update active count badge
+        const totalKeys = Object.keys(defaultPreferences).length;
+        const activeCount = Object.values(state).filter(Boolean).length;
+        const countEl = document.getElementById('active-prefs-count');
+        if (countEl) {
+          countEl.textContent = activeCount + ' OF ' + totalKeys + ' ON';
+          countEl.classList.toggle('is-on', activeCount > 0);
+        }
+
+        // Update hero preference summary banner
+        const summaryEl = document.getElementById('hero-pref-summary');
+        if (summaryEl) {
+          const themePart = state.darkRoastMode ? 'Dark Roast Theme: ON' : 'Standard Theme';
+          const milkPart = state.oatMilkDefault ? 'Oat Milk: ON' : 'Dairy Default';
+          const cafPart = state.decafRoast ? 'Swiss Water Decaf: ON' : 'Regular Caffeine';
+          summaryEl.textContent = 'Preferences: ' + themePart + ' \u2022 ' + milkPart + ' \u2022 ' + cafPart;
+        }
+      }
+
+      document.addEventListener('change', (event) => {
+        const target = event.target;
+        if (target && target.matches('input[type="checkbox"][data-pref-key]')) {
+          const key = target.getAttribute('data-pref-key');
+          state[key] = Boolean(target.checked);
+          savePreferences(state);
+          renderPreferences();
+        }
+      });
+
+      renderPreferences();
+    })();
