+    const menuSection = document.getElementById('coffee-menu');
+    const tablist = menuSection.querySelector('.tablist');
+    const tabs = Array.from(tablist.querySelectorAll('button'));
+    const panels = Array.from(menuSection.querySelectorAll('[role="tabpanel"]'));
+
+    function selectTab(selected) {
+      if (!selected) return;
+
+      for (const tab of tabs) {
+        const isCurrent = tab === selected;
+        tab.ariaSelected = String(isCurrent);
+        tab.toggleAttribute('focusgroupstart', isCurrent);
+      }
+
+      for (const panel of panels) {
+        const isCurrent = panel.getAttribute('aria-labelledby') === selected.id;
+        if (isCurrent) {
+          panel.removeAttribute('hidden');
+          panel.tabIndex = 0;
+        } else {
+          panel.hidden = 'until-found';
+          panel.removeAttribute('tabindex');
+        }
+      }
+
+      selected.scrollIntoView({
+        block: 'nearest',
+        inline: 'nearest',
+        container: 'nearest'
+      });
+    }
+
+    tablist.addEventListener('focusin', (event) => {
+      const tab = event.target.closest('button');
+      if (tab && tablist.contains(tab)) {
+        selectTab(tab);
+      }
+    });
+
+    tablist.addEventListener('click', (event) => {
+      const tab = event.target.closest('button');
+      if (tab && tablist.contains(tab)) {
+        selectTab(tab);
+      }
+    });
+
+    menuSection.addEventListener('beforematch', (event) => {
+      const matchedPanel = event.target.closest('[role="tabpanel"]');
+      if (!matchedPanel) return;
+      const tabId = matchedPanel.getAttribute('aria-labelledby');
+      const associatedTab = tabs.find((tab) => tab.id === tabId);
