+    (function () {
+      const menuSection = document.getElementById('coffee-menu');
+      if (!menuSection) return;
+
+      const tabsWrapper = document.getElementById('coffee-tabs-wrapper');
+      const tabBar = menuSection.querySelector('[role="tablist"]');
+      const tabs = Array.from(menuSection.querySelectorAll('[role="tab"]'));
+      const panels = Array.from(menuSection.querySelectorAll('[role="tabpanel"]'));
+
+      function updateScrollIndicators() {
+        if (!tabBar || !tabsWrapper) return;
+        const maxScrollLeft = tabBar.scrollWidth - tabBar.clientWidth;
+        tabsWrapper.classList.toggle('can-scroll-left', tabBar.scrollLeft > 4);
+        tabsWrapper.classList.toggle('can-scroll-right', maxScrollLeft - tabBar.scrollLeft > 4);
+      }
+
+      function scrollTabIntoView(tab) {
+        if (!tabBar || !tab) return;
+        const tabRect = tab.getBoundingClientRect();
+        const barRect = tabBar.getBoundingClientRect();
+        const targetScrollLeft =
+          tabBar.scrollLeft +
+          (tabRect.left - barRect.left) -
+          barRect.width / 2 +
+          tabRect.width / 2;
+
+        tabBar.scrollTo({
+          left: Math.max(0, targetScrollLeft),
+          behavior: 'smooth'
+        });
+      }
+
+      function activateTab(nextTab, { focus = false } = {}) {
+        if (!nextTab) return;
+        const targetPanelId = nextTab.getAttribute('aria-controls');
+
+        tabs.forEach((tab) => {
+          const isSelected = tab === nextTab;
+          tab.setAttribute('aria-selected', isSelected ? 'true' : 'false');
+          tab.setAttribute('tabindex', isSelected ? '0' : '-1');
+        });
+
+        panels.forEach((panel) => {
+          if (panel.id === targetPanelId) {
+            panel.removeAttribute('hidden');
+          } else {
+            panel.setAttribute('hidden', '');
+          }
+        });
+
+        if (focus) {
+          nextTab.focus({ preventScroll: true });
+        }
+        scrollTabIntoView(nextTab);
+      }
+
+      tabs.forEach((tab, index) => {
+        tab.addEventListener('click', () => {
+          activateTab(tab);
+        });
+
+        tab.addEventListener('keydown', (event) => {
+          let targetIndex = null;
+          if (event.key === 'ArrowRight') {
+            targetIndex = (index + 1) % tabs.length;
+          } else if (event.key === 'ArrowLeft') {
+            targetIndex = (index - 1 + tabs.length) % tabs.length;
+          } else if (event.key === 'Home') {
+            targetIndex = 0;
+          } else if (event.key === 'End') {
+            targetIndex = tabs.length - 1;
+          }
+
+          if (targetIndex !== null) {
+            event.preventDefault();
+            activateTab(tabs[targetIndex], { focus: true });
+          }
+        });
+      });
+
+      if (tabBar) {
+        tabBar.addEventListener('scroll', updateScrollIndicators, { passive: true });
+        window.addEventListener('resize', updateScrollIndicators);
+        updateScrollIndicators();
+      }
+    })();
+  </script>
