+        document.getElementById('translatable-main'),
+      ];
+
+      // Preserve original English content and keep track of active language
+      for (const el of translatableElements) {
+        el.dataset.originalText = el.textContent.trim();
+      }
+      let currentContentLang = 'en';
+
+      function setStatus(message, state = 'idle') {
+        statusMessage.textContent = message;
+        statusContainer.dataset.state = state;
+      }
+
+      function setContentLang(langCode) {
+        currentContentLang = langCode;
+        for (const container of langContainers) {
+          if (container) {
+            container.setAttribute('lang', langCode);
+          }
+        }
+      }
+
+      function restoreOriginalEnglish() {
+        for (const el of translatableElements) {
+          if (el.dataset.originalText) {
+            el.textContent = el.dataset.originalText;
+          }
+        }
+        setContentLang('en');
+        sourceSelect.value = 'en';
+        resetBtn.hidden = true;
+      }
+
+      // Check if global Translator API is supported
+      const isTranslatorSupported = 'Translator' in self;
+
+      if (!isTranslatorSupported) {
+        translateBtn.disabled = true;
+        sourceSelect.disabled = true;
+        targetSelect.disabled = true;
+        setStatus(
+          'Client-side translation is currently unsupported in this browser. Use Chrome 138+ or Edge 148+ on desktop for on-device translation.',
+          'unavailable'
+        );
+      }
+
+      async function checkPairAvailability() {
+        if (!('Translator' in self)) return 'unavailable';
+
+        const sourceLanguage = sourceSelect.value;
+        const targetLanguage = targetSelect.value;
+
+        if (sourceLanguage === targetLanguage) {
+          translateBtn.disabled = false;
+          setStatus('Source and target languages are the same.', 'idle');
+          return 'same';
+        }
+
+        const options = { sourceLanguage, targetLanguage };
+
+        try {
+          const availability = await Translator.availability(options);
+          if (availability === 'unavailable') {
+            translateBtn.disabled = true;
+            setStatus(
+              `Translation model for ${sourceLanguage.toUpperCase()} → ${targetLanguage.toUpperCase()} is unavailable on this device.`,
+              'unavailable'
+            );
+          } else if (availability === 'downloadable' || availability === 'downloading') {
+            translateBtn.disabled = false;
+            setStatus(
+              `Language pack (${sourceLanguage.toUpperCase()} → ${targetLanguage.toUpperCase()}) is ${availability}. Click "Translate On-Device" to download and translate.`,
+              'ready'
+            );
+          } else if (availability === 'available') {
+            translateBtn.disabled = false;
+            setStatus(
+              `On-device model (${sourceLanguage.toUpperCase()} → ${targetLanguage.toUpperCase()}) is ready for instant translation.`,
+              'ready'
+            );
+          }
+          return availability;
+        } catch (err) {
+          translateBtn.disabled = true;
+          setStatus('Unable to check on-device translation model availability.', 'error');
+          return 'unavailable';
+        }
+      }
+
+      async function runTranslation(userInitiated = false) {
+        if (!('Translator' in self)) return;
+
+        const sourceLanguage = sourceSelect.value;
+        const targetLanguage = targetSelect.value;
+
+        if (targetLanguage === 'en' && sourceLanguage === 'en') {
+          restoreOriginalEnglish();
+          setStatus('Showing original English content.', 'idle');
+          return;
+        }
+
+        if (sourceLanguage === targetLanguage) {
+          setStatus('Please choose different source and target languages.', 'idle');
+          return;
+        }
+
+        // Identical options object passed to availability() and create()
+        const options = {
+          sourceLanguage,
+          targetLanguage,
+        };
+
+        try {
+          const availability = await Translator.availability(options);
+
+          if (availability === 'unavailable') {
+            translateBtn.disabled = true;
+            setStatus(
+              `Translation model for ${sourceLanguage.toUpperCase()} → ${targetLanguage.toUpperCase()} is unavailable on this device.`,
+              'unavailable'
+            );
+            return;
+          }
+
+          if ((availability === 'downloadable' || availability === 'downloading') && !userInitiated) {
+            // Strictly require a user gesture (button click) to trigger or attach to model download
+            translateBtn.disabled = false;
+            setStatus(
+              `Click "Translate On-Device" to download the ${sourceLanguage.toUpperCase()} → ${targetLanguage.toUpperCase()} language pack.`,
+              'ready'
+            );
+            return;
+          }
+
+          translateBtn.disabled = true;
+          sourceSelect.disabled = true;
+          targetSelect.disabled = true;
+
+          if (availability === 'downloadable' || availability === 'downloading') {
+            progressWrapper.hidden = false;
+            downloadProgress.value = 0;
+            progressPercent.textContent = '0%';
+            setStatus(`Downloading on-device language pack (${sourceLanguage.toUpperCase()} → ${targetLanguage.toUpperCase()})...`, 'loading');
+          } else {
+            setStatus(`Translating menu descriptions and story to ${targetLanguage.toUpperCase()}...`, 'loading');
+          }
+
+          const translator = await Translator.create({
+            ...options,
+            monitor(m) {
+              m.addEventListener('downloadprogress', (e) => {
+                const pct = Math.round((e.loaded || 0) * 100);
+                progressWrapper.hidden = false;
+                downloadProgress.value = pct;
+                progressPercent.textContent = `${pct}%`;
+                setStatus(`Downloading language pack: ${pct}%`, 'loading');
+              });
+            },
+          });
+
+          progressWrapper.hidden = true;
+          setStatus(`Translating content on-device...`, 'loading');
+
+          // Ensure source text matches selected sourceLanguage
+          for (const el of translatableElements) {
+            const inputText =
+              sourceLanguage === 'en' && el.dataset.originalText
+                ? el.dataset.originalText
+                : el.textContent.trim();
+            if (!inputText) continue;
+            const translated = await translator.translate(inputText);
+            el.textContent = translated;
+          }
+
+          // Update lang attribute on container elements to match BCP 47 target language code
+          setContentLang(targetLanguage);
+          // Sync source language selector so visitors can translate between any languages next
+          sourceSelect.value = targetLanguage;
+          resetBtn.hidden = targetLanguage === 'en';
+          setStatus(`Translated on-device to ${targetLanguage.toUpperCase()}.`, 'success');
+        } catch (error) {
+          progressWrapper.hidden = true;
+          setStatus(
+            `Translation could not be completed: ${error && error.message ? error.message : 'On-device model unavailable.'}`,
+            'error'
+          );
+        } finally {
+          if ('Translator' in self) {
+            translateBtn.disabled = false;
+            sourceSelect.disabled = false;
+            targetSelect.disabled = false;
+          }
+        }
+      }
+
+      sourceSelect.addEventListener('change', () => {
+        checkPairAvailability();
+      });
+
+      targetSelect.addEventListener('change', async () => {
+        const availability = await checkPairAvailability();
+        // If the model is already available on-device, we can translate immediately;
+        // if downloadable/downloading, wait for the explicit button click user gesture.
+        if (availability === 'available') {
+          runTranslation(true);
+        }
+      });
+
+      translateBtn.addEventListener('click', () => {
+        runTranslation(true);
+      });
+
+      resetBtn.addEventListener('click', () => {
+        restoreOriginalEnglish();
+        setStatus('Restored original English text.', 'idle');
+        checkPairAvailability();
+      });
+
+      if (isTranslatorSupported) {
+        checkPairAvailability();
+      }
+    })();
+  </script>
+
 </body>

 </html>

