diff --git a/src/components/ArticleTranslator.tsx b/src/components/ArticleTranslator.tsx
new file mode 100644
index 0000000..7f96204
--- /dev/null
+++ b/src/components/ArticleTranslator.tsx
@@ -0,0 +1,414 @@
+import React, { useState, useEffect, useRef, useId } from 'react';
+import {
+  SUPPORTED_LANGUAGES,
+  isTranslatorSupported,
+  isLanguageDetectorSupported,
+  checkTranslationAvailability,
+  detectTextLanguage,
+  translateScopeElements,
+  restoreScopeToOriginal,
+} from '../utils/translator';
+
+export interface ArticleTranslatorProps {
+  variant?: 'article' | 'teaser' | 'page';
+  scopeSelector?: string;
+  initialSourceLang?: string;
+  initialTargetLang?: string;
+  label?: string;
+}
+
+export default function ArticleTranslator({
+  variant = 'article',
+  scopeSelector,
+  initialSourceLang = 'en',
+  initialTargetLang = 'es',
+  label,
+}: ArticleTranslatorProps) {
+  const uniqueId = useId();
+  const rootRef = useRef<HTMLDivElement>(null);
+
+  const [sourceLang, setSourceLang] = useState(initialSourceLang);
+  const [targetLang, setTargetLang] = useState(initialTargetLang);
+  const [availability, setAvailability] = useState<
+    'checking' | 'available' | 'downloadable' | 'downloading' | 'unavailable' | 'unsupported'
+  >('checking');
+  const [status, setStatus] = useState<
+    'idle' | 'detecting' | 'downloading' | 'translating' | 'translated' | 'error'
+  >('idle');
+  const [downloadProgress, setDownloadProgress] = useState<number | null>(null);
+  const [errorMessage, setErrorMessage] = useState<string | null>(null);
+  const [detectedBadge, setDetectedBadge] = useState<string | null>(null);
+  const [isExpanded, setIsExpanded] = useState(variant !== 'teaser');
+  const [detectorSupported, setDetectorSupported] = useState(false);
+
+  useEffect(() => {
+    setDetectorSupported(isLanguageDetectorSupported());
+  }, []);
+
+  useEffect(() => {
+    let cancelled = false;
+    async function verifyAvailability() {
+      if (!isTranslatorSupported()) {
+        if (!cancelled) setAvailability('unsupported');
+        return;
+      }
+      setAvailability('checking');
+      const result = await checkTranslationAvailability(sourceLang, targetLang);
+      if (!cancelled) {
+        setAvailability(result);
+      }
+    }
+    verifyAvailability();
+    return () => {
+      cancelled = true;
+    };
+  }, [sourceLang, targetLang]);
+
+  const resolveScopeElements = (): HTMLElement[] => {
+    if (typeof document === 'undefined') return [];
+    if (variant === 'page') {
+      const scopes = Array.from(
+        document.querySelectorAll<HTMLElement>('[data-translation-scope]')
+      );
+      return scopes.length > 0 ? scopes : [document.querySelector('main') || document.body];
+    }
+    if (scopeSelector) {
+      const el = document.querySelector<HTMLElement>(scopeSelector);
+      if (el) return [el];
+    }
+    if (rootRef.current) {
+      const closestScope = rootRef.current.closest<HTMLElement>(
+        '[data-translation-scope], article'
+      );
+      if (closestScope) return [closestScope];
+    }
+    return [];
+  };
+
+  const handleDetectLanguage = async () => {
+    setErrorMessage(null);
+    const scopes = resolveScopeElements();
+    const sampleEl =
+      scopes[0]?.querySelector('[data-translatable="summary"], [data-translatable="title"]') ||
+      scopes[0];
+    const sampleText = sampleEl?.textContent?.trim() || '';
+    if (!sampleText) return;
+
+    setStatus('detecting');
+    const result = await detectTextLanguage(sampleText, (pct) => {
+      setDownloadProgress(pct);
+    });
+    setDownloadProgress(null);
+
+    if (result && result.detectedLanguage) {
+      const matched = SUPPORTED_LANGUAGES.find(
+        (l) => l.code.toLowerCase() === result.detectedLanguage.toLowerCase()
+      );
+      const code = matched ? matched.code : result.detectedLanguage;
+      setSourceLang(code);
+      setDetectedBadge(
+        `${matched ? matched.name : code.toUpperCase()} (${Math.round(result.confidence * 100)}%)`
+      );
+      if (code === targetLang) {
+        setTargetLang(code === 'en' ? 'es' : 'en');
+      }
+      setStatus('idle');
+    } else {
+      setStatus('idle');
+      setErrorMessage('Could not automatically detect language from text sample.');
+    }
+  };
+
+  const handleSwapLanguages = () => {
+    setSourceLang(targetLang);
+    setTargetLang(sourceLang);
+    setErrorMessage(null);
+  };
+
+  const handleTranslate = async (e: React.MouseEvent<HTMLButtonElement>) => {
+    e.preventDefault();
+    e.stopPropagation();
+    setErrorMessage(null);
+
+    if (!isTranslatorSupported()) {
+      setAvailability('unsupported');
+      setStatus('error');
+      setErrorMessage('Client-side translation is currently unsupported in this browser.');
+      return;
+    }
+
+    const scopes = resolveScopeElements();
+    if (scopes.length === 0) return;
+
+    try {
+      setStatus(
+        availability === 'downloadable' || availability === 'downloading'
+          ? 'downloading'
+          : 'translating'
+      );
+      setDownloadProgress(null);
+
+      for (const scope of scopes) {
+        await translateScopeElements(scope, sourceLang, targetLang, (pct) => {
+          setStatus('downloading');
+          setDownloadProgress(pct);
+        });
+      }
+
+      setDownloadProgress(null);
+      setAvailability('available');
+      setStatus('translated');
+    } catch (err: any) {
+      setDownloadProgress(null);
+      setStatus('error');
+      setErrorMessage(
+        err?.message || 'Unable to complete on-device translation for this language pair.'
+      );
+    }
+  };
+
+  const handleReset = (e: React.MouseEvent<HTMLButtonElement>) => {
+    e.preventDefault();
+    e.stopPropagation();
+    const scopes = resolveScopeElements();
+    for (const scope of scopes) {
+      restoreScopeToOriginal(scope);
+    }
+    setSourceLang('en');
+    setStatus('idle');
+    setErrorMessage(null);
+    setDetectedBadge(null);
+  };
+
+  const isUnavailable = availability === 'unsupported' || availability === 'unavailable';
+  const isBusy =
+    status === 'translating' || status === 'downloading' || status === 'detecting';
+
+  const sourceSelectId = `source-lang-${uniqueId}`;
+  const targetSelectId = `target-lang-${uniqueId}`;
+  const statusRegionId = `translator-status-${uniqueId}`;
+
+  if (variant === 'teaser' && !isExpanded) {
+    return (
+      <div ref={rootRef} className="inline-flex items-center">
+        <button
+          type="button"
+          onClick={(e) => {
+            e.preventDefault();
+            e.stopPropagation();
+            setIsExpanded(true);
+          }}
+          aria-expanded="false"
+          className="inline-flex items-center gap-1 text-xs font-medium text-gray-600 hover:text-amber-700 px-2 py-1 rounded border border-gray-200 hover:border-amber-400 bg-gray-50 transition-colors"
+        >
+          <svg
+            aria-hidden="true"
+            className="w-3.5 h-3.5 text-amber-700"
+            fill="none"
+            viewBox="0 0 24 24"
+            strokeWidth={1.75}
+            stroke="currentColor"
+          >
+            <path
+              strokeLinecap="round"
+              strokeLinejoin="round"
+              d="m10.5 21 5.25-11.25L21 21m-9-3h7.5M3 5.621a48.474 48.474 0 0 1 6-.371m0 0c1.12 0 2.233.038 3.334.114M9 5.25V3m3.334 2.364C11.176 10.658 7.69 15.08 3 17.502m9.334-12.138c.896.061 1.785.147 2.666.257m-4.589 8.495a18.023 18.023 0 0 1-3.827-5.802"
+            />
+          </svg>
+          <span>Translate{label ? ` ${label}` : ''}</span>
+        </button>
+      </div>
+    );
+  }
+
+  return (
+    <div
+      ref={rootRef}
+      className={
+        variant === 'teaser'
+          ? 'mt-2 pt-2 border-t border-gray-100 bg-gray-50/90 rounded p-2.5 text-xs'
+          : variant === 'page'
+          ? 'bg-amber-50/60 border border-amber-200/80 rounded-md px-3 py-2 text-xs'
+          : 'bg-gray-50 border border-gray-200 rounded-lg p-3.5 my-4 text-sm'
+      }
+      onClick={(e) => e.stopPropagation()}
+    >
+      <div className="flex flex-wrap items-center justify-between gap-2">
+        <div className="flex items-center gap-1.5 font-semibold text-gray-800">
+          <svg
+            aria-hidden="true"
+            className="w-4 h-4 text-amber-700 flex-shrink-0"
+            fill="none"
+            viewBox="0 0 24 24"
+            strokeWidth={1.75}
+            stroke="currentColor"
+          >
+            <path
+              strokeLinecap="round"
+              strokeLinejoin="round"
+              d="m10.5 21 5.25-11.25L21 21m-9-3h7.5M3 5.621a48.474 48.474 0 0 1 6-.371m0 0c1.12 0 2.233.038 3.334.114M9 5.25V3m3.334 2.364C11.176 10.658 7.69 15.08 3 17.502m9.334-12.138c.896.061 1.785.147 2.666.257m-4.589 8.495a18.023 18.023 0 0 1-3.827-5.802"
+            />
+          </svg>
+          <span>
+            {variant === 'page'
+              ? 'On-Device Teaser & Page Translator'
+              : variant === 'teaser'
+              ? 'Translate Teaser'
+              : 'On-Device Article Translator'}
+          </span>
+          {availability === 'available' && (
+            <span className="inline-flex items-center px-1.5 py-0.5 rounded text-[10px] font-medium bg-green-100 text-green-800">
+              Ready on device
+            </span>
+          )}
+          {(availability === 'downloadable' || availability === 'downloading') && (
+            <span className="inline-flex items-center px-1.5 py-0.5 rounded text-[10px] font-medium bg-amber-100 text-amber-800">
+              Model downloadable
+            </span>
+          )}
+          {detectedBadge && (
+            <span className="inline-flex items-center px-1.5 py-0.5 rounded text-[10px] font-medium bg-blue-100 text-blue-800">
+              Detected: {detectedBadge}
+            </span>
+          )}
+        </div>
+
+        {variant === 'teaser' && (
+          <button
+            type="button"
+            onClick={() => setIsExpanded(false)}
+            aria-label="Close teaser translator"
+            className="text-gray-400 hover:text-gray-600 px-1"
+          >
+            ✕
+          </button>
+        )}
+      </div>
+
+      <div className="mt-2 flex flex-wrap items-center gap-2">
+        <div className="flex items-center gap-1.5">
+          <label htmlFor={sourceSelectId} className="text-xs font-medium text-gray-600">
+            From:
+          </label>
+          <select
+            id={sourceSelectId}
+            value={sourceLang}
+            onChange={(e) => setSourceLang(e.target.value)}
+            disabled={isBusy}
+            className="bg-white border border-gray-300 rounded px-2 py-1 text-xs text-gray-800 focus:ring-2 focus:ring-amber-400 focus:outline-none"
+          >
+            {SUPPORTED_LANGUAGES.map((lang) => (
+              <option key={`src-${lang.code}`} value={lang.code}>
+                {lang.name} ({lang.code})
+              </option>
+            ))}
+          </select>
+        </div>
+
+        <button
+          type="button"
+          onClick={handleSwapLanguages}
+          disabled={isBusy}
+          aria-label="Swap source and target languages"
+          className="px-2 py-1 rounded border border-gray-300 bg-white hover:bg-gray-100 text-gray-700 text-xs font-medium transition-colors disabled:opacity-50"
+        >
+          ⇄
+        </button>
+
+        <div className="flex items-center gap-1.5">
+          <label htmlFor={targetSelectId} className="text-xs font-medium text-gray-600">
+            To:
+          </label>
+          <select
+            id={targetSelectId}
+            value={targetLang}
+            onChange={(e) => setTargetLang(e.target.value)}
+            disabled={isBusy}
+            className="bg-white border border-gray-300 rounded px-2 py-1 text-xs text-gray-800 focus:ring-2 focus:ring-amber-400 focus:outline-none"
+          >
+            {SUPPORTED_LANGUAGES.map((lang) => (
+              <option key={`tgt-${lang.code}`} value={lang.code}>
+                {lang.name} ({lang.code})
+              </option>
+            ))}
+          </select>
+        </div>
+
+        {detectorSupported && variant !== 'page' && (
+          <button
+            type="button"
+            onClick={handleDetectLanguage}
+            disabled={isBusy}
+            className="px-2 py-1 rounded border border-gray-300 bg-white hover:bg-gray-100 text-gray-700 text-xs font-medium transition-colors disabled:opacity-50"
+          >
+            {status === 'detecting' ? 'Detecting…' : 'Detect source'}
+          </button>
+        )}
+
+        <button
+          type="button"
+          onClick={handleTranslate}
+          disabled={isBusy || isUnavailable || sourceLang === targetLang}
+          aria-describedby={statusRegionId}
+          className="px-3 py-1 rounded bg-gray-900 hover:bg-amber-600 text-white text-xs font-semibold transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
+        >
+          {status === 'downloading'
+            ? `Downloading model${downloadProgress !== null ? ` (${downloadProgress}%)` : '…'}`
+            : status === 'translating'
+            ? 'Translating…'
+            : variant === 'page'
+            ? 'Translate All on Page'
+            : 'Translate'}
+        </button>
+
+        {status === 'translated' && (
+          <button
+            type="button"
+            onClick={handleReset}
+            className="px-2.5 py-1 rounded border border-gray-300 bg-white hover:bg-gray-100 text-gray-700 text-xs font-medium transition-colors"
+          >
+            Show Original
+          </button>
+        )}
+      </div>
+
+      {downloadProgress !== null && status === 'downloading' && (
+        <div className="mt-2 flex items-center gap-2">
+          <label htmlFor={`progress-${uniqueId}`} className="text-xs text-gray-600">
+            Language pack download:
+          </label>
+          <progress
+            id={`progress-${uniqueId}`}
+            value={downloadProgress}
+            max={100}
+            className="h-2 w-36 rounded overflow-hidden"
+          />
+          <span className="text-xs font-medium text-gray-700">{downloadProgress}%</span>
+        </div>
+      )}
+
+      <div id={statusRegionId} aria-live="polite" className="mt-1.5">
+        {availability === 'unsupported' && (
+          <p className="text-xs text-amber-800 bg-amber-50/90 border border-amber-200 rounded px-2 py-1">
+            Client-side translation is currently unsupported in this browser (requires Chrome 138+ or Edge 148+ Desktop with Built-in AI Translator API).
+          </p>
+        )}
+        {availability === 'unavailable' && (
+          <p className="text-xs text-amber-800 bg-amber-50/90 border border-amber-200 rounded px-2 py-1">
+            This language pair ({sourceLang.toUpperCase()} → {targetLang.toUpperCase()}) is currently unavailable for on-device translation on this device.
+          </p>
+        )}
+        {errorMessage && (
+          <p role="alert" className="text-xs text-red-700 bg-red-50 border border-red-200 rounded px-2 py-1">
+            {errorMessage}
+          </p>
+        )}
+        {status === 'translated' && !errorMessage && (
+          <p className="text-xs text-green-800">
+            Translated on-device from {sourceLang.toUpperCase()} to {targetLang.toUpperCase()}.
+          </p>
+        )}
+      </div>
+    </div>
+  );
+}
