@@ -0,0 +1,271 @@
+export interface SupportedLanguage {
+  code: string;
+  name: string;
+}
+
+export const SUPPORTED_LANGUAGES: SupportedLanguage[] = [
+  { code: 'en', name: 'English' },
+  { code: 'es', name: 'Spanish' },
+  { code: 'fr', name: 'French' },
+  { code: 'de', name: 'German' },
+  { code: 'it', name: 'Italian' },
+  { code: 'pt', name: 'Portuguese' },
+  { code: 'nl', name: 'Dutch' },
+  { code: 'ja', name: 'Japanese' },
+  { code: 'ko', name: 'Korean' },
+  { code: 'zh', name: 'Chinese (Simplified)' },
+  { code: 'zh-Hant', name: 'Chinese (Traditional)' },
+  { code: 'ar', name: 'Arabic' },
+  { code: 'bg', name: 'Bulgarian' },
+  { code: 'bn', name: 'Bengali' },
+  { code: 'cs', name: 'Czech' },
+  { code: 'da', name: 'Danish' },
+  { code: 'el', name: 'Greek' },
+  { code: 'fi', name: 'Finnish' },
+  { code: 'he', name: 'Hebrew' },
+  { code: 'hi', name: 'Hindi' },
+  { code: 'hr', name: 'Croatian' },
+  { code: 'hu', name: 'Hungarian' },
+  { code: 'id', name: 'Indonesian' },
+  { code: 'kn', name: 'Kannada' },
+  { code: 'lt', name: 'Lithuanian' },
+  { code: 'mr', name: 'Marathi' },
+  { code: 'no', name: 'Norwegian' },
+  { code: 'pl', name: 'Polish' },
+  { code: 'ro', name: 'Romanian' },
+  { code: 'ru', name: 'Russian' },
+  { code: 'sk', name: 'Slovak' },
+  { code: 'sl', name: 'Slovenian' },
+  { code: 'sv', name: 'Swedish' },
+  { code: 'ta', name: 'Tamil' },
+  { code: 'te', name: 'Telugu' },
+  { code: 'th', name: 'Thai' },
+  { code: 'tr', name: 'Turkish' },
+  { code: 'uk', name: 'Ukrainian' },
+  { code: 'vi', name: 'Vietnamese' },
+];
+
+export function isTranslatorSupported(): boolean {
+  return typeof self !== 'undefined' && 'Translator' in self && Boolean(self.Translator);
+}
+
+export function isLanguageDetectorSupported(): boolean {
+  return (
+    typeof self !== 'undefined' &&
+    'LanguageDetector' in self &&
+    Boolean(self.LanguageDetector)
+  );
+}
+
+const translatorCache = new Map<string, Promise<TranslatorInstance>>();
+
+export async function checkTranslationAvailability(
+  sourceLanguage: string,
+  targetLanguage: string
+): Promise<TranslatorAvailability> {
+  if (!isTranslatorSupported() || !self.Translator) {
+    return 'unavailable';
+  }
+  if (sourceLanguage === targetLanguage) {
+    return 'available';
+  }
+  try {
+    const options = { sourceLanguage, targetLanguage };
+    return await self.Translator.availability(options);
+  } catch {
+    return 'unavailable';
+  }
+}
+
+export async function getOrCreateTranslator(
+  sourceLanguage: string,
+  targetLanguage: string,
+  onProgress?: (percent: number) => void
+): Promise<TranslatorInstance> {
+  if (!isTranslatorSupported() || !self.Translator) {
+    throw new Error('Client-side translation is currently unsupported in this browser.');
+  }
+
+  const options = { sourceLanguage, targetLanguage };
+  const availability = await self.Translator.availability(options);
+
+  if (availability === 'unavailable') {
+    throw new Error(
+      `Translation between ${sourceLanguage.toUpperCase()} and ${targetLanguage.toUpperCase()} is unavailable on this device.`
+    );
+  }
+
+  const cacheKey = `${sourceLanguage}->${targetLanguage}`;
+  if (availability === 'available' && translatorCache.has(cacheKey)) {
+    return translatorCache.get(cacheKey)!;
+  }
+
+  const createPromise = self.Translator.create({
+    ...options,
+    monitor(m) {
+      m.addEventListener('downloadprogress', (e) => {
+        const pct = Math.round((e.loaded || 0) * 100);
+        onProgress?.(pct);
+      });
+    },
+  });
+
+  translatorCache.set(cacheKey, createPromise);
+  try {
+    return await createPromise;
+  } catch (err) {
+    translatorCache.delete(cacheKey);
+    throw err;
+  }
+}
+
+export async function detectTextLanguage(
+  sampleText: string,
+  onProgress?: (percent: number) => void
+): Promise<{ detectedLanguage: string; confidence: number } | null> {
+  if (!isLanguageDetectorSupported() || !self.LanguageDetector) {
+    return null;
+  }
+  if (!sampleText || sampleText.trim().length < 15) {
+    return null;
+  }
+  try {
+    const availability = await self.LanguageDetector.availability();
+    if (availability === 'unavailable') {
+      return null;
+    }
+    const detector = await self.LanguageDetector.create({
+      monitor(m) {
+        m.addEventListener('downloadprogress', (e) => {
+          onProgress?.(Math.round((e.loaded || 0) * 100));
+        });
+      },
+    });
+    const results = await detector.detect(sampleText);
+    if (results && results.length > 0 && results[0].detectedLanguage) {
+      return {
+        detectedLanguage: results[0].detectedLanguage,
+        confidence: results[0].confidence,
+      };
+    }
+    return null;
+  } catch {
+    return null;
+  }
+}
+
+export async function translateTextContent(
+  translator: TranslatorInstance,
+  text: string,
+  useStreaming = false,
+  onStreamUpdate?: (partial: string) => void
+): Promise<string> {
+  const trimmed = text.trim();
+  if (!trimmed) return text;
+
+  if (useStreaming && typeof translator.translateStreaming === 'function' && trimmed.length > 180) {
+    let accumulated = '';
+    const stream = translator.translateStreaming(trimmed);
+    for await (const chunk of stream) {
+      accumulated += chunk;
+      onStreamUpdate?.(accumulated);
+    }
+    return accumulated || trimmed;
+  }
+
+  return await translator.translate(trimmed);
+}
+
+const originalTextMap = new WeakMap<Element, string>();
+
+export function restoreScopeToOriginal(scopeRoot: HTMLElement): void {
+  const elements = scopeRoot.querySelectorAll('[data-translatable]');
+  elements.forEach((el) => {
+    const orig = originalTextMap.get(el);
+    if (orig !== undefined) {
+      el.textContent = orig;
+    }
+    el.removeAttribute('data-translated-lang');
+  });
+  const origLang = scopeRoot.getAttribute('data-original-lang') || 'en';
+  scopeRoot.setAttribute('lang', origLang);
+}
+
+export async function translateScopeElements(
+  scopeRoot: HTMLElement,
+  sourceLanguage: string,
+  targetLanguage: string,
+  onProgress?: (percent: number) => void
+): Promise<void> {
+  if (!scopeRoot.hasAttribute('data-original-lang')) {
+    scopeRoot.setAttribute('data-original-lang', scopeRoot.getAttribute('lang') || 'en');
+  }
+
+  if (sourceLanguage === targetLanguage) {
+    restoreScopeToOriginal(scopeRoot);
+    return;
+  }
+
+  const translator = await getOrCreateTranslator(sourceLanguage, targetLanguage, onProgress);
+  const elements = Array.from(scopeRoot.querySelectorAll('[data-translatable]'));
+
+  // Ensure original texts are saved first
+  for (const el of elements) {
+    if (!originalTextMap.has(el)) {
+      originalTextMap.set(el, el.textContent || '');
+    }
+  }
+
+  for (const el of elements) {
+    const kind = el.getAttribute('data-translatable');
+    if (kind === 'body') {
+      const blocks = Array.from(
+        el.querySelectorAll('p, h2, h3, h4, h5, h6, li, blockquote, figcaption')
+      );
+      if (blocks.length > 0) {
+        for (const block of blocks) {
+          if (!originalTextMap.has(block)) {
+            originalTextMap.set(block, block.textContent || '');
+          }
+          const sourceText =
+            sourceLanguage === (scopeRoot.getAttribute('data-original-lang') || 'en')
+              ? originalTextMap.get(block) || ''
+              : block.textContent || '';
+          if (!sourceText.trim()) continue;
+          const translated = await translateTextContent(
+            translator,
+            sourceText,
+            true,
+            (partial) => {
+              block.textContent = partial;
+            }
+          );
+          block.textContent = translated;
+        }
+        continue;
+      }
+    }
+
+    const sourceText =
+      sourceLanguage === (scopeRoot.getAttribute('data-original-lang') || 'en')
+        ? originalTextMap.get(el) || ''
+        : el.textContent || '';
+    if (!sourceText.trim()) continue;
+
+    const isLong = sourceText.length > 200;
+    const translated = await translateTextContent(
+      translator,
+      sourceText,
+      isLong,
+      isLong
+        ? (partial) => {
+            el.textContent = partial;
+          }
+        : undefined
+    );
+    el.textContent = translated;
+    el.setAttribute('data-translated-lang', targetLanguage);
+  }
+
+  scopeRoot.setAttribute('lang', targetLanguage);
+}

