+
+  // Sync preferences on mount and across components via custom events
+  useEffect(() => {
+    const prefs = loadTranslationPrefs();
+    setSourceLang(prefs.sourceLanguage);
+    setTargetLang(prefs.targetLanguage);
+    setAutoTranslate(prefs.autoTranslate);
+
+    const checkCurrentPageTranslated = () => {
+      const activeLang = document.documentElement.getAttribute('data-page-translated');
+      setIsTranslated(Boolean(activeLang));
+    };
+    checkCurrentPageTranslated();
