+    const handleSyncEvent = (e: Event) => {
+      const custom = e as CustomEvent<{
+        sourceLanguage: string;
+        targetLanguage: string;
+        autoTranslate: boolean;
+        isTranslated: boolean;
+        progress: TranslationProgress | null;
+      }>;
+      if (custom.detail) {
+        setSourceLang(custom.detail.sourceLanguage);
+        setTargetLang(custom.detail.targetLanguage);
+        setAutoTranslate(custom.detail.autoTranslate);
+        setIsTranslated(custom.detail.isTranslated);
+        setProgress(custom.detail.progress);
+      }
