+            title="Swap source and target languages"
+            aria-label="Swap source and target languages"
+            className="p-1.5 bg-white border border-gray-300 rounded-md hover:bg-gray-100 text-gray-700 text-xs cursor-pointer"
+          >
+            ⇄
+          </button>
+
+          <div className="flex items-center bg-white border border-gray-300 rounded-md px-2 py-1 text-xs">
+            <span className="text-gray-400 font-medium mr-1">To:</span>
+            <select
+              aria-label="Target language"
+              value={targetLang}
+              onChange={(e) => handleTargetChange(e.target.value)}
+              className="bg-transparent font-semibold text-gray-800 focus:outline-none cursor-pointer"
+            >
+              {SUPPORTED_LANGUAGES.map((lang) => (
+                <option key={lang.code} value={lang.code}>
+                  {lang.flag} {lang.name} ({lang.nativeName})
+                </option>
+              ))}
+            </select>
+          </div>
+
+          <button
+            type="button"
+            disabled={isBusy}
+            onClick={() => runTranslation(sourceLang, targetLang)}
+            data-testid="article-translate-submit"
+            className="bg-gray-900 hover:bg-gray-800 disabled:opacity-50 text-white text-xs font-semibold px-3.5 py-1.5 rounded-md transition-colors cursor-pointer"
+          >
+            {isBusy
+              ? 'Translating...'
+              : isTranslated
+              ? `Re-translate (${targetLangObj.code.toUpperCase()})`
+              : `Translate to ${targetLangObj.name}`}
+          </button>
+
+          {isTranslated && (
+            <button
+              type="button"
+              onClick={handleRestoreOriginal}
+              data-testid="article-restore-original"
+              className="bg-white hover:bg-gray-100 text-gray-800 text-xs font-semibold px-3 py-1.5 rounded-md border border-gray-300 transition-colors cursor-pointer"
+            >
+              Show Original
+            </button>
+          )}
+        </div>
+      </div>
+
+      {/* Progress / Status Footer */}
+      {progress && progress.phase !== 'idle' && (
+        <div className="mt-3 pt-2.5 border-t border-gray-200 flex flex-col sm:flex-row sm:items-center sm:justify-between gap-2 text-xs text-gray-600">
+          <div className="flex items-center space-x-2">
+            {isBusy && (
+              <span className="w-3.5 h-3.5 border-2 border-amber-500 border-t-transparent rounded-full animate-spin inline-block" />
+            )}
+            <span>
+              {progress.phase === 'detecting' && 'Detecting source language on-device...'}
+              {progress.phase === 'downloading-model' &&
+                `Downloading on-device translation model (${progress.downloadProgress ?? 0}%)...`}
+              {progress.phase === 'translating' &&
+                `Translating paragraphs & teasers (${progress.completedItems} of ${progress.totalItems})...`}
+              {progress.phase === 'completed' && (
+                <>
+                  Translated <strong>{progress.completedItems}</strong> text segments from{' '}
+                  <strong>{progress.sourceLanguage.toUpperCase()}</strong> to{' '}
+                  <strong>{progress.targetLanguage.toUpperCase()}</strong>
+                  {progress.detectedConfidence
+                    ? ` (detected confidence: ${Math.round(progress.detectedConfidence * 100)}%)`
+                    : ''}
+                  .
+                </>
+              )}
+              {progress.phase === 'error' && (
+                <span className="text-red-600">{progress.errorMessage}</span>
+              )}
+            </span>
+          </div>
+          {progress.totalItems > 0 && (
+            <div className="w-full sm:w-44 bg-gray-200 h-1.5 rounded-full overflow-hidden">
+              <div
+                className="bg-amber-500 h-full transition-all duration-150"
+                style={{
+                  width: `${Math.min(
+                    100,
+                    Math.round((progress.completedItems / progress.totalItems) * 100)
+                  )}%`,
+                }}
+              />
+            </div>
+          )}
+        </div>
+      )}
+    </div>
+  );
+}
