diff --git a/src/components/TeaserTranslateButton.tsx b/src/components/TeaserTranslateButton.tsx
new file mode 100644
index 0000000..391be29
--- /dev/null
+++ b/src/components/TeaserTranslateButton.tsx
@@ -0,0 +1,165 @@
+import React, { useState, useEffect, useRef } from 'react';
+import {
+  SUPPORTED_LANGUAGES,
+  translateDOMScope,
+  restoreOriginalDOM,
+  loadTranslationPrefs,
+  saveTranslationPrefs,
+} from '../utils/onDeviceTranslator';
+
+export default function TeaserTranslateButton() {
+  const [targetLang, setTargetLang] = useState<string>('es');
+  const [isTranslated, setIsTranslated] = useState<boolean>(false);
+  const [isTranslating, setIsTranslating] = useState<boolean>(false);
+  const [showPicker, setShowPicker] = useState<boolean>(false);
+  const buttonRef = useRef<HTMLDivElement | null>(null);
+
+  useEffect(() => {
+    const prefs = loadTranslationPrefs();
+    setTargetLang(prefs.targetLanguage || 'es');
+
+    const handleGlobalState = (e: Event) => {
+      const custom = e as CustomEvent<{
+        targetLanguage: string;
+        isTranslated: boolean;
+      }>;
+      if (custom.detail) {
+        setTargetLang(custom.detail.targetLanguage);
+        setIsTranslated(custom.detail.isTranslated);
+      }
+    };
+
+    window.addEventListener('devtools-times:translation-state', handleGlobalState);
+    return () => {
+      window.removeEventListener('devtools-times:translation-state', handleGlobalState);
+    };
+  }, []);
+
+  useEffect(() => {
+    if (!showPicker) return;
+    const handleOutside = (e: MouseEvent) => {
+      if (buttonRef.current && !buttonRef.current.contains(e.target as Node)) {
+        setShowPicker(false);
+      }
+    };
+    document.addEventListener('mousedown', handleOutside);
+    return () => document.removeEventListener('mousedown', handleOutside);
+  }, [showPicker]);
+
+  const getTeaserRoot = (): HTMLElement | null => {
+    if (!buttonRef.current) return null;
+    return buttonRef.current.closest('[data-teaser-card]') as HTMLElement | null;
+  };
+
+  const handleTranslateCard = async (langCode: string) => {
+    const card = getTeaserRoot();
+    if (!card) return;
+
+    if (isTranslated && langCode === targetLang) {
+      restoreOriginalDOM(card);
+      setIsTranslated(false);
+      return;
+    }
+
+    setIsTranslating(true);
+    setTargetLang(langCode);
+    saveTranslationPrefs({ targetLanguage: langCode });
+
+    try {
+      const prefs = loadTranslationPrefs();
+      await translateDOMScope({
+        root: card,
+        sourceLanguage: prefs.sourceLanguage || 'en',
+        targetLanguage: langCode,
+      });
+      setIsTranslated(true);
+    } finally {
+      setIsTranslating(false);
+      setShowPicker(false);
+    }
+  };
+
+  const langObj =
+    SUPPORTED_LANGUAGES.find((l) => l.code === targetLang) || SUPPORTED_LANGUAGES[1];
+
+  return (
+    <div className="relative inline-flex items-center" ref={buttonRef} data-no-translate="true">
+      <div className="inline-flex items-center rounded border border-gray-200 bg-gray-50 text-xs">
+        <button
+          type="button"
+          onClick={() => handleTranslateCard(targetLang)}
+          disabled={isTranslating}
+          title={
+            isTranslated
+              ? 'Restore original teaser language'
+              : `Translate teaser to ${langObj.name} on-device`
+          }
+          aria-label={
+            isTranslated
+              ? 'Restore original teaser language'
+              : `Translate teaser to ${langObj.name}`
+          }
+          data-testid="teaser-translate-btn"
+          className={`flex items-center space-x-1 px-2 py-0.5 rounded-l transition-colors cursor-pointer ${
+            isTranslated
+              ? 'bg-amber-100 text-amber-900 font-semibold'
+              : 'text-gray-600 hover:text-amber-700 hover:bg-gray-100'
+          }`}
+        >
+          <svg
+            xmlns="http://www.w3.org/2000/svg"
+            fill="none"
+            viewBox="0 0 24 24"
+            strokeWidth={1.8}
+            stroke="currentColor"
+            className="w-3.5 h-3.5"
+          >
+            <path
+              strokeLinecap="round"
+              strokeLinejoin="round"
+              d="m10.5 21 5.25-11.25L21 21m-9-3h7.5M3 5.621a48.474 48.474 0 0 1 6-.371m0 0c1.12 0 2.233.038 3.334.114M9 5.25V3m3.334 2.364C11.176 10.658 7.69 15.08 3 17.502m9.334-12.138c.896.061 1.785.147 2.666.257m-4.589 8.495a18.023 18.023 0 0 1-3.827-5.802"
+            />
+          </svg>
+          <span>
+            {isTranslating
+              ? '...'
+              : isTranslated
+              ? `Original (${langObj.code.toUpperCase()})`
+              : langObj.code.toUpperCase()}
+          </span>
+        </button>
+        <button
+          type="button"
+          onClick={() => setShowPicker((prev) => !prev)}
+          aria-label="Choose teaser translation language"
+          className="px-1 py-0.5 border-l border-gray-200 text-gray-500 hover:text-gray-800 hover:bg-gray-100 rounded-r cursor-pointer"
+        >
+          ▾
+        </button>
+      </div>
+
+      {showPicker && (
+        <div className="absolute bottom-full right-0 mb-1 w-40 bg-white border border-gray-200 rounded-md shadow-lg py-1 z-30 max-h-48 overflow-y-auto">
+          <div className="px-2 py-1 text-[10px] font-semibold text-gray-400 uppercase border-b border-gray-100">
+            Translate Teaser
+          </div>
+          {SUPPORTED_LANGUAGES.map((lang) => (
+            <button
+              key={lang.code}
+              type="button"
+              onClick={() => handleTranslateCard(lang.code)}
+              className={`w-full text-left px-2.5 py-1 text-xs flex items-center justify-between hover:bg-amber-50 cursor-pointer ${
+                lang.code === targetLang ? 'font-semibold text-amber-800 bg-amber-50/50' : 'text-gray-700'
+              }`}
+            >
+              <span>
+                {lang.flag} {lang.name}
+              </span>
+              <span className="text-[10px] text-gray-400 uppercase">{lang.code}</span>
+            </button>
+          ))}
+        </div>
+      )}
+    </div>
+  );
+}
