+export interface TranslationPrefs {
+  sourceLanguage: string; // 'auto' or BCP-47
+  targetLanguage: string; // BCP-47
+  autoTranslate: boolean;
+}
+
+export function loadTranslationPrefs(): TranslationPrefs {
+  if (typeof window === 'undefined') {
+    return { sourceLanguage: 'en', targetLanguage: 'es', autoTranslate: false };
+  }
+  try {
+    const raw = localStorage.getItem(STORAGE_KEY);
+    if (raw) {
+      const parsed = JSON.parse(raw);
+      return {
+        sourceLanguage: parsed.sourceLanguage || 'en',
+        targetLanguage: parsed.targetLanguage || 'es',
+        autoTranslate: Boolean(parsed.autoTranslate),
+      };
+    }
+  } catch {
+    // ignore storage errors
+  }
+  return { sourceLanguage: 'en', targetLanguage: 'es', autoTranslate: false };
+}
+
+export function saveTranslationPrefs(prefs: Partial<TranslationPrefs>): TranslationPrefs {
+  const current = loadTranslationPrefs();
+  const updated = { ...current, ...prefs };
+  if (typeof window !== 'undefined') {
+    try {
+      localStorage.setItem(STORAGE_KEY, JSON.stringify(updated));
+    } catch {
+      // ignore storage errors
+    }
+  }
+  return updated;
+}
