+/**
+ * Detects which on-device translation API is supported in the current browser environment.
+ */
+export function detectTranslationEngine(): EngineType {
+  if (typeof window === 'undefined') return 'local-fallback';
+  if ('Translator' in self && self.Translator && typeof self.Translator.create === 'function') {
+    return 'chrome-translator';
+  }
+  if (
+    (window.translation && typeof window.translation.createTranslator === 'function') ||
+    (window.ai?.translator && typeof window.ai.translator.create === 'function')
+  ) {
+    return 'legacy-ai';
+  }
+  return 'local-fallback';
+}
+
+/**
+ * Checks availability of a language pair in the on-device Translator API.
+ */
+export async function checkPairAvailability(
+  sourceLanguage: string,
+  targetLanguage: string
+): Promise<{ status: AvailabilityStatus; engine: EngineType }> {
+  const engine = detectTranslationEngine();
+  if (sourceLanguage === targetLanguage) {
+    return { status: 'available', engine };
+  }
+
+  try {
+    if (engine === 'chrome-translator' && self.Translator) {
+      if (typeof self.Translator.availability === 'function') {
+        const res = await self.Translator.availability({ sourceLanguage, targetLanguage });
+        if (res === 'available' || res === 'readily') {
+          return { status: 'available', engine };
+        }
+        if (res === 'downloadable' || res === 'after-download') {
+          return { status: 'downloadable', engine };
+        }
+        if (res === 'downloading') {
+          return { status: 'downloading', engine };
+        }
+        return { status: 'unavailable', engine };
+      }
+      if (typeof self.Translator.canTranslate === 'function') {
+        const res = await self.Translator.canTranslate({ sourceLanguage, targetLanguage });
+        if (res === 'readily' || res === 'available') return { status: 'available', engine };
+        if (res === 'after-download' || res === 'downloadable') return { status: 'downloadable', engine };
+        return { status: 'unavailable', engine };
+      }
+    }
+
+    if (engine === 'legacy-ai') {
+      if (window.translation?.canTranslate) {
+        const res = await window.translation.canTranslate({ sourceLanguage, targetLanguage });
+        if (res === 'readily' || res === 'available') return { status: 'available', engine };
+        if (res === 'after-download' || res === 'downloadable') return { status: 'downloadable', engine };
+      }
