+    de: 'DE',
+    pt: 'PT',
+    it: 'IT',
+    ja: 'JA',
+    zh: 'ZH',
+    ko: 'KO',
+    hi: 'HI',
+    ar: 'AR',
+    ru: 'RU',
+    nl: 'NL',
