+    completedItems++;
+    onProgress?.({
+      phase: 'translating',
+      completedItems,
+      totalItems,
+      engine: currentEngine,
+      sourceLanguage: resolvedSource,
+      targetLanguage,
+      detectedConfidence,
+    });
+  }
+
+  if (root === document && typeof document !== 'undefined') {
+    document.documentElement.setAttribute('data-page-translated', targetLanguage);
+  }
+
+  const finalState: TranslationProgress = {
+    phase: 'completed',
+    completedItems,
+    totalItems,
+    engine: currentEngine,
+    sourceLanguage: resolvedSource,
+    targetLanguage,
+    detectedConfidence,
+  };
