+}
+
+:root {
+  --brand-accent: #b45309;
+  --brand-accent-hover: #92400e;
+}
+
+/* Semantic surface context flag for featured sections */
+.featured {
+  --surface: featured;
+}
+
+/* Default subtle presentation: hidden promotional badge and outlined action button */
+.teaser-badge,
+.badge {
+  display: none;
+  align-items: center;
+  gap: 0.25rem;
+  font-size: 0.75rem;
+  font-weight: 700;
+  text-transform: uppercase;
+  letter-spacing: 0.05em;
+  padding: 0.125rem 0.5rem;
+  border-radius: 9999px;
+  background-color: #fef3c7;
+  color: #92400e;
+  width: fit-content;
+}
+
+.teaser-action-button,
+.button {
+  display: inline-flex;
+  align-items: center;
+  gap: 0.375rem;
+  padding: 0.375rem 0.75rem;
+  border-radius: 0.375rem;
+  font-size: 0.75rem;
+  font-weight: 600;
+  background: transparent;
+  color: #374151;
+  border: 1px solid currentColor;
+  transition: background-color 0.15s ease, color 0.15s ease, border-color 0.15s ease;
+}
+
+.teaser-action-button:hover,
+.button:hover {
+  color: var(--brand-accent-hover);
+}
+
+/* Selector-based contextual fallback — broad browser support with zero container specificity */
+:where(.featured) .teaser-badge,
+:where(.featured) .badge {
+  display: inline-flex;
+}
+
+:where(.featured) .teaser-action-button,
+:where(.featured) .button {
+  background: var(--brand-accent);
+  color: #ffffff;
+  border: none;
+}
+
+:where(.featured) .teaser-action-button:hover,
+:where(.featured) .button:hover {
+  background: var(--brand-accent-hover);
+  color: #ffffff;
+}
+
+/* Progressive enhancement: container style queries override when supported */
+@container style(--surface: featured) {
+  .teaser-badge,
+  .badge {
+    display: inline-flex;
+  }
+
+  .teaser-action-button,
+  .button {
+    background: var(--brand-accent);
+    color: #ffffff;
+    border: none;
+  }
+
+  .teaser-action-button:hover,
+  .button:hover {
+    background: var(--brand-accent-hover);
+    color: #ffffff;
+  }
+}

