+import { createServer } from 'node:http';
+import { createHash, randomBytes } from 'node:crypto';
+import { readFile } from 'node:fs/promises';
+import path from 'node:path';
+import { fileURLToPath } from 'node:url';
+import dns from 'node:dns/promises';
+import { decodeSdJwtSync, SDJwtInstance } from '@sd-jwt/core';
+import { createRemoteJWKSet, importJWK, jwtVerify } from 'jose';
+
+const __dirname = path.dirname(fileURLToPath(import.meta.url));
+const PORT = Number(process.env.PORT) || 11222;
+const ORIGIN_TRIAL_TOKEN = process.env.ORIGIN_TRIAL_TOKEN || 'A_DAILY_GRIND_EMAIL_VERIFICATION_ORIGIN_TRIAL_TOKEN';
+const RP_ORIGIN = process.env.RP_ORIGIN || `http://localhost:${PORT}`;
+
+// Server-side session store mapping HttpOnly session IDs to single-use nonces
+const sessionNonces = new Map();
+
+// IETF draft-hardt-email-verification-02 (§3.3, §5.1.1) specifies RFC 9864 'Ed25519' and 'ES256'.
+// Keep 'EdDSA' while live issuers (e.g. Gmail) and Chrome Origin Trial builds finish
+// transitioning from 'EdDSA' (with crv: 'Ed25519') to 'Ed25519'.
+const ALLOWED_ALGS = ['Ed25519', 'EdDSA', 'ES256'];
+const normalizeAlg = (alg) => (alg === 'Ed25519' ? 'EdDSA' : alg);
+
+const hasher = (data, alg) =>
+  createHash(alg === 'sha-256' ? 'sha256' : alg).update(data).digest();
+
+function parseCookies(cookieHeader = '') {
+  const cookies = {};
+  for (const part of cookieHeader.split(';')) {
+    const [rawName, ...rest] = part.trim().split('=');
+    if (rawName) {
+      cookies[rawName] = decodeURIComponent(rest.join('='));
+    }
+  }
+  return cookies;
+}
+
+export function issueSessionNonce(req, res) {
+  const cookies = parseCookies(req.headers?.cookie || '');
+  const sessionId = cookies.dg_session || randomBytes(16).toString('base64url');
+  const nonce = randomBytes(32).toString('base64url');
+
+  sessionNonces.set(sessionId, {
+    nonce,
+    createdAt: Date.now(),
+  });
+
+  if (res?.setHeader) {
+    res.setHeader(
+      'Set-Cookie',
+      `dg_session=${encodeURIComponent(sessionId)}; Path=/; HttpOnly; Secure; SameSite=Lax`
+    );
+  }
+
+  return { sessionId, nonce };
+}
+
+export async function consumeSessionNonce(requestOrReq) {
+  const cookieHeader =
+    typeof requestOrReq?.headers?.get === 'function'
+      ? requestOrReq.headers.get('cookie') || ''
+      : requestOrReq?.headers?.cookie || '';
+  const cookies = parseCookies(cookieHeader);
+  const sessionId = cookies.dg_session;
+  if (!sessionId) return null;
+
+  // Atomically read and delete the single-use nonce from server-side session state
+  const entry = sessionNonces.get(sessionId);
+  sessionNonces.delete(sessionId);
+  if (!entry) return null;
+
+  // Expire nonces older than 5 minutes
+  if (Date.now() - entry.createdAt > 5 * 60 * 1000) {
+    return null;
+  }
+  return entry.nonce;
+}
+
+export async function verifyEmailVerificationToken({
+  rawToken,
+  submittedEmail,
+  expectedNonce,
+  expectedAudience = RP_ORIGIN,
+}) {
+  // Step 1: Parse the SD-JWT claims and validate the email address
+  const decoded = decodeSdJwtSync(rawToken, hasher);
+  const evtPayload = decoded.jwt.payload;
+  const iss = evtPayload.iss;
+
+  if (!expectedNonce || !decoded.kbJwt || !iss || evtPayload.email_verified !== true) {
+    throw new Error('Missing nonce, KB-JWT, issuer, or email_verified !== true.');
+  }
+  // MANDATORY: Compare email addresses case-insensitively
+  if (evtPayload.email?.toLowerCase() !== submittedEmail.toLowerCase()) {
+    throw new Error('Submitted email does not match the EVT email claim.');
+  }
+
+  // Step 2: Validate DNS TXT delegation and load the issuer JWKS
+  const domain = submittedEmail.split('@')[1];
+  const txtRecords = (await dns.resolveTxt(`_email-verification.${domain}`)).map((r) => r.join(''));
+  if (!txtRecords.some((txt) => txt.startsWith('iss=') && `https://${txt.slice(4).trim()}` === iss)) {
+    throw new Error(`Issuer "${iss}" is not delegated via DNS for "${domain}".`);
+  }
+
+  const discoveryUrl = new URL('/.well-known/email-verification', iss);
+  if (discoveryUrl.protocol !== 'https:') throw new Error('Issuer must use HTTPS.');
+  const metadata = await (await fetch(discoveryUrl)).json();
+  if (metadata.issuer !== iss || !metadata.jwks_uri?.startsWith('https://')) {
+    throw new Error('Invalid issuer metadata or non-HTTPS jwks_uri.');
+  }
+  const issuerJwks = createRemoteJWKSet(new URL(metadata.jwks_uri));
+
+  // Step 3: Verify the EVT signature and Key Binding JWT (KB-JWT)
+  const evtOptions = {
+    typ: 'ev+sd-jwt',
+    issuer: iss,
+    algorithms: ALLOWED_ALGS,
+    maxTokenAge: '5m',
+    clockTolerance: '1m',
+  };
+
+  const sdJwt = new SDJwtInstance({
+    hasher,
+    verifier: async (data, sig) => {
+      const compactEvt = `${data}.${sig}`;
+      try {
+        await jwtVerify(compactEvt, issuerJwks, evtOptions);
+      } catch (err) {
+        // When `kid` is omitted (e.g. Gmail) and multiple keys match in the JWKS,
+        // jose throws JWKSMultipleMatchingKeys, which yields each matching CryptoKey.
+        if (err?.code !== 'ERR_JWKS_MULTIPLE_MATCHING_KEYS') throw err;
+        let matched = false;
+        for await (const publicKey of err) {
+          try {
+            await jwtVerify(compactEvt, publicKey, evtOptions);
+            matched = true;
+            break;
+          } catch {}
+        }
+        if (!matched) throw err;
+      }
+      return true;
+    },
+    kbVerifier: async (data, sig) => {
+      const holderJwk = evtPayload.cnf?.jwk;
+      const holderAlg = holderJwk?.alg;
+      const kbAlg = decoded.kbJwt.header.alg;
+      if (
+        !holderAlg ||
+        !kbAlg ||
+        !ALLOWED_ALGS.includes(holderAlg) ||
+        !ALLOWED_ALGS.includes(kbAlg) ||
+        normalizeAlg(kbAlg) !== normalizeAlg(holderAlg)
+      ) {
+        throw new Error('Missing, disallowed, or mismatched KB-JWT algorithm.');
+      }
+      const holderKey = await importJWK(holderJwk, kbAlg);
+      await jwtVerify(`${data}.${sig}`, holderKey, {
+        typ: 'kb+jwt',
+        audience: expectedAudience,
+        algorithms: [kbAlg],
+        maxTokenAge: '5m',
+        clockTolerance: '1m',
+      });
+      return true;
+    },
+  });
+
+  const verified = await sdJwt.verify(rawToken, {
+    requiredClaimKeys: ['email', 'email_verified'],
+    keyBindingNonce: expectedNonce,
+    expectedKeyBindingAudience: expectedAudience,
+    keyBindingMaxAgeSeconds: 300,
+    skewSeconds: 60,
+  });
+
+  return verified;
+}
+
+export function completeAccountCreation(submittedEmail, fullName = '') {
+  return {
+    ok: true,
+    verified: true,
+    verificationMethod: 'evp',
+    email: submittedEmail,
+    fullName,
+    message: `Welcome to Daily Grind Rewards! Your email (${submittedEmail}) was cryptographically verified by your browser.`,
+  };
+}
+
+export function sendTraditionalVerificationEmail(submittedEmail, fullName = '') {
+  return {
+    ok: true,
+    verified: false,
+    verificationMethod: 'email-fallback',
+    email: submittedEmail,
+    fullName,
+    message: `Almost there! We sent a verification link to ${submittedEmail} to complete your Daily Grind Rewards registration.`,
+  };
+}
+
+export async function handleSignupSubmission(request) {
+  const formData = await request.formData();
+  const fullName = String(formData.get('full-name') || '').trim();
+  const submittedEmail = String(formData.get('email') || '').trim();
+  const rawToken = String(formData.get('token') || '').trim();
+  // Atomically read and delete the single-use nonce from server-side session state
+  const expectedNonce = await consumeSessionNonce(request);
+
+  if (rawToken && expectedNonce) {
+    try {
+      await verifyEmailVerificationToken({
+        rawToken,
+        submittedEmail,
+        expectedNonce,
+        expectedAudience: RP_ORIGIN,
+      });
+      // Fast path: email ownership is cryptographically verified; skip OTP email.
+      return completeAccountCreation(submittedEmail, fullName);
+    } catch (err) {
+      // Log token verification failures before falling back to standard email verification.
+      console.error('Email verification token check failed:', err);
+    }
+  }
+
+  // Fallback path: send standard OTP code or magic link email to submittedEmail.
+  return sendTraditionalVerificationEmail(submittedEmail, fullName);
+}
+
+async function readBodyBuffer(req) {
+  const chunks = [];
+  for await (const chunk of req) {
+    chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk));
+  }
+  return Buffer.concat(chunks);
+}
+
+export function createAppServer() {
+  return createServer(async (req, res) => {
+    try {
+      const host = req.headers.host || `localhost:${PORT}`;
+      const url = new URL(req.url || '/', `http://${host}`);
+
+      if (req.method === 'GET' && (url.pathname === '/' || url.pathname === '/index.html')) {
+        const { nonce } = issueSessionNonce(req, res);
+        const rawHtml = await readFile(path.join(__dirname, 'index.html'), 'utf8');
+        const renderedHtml = rawHtml
+          .replaceAll('SERVER_GENERATED_PER_FORM_NONCE', nonce)
+          .replaceAll('YOUR_ORIGIN_TRIAL_TOKEN', ORIGIN_TRIAL_TOKEN);
+
+        res.writeHead(200, {
+          'Content-Type': 'text/html; charset=utf-8',
+          'Cache-Control': 'no-store',
+          'Origin-Trial': ORIGIN_TRIAL_TOKEN,
+        });
+        res.end(renderedHtml);
+        return;
+      }
+
+      if (req.method === 'GET' && url.pathname === '/api/session-nonce') {
+        const { nonce } = issueSessionNonce(req, res);
+        res.writeHead(200, {
+          'Content-Type': 'application/json; charset=utf-8',
+          'Cache-Control': 'no-store',
+          'Origin-Trial': ORIGIN_TRIAL_TOKEN,
+        });
+        res.end(JSON.stringify({ nonce }));
+        return;
+      }
+
+      if (
+        req.method === 'POST' &&
+        (url.pathname === '/api/verify-email' || url.pathname === '/api/rewards/signup')
+      ) {
+        const bodyBuffer = await readBodyBuffer(req);
+        const contentType = req.headers['content-type'] || 'application/x-www-form-urlencoded';
+
+        let result;
+        if (contentType.includes('application/json')) {
+          const parsed = JSON.parse(bodyBuffer.toString('utf8') || '{}');
+          const form = new URLSearchParams();
+          for (const [k, v] of Object.entries(parsed)) {
+            if (v !== undefined && v !== null) form.set(k, String(v));
+          }
+          const webReq = new Request(url.toString(), {
+            method: 'POST',
+            headers: {
+              ...req.headers,
+              'content-type': 'application/x-www-form-urlencoded',
+            },
+            body: form.toString(),
+          });
+          result = await handleSignupSubmission(webReq);
+        } else {
+          const webReq = new Request(url.toString(), {
+            method: 'POST',
+            headers: req.headers,
+            body: bodyBuffer,
+          });
+          result = await handleSignupSubmission(webReq);
+        }
+
+        const acceptsJson = (req.headers.accept || '').includes('application/json');
+        res.writeHead(200, {
+          'Content-Type': acceptsJson ? 'application/json; charset=utf-8' : 'text/html; charset=utf-8',
+          'Cache-Control': 'no-store',
+        });
+
+        if (acceptsJson) {
+          res.end(JSON.stringify(result));
+        } else {
+          res.end(`<!DOCTYPE html>
+<html lang="en">
+<head>
+  <meta charset="UTF-8">
+  <meta name="viewport" content="width=device-width, initial-scale=1.0">
+  <title>Daily Grind Rewards | Registration Status</title>
+</head>
+<body>
+  <main style="max-width: 600px; margin: 4rem auto; font-family: system-ui, sans-serif; padding: 2rem; border-radius: 8px; background: #fff; box-shadow: 0 2px 8px rgba(0,0,0,0.1);">
+    <h1>${result.verified ? 'Rewards Account Verified!' : 'Check Your Email'}</h1>
+    <p>${result.message}</p>
+    <p><a href="/">Return to The Daily Grind</a></p>
+  </main>
+</body>
+</html>`);
+        }
+        return;
+      }
+
+      res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
+      res.end('Not Found');
+    } catch (err) {
+      console.error('Server error:', err);
+      res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
+      res.end(JSON.stringify({ ok: false, error: 'Internal Server Error' }));
+    }
+  });
+}
+
+if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
+  const server = createAppServer();
+  server.listen(PORT, () => {
+    console.log(`Daily Grind server listening on http://localhost:${PORT}`);
+  });
+}

