+        const currentNonce = tokenInput.getAttribute('nonce');
+        if (!currentNonce || currentNonce === '__SERVER_NONCE__') {
+          try {
+            const res = await fetch('/api/nonce', { credentials: 'same-origin', cache: 'no-store' });
+            if (res.ok) {
+              const data = await res.json();
+              if (data.nonce) {
+                tokenInput.setAttribute('nonce', data.nonce);
+                tokenInput.nonce = data.nonce;
+              }
+            }
+          } catch {
+            // Nonce will remain as rendered
+          }
+        }
+      }
+
+      // Ensure a server-bound session nonce is initialized if index.html was loaded statically
+      ensureFreshNonce();
+
+      // Support early WICG `emailverified` event if dispatched by the user agent
+      emailInput.addEventListener('emailverified', (event) => {
+        if (event.presentationToken && !tokenInput.value) {
+          tokenInput.value = event.presentationToken;
+        }
+      });
+
+      form.addEventListener('submit', async (event) => {
+        event.preventDefault();
+        submitBtn.disabled = true;
+        submitBtn.textContent = 'Verifying with Browser...';
+        statusBox.className = 'verification-status';
+        statusBox.textContent = '';
+
+        const formData = new FormData(form);
+        const payload = {
+          name: formData.get('name'),
+          email: formData.get('email'),
+          favoriteDrink: formData.get('favoriteDrink'),
+          token: formData.get('token') || tokenInput.value || '',
+        };
+
+        try {
+          const response = await fetch(form.action, {
+            method: 'POST',
+            headers: {
+              'Content-Type': 'application/json',
+              'Accept': 'application/json',
+            },
+            credentials: 'same-origin',
+            body: JSON.stringify(payload),
+          });
+
+          const result = await response.json();
+
+          if (response.ok && result.verified) {
+            setStatus(
+              'success',
+              '<strong>Email Verified Instantly!</strong> Welcome, ' +
+                (result.member?.name || payload.name) +
+                '! Your email (<code>' +
+                result.email +
+                '</code>) was cryptographically confirmed by your browser without sending an OTP or magic link. <strong>150 Bonus Beans</strong> have been credited to your account.'
+            );
+            form.reset();
+            tokenInput.value = '';
+          } else {
+            setStatus(
+              result.fallbackRequired ? 'warning' : 'error',
+              '<strong>Verification Notice:</strong> ' +
+                (result.error || 'Could not verify email token.')
+            );
+          }
+        } catch (err) {
+          setStatus(
+            'error',
+            '<strong>Network Error:</strong> Unable to reach the verification server.'
+          );
+        } finally {
+          submitBtn.disabled = false;
+          submitBtn.textContent = 'Join Rewards & Verify Email';
+          // Refresh single-use nonce for any subsequent form submission
+          tokenInput.setAttribute('nonce', '');
+          await ensureFreshNonce();
+        }
+      });
+    })();
+  </script>
 </body>

