+import http from 'node:http';
+import fs from 'node:fs/promises';
+import path from 'node:path';
+import { createHash, randomBytes } from 'node:crypto';
+import dns from 'node:dns/promises';
+import { fileURLToPath } from 'node:url';
+import { decodeSdJwtSync, SdJwtInstance } from '@sd-jwt/core';
+import { createRemoteJWKSet, importJWK, jwtVerify } from 'jose';
+
+const __filename = fileURLToPath(import.meta.url);
+const __dirname = path.dirname(__filename);
+
+const PORT = Number(process.env.PORT) || 11222;
+
+// IETF draft-hardt-email-verification-02 (§3.3, §5.1.1) specifies RFC 9864 'Ed25519' and 'ES256'.
+// Support 'EdDSA' alongside 'Ed25519' and 'ES256' for live issuers and origin trial builds.
+const ALLOWED_ALGS = ['Ed25519', 'EdDSA', 'ES256'];
+const normalizeAlg = (alg) => (alg === 'Ed25519' ? 'EdDSA' : alg);
+
+const hasher = (data, alg) =>
+  createHash(alg === 'sha-256' ? 'sha256' : alg).update(data).digest();
+
+// Server-side session store (keyed by HttpOnly session ID cookie)
+const sessions = new Map();
+const SESSION_COOKIE_NAME = 'dg_session_id';
+
+// In-memory store of registered rewards members
+const rewardsMembers = new Map();
+
+function parseCookies(cookieHeader = '') {
+  const cookies = {};
+  for (const part of cookieHeader.split(';')) {
+    const [rawName, ...rawVal] = part.trim().split('=');
+    if (rawName) {
+      cookies[rawName] = decodeURIComponent(rawVal.join('='));
+    }
+  }
+  return cookies;
+}
+
+function getOrCreateSession(req, res) {
+  const cookies = parseCookies(req.headers.cookie);
+  let sessionId = cookies[SESSION_COOKIE_NAME];
+  let session = sessionId ? sessions.get(sessionId) : undefined;
+
+  if (!session) {
+    sessionId = randomBytes(32).toString('base64url');
+    session = { createdAt: Date.now(), nonce: null };
+    sessions.set(sessionId, session);
+    res.setHeader(
+      'Set-Cookie',
+      `${SESSION_COOKIE_NAME}=${sessionId}; Path=/; HttpOnly; Secure; SameSite=Lax`
+    );
+  }
+  return { sessionId, session };
+}
+
+/**
+ * Verifies an Email Verification Token (EVT) SD-JWT+KB presentation package
+ * according to the WICG Email Verification API / IETF EVP specification.
+ */
+export async function verifyEmailVerificationToken({
+  rawToken,
+  submittedEmail,
+  expectedNonce,
+  expectedAudience,
+}) {
+  if (!rawToken || typeof rawToken !== 'string') {
+    throw new Error('Missing email verification token.');
+  }
+  if (!submittedEmail || typeof submittedEmail !== 'string' || !submittedEmail.includes('@')) {
+    throw new Error('Invalid or missing email address.');
+  }
+  if (!expectedNonce || typeof expectedNonce !== 'string') {
+    throw new Error('Missing or expired session nonce.');
+  }
+
+  // 1. Decode SD-JWT synchronously to inspect claims and KB-JWT
+  const decoded = decodeSdJwtSync(rawToken, hasher);
+  const evtPayload = decoded.jwt?.payload;
+  const iss = evtPayload?.iss;
+
+  if (!expectedNonce || !decoded.kbJwt || !iss || evtPayload.email_verified !== true) {
+    throw new Error('Missing nonce, KB-JWT, issuer, or email_verified !== true.');
+  }
+
+  if (evtPayload.email?.toLowerCase() !== submittedEmail.trim().toLowerCase()) {
+    throw new Error('Submitted email does not match the EVT email claim.');
+  }
+
+  // 2. DNS TXT delegation check on _email-verification.<domain>
+  const domain = submittedEmail.trim().split('@')[1];
+  const txtRecords = (await dns.resolveTxt(`_email-verification.${domain}`)).map((r) =>
+    r.join('')
+  );
+
+  if (
+    !txtRecords.some(
+      (txt) => txt.startsWith('iss=') && `https://${txt.slice(4).trim()}` === iss
+    )
+  ) {
+    throw new Error(`Issuer "${iss}" is not delegated via DNS for "${domain}".`);
+  }
+
+  // 3. Fetch issuer metadata from /.well-known/email-verification and load JWKS
+  const discoveryUrl = new URL('/.well-known/email-verification', iss);
+  if (discoveryUrl.protocol !== 'https:') {
+    throw new Error('Issuer must use HTTPS.');
+  }
+
+  const metadataResponse = await fetch(discoveryUrl);
+  if (!metadataResponse.ok) {
+    throw new Error(`Failed to fetch issuer metadata from ${discoveryUrl}.`);
+  }
+  const metadata = await metadataResponse.json();
+  if (metadata.issuer !== iss || !metadata.jwks_uri?.startsWith('https://')) {
+    throw new Error('Invalid issuer metadata or non-HTTPS jwks_uri.');
+  }
+
+  const issuerJwks = createRemoteJWKSet(new URL(metadata.jwks_uri));
+
+  // 4. Configure SD-JWT and Key Binding verification
+  const evtOptions = {
+    typ: 'ev+sd-jwt',
+    issuer: iss,
+    algorithms: ALLOWED_ALGS,
+    maxTokenAge: '5m',
+    clockTolerance: '1m',
+  };
+
+  const sdJwt = new SdJwtInstance({
+    hasher,
+    verifier: async (data, sig) => {
+      const compactEvt = `${data}.${sig}`;
+      try {
+        await jwtVerify(compactEvt, issuerJwks, evtOptions);
+      } catch (err) {
+        // When `kid` is omitted (e.g. Gmail) and multiple keys match in the JWKS,
+        // jose throws JWKSMultipleMatchingKeys, which yields each matching CryptoKey.
+        if (err?.code !== 'ERR_JWKS_MULTIPLE_MATCHING_KEYS') throw err;
+        let matched = false;
+        for await (const publicKey of err) {
+          try {
+            await jwtVerify(compactEvt, publicKey, evtOptions);
+            matched = true;
+            break;
+          } catch {}
+        }
+        if (!matched) throw err;
+      }
+      return true;
+    },
+    kbVerifier: async (data, sig) => {
+      const holderJwk = evtPayload.cnf?.jwk;
+      const holderAlg = holderJwk?.alg;
+      const kbAlg = decoded.kbJwt.header.alg;
+
+      if (
+        !holderAlg ||
+        !kbAlg ||
+        !ALLOWED_ALGS.includes(holderAlg) ||
+        !ALLOWED_ALGS.includes(kbAlg) ||
+        normalizeAlg(kbAlg) !== normalizeAlg(holderAlg)
+      ) {
+        throw new Error('Missing, disallowed, or mismatched KB-JWT algorithm.');
+      }
+
+      const holderKey = await importJWK(
+        { ...holderJwk, alg: normalizeAlg(holderAlg) },
+        normalizeAlg(kbAlg)
+      );
+      await jwtVerify(`${data}.${sig}`, holderKey, {
+        typ: 'kb+jwt',
+        audience: expectedAudience,
+        algorithms: [kbAlg, normalizeAlg(kbAlg)],
+        maxTokenAge: '5m',
+        clockTolerance: '1m',
+      });
+      return true;
+    },
+  });
+
+  const verified = await sdJwt.verify(rawToken, {
+    requiredClaimKeys: ['email', 'email_verified'],
+    keyBindingNonce: expectedNonce,
+    expectedKeyBindingAudience: expectedAudience,
+    keyBindingMaxAgeSeconds: 300,
+    skewSeconds: 60,
+  });
+
+  return verified;
+}
+
+async function readRequestBody(req) {
+  const chunks = [];
+  for await (const chunk of req) {
+    chunks.push(chunk);
+  }
+  const raw = Buffer.concat(chunks).toString('utf8');
+  const contentType = (req.headers['content-type'] || '').split(';')[0].trim();
+
+  if (contentType === 'application/json') {
+    return raw ? JSON.parse(raw) : {};
+  }
+  if (contentType === 'application/x-www-form-urlencoded') {
+    return Object.fromEntries(new URLSearchParams(raw));
+  }
+  try {
+    return raw ? JSON.parse(raw) : {};
+  } catch {
+    return Object.fromEntries(new URLSearchParams(raw));
+  }
+}
+
+function getExpectedOrigin(req) {
+  const originHeader = req.headers.origin;
+  if (originHeader) return originHeader;
+  const proto = req.headers['x-forwarded-proto'] || 'http';
+  const host = req.headers['x-forwarded-host'] || req.headers.host || `localhost:${PORT}`;
+  return `${proto}://${host}`;
+}
+
+async function handleVerificationRequest(req, res) {
+  // Atomically read and consume the expected nonce from server-side session storage
+  const cookies = parseCookies(req.headers.cookie);
+  const sessionId = cookies[SESSION_COOKIE_NAME];
+  const session = sessionId ? sessions.get(sessionId) : undefined;
+  const expectedNonce = session?.nonce ?? null;
+  if (session) {
+    session.nonce = null;
+  }
+
+  let body;
+  try {
+    body = await readRequestBody(req);
+  } catch {
+    res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
+    res.end(JSON.stringify({ ok: false, verified: false, error: 'Invalid request body.' }));
+    return;
+  }
+
+  const submittedEmail = (body.email || body['email-address'] || '').trim();
+  const fullName = (body.name || body.fullName || '').trim();
+  const favoriteDrink = (body.favoriteDrink || 'Maple Oat Latte').trim();
+  const rawToken =
+    body.token ||
+    body.evt ||
+    body.presentationToken ||
+    body['email-verification-token'] ||
+    '';
+
+  if (!submittedEmail || !submittedEmail.includes('@')) {
+    res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
+    res.end(
+      JSON.stringify({
+        ok: false,
+        verified: false,
+        error: 'Please provide a valid email address.',
+      })
+    );
+    return;
+  }
+
+  const expectedAudience = getExpectedOrigin(req);
+
+  // If no token was provided (e.g. browser or email provider does not support EVP),
+  // report that browser verification token was not present so the app can handle fallback.
+  if (!rawToken) {
+    res.writeHead(400, {
+      'Content-Type': 'application/json; charset=utf-8',
+      'Cache-Control': 'no-store',
+    });
+    res.end(
+      JSON.stringify({
+        ok: false,
+        verified: false,
+        fallbackRequired: true,
+        email: submittedEmail,
+        error:
+          'No Email Verification Token (EVT) was provided by the browser. Please use a browser and email provider that support the Email Verification API.',
+      })
+    );
+    return;
+  }
+
+  try {
+    const verified = await verifyEmailVerificationToken({
+      rawToken,
+      submittedEmail,
+      expectedNonce,
+      expectedAudience,
+    });
+
+    const memberRecord = {
+      name: fullName || submittedEmail.split('@')[0],
+      email: verified.payload.email,
+      email_verified: true,
+      issuer: verified.payload.iss,
+      favoriteDrink,
+      points: 150,
+      joinedAt: new Date().toISOString(),
+    };
+    rewardsMembers.set(verified.payload.email.toLowerCase(), memberRecord);
+
+    const acceptsHtml =
+      (req.headers.accept || '').includes('text/html') &&
+      !(req.headers['content-type'] || '').includes('application/json');
+
+    if (acceptsHtml) {
+      res.writeHead(200, {
+        'Content-Type': 'text/html; charset=utf-8',
+        'Cache-Control': 'no-store',
+      });
+      res.end(`<!DOCTYPE html>
+<html lang="en">
+<head>
+  <meta charset="UTF-8">
+  <title>Rewards Account Confirmed | The Daily Grind</title>
+  <style>
+    body { font-family: 'Segoe UI', Tahoma, sans-serif; background: #fafafa; color: #3e2723; display: flex; justify-content: center; align-items: center; min-height: 100vh; margin: 0; }
+    .card { background: white; padding: 2.5rem; border-radius: 12px; box-shadow: 0 6px 20px rgba(0,0,0,0.1); max-width: 480px; text-align: center; }
+    .badge { display: inline-block; background: #2e7d32; color: white; padding: 6px 14px; border-radius: 999px; font-size: 0.85rem; font-weight: 600; margin-bottom: 1rem; }
+    a { display: inline-block; margin-top: 1.5rem; background: #4e342e; color: white; padding: 10px 20px; border-radius: 6px; text-decoration: none; }
+  </style>
+</head>
+<body>
+  <div class="card">
+    <span class="badge">Email Cryptographically Verified</span>
+    <h1>Welcome to Daily Grind Rewards!</h1>
+    <p>Your email <strong>${verified.payload.email}</strong> was confirmed directly by your browser without an OTP or magic link.</p>
+    <p><strong>150 Bonus Beans</strong> have been added to your account.</p>
+    <a href="/">Return to Homepage</a>
+  </div>
+</body>
+</html>`);
+      return;
+    }
+
+    res.writeHead(200, {
+      'Content-Type': 'application/json; charset=utf-8',
+      'Cache-Control': 'no-store',
+    });
+    res.end(
+      JSON.stringify({
+        ok: true,
+        verified: true,
+        email: verified.payload.email,
+        issuer: verified.payload.iss,
+        member: memberRecord,
+        message:
+          'Email verified by browser via Email Verification Token (EVT). Welcome to Daily Grind Rewards!',
+      })
+    );
+  } catch (err) {
+    res.writeHead(400, {
+      'Content-Type': 'application/json; charset=utf-8',
+      'Cache-Control': 'no-store',
+    });
+    res.end(
+      JSON.stringify({
+        ok: false,
+        verified: false,
+        error: err instanceof Error ? err.message : 'Email verification failed.',
+      })
+    );
+  }
+}
+
+const MIME_TYPES = {
+  '.html': 'text/html; charset=utf-8',
+  '.css': 'text/css; charset=utf-8',
+  '.js': 'application/javascript; charset=utf-8',
+  '.mjs': 'application/javascript; charset=utf-8',
+  '.json': 'application/json; charset=utf-8',
+  '.png': 'image/png',
+  '.jpg': 'image/jpeg',
+  '.jpeg': 'image/jpeg',
+  '.svg': 'image/svg+xml',
+  '.ico': 'image/x-icon',
+};
+
+export function createServer() {
+  return http.createServer(async (req, res) => {
+    try {
+      const url = new URL(req.url || '/', getExpectedOrigin(req));
+      const pathname = url.pathname;
+
+      // Endpoint to fetch or refresh a server-generated session-bound nonce
+      if (req.method === 'GET' && pathname === '/api/nonce') {
+        const { session } = getOrCreateSession(req, res);
+        const nonce = randomBytes(32).toString('base64url');
+        session.nonce = nonce;
+        res.writeHead(200, {
+          'Content-Type': 'application/json; charset=utf-8',
+          'Cache-Control': 'no-store',
+        });
+        res.end(JSON.stringify({ nonce }));
+        return;
+      }
+
+      // Server verification endpoints for the rewards sign-up form
+      if (
+        req.method === 'POST' &&
+        (pathname === '/api/verify-email' ||
+          pathname === '/api/rewards/signup' ||
+          pathname === '/submit-registration')
+      ) {
+        await handleVerificationRequest(req, res);
+        return;
+      }
+
+      // Serve homepage with fresh per-form cryptographic nonce and Cache-Control: no-store
+      if (req.method === 'GET' && (pathname === '/' || pathname === '/index.html')) {
+        const { session } = getOrCreateSession(req, res);
+        const nonce = randomBytes(32).toString('base64url');
+        session.nonce = nonce;
+
+        const rawHtml = await fs.readFile(path.join(__dirname, 'index.html'), 'utf8');
+        const renderedHtml = rawHtml.replaceAll('__SERVER_NONCE__', nonce);
+
+        res.writeHead(200, {
+          'Content-Type': 'text/html; charset=utf-8',
+          'Cache-Control': 'no-store',
+        });
+        res.end(renderedHtml);
+        return;
+      }
+
+      // Static file fallback
+      if (req.method === 'GET') {
+        const safePath = path.normalize(pathname).replace(/^(\.\.(\/|\\|$))+/, '');
+        const filePath = path.join(__dirname, safePath);
+        if (!filePath.startsWith(__dirname)) {
+          res.writeHead(403);
+          res.end('Forbidden');
+          return;
+        }
+        try {
+          const stat = await fs.stat(filePath);
+          if (stat.isFile()) {
+            const ext = path.extname(filePath).toLowerCase();
+            const content = await fs.readFile(filePath);
+            res.writeHead(200, {
+              'Content-Type': MIME_TYPES[ext] || 'application/octet-stream',
+            });
+            res.end(content);
+            return;
+          }
+        } catch {
+          // Fall through to 404
+        }
+      }
+
+      res.writeHead(404, { 'Content-Type': 'application/json; charset=utf-8' });
+      res.end(JSON.stringify({ error: 'Not Found' }));
+    } catch (err) {
+      res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
+      res.end(
+        JSON.stringify({
+          error: err instanceof Error ? err.message : 'Internal Server Error',
+        })
+      );
+    }
+  });
+}
+
+if (process.argv[1] && path.resolve(process.argv[1]) === __filename) {
+  const server = createServer();
+  server.listen(PORT, () => {
+    console.log(`The Daily Grind server listening on http://localhost:${PORT}`);
+  });
+}

