+  <title>Visually Stable Mixed Fonts &amp; Metric Normalization</title>
+  <style>
+    @layer base, theme, components;
+
+    @layer base {
+      :root {
+        color-scheme: light dark;
+        --font-primary: Verdana, "Segoe UI", system-ui, sans-serif;
+        --font-code: "Courier New", Consolas, monospace;
+        --font-alternate-theme: "Times New Roman", Times, Georgia, serif;
+        --x-height-ratio: 0.51;
+
+        --surface-bg: light-dark(#f8fafc, #0f172a);
+        --card-bg: light-dark(#ffffff, #1e293b);
+        --card-border: light-dark(#e2e8f0, #334155);
+        --text-primary: light-dark(#0f172a, #f8fafc);
+        --text-muted: light-dark(#475569, #94a3b8);
+        --code-bg: light-dark(#f1f5f9, #0f172a);
+        --code-border: light-dark(#cbd5e1, #475569);
