+
+      h1, h2 {
+        line-height: 1.25;
+        margin-block-start: 0;
+        margin-block-end: 0.75rem;
+        text-wrap: balance;
+      }
+
+      h1 {
+        font-size: clamp(1.5rem, 1rem + 2vw, 2.25rem);
+      }
+
+      h2 {
+        font-size: clamp(1.15rem, 0.95rem + 1vw, 1.5rem);
+      }
+
+      p {
+        margin-block-start: 0;
+        margin-block-end: 1rem;
+        max-inline-size: 65ch;
+        text-wrap: pretty;
+        overflow-wrap: break-word;
+
+        &:last-child {
+          margin-block-end: 0;
+        }
+      }
+    }
+
+    @layer components {
+      .demo-card {
+        background-color: var(--card-bg);
+        border: 1px solid var(--card-border);
+        border-radius: 0.75rem;
+        padding-block: 1.75rem;
+        padding-inline: 1.75rem;
+      }
+
+      .badge {
+        display: inline-block;
+        font-size: 0.75rem;
+        font-weight: 600;
+        padding-block: 0.2rem;
+        padding-inline: 0.6rem;
+        border-radius: 999rem;
+        margin-block-end: 0.75rem;
+        background-color: var(--code-bg);
+        border: 1px solid var(--code-border);
+        color: var(--accent-primary);
+      }
+
+      /* 1. Automatic x-height normalization across mixed fonts */
+      #mixed-fonts-container {
+        font-family: var(--font-primary);
+        font-size: 1.0625rem;
+        line-height: 1.65;
+        /* Automatically extract and apply x-height aspect ratio from the primary font
+           so nested inline code elements match its visual lowercase height */
+        font-size-adjust: from-font;
+
+        & :where(code, kbd, samp) {
+          font-family: var(--font-code);
+          font-size-adjust: inherit;
+          background-color: var(--code-bg);
+          border: 1px solid var(--code-border);
+          border-radius: 0.375rem;
+          padding-block: 0.1rem;
+          padding-inline: 0.35rem;
+        }
+      }
+
+      /* 2. Independent theme container with specific numeric metric override */
+      #independent-theme-container {
+        background-color: var(--theme-alt-bg);
+        border-color: var(--theme-alt-border);
+        font-family: var(--font-alternate-theme);
+        font-size: 1.0625rem;
+        line-height: 1.65;
+        /* Lock down visual proportions using an explicit numeric x-height aspect ratio override */
+        font-size-adjust: ex-height 0.51;
+        font-size-adjust: 0.51;
+
+        & .badge {
+          color: var(--theme-alt-accent);
+          border-color: var(--theme-alt-border);
+        }
+
+        & code {
+          font-family: var(--font-code);
+          font-size-adjust: 0.51;
+          background-color: var(--card-bg);
+          border: 1px solid var(--theme-alt-border);
+          border-radius: 0.375rem;
+          padding-block: 0.1rem;
+          padding-inline: 0.35rem;
+        }
+      }
+
+      /* Fallback strategy for browsers without font-size-adjust support */
+      @supports not (font-size-adjust: from-font) {
+        #mixed-fonts-container {
+          line-height: 1.7;
+          font-size: 1.0625rem;
+
+          & :where(code, kbd, samp) {
+            font-size: 1.08em;
+            line-height: 1.5;
+          }
+        }
+
+        #independent-theme-container {
+          font-size: 1.18rem;
+          line-height: 1.6;
+
+          & code {
