+            line-height: 1.5;
+          }
+        }
+      }
+    }
+  </style>
+</head>
+<body>
+  <main>
+    <header>
+      <h1>Font Metric Normalization with Modern CSS</h1>
+      <p>
+        Comparing automatic visual x-height alignment across mixed font families against an independent theme container with a locked numeric metric override.
+      </p>
+    </header>
+
+    <section id="mixed-fonts-container" class="demo-card" aria-labelledby="mixed-fonts-heading">
+      <span class="badge">font-size-adjust: from-font</span>
+      <h2 id="mixed-fonts-heading">Mixed Font Families (Prose &amp; Inline Code)</h2>
+      <p>
+        When mixing body text with inline code such as <code>const ratio = getComputedStyle(el).fontSizeAdjust</code> or <code>font-size-adjust: from-font</code>, differing font families normally exhibit mismatched lowercase heights (x-heights) even at the exact same declared <code>font-size</code>.
+      </p>
+      <p>
+        By applying <code>font-size-adjust: from-font</code> to <code>#mixed-fonts-container</code>, the browser extracts the x-height aspect ratio from the primary typeface and automatically scales nested <code>&lt;code&gt;</code> and <code>&lt;kbd&gt;</code> spans so their lowercase glyphs align seamlessly with surrounding prose.
+      </p>
+    </section>
+
+    <section id="independent-theme-container" class="demo-card" aria-labelledby="independent-theme-heading">
+      <span class="badge">font-size-adjust: 0.51</span>
+      <h2 id="independent-theme-heading">Independent Theme Container (Numeric Metric Override)</h2>
+      <p>
+        Because this container represents an independent editorial theme using a classic serif stack (<code>Times New Roman</code> / <code>Georgia</code>) rather than inheriting the primary font family, it applies a specific numeric metric override via <code>font-size-adjust: 0.51</code>.
+      </p>
+      <p>
+        Locking the x-height aspect ratio to <code>0.51</code> guarantees that lowercase letters and embedded tokens like <code>theme.lockProportions(0.51)</code> maintain consistent visual proportions and readability regardless of which theme font is active.
+      </p>
+    </section>
+  </main>
+</body>
+</html>

