+  }
+
+  disconnectedCallback() {
+    document.removeEventListener('coffee-order', this.#handleExternalOrder);
+  }
+
+  #handleExternalOrder = (e) => {
+    const detail = e.detail || {};
+    if (!detail.name) return;
+    this.addItem({
+      name: detail.name,
