+    const basePrice = Number.parseFloat(baseInput?.dataset.price || '0');
+    const size = sizeInput ? sizeInput.value : 'Medium (12 oz)';
+    const sizePrice = Number.parseFloat(sizeInput?.dataset.price || '0');
+
+    const extras = extraInputs.map((el) => el.value);
+    const extrasPrice = extraInputs.reduce(
+      (sum, el) => sum + Number.parseFloat(el.dataset.price || '0'),
+      0
+    );
+
+    const total = basePrice + sizePrice + extrasPrice;
+    return { base, size, extras, total };
+  }
