+    const total = this.#bag.reduce((sum, item) => sum + item.price, 0);
+    const itemWord = count === 1 ? 'item' : 'items';
+    this.#els.bagStatus.textContent = `Bag: ${count} ${itemWord} ($${total.toFixed(2)})`;
+  }
+
+  #renderBagDialog() {
+    this.#els.bagList.replaceChildren();
+    if (this.#bag.length === 0) {
