+      this.#els.bagList.append(emptyLi);
+      this.#els.dialogTotal.textContent = 'Total: $0.00';
+      return;
+    }
+
+    let total = 0;
+    for (const item of this.#bag) {
+      total += item.price;
+      const li = document.createElement('li');
+      li.className = 'bag-item';
+
+      const info = document.createElement('div');
+      info.className = 'bag-item-info';
+
+      const title = document.createElement('span');
+      title.className = 'bag-item-title';
+      title.textContent = `${item.name} — $${item.price.toFixed(2)}`;
+
+      const meta = document.createElement('span');
+      meta.className = 'bag-item-meta';
+      meta.textContent = item.details;
+
+      info.append(title, meta);
+
+      const removeBtn = document.createElement('button');
+      removeBtn.type = 'button';
+      removeBtn.className = 'remove-btn';
