+import React, { useState, useEffect } from 'react';
+import { useWebMCP } from 'use-webmcp-tool';
+
+export interface ArticleUtilityProps {
+  slug?: string;
+  title?: string;
+  summary?: string;
+  author?: string;
+  date?: string;
+  category?: string;
+  readingTime?: number;
+  initialIsBookmarked?: boolean;
+}
+
+const FONT_SIZES = ['small', 'medium', 'large'] as const;
+type FontSizeOption = (typeof FONT_SIZES)[number];
+
+export default function ArticleUtilities({
+  slug,
+  title,
+  summary,
+  author,
+  date,
+  category,
+  readingTime,
+  initialIsBookmarked = false,
+}: ArticleUtilityProps) {
+  const [isBookmarked, setIsBookmarked] = useState(initialIsBookmarked);
+  const [fontSize, setFontSize] = useState<FontSizeOption>('medium');
+  const [shareFeedback, setShareFeedback] = useState<string | null>(null);
+
+  const isOnArticlePage = Boolean(slug);
+
+  useEffect(() => {
+    setIsBookmarked(initialIsBookmarked);
+  }, [initialIsBookmarked]);
+
+  useEffect(() => {
+    if (!slug) return;
+    const handleReadingListUpdated = (event: Event) => {
+      const customEvent = event as CustomEvent<{ readingList?: string[] }>;
+      if (customEvent.detail?.readingList) {
+        setIsBookmarked(customEvent.detail.readingList.includes(slug));
+      }
+    };
+    window.addEventListener('reading-list-updated', handleReadingListUpdated);
+    return () => {
+      window.removeEventListener('reading-list-updated', handleReadingListUpdated);
+    };
+  }, [slug]);
+
+  const applyFontSize = (size: FontSizeOption) => {
+    const proseEl = document.querySelector('article .prose') as HTMLElement | null;
+    if (!proseEl) {
+      return false;
+    }
+    proseEl.classList.remove('prose-sm', 'prose-base', 'prose-lg', 'prose-xl');
+    const sizeClass = size === 'small' ? 'prose-sm' : size === 'large' ? 'prose-lg' : 'prose-base';
+    proseEl.classList.add(sizeClass);
+    setFontSize(size);
+    return true;
+  };
+
+  // Site-wide utility: List all articles or filter by category
+  useWebMCP<{ category?: string; limit?: number }, unknown>({
+    name: 'list_articles',
+    description: 'Lists published articles across The DevTools Times, optionally filtered by category.',
+    inputSchema: {
+      type: 'object',
+      properties: {
+        category: {
+          type: 'string',
+          description: 'Category name to filter articles by, e.g., lifestyle, science, sports, politics.',
+        },
+        limit: {
+          type: 'number',
+          minimum: 1,
+          maximum: 50,
+          default: 20,
+          description: 'Maximum number of articles to return.',
+        },
+      },
+    },
+    async execute({ category: filterCat, limit = 20 }, { signal }) {
+      const effectiveLimit = typeof limit === 'number' && limit > 0 ? Math.min(limit, 50) : 20;
+      try {
+        const response = await fetch(`${import.meta.env.BASE_URL}api/articles.json`, { signal });
+        if (!response.ok) {
+          return { error: `Request failed with status ${response.status}` };
+        }
+        const data: Array<{ slug: string; title: string; summary: string; category?: string }> = await response.json();
+        const filtered =
+          typeof filterCat === 'string' && filterCat.trim()
+            ? data.filter(
+                item =>
+                  item.category?.toLowerCase() === filterCat.trim().toLowerCase() ||
+                  item.title.toLowerCase().includes(filterCat.trim().toLowerCase()) ||
+                  item.summary.toLowerCase().includes(filterCat.trim().toLowerCase())
+              )
+            : data;
+        const sliced = filtered.slice(0, effectiveLimit).map(item => ({
+          slug: item.slug,
+          title: item.title,
+          summary: item.summary,
+          url: `${import.meta.env.BASE_URL}articles/${item.slug}`,
+        }));
+        return {
+          count: sliced.length,
+          articles: sliced,
+        };
+      } catch (err) {
+        if (signal.aborted) throw err;
+        return { error: err instanceof Error ? err.message : String(err) };
+      }
+    },
+    annotations: { readOnlyHint: true },
+  });
+
+  // Site-wide utility: Fetch article popularity stats
+  useWebMCP<{ slug?: string }, unknown>({
+    name: 'get_article_popularity',
+    description: 'Retrieves view count and trending status for an article.',
+    inputSchema: {
+      type: 'object',
+      properties: {
+        slug: {
+          type: 'string',
+          description: 'The slug identifier of the article to inspect. Defaults to the current article when viewing an article page.',
+        },
+      },
+    },
+    async execute({ slug: targetSlug }, { signal }) {
+      const resolvedSlug = (typeof targetSlug === 'string' && targetSlug.trim()) ? targetSlug.trim() : slug;
+      if (!resolvedSlug) {
+        return { error: 'Pass an article slug to check popularity.' };
+      }
+      try {
+        const response = await fetch(
+          `${import.meta.env.BASE_URL}api/article-popularity?id=${encodeURIComponent(resolvedSlug)}`,
+          { signal }
+        );
+        if (!response.ok) {
+          return { error: `Failed to fetch article popularity (status ${response.status}).` };
+        }
+        const data = await response.json();
+        return {
+          slug: resolvedSlug,
+          views: data.views,
+          trending: Boolean(data.trending),
+        };
+      } catch (err) {
+        if (signal.aborted) throw err;
+        return { error: err instanceof Error ? err.message : String(err) };
+      }
+    },
+    annotations: { readOnlyHint: true },
+  });
+
+  // Current article utility: Extract current article content and metadata
+  useWebMCP<{ includeFullText?: boolean }, unknown>({
+    name: 'get_current_article_details',
+    description: 'Extracts the headline, author, publication date, reading time, and body text of the article currently open on the page.',
+    inputSchema: {
+      type: 'object',
+      properties: {
+        includeFullText: {
+          type: 'boolean',
+          default: true,
+          description: 'Whether to include the full text of the article body.',
+        },
+      },
+    },
+    enabled: isOnArticlePage,
+    execute({ includeFullText = true }) {
+      if (!slug) {
+        return { error: 'No article is currently open on this page.' };
+      }
+      const proseEl = document.querySelector('article .prose');
+      const headings = proseEl
+        ? Array.from(proseEl.querySelectorAll('h1, h2, h3, h4')).map(h => h.textContent?.trim() || '').filter(Boolean)
