+
+      return {
+        slug,
+        title: title || document.querySelector('article h1')?.textContent?.trim() || document.title,
+        summary: summary || '',
+        author: author || '',
+        date: date || '',
+        category: category || '',
+        readingTimeMinutes: readingTime ?? Math.max(1, Math.ceil(wordCount / 200)),
+        wordCount,
+        headings,
+        bookmarked: isBookmarked,
+        url: window.location.href,
+        ...(includeFullText ? { content: bodyText } : {}),
+      };
+    },
+    annotations: { readOnlyHint: true },
+  });
+
+  // Current article utility: Bookmark or unbookmark the current article
+  useWebMCP<{ bookmarked?: boolean }, unknown>({
+    name: 'bookmark_current_article',
+    description: "Bookmarks or unbookmarks the currently open article in the user's reading list.",
+    inputSchema: {
+      type: 'object',
+      properties: {
+        bookmarked: {
+          type: 'boolean',
+          description: 'Desired bookmark state. Omit to toggle the current bookmark status.',
+        },
+      },
+    },
+    enabled: isOnArticlePage,
+    async execute({ bookmarked: desiredState }, { signal }) {
+      if (!slug) {
+        return { error: 'No article is currently open on this page.' };
+      }
+      try {
+        if (typeof desiredState === 'boolean' && desiredState === isBookmarked) {
+          return {
+            slug,
+            bookmarked: isBookmarked,
+            message: `Article "${title || slug}" is already ${isBookmarked ? 'bookmarked' : 'not in the reading list'}.`,
+          };
+        }
+        const response = await fetch(`${import.meta.env.BASE_URL}api/reading-list.json`, {
+          method: 'POST',
+          headers: { 'Content-Type': 'application/json' },
+          body: JSON.stringify({ slug }),
+          signal,
+        });
+        if (!response.ok) {
+          return { error: `Request failed with status ${response.status}` };
+        }
+        const data = await response.json();
+        const list: string[] = Array.isArray(data.readingList) ? data.readingList : [];
+        const updatedBookmarked = list.includes(slug);
+        setIsBookmarked(updatedBookmarked);
+        window.dispatchEvent(new CustomEvent('reading-list-updated', { detail: { readingList: list } }));
+        return {
+          slug,
+          bookmarked: updatedBookmarked,
+          readingList: list,
+        };
+      } catch (err) {
+        if (signal.aborted) throw err;
+        return { error: err instanceof Error ? err.message : String(err) };
+      }
+    },
+    annotations: { readOnlyHint: false },
+  });
+
+  // Current article utility: Share or copy link for the current article
+  useWebMCP<{ method?: 'copy_link' | 'web_share' }, unknown>({
+    name: 'share_current_article',
+    description: 'Shares the current article or copies its canonical URL to the clipboard.',
+    inputSchema: {
+      type: 'object',
+      properties: {
+        method: {
+          type: 'string',
+          enum: ['copy_link', 'web_share'],
+          default: 'copy_link',
+          description: 'How to share the article.',
+        },
+      },
+    },
+    enabled: isOnArticlePage,
+    async execute({ method = 'copy_link' }) {
+      if (!slug) {
+        return { error: 'No article is currently open on this page.' };
+      }
+      const shareUrl = window.location.href;
+      const shareTitle = title || document.title;
+
+      if (method === 'web_share' && typeof navigator !== 'undefined' && typeof navigator.share === 'function') {
