+import React, { useState, useEffect } from 'react';
+import {
+  applyArticleReadingPreferences,
+  extractCurrentArticleMetadata,
+  registerAllBrowserTools,
+} from '../utils/webmcp';
+
+interface Props {
+  slug: string;
+  title: string;
+  author: string;
+  publishedDate: string;
+  readingTime?: number;
+}
+
+export default function ArticleUtilities({
+  slug,
+  title,
+  author,
+  publishedDate,
+  readingTime,
+}: Props) {
+  const [fontSize, setFontSize] = useState<'small' | 'medium' | 'large' | 'xlarge'>('medium');
+  const [lineSpacing, setLineSpacing] = useState<'normal' | 'relaxed' | 'loose'>('normal');
+  const [theme, setTheme] = useState<'default' | 'sepia' | 'high-contrast'>('default');
+  const [highlightQuery, setHighlightQuery] = useState('');
+  const [citationFormat, setCitationFormat] = useState<'markdown' | 'apa' | 'mla' | 'chicago' | 'plain'>('markdown');
+  const [statusNote, setStatusNote] = useState<string | null>(null);
+  const [stats, setStats] = useState<{ wordCount: number; estimatedMinutes: number; headingsCount: number } | null>(null);
+
+  useEffect(() => {
+    registerAllBrowserTools();
+
+    const meta = extractCurrentArticleMetadata();
+    if (meta.wordCount > 0) {
+      setStats({
+        wordCount: meta.wordCount,
+        estimatedMinutes: meta.estimatedReadingTimeMinutes,
+        headingsCount: meta.headings.length,
+      });
+    }
+
+    const handlePrefsUpdate = (event: Event) => {
+      const customEvent = event as CustomEvent<{
+        fontSize?: 'small' | 'medium' | 'large' | 'xlarge';
+        lineSpacing?: 'normal' | 'relaxed' | 'loose';
+        theme?: 'default' | 'sepia' | 'high-contrast';
+        highlightQuery?: string;
+      }>;
+      if (customEvent.detail?.fontSize) setFontSize(customEvent.detail.fontSize);
+      if (customEvent.detail?.lineSpacing) setLineSpacing(customEvent.detail.lineSpacing);
+      if (customEvent.detail?.theme) setTheme(customEvent.detail.theme);
+      if (customEvent.detail?.highlightQuery !== undefined) {
+        setHighlightQuery(customEvent.detail.highlightQuery);
+      }
+    };
+
+    window.addEventListener('devtools-times:reader-preferences-updated', handlePrefsUpdate);
+    return () => {
+      window.removeEventListener('devtools-times:reader-preferences-updated', handlePrefsUpdate);
+    };
+  }, []);
+
+  const handleReaderSubmit = (e: React.FormEvent<HTMLFormElement>) => {
+    e.preventDefault();
+    const formData = new FormData(e.currentTarget);
+    const nextFontSize =
+      ((formData.get('fontSize') as 'small' | 'medium' | 'large' | 'xlarge' | null) ?? fontSize) ||
+      'medium';
+    const nextLineSpacing =
+      ((formData.get('lineSpacing') as 'normal' | 'relaxed' | 'loose' | null) ?? lineSpacing) ||
+      'normal';
+    const nextTheme =
+      ((formData.get('theme') as 'default' | 'sepia' | 'high-contrast' | null) ?? theme) ||
+      'default';
+    const nextHighlight =
+      (formData.get('highlightQuery') as string | null) ?? highlightQuery;
+
+    setFontSize(nextFontSize);
+    setLineSpacing(nextLineSpacing);
+    setTheme(nextTheme);
+    setHighlightQuery(nextHighlight);
+
+    const result = applyArticleReadingPreferences({
+      fontSize: nextFontSize,
+      lineSpacing: nextLineSpacing,
+      theme: nextTheme,
+      highlightQuery: nextHighlight,
+    });
+
+    setStatusNote(result.message);
+
+    const nativeEvent = e.nativeEvent as SubmitEvent;
+    if (typeof nativeEvent?.respondWith === 'function') {
+      nativeEvent.respondWith(Promise.resolve({ slug, ...result }));
+    }
+  };
+
+  const handleCitationSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
+    e.preventDefault();
+    const formData = new FormData(e.currentTarget);
+    const fmt =
+      ((formData.get('format') as 'markdown' | 'apa' | 'mla' | 'chicago' | 'plain' | null) ??
+        citationFormat) ||
+      'markdown';
+    setCitationFormat(fmt);
+
+    const url = typeof window !== 'undefined' ? window.location.href : '';
+    let citation = '';
+    switch (fmt) {
+      case 'apa':
+        citation = `${author}. (${publishedDate}). ${title}. The DevTools Times. ${url}`;
+        break;
+      case 'mla':
+        citation = `${author}. "${title}." The DevTools Times, ${publishedDate}, ${url}.`;
+        break;
+      case 'chicago':
+        citation = `${author}. "${title}." The DevTools Times. Published ${publishedDate}. ${url}.`;
+        break;
+      case 'plain':
+        citation = `${title} — ${url}`;
+        break;
+      case 'markdown':
+      default:
+        citation = `[${title}](${url})`;
+        break;
+    }
+
+    let copied = false;
+    if (typeof navigator !== 'undefined' && navigator.clipboard?.writeText) {
+      try {
+        await navigator.clipboard.writeText(citation);
+        copied = true;
+      } catch {
+        copied = false;
+      }
+    }
+
+    const meta = extractCurrentArticleMetadata();
+    setStats({
+      wordCount: meta.wordCount,
+      estimatedMinutes: meta.estimatedReadingTimeMinutes || readingTime || 3,
+      headingsCount: meta.headings.length,
+    });
+    setStatusNote(copied ? `Copied ${fmt.toUpperCase()} citation to clipboard.` : `Citation: ${citation}`);
+
+    const nativeEvent = e.nativeEvent as SubmitEvent;
+    if (typeof nativeEvent?.respondWith === 'function') {
+      nativeEvent.respondWith(
+        Promise.resolve({
+          slug,
+          title,
+          author,
+          publishedDate,
+          format: fmt,
+          citation,
+          copiedToClipboard: copied,
+          wordCount: meta.wordCount,
+          estimatedReadingTimeMinutes: meta.estimatedReadingTimeMinutes || readingTime || 3,
+          headings: meta.headings,
+        })
+      );
+    }
+  };
+
+  return (
+    <div className="bg-gray-50 border border-gray-200 rounded-lg p-4 mb-6 text-sm">
+      <div className="flex flex-wrap items-center justify-between gap-2 mb-3">
+        <span className="font-semibold text-gray-800">Article Utilities</span>
+        {stats && (
+          <span className="text-xs text-gray-500">
+            {stats.wordCount} words · ~{stats.estimatedMinutes} min read
+            {stats.headingsCount > 0 ? ` · ${stats.headingsCount} sections` : ''}
+          </span>
+        )}
+      </div>
+
+      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
+        <form
+          toolname="article_reader_preferences_form"
+          tooldescription="Adjust client-side article reading preferences including font size, line spacing, color theme, and keyword highlighting."
+          toolautosubmit="true"
+          onSubmit={handleReaderSubmit}
+          className="flex flex-wrap items-center gap-2"
+        >
+          <label htmlFor="reader-font-size" className="sr-only">
+            Font Size
+          </label>
+          <select
+            id="reader-font-size"
+            name="fontSize"
+            value={fontSize}
+            onChange={e => setFontSize(e.target.value as 'small' | 'medium' | 'large' | 'xlarge')}
+            toolparamtitle="Font Size"
+            toolparamdescription="Article text size: 'small', 'medium', 'large', or 'xlarge'."
+            className="p-1.5 border border-gray-300 rounded bg-white text-xs text-gray-700"
+          >
+            <option value="small">Small Text</option>
+            <option value="medium">Medium Text</option>
+            <option value="large">Large Text</option>
+            <option value="xlarge">Extra Large</option>
+          </select>
+
+          <label htmlFor="reader-line-spacing" className="sr-only">
+            Line Spacing
+          </label>
+          <select
+            id="reader-line-spacing"
+            name="lineSpacing"
+            value={lineSpacing}
+            onChange={e => setLineSpacing(e.target.value as 'normal' | 'relaxed' | 'loose')}
+            toolparamtitle="Line Spacing"
+            toolparamdescription="Article line height spacing: 'normal', 'relaxed', or 'loose'."
+            className="p-1.5 border border-gray-300 rounded bg-white text-xs text-gray-700"
+          >
+            <option value="normal">Normal Spacing</option>
+            <option value="relaxed">Relaxed Spacing</option>
+            <option value="loose">Loose Spacing</option>
+          </select>
+
+          <label htmlFor="reader-theme" className="sr-only">
+            Reader Theme
+          </label>
+          <select
+            id="reader-theme"
+            name="theme"
+            value={theme}
