@@ -0,0 +1,809 @@
+import type { ModelContext, WebMCPToolDefinition } from '../global';
+
+export interface ArticleSummary {
+  slug: string;
+  title: string;
+  summary: string;
+  image?: string;
+  category?: string;
+  author?: string;
+  readingTime?: number;
+  date?: string;
+}
+
+const getBaseUrl = (): string => {
+  const base = import.meta.env.BASE_URL || '/';
+  return base.endsWith('/') ? base : `${base}/`;
+};
+
+let cachedArticles: ArticleSummary[] | null = null;
+
+export async function fetchAllArticles(forceRefresh = false): Promise<ArticleSummary[]> {
+  if (cachedArticles && !forceRefresh) {
+    return cachedArticles;
+  }
+  const response = await fetch(`${getBaseUrl()}api/articles.json`);
+  if (!response.ok) {
+    throw new Error(`Failed to fetch articles: ${response.status}`);
+  }
+  const data = await response.json();
+  cachedArticles = Array.isArray(data) ? data : [];
+  return cachedArticles;
+}
+
+export async function searchArticlesClient(
+  query: string,
+  category?: string,
+  articlesSource?: ArticleSummary[]
+): Promise<ArticleSummary[]> {
+  const articles = articlesSource && articlesSource.length > 0 ? articlesSource : await fetchAllArticles();
+  const normalizedQuery = (query || '').trim().toLowerCase();
+  const normalizedCategory = (category || '').trim().toLowerCase();
+
+  return articles.filter((article) => {
+    const matchesCategory =
+      !normalizedCategory ||
+      normalizedCategory === 'all' ||
+      (article.category && article.category.toLowerCase() === normalizedCategory);
+
+    if (!matchesCategory) {
+      return false;
+    }
+
+    if (!normalizedQuery) {
+      return true;
+    }
+
+    const inTitle = article.title?.toLowerCase().includes(normalizedQuery);
+    const inSummary = article.summary?.toLowerCase().includes(normalizedQuery);
+    const inSlug = article.slug?.toLowerCase().includes(normalizedQuery);
+    const inCategory = article.category?.toLowerCase().includes(normalizedQuery);
+    const inAuthor = article.author?.toLowerCase().includes(normalizedQuery);
+
+    return Boolean(inTitle || inSummary || inSlug || inCategory || inAuthor);
+  });
+}
+
+export async function fetchReadingListSlugs(): Promise<string[]> {
+  const response = await fetch(`${getBaseUrl()}api/reading-list.json`);
+  if (!response.ok) {
+    throw new Error(`Failed to fetch reading list: ${response.status}`);
+  }
+  const data = await response.json();
+  return Array.isArray(data.readingList) ? data.readingList : [];
+}
+
+export async function updateReadingListClient(
+  slug: string,
+  action: 'add' | 'remove' | 'toggle' = 'toggle'
+): Promise<{ readingList: string[]; isBookmarked: boolean; status: string }> {
+  const cleanSlug = (slug || '').trim();
+  if (!cleanSlug) {
+    throw new Error('Article slug is required.');
+  }
+
+  const currentList = await fetchReadingListSlugs();
+  const currentlyBookmarked = currentList.includes(cleanSlug);
+
+  if (action === 'add' && currentlyBookmarked) {
+    return {
+      readingList: currentList,
+      isBookmarked: true,
+      status: `Article "${cleanSlug}" is already in the reading list.`,
+    };
+  }
+
+  if (action === 'remove' && !currentlyBookmarked) {
+    return {
+      readingList: currentList,
+      isBookmarked: false,
+      status: `Article "${cleanSlug}" was not in the reading list.`,
+    };
+  }
+
+  const response = await fetch(`${getBaseUrl()}api/reading-list.json`, {
+    method: 'POST',
+    headers: {
+      'Content-Type': 'application/json',
+    },
+    body: JSON.stringify({ slug: cleanSlug }),
+  });
+
+  if (!response.ok) {
+    throw new Error(`Failed to update reading list: ${response.status}`);
+  }
+
+  const data = await response.json();
+  const updatedList: string[] = Array.isArray(data.readingList) ? data.readingList : [];
+  const isBookmarked = updatedList.includes(cleanSlug);
+
+  if (typeof window !== 'undefined') {
+    window.dispatchEvent(
+      new CustomEvent('devtools-times:reading-list-updated', {
+        detail: { slug: cleanSlug, readingList: updatedList, isBookmarked },
+      })
+    );
+  }
+
+  return {
+    readingList: updatedList,
+    isBookmarked,
+    status: isBookmarked
+      ? `Added "${cleanSlug}" to your reading list.`
+      : `Removed "${cleanSlug}" from your reading list.`,
+  };
+}
+
+export function extractCurrentArticleMetadata(): {
+  isArticlePage: boolean;
+  slug: string | null;
+  title: string;
+  summary: string;
+  author: string;
+  publishedDate: string;
+  category: string;
+  wordCount: number;
+  estimatedReadingTimeMinutes: number;
+  contentText: string;
+  headings: string[];
+  relatedArticles: { title: string; url: string; slug: string }[];
+  url: string;
+} {
+  if (typeof document === 'undefined' || typeof window === 'undefined') {
+    return {
+      isArticlePage: false,
+      slug: null,
+      title: '',
+      summary: '',
+      author: '',
+      publishedDate: '',
+      category: '',
+      wordCount: 0,
+      estimatedReadingTimeMinutes: 0,
+      contentText: '',
+      headings: [],
+      relatedArticles: [],
+      url: '',
+    };
+  }
+
+  const pathMatch = window.location.pathname.match(/\/articles\/([^/?#]+)/);
+  const slug = pathMatch ? decodeURIComponent(pathMatch[1]) : null;
+  const articleEl = document.querySelector('main article');
+  const proseEl = document.querySelector('main article .prose') || articleEl;
+
+  const title =
+    document.querySelector('main article h1')?.textContent?.trim() ||
+    document.title.replace(/\s*\|\s*The DevTools Times.*$/i, '').trim();
+
+  const summary =
+    document.querySelector('main article h1 + p')?.textContent?.trim() || '';
+
+  const authorEl = document.querySelector('main article span.font-semibold.text-gray-700');
+  const author = authorEl?.textContent?.trim() || '';
+
+  const bylineText = authorEl?.parentElement?.textContent || '';
+  const dateParts = bylineText.split('|');
+  const publishedDate = dateParts.length > 1 ? dateParts[1].trim() : '';
+
+  const categoryEl = document.querySelector('main article a[href*="/category/"]');
+  const category = categoryEl?.textContent?.trim() || '';
+
+  const contentText = proseEl?.textContent?.replace(/\s+/g, ' ').trim() || '';
+  const words = contentText ? contentText.split(/\s+/).filter(Boolean) : [];
+  const wordCount = words.length;
+  const estimatedReadingTimeMinutes = wordCount > 0 ? Math.max(1, Math.ceil(wordCount / 200)) : 0;
+
+  const headings = Array.from(
+    (proseEl || document).querySelectorAll('h2, h3, h4')
+  )
+    .map((h) => h.textContent?.trim() || '')
+    .filter(Boolean);
+
+  const relatedLinks = Array.from(
+    document.querySelectorAll('section a[href*="/articles/"]')
+  );
+  const relatedMap = new Map<string, { title: string; url: string; slug: string }>();
+  for (const link of relatedLinks) {
+    const href = (link as HTMLAnchorElement).getAttribute('href') || '';
+    const match = href.match(/\/articles\/([^/?#]+)/);
+    const relSlug = match ? decodeURIComponent(match[1]) : '';
+    if (relSlug && relSlug !== slug && !relatedMap.has(relSlug)) {
+      const headingText = link.querySelector('h3, h4, h2')?.textContent?.trim();
+      relatedMap.set(relSlug, {
+        slug: relSlug,
+        title: headingText || link.textContent?.trim() || relSlug,
+        url: href,
+      });
+    }
+  }
+
+  return {
+    isArticlePage: Boolean(slug && articleEl),
+    slug,
+    title,
+    summary,
+    author,
+    publishedDate,
+    category,
+    wordCount,
+    estimatedReadingTimeMinutes,
+    contentText,
+    headings,
+    relatedArticles: Array.from(relatedMap.values()),
+    url: window.location.href,
+  };
+}
+
+export function applyArticleReadingPreferences(options: {
+  fontSize?: 'small' | 'medium' | 'large' | 'xlarge';
+  lineSpacing?: 'normal' | 'relaxed' | 'loose';
+  theme?: 'default' | 'sepia' | 'high-contrast';
+  highlightQuery?: string;
+}): {
+  applied: boolean;
+  fontSize: string;
+  lineSpacing: string;
+  theme: string;
+  highlightedMatches: number;
+  message: string;
+} {
+  if (typeof document === 'undefined') {
+    return {
+      applied: false,
+      fontSize: 'medium',
+      lineSpacing: 'normal',
+      theme: 'default',
+      highlightedMatches: 0,
+      message: 'Document is not available.',
+    };
+  }
+
+  const target =
+    (document.querySelector('main article .prose') as HTMLElement | null) ||
+    (document.querySelector('main article') as HTMLElement | null) ||
+    (document.querySelector('main') as HTMLElement | null);
+
+  if (!target) {
+    return {
+      applied: false,
+      fontSize: options.fontSize || 'medium',
+      lineSpacing: options.lineSpacing || 'normal',
+      theme: options.theme || 'default',
+      highlightedMatches: 0,
+      message: 'No article container found on this page.',
+    };
+  }
+
+  const fontSizeMap: Record<string, string> = {
+    small: '0.925rem',
+    medium: '1rem',
+    large: '1.15rem',
+    xlarge: '1.3rem',
+  };
+
+  const lineSpacingMap: Record<string, string> = {
+    normal: '1.6',
+    relaxed: '1.85',
+    loose: '2.1',
+  };
+
+  const fontSize = options.fontSize || 'medium';
+  const lineSpacing = options.lineSpacing || 'normal';
+  const theme = options.theme || 'default';
+
+  target.style.fontSize = fontSizeMap[fontSize] || fontSizeMap.medium;
+  target.style.lineHeight = lineSpacingMap[lineSpacing] || lineSpacingMap.normal;
+
+  if (theme === 'sepia') {
+    target.style.backgroundColor = '#fdf6e3';
+    target.style.color = '#3b2f2f';
+    target.style.padding = '1.25rem';
+    target.style.borderRadius = '0.5rem';
+  } else if (theme === 'high-contrast') {
+    target.style.backgroundColor = '#111827';
+    target.style.color = '#f9fafb';
+    target.style.padding = '1.25rem';
+    target.style.borderRadius = '0.5rem';
+  } else {
+    target.style.backgroundColor = '';
+    target.style.color = '';
+    target.style.padding = '';
+    target.style.borderRadius = '';
+  }
+
+  target.setAttribute('data-reader-font-size', fontSize);
+  target.setAttribute('data-reader-line-spacing', lineSpacing);
+  target.setAttribute('data-reader-theme', theme);
+
+  let highlightedMatches = 0;
+  if (options.highlightQuery !== undefined) {
+    // Clear previous highlights
+    const existingMarks = target.querySelectorAll('mark[data-webmcp-highlight="true"]');
+    existingMarks.forEach((mark) => {
+      const parent = mark.parentNode;
+      if (parent) {
+        parent.replaceChild(document.createTextNode(mark.textContent || ''), mark);
+        parent.normalize();
+      }
+    });
+
+    const term = options.highlightQuery.trim();
+    if (term.length > 0) {
+      const walker = document.createTreeWalker(target, NodeFilter.SHOW_TEXT);
+      const textNodes: Text[] = [];
+      let currentNode = walker.nextNode();
+      while (currentNode) {
+        if (
+          currentNode.parentElement &&
+          !['SCRIPT', 'STYLE', 'MARK'].includes(currentNode.parentElement.tagName)
+        ) {
+          textNodes.push(currentNode as Text);
+        }
+        currentNode = walker.nextNode();
+      }
+
+      const escaped = term.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
+      const regex = new RegExp(`(${escaped})`, 'gi');
+
+      for (const node of textNodes) {
+        const val = node.nodeValue || '';
+        if (regex.test(val)) {
+          const frag = document.createDocumentFragment();
+          let lastIdx = 0;
+          val.replace(regex, (match, _p1, offset) => {
+            if (offset > lastIdx) {
+              frag.appendChild(document.createTextNode(val.slice(lastIdx, offset)));
+            }
+            const mark = document.createElement('mark');
+            mark.setAttribute('data-webmcp-highlight', 'true');
+            mark.className = 'bg-amber-200 text-gray-900 px-0.5 rounded';
+            mark.textContent = match;
+            frag.appendChild(mark);
+            highlightedMatches++;
+            lastIdx = offset + match.length;
+            return match;
+          });
+          if (lastIdx < val.length) {
+            frag.appendChild(document.createTextNode(val.slice(lastIdx)));
+          }
+          node.parentNode?.replaceChild(frag, node);
+        }
+      }
+    }
+  }
+
+  return {
+    applied: true,
+    fontSize,
+    lineSpacing,
+    theme,
+    highlightedMatches,
+    message: `Applied reading preferences (fontSize: ${fontSize}, lineSpacing: ${lineSpacing}, theme: ${theme}, highlightedMatches: ${highlightedMatches}).`,
+  };
+}
+
+function getModelContexts(): ModelContext[] {
+  const contexts: ModelContext[] = [];
+  if (typeof navigator !== 'undefined' && navigator.modelContext) {
+    contexts.push(navigator.modelContext);
+  }
+  if (
+    typeof document !== 'undefined' &&
+    document.modelContext &&
+    !contexts.includes(document.modelContext)
+  ) {
+    contexts.push(document.modelContext);
+  }
+  return contexts;
+}
+
+export function createBrowserTools(): WebMCPToolDefinition[] {
+  return [
+    {
+      name: 'search_articles',
+      description:
+        'Search articles across The DevTools Times by keyword query and optional category filter. Also updates the client-side search UI if requested.',
+      inputSchema: {
+        type: 'object',
+        properties: {
+          query: {
+            type: 'string',
+            description: 'Keyword or phrase to search for in article titles, summaries, authors, or slugs.',
+          },
+          category: {
+            type: 'string',
+            description: 'Optional category name to filter articles (e.g., science, sports, lifestyle, Culture, Politics, Business, Economy, Media, National, Labor, Urban Development).',
+          },
+          openSearchUI: {
+            type: 'boolean',
+            description: 'Whether to open and populate the interactive search flyout on the page.',
+          },
+        },
+        required: ['query'],
+      },
+      annotations: {
+        readOnlyHint: true,
+      },
+      execute: async (params: { query?: string; category?: string; openSearchUI?: boolean } = {}) => {
+        const query = params.query || '';
+        const category = params.category;
+        const results = await searchArticlesClient(query, category);
+
+        if (typeof window !== 'undefined' && params.openSearchUI !== false) {
+          window.dispatchEvent(
+            new CustomEvent('devtools-times:search', {
+              detail: { query, category, results, open: Boolean(params.openSearchUI) },
+            })
+          );
+        }
+
+        const formatted = results.map((a) => ({
+          slug: a.slug,
+          title: a.title,
+          summary: a.summary,
+          category: a.category,
+          author: a.author,
+          readingTime: a.readingTime,
+          url: `${getBaseUrl()}articles/${a.slug}`,
+        }));
+
+        return {
+          query,
+          category: category || 'all',
+          count: formatted.length,
+          articles: formatted,
+          content: [
+            {
+              type: 'text',
+              text: JSON.stringify({
+                query,
+                category: category || 'all',
+                count: formatted.length,
+                articles: formatted,
+              }),
+            },
+          ],
+        };
+      },
+    },
+    {
+      name: 'get_reading_list',
+      description:
+        'Retrieve the user’s current saved reading list (bookmarked articles) with full article details.',
+      inputSchema: {
+        type: 'object',
+        properties: {
+          openFlyout: {
+            type: 'boolean',
+            description: 'Optional flag to open the reading list UI flyout in the browser.',
+          },
+        },
+      },
+      annotations: {
+        readOnlyHint: true,
+      },
+      execute: async (params: { openFlyout?: boolean } = {}) => {
+        const [slugs, allArticles] = await Promise.all([
+          fetchReadingListSlugs(),
+          fetchAllArticles(),
+        ]);
+
+        const items = allArticles
+          .filter((a) => slugs.includes(a.slug))
+          .map((a) => ({
+            slug: a.slug,
+            title: a.title,
+            summary: a.summary,
+            url: `${getBaseUrl()}articles/${a.slug}`,
+          }));
+
+        if (typeof window !== 'undefined' && params?.openFlyout) {
+          window.dispatchEvent(
+            new CustomEvent('devtools-times:open-reading-list', {
+              detail: { readingList: slugs },
+            })
+          );
+        }
+
+        return {
+          count: items.length,
+          slugs,
+          articles: items,
+          content: [
+            {
+              type: 'text',
+              text: JSON.stringify({ count: items.length, slugs, articles: items }),
+            },
+          ],
+        };
+      },
+    },
+    {
+      name: 'manage_reading_list',
+      description:
+        'Add, remove, or toggle an article in the user’s reading list (bookmarks) by its article slug.',
+      inputSchema: {
+        type: 'object',
+        properties: {
+          slug: {
+            type: 'string',
+            description: 'The article slug identifier (e.g., "coffee-alchemy", "silent-architects"). If omitted on an article page, defaults to the current article slug.',
+          },
+          action: {
+            type: 'string',
+            enum: ['add', 'remove', 'toggle'],
+            description: 'Whether to add, remove, or toggle the article in the reading list. Defaults to "toggle".',
+          },
+        },
+        required: ['slug'],
+      },
+      annotations: {
+        readOnlyHint: false,
+        idempotentHint: false,
+      },
+      execute: async (params: { slug?: string; action?: 'add' | 'remove' | 'toggle' } = {}) => {
+        const fallbackSlug = extractCurrentArticleMetadata().slug || '';
+        const targetSlug = params.slug || fallbackSlug;
+        const result = await updateReadingListClient(targetSlug, params.action || 'toggle');
+
+        return {
+          ...result,
+          slug: targetSlug,
+          content: [
+            {
+              type: 'text',
+              text: JSON.stringify({ ...result, slug: targetSlug }),
+            },
+          ],
+        };
+      },
+    },
+    {
+      name: 'get_current_article_utilities',
+      description:
+        'Extract client-side article metadata, full text, word count, estimated reading time, section headings, and related articles for the currently viewed article, or look up an article by slug.',
+      inputSchema: {
+        type: 'object',
+        properties: {
+          slug: {
+            type: 'string',
+            description: 'Optional article slug. If omitted, inspects the currently open article page in the DOM.',
+          },
+          includeFullText: {
+            type: 'boolean',
+            description: 'Whether to include the full plain text of the article body (default: true).',
+          },
+        },
+      },
+      annotations: {
+        readOnlyHint: true,
+      },
+      execute: async (params: { slug?: string; includeFullText?: boolean } = {}) => {
+        const domArticle = extractCurrentArticleMetadata();
+        if (!params.slug || params.slug === domArticle.slug) {
+          if (domArticle.isArticlePage) {
+            const payload = {
+              ...domArticle,
+              contentText: params.includeFullText === false ? undefined : domArticle.contentText,
+            };
+            return {
+              ...payload,
+              content: [{ type: 'text', text: JSON.stringify(payload) }],
+            };
+          }
+        }
+
+        const articles = await fetchAllArticles();
+        const targetSlug = params.slug || domArticle.slug;
+        const matched = targetSlug
+          ? articles.find((a) => a.slug === targetSlug)
+          : undefined;
+
+        const payload = matched
+          ? {
+              isArticlePage: domArticle.isArticlePage,
+              slug: matched.slug,
+              title: matched.title,
+              summary: matched.summary,
+              author: matched.author || '',
+              category: matched.category || '',
+              estimatedReadingTimeMinutes: matched.readingTime || 3,
+              url: `${getBaseUrl()}articles/${matched.slug}`,
+            }
+          : {
+              ...domArticle,
+              message: 'Not currently on an article page and no matching article slug was provided.',
+            };
+
+        return {
+          ...payload,
+          content: [{ type: 'text', text: JSON.stringify(payload) }],
+        };
+      },
+    },
+    {
+      name: 'customize_article_reader',
+      description:
+        'Client-side article utility to adjust reading view preferences (font size, line spacing, color theme) and highlight search terms within the article text.',
+      inputSchema: {
+        type: 'object',
+        properties: {
+          fontSize: {
+            type: 'string',
+            enum: ['small', 'medium', 'large', 'xlarge'],
+            description: 'Text size for the article body.',
+          },
+          lineSpacing: {
+            type: 'string',
+            enum: ['normal', 'relaxed', 'loose'],
+            description: 'Line height spacing for comfortable reading.',
+          },
+          theme: {
+            type: 'string',
+            enum: ['default', 'sepia', 'high-contrast'],
+            description: 'Color scheme for the article reader container.',
+          },
+          highlightQuery: {
+            type: 'string',
+            description: 'Optional keyword or phrase to highlight inside the article body (pass empty string to clear).',
+          },
+        },
+      },
+      annotations: {
+        readOnlyHint: false,
+        idempotentHint: true,
+      },
+      execute: async (params: {
+        fontSize?: 'small' | 'medium' | 'large' | 'xlarge';
+        lineSpacing?: 'normal' | 'relaxed' | 'loose';
+        theme?: 'default' | 'sepia' | 'high-contrast';
+        highlightQuery?: string;
+      } = {}) => {
+        const result = applyArticleReadingPreferences(params);
+        if (typeof window !== 'undefined') {
+          window.dispatchEvent(
+            new CustomEvent('devtools-times:reader-preferences-updated', {
+              detail: params,
+            })
+          );
+        }
+        return {
+          ...result,
+          content: [{ type: 'text', text: JSON.stringify(result) }],
+        };
+      },
+    },
+    {
+      name: 'share_or_cite_article',
+      description:
+        'Client-side article utility to generate a formatted citation (APA, MLA, Chicago, or Markdown link) or copy/share the article URL.',
+      inputSchema: {
+        type: 'object',
+        properties: {
+          format: {
+            type: 'string',
+            enum: ['markdown', 'apa', 'mla', 'chicago', 'plain'],
+            description: 'Citation or share link format to generate (default: "markdown").',
+          },
+          copyToClipboard: {
+            type: 'boolean',
+            description: 'Whether to copy the generated citation/link to the browser clipboard.',
+          },
+        },
+      },
+      annotations: {
+        readOnlyHint: true,
+      },
+      execute: async (params: {
+        format?: 'markdown' | 'apa' | 'mla' | 'chicago' | 'plain';
+        copyToClipboard?: boolean;
+      } = {}) => {
+        const meta = extractCurrentArticleMetadata();
+        const title = meta.title || document.title || 'The DevTools Times';
+        const author = meta.author || 'The DevTools Times Editorial';
+        const dateStr = meta.publishedDate || new Date().toDateString();
+        const url = meta.url || (typeof window !== 'undefined' ? window.location.href : '');
+        const format = params.format || 'markdown';
+
+        let citation = '';
+        switch (format) {
+          case 'apa':
+            citation = `${author}. (${dateStr}). ${title}. The DevTools Times. ${url}`;
+            break;
+          case 'mla':
+            citation = `${author}. "${title}." The DevTools Times, ${dateStr}, ${url}.`;
+            break;
+          case 'chicago':
+            citation = `${author}. "${title}." The DevTools Times. Published ${dateStr}. ${url}.`;
+            break;
+          case 'plain':
+            citation = `${title} — ${url}`;
+            break;
+          case 'markdown':
+          default:
+            citation = `[${title}](${url})`;
+            break;
+        }
+
+        let copied = false;
+        if (
+          params.copyToClipboard &&
+          typeof navigator !== 'undefined' &&
+          navigator.clipboard?.writeText
+        ) {
+          try {
+            await navigator.clipboard.writeText(citation);
+            copied = true;
+          } catch {
+            copied = false;
+          }
+        }
+
+        const payload = {
+          title,
+          author,
+          publishedDate: dateStr,
+          url,
+          format,
+          citation,
+          copiedToClipboard: copied,
+        };
+
+        return {
+          ...payload,
+          content: [{ type: 'text', text: JSON.stringify(payload) }],
+        };
+      },
+    },
+  ];
+}
+
+const registeredToolNames = new Set<string>();
+
+export function registerAllBrowserTools(): void {
+  if (typeof window === 'undefined') {
+    return;
+  }
+
+  const tools = createBrowserTools();
+  const contexts = getModelContexts();
+
+  for (const ctx of contexts) {
+    if (typeof ctx.registerTool === 'function') {
+      for (const tool of tools) {
+        try {
+          if (typeof ctx.unregisterTool === 'function' && registeredToolNames.has(tool.name)) {
+            ctx.unregisterTool(tool.name);
+          }
+          ctx.registerTool(tool);
+          registeredToolNames.add(tool.name);
+        } catch (err) {
+          // Ignore duplicate registration errors if already registered
+          console.debug(`WebMCP tool registration note for ${tool.name}:`, err);
+        }
+      }
+    } else if (typeof ctx.provideContext === 'function') {
+      try {
+        ctx.provideContext({ tools });
+      } catch {
+        try {
+          ctx.provideContext(tools);
+        } catch (err) {
+          console.debug('WebMCP provideContext note:', err);
+        }
+      }
+    }
+  }
+
+  // Expose a global reference for easy programmatic inspection in DevTools
+  (window as any).__devtoolsTimesBrowserTools = {
+    tools,
+    registerAllBrowserTools,
+    searchArticlesClient,
+    fetchReadingListSlugs,
+    updateReadingListClient,
+    extractCurrentArticleMetadata,
+    applyArticleReadingPreferences,
+  };
+}
